-- Launch catalog: 199 new exercises, clearer names, and own instructions for exercises that
-- shared copied texts. The Smith machine close-grip press moves to its own id; the old id becomes
-- the barbell close-grip bench press, so plans and workouts that used it move along with it.
-- Rows get a fresh updated_at (insert default, update trigger), so installed apps fetch them.

-- The Smith machine version under its own id, keeping its image.
insert into public.exercises
  (id, name, instructions, equipment, measures, muscles, rest_seconds, image_path)
select 'smith-close-grip-bench-press', '{"en":"Smith Machine Close-Grip Bench Press","de":"Enges Bankdrücken an der Multipresse","pt-PT":"Supino pega fechada na máquina Smith","pt-BR":"Supino pegada fechada no Smith"}'::jsonb,
  '{"en":[{"title":"Set up","text":"Place a flat bench under the bar so it lines up with your lower chest. Grip the bar about shoulder-width apart."},{"title":"Lower","text":"Rotate the bar off the hooks and lower it to your lower chest, keeping your elbows tucked close to your sides."},{"title":"Press","text":"Press up until your arms are straight, driving through your triceps. Keep your wrists stacked over your elbows."}],"de":[{"title":"Aufbauen","text":"Stell eine Flachbank so unter die Multipresse, dass die Stange über deiner unteren Brust liegt. Greif etwa schulterbreit."},{"title":"Absenken","text":"Dreh die Stange aus den Haken und senk sie zur unteren Brust. Die Ellbogen bleiben dabei eng am Körper."},{"title":"Drücken","text":"Drück nach oben, bis die Arme gestreckt sind, und spür dabei den Trizeps arbeiten. Die Handgelenke bleiben über den Ellbogen."}],"pt-PT":[{"title":"Preparação","text":"Coloca um banco plano por baixo da máquina Smith, com a barra alinhada com a parte inferior do peito. Agarra-a à largura dos ombros."},{"title":"Descida","text":"Roda a barra para a soltar dos ganchos e desce-a até à parte inferior do peito, com os cotovelos junto ao corpo."},{"title":"Empurrar","text":"Empurra até esticar os braços, sentindo os tríceps a trabalhar. Mantém os pulsos alinhados sobre os cotovelos."}],"pt-BR":[{"title":"Preparação","text":"Coloque um banco reto embaixo do Smith, com a barra alinhada com a parte baixa do peito. Segure a barra na largura dos ombros."},{"title":"Descida","text":"Gire a barra para soltar dos ganchos e desça até a parte baixa do peito, com os cotovelos perto do corpo."},{"title":"Empurrar","text":"Empurre até estender os braços, sentindo o tríceps trabalhar. Mantenha os punhos alinhados sobre os cotovelos."}]}'::jsonb,
  'machine', '{weight,reps}', '{"triceps":0.45,"chest":0.4,"front_delts":0.15}'::jsonb, 120, image_path
from public.exercises where id = 'close-grip-bench-press';

update public.template_exercises set exercise_id = 'smith-close-grip-bench-press'
where exercise_id = 'close-grip-bench-press';
update public.workout_exercises set exercise_id = 'smith-close-grip-bench-press'
where exercise_id = 'close-grip-bench-press';

-- Existing exercises: names, instructions, and the close-grip id now meaning the barbell lift.
update public.exercises set
  instructions = '{"en":[{"title":"Start","text":"Sit or stand with the dumbbells in front of your shoulders, palms facing you and elbows in front of your body."},{"title":"Rotate and press","text":"Press up while turning your palms outward, so they face forward as your arms reach full extension overhead."},{"title":"Lower","text":"Reverse the movement slowly, turning your palms back towards you as the dumbbells return in front of your shoulders."}],"de":[{"title":"Start","text":"Sitz oder steh aufrecht, die Kurzhanteln vor den Schultern, Handflächen zu dir, Ellbogen vor dem Körper."},{"title":"Drehen und drücken","text":"Drück die Hanteln nach oben und dreh dabei die Handflächen nach außen, bis sie bei gestreckten Armen nach vorne zeigen."},{"title":"Absenken","text":"Kehr die Bewegung langsam um und dreh die Handflächen wieder zu dir, bis die Hanteln vor den Schultern sind."}],"pt-PT":[{"title":"Início","text":"Senta-te ou fica de pé com os halteres à frente dos ombros, palmas viradas para ti e cotovelos à frente do corpo."},{"title":"Rodar e empurrar","text":"Empurra para cima enquanto rodas as palmas para fora, de modo a ficarem viradas para a frente com os braços esticados."},{"title":"Descida","text":"Faz o movimento inverso devagar, rodando as palmas de volta para ti até os halteres voltarem à frente dos ombros."}],"pt-BR":[{"title":"Início","text":"Sente ou fique em pé com os halteres na frente dos ombros, palmas voltadas para você e cotovelos à frente do corpo."},{"title":"Girar e empurrar","text":"Empurre para cima enquanto gira as palmas para fora, de modo que fiquem voltadas para a frente com os braços estendidos."},{"title":"Descida","text":"Faça o movimento inverso devagar, girando as palmas de volta para você até os halteres voltarem à frente dos ombros."}]}'::jsonb
where id = 'arnold-press';

update public.exercises set
  name = '{"en":"Standing Calf Raise","de":"Wadenheben stehend","pt-PT":"Gémeos em pé","pt-BR":"Panturrilha em pé"}'::jsonb
where id = 'calf-raise';

update public.exercises set
  instructions = '{"en":[{"title":"Grip","text":"Take the bar with your palms facing you, hands about shoulder-width apart, and hang with straight arms."},{"title":"Pull","text":"Pull your elbows down in front of your body until your chin clears the bar. Keep your legs still."},{"title":"Lower","text":"Lower yourself slowly until your arms are fully straight. Don''t swing into the next rep."}],"de":[{"title":"Griff","text":"Greif die Stange schulterbreit im Untergriff, die Handflächen zeigen zu dir, und häng dich mit gestreckten Armen hin."},{"title":"Ziehen","text":"Zieh die Ellbogen vor dem Körper nach unten, bis dein Kinn über der Stange ist. Die Beine bleiben ruhig."},{"title":"Absenken","text":"Lass dich langsam ab, bis die Arme ganz gestreckt sind. Kein Schwung in die nächste Wiederholung."}],"pt-PT":[{"title":"Pega","text":"Agarra a barra com as palmas viradas para ti, mãos à largura dos ombros, e fica suspenso com os braços esticados."},{"title":"Puxar","text":"Leva os cotovelos para baixo, à frente do corpo, até o queixo passar a barra. Mantém as pernas quietas."},{"title":"Descida","text":"Desce devagar até os braços ficarem totalmente esticados. Não dês balanço para a repetição seguinte."}],"pt-BR":[{"title":"Pegada","text":"Segure a barra com as palmas voltadas para você, mãos na largura dos ombros, e fique pendurado com os braços estendidos."},{"title":"Puxar","text":"Leve os cotovelos para baixo, à frente do corpo, até o queixo passar da barra. Mantenha as pernas paradas."},{"title":"Descida","text":"Desça devagar até os braços ficarem totalmente estendidos. Não pegue embalo para a próxima repetição."}]}'::jsonb
where id = 'chin-up';

update public.exercises set
  name = '{"en":"Close-Grip Bench Press","de":"Enges Bankdrücken","pt-PT":"Supino pega fechada","pt-BR":"Supino fechado"}'::jsonb,
  instructions = '{"en":[{"title":"Set up","text":"Lie on the bench with your eyes under the bar and grip it about shoulder-width apart. Squeeze your shoulder blades together and plant your feet."},{"title":"Lower","text":"Unrack and lower the bar under control to your lower chest, keeping your elbows tucked close to your sides."},{"title":"Press","text":"Press the bar back up until your arms are straight. Keep your wrists stacked over your elbows."}],"de":[{"title":"Aufbauen","text":"Leg dich so auf die Bank, dass deine Augen unter der Stange sind, und greif etwa schulterbreit. Schulterblätter zusammen, Füße fest am Boden."},{"title":"Absenken","text":"Heb die Stange aus und senk sie kontrolliert zur unteren Brust. Die Ellbogen bleiben eng am Oberkörper."},{"title":"Drücken","text":"Drück die Stange nach oben, bis die Arme gestreckt sind. Die Handgelenke bleiben über den Ellbogen."}],"pt-PT":[{"title":"Preparação","text":"Deita-te no banco com os olhos por baixo da barra e agarra-a à largura dos ombros. Junta as omoplatas e apoia bem os pés."},{"title":"Descida","text":"Tira a barra do suporte e desce-a de forma controlada até à parte inferior do peito, com os cotovelos junto ao tronco."},{"title":"Empurrar","text":"Empurra a barra para cima até esticares os braços. Mantém os pulsos alinhados por cima dos cotovelos."}],"pt-BR":[{"title":"Preparação","text":"Deite no banco com os olhos embaixo da barra e segure a barra na largura dos ombros. Junte as escápulas e firme bem os pés."},{"title":"Descida","text":"Tire a barra do suporte e desça com controle até a parte baixa do peito, com os cotovelos colados ao tronco."},{"title":"Empurrar","text":"Empurre a barra para cima até estender os braços. Mantenha os punhos alinhados acima dos cotovelos."}]}'::jsonb,
  equipment = 'barbell',
  measures = '{weight,reps}',
  muscles = '{"triceps":0.45,"chest":0.4,"front_delts":0.15}'::jsonb,
  rest_seconds = 120,
  image_path = null
where id = 'close-grip-bench-press';

update public.exercises set
  name = '{"en":"Dumbbell Shoulder Press","de":"Kurzhantel-Schulterdrücken","pt-PT":"Desenvolvimento com halteres","pt-BR":"Desenvolvimento com halteres"}'::jsonb
where id = 'dumbbell-shoulder-press';

update public.exercises set
  instructions = '{"en":[{"title":"Set up","text":"Attach a rope to a pulley between upper-chest and face height. Grip the ends with your thumbs pointing back and step back."},{"title":"Pull","text":"Pull the rope towards your face, spreading the ends apart so your hands finish beside your ears, elbows high."},{"title":"Return","text":"Hold briefly and squeeze your rear delts, then let the rope return slowly until your arms are straight."}],"de":[{"title":"Aufbauen","text":"Häng ein Seil an einen Seilzug zwischen Brust- und Gesichtshöhe. Greif die Enden mit den Daumen nach hinten und geh einen Schritt zurück."},{"title":"Ziehen","text":"Zieh das Seil Richtung Gesicht und die Enden dabei auseinander, bis die Hände neben den Ohren sind. Die Ellbogen bleiben hoch."},{"title":"Zurück","text":"Halte kurz und spann die hinteren Schultern an. Lass das Seil dann langsam zurück, bis die Arme gestreckt sind."}],"pt-PT":[{"title":"Preparação","text":"Prende uma corda a uma polia entre a altura do peito e a da cara. Agarra as pontas com os polegares para trás e dá um passo atrás."},{"title":"Puxar","text":"Puxa a corda em direção à cara, afastando as pontas até as mãos ficarem ao lado das orelhas, com os cotovelos altos."},{"title":"Voltar","text":"Faz uma breve pausa, contraindo os deltoides posteriores, e deixa a corda voltar devagar até esticares os braços."}],"pt-BR":[{"title":"Preparação","text":"Prenda uma corda em uma polia entre a altura do peito e a do rosto. Segure as pontas com os polegares para trás e dê um passo para trás."},{"title":"Puxar","text":"Puxe a corda em direção ao rosto, afastando as pontas até as mãos ficarem ao lado das orelhas, com os cotovelos altos."},{"title":"Voltar","text":"Segure um instante contraindo o deltoide posterior e deixe a corda voltar devagar até estender os braços."}]}'::jsonb
where id = 'face-pull';

update public.exercises set
  name = '{"en":"French Press","de":"French Press","pt-PT":"Extensão francesa","pt-BR":"Tríceps testa"}'::jsonb,
  instructions = '{"en":[{"title":"Set up","text":"Lie on a flat bench and hold an EZ or straight bar over your shoulders with a narrow overhand grip, arms straight."},{"title":"Lower","text":"Bend only your elbows to lower the bar towards your forehead. Keep your upper arms still and your elbows pointing up."},{"title":"Extend","text":"Straighten your arms to press the bar back over your shoulders. Don''t let your elbows flare out."}],"de":[{"title":"Aufbauen","text":"Leg dich auf eine Flachbank und halt eine SZ- oder Langhantelstange eng im Obergriff über den Schultern, die Arme gestreckt."},{"title":"Absenken","text":"Beug nur die Ellbogen und senk die Stange Richtung Stirn. Die Oberarme bleiben ruhig, die Ellbogen zeigen nach oben."},{"title":"Strecken","text":"Streck die Arme, bis die Stange wieder über den Schultern ist. Lass die Ellbogen nicht nach außen wandern."}],"pt-PT":[{"title":"Preparação","text":"Deita-te num banco plano e segura uma barra EZ ou reta por cima dos ombros, em pega pronada estreita e com os braços esticados."},{"title":"Descida","text":"Flete só os cotovelos e desce a barra em direção à testa. Mantém os braços imóveis e os cotovelos apontados para cima."},{"title":"Estender","text":"Estica os braços até a barra voltar a ficar por cima dos ombros. Não deixes os cotovelos abrir."}],"pt-BR":[{"title":"Preparação","text":"Deite em um banco reto e segure uma barra W ou reta acima dos ombros, com pegada pronada fechada e braços estendidos."},{"title":"Descida","text":"Flexione só os cotovelos e desça a barra em direção à testa. Mantenha os braços parados e os cotovelos apontados para cima."},{"title":"Estender","text":"Estenda os braços até a barra voltar para cima dos ombros. Não deixe os cotovelos abrirem."}]}'::jsonb
where id = 'french-press';

update public.exercises set
  instructions = '{"en":[{"title":"Start","text":"Stand tall with the dumbbells in front of your thighs, palms facing your body and elbows slightly bent."},{"title":"Raise","text":"Lift the weights straight in front of you to shoulder height. Keep your torso still and don''t swing."},{"title":"Lower","text":"Lower slowly over two to three seconds until the dumbbells are back in front of your thighs."}],"de":[{"title":"Start","text":"Steh aufrecht, die Kurzhanteln vor den Oberschenkeln, Handflächen zum Körper, Ellbogen leicht gebeugt."},{"title":"Heben","text":"Heb die Gewichte gerade nach vorne bis auf Schulterhöhe. Oberkörper ruhig halten, nicht schwingen."},{"title":"Absenken","text":"Senk die Hanteln über zwei bis drei Sekunden ab, bis sie wieder vor den Oberschenkeln sind."}],"pt-PT":[{"title":"Início","text":"Fica de pé com os halteres à frente das coxas, palmas viradas para o corpo e cotovelos ligeiramente fletidos."},{"title":"Elevar","text":"Eleva os pesos a direito à tua frente até à altura dos ombros. Mantém o tronco imóvel e não balances."},{"title":"Descida","text":"Desce devagar, em dois a três segundos, até os halteres voltarem à frente das coxas."}],"pt-BR":[{"title":"Início","text":"Fique em pé com os halteres na frente das coxas, palmas voltadas para o corpo e cotovelos levemente flexionados."},{"title":"Elevar","text":"Eleve os pesos retos à sua frente até a altura dos ombros. Mantenha o tronco parado e não balance."},{"title":"Descida","text":"Desça devagar, em dois a três segundos, até os halteres voltarem para a frente das coxas."}]}'::jsonb
where id = 'front-raise';

update public.exercises set
  instructions = '{"en":[{"title":"Set up","text":"Stand with your back and shoulders flat against the pads. Place your feet shoulder-width apart in the middle of the platform."},{"title":"Descend","text":"Release the safety handles and bend your knees until your thighs are at least parallel, back staying on the pad."},{"title":"Drive","text":"Push through your whole foot without locking your knees, and engage the safeties again after your last rep."}],"de":[{"title":"Aufbau","text":"Stell dich mit Rücken und Schultern flach an die Polster. Füße schulterbreit in der Mitte der Plattform."},{"title":"Runter","text":"Löse die Sicherungsgriffe und beug die Knie, bis die Oberschenkel mindestens parallel sind. Der Rücken bleibt am Polster."},{"title":"Hoch","text":"Drück dich über den ganzen Fuß hoch, ohne die Knie durchzustrecken, und klapp nach der letzten Wiederholung die Sicherung wieder ein."}],"pt-PT":[{"title":"Preparação","text":"Encosta as costas e os ombros às almofadas. Coloca os pés à largura dos ombros no meio da plataforma."},{"title":"Descer","text":"Solta os travões e flete os joelhos até as coxas ficarem pelo menos paralelas, com as costas sempre no encosto."},{"title":"Subir","text":"Empurra com o pé todo sem bloquear os joelhos e volta a pôr os travões depois da última repetição."}],"pt-BR":[{"title":"Preparação","text":"Apoie as costas e os ombros nas almofadas. Coloque os pés na largura dos ombros no meio da plataforma."},{"title":"Descer","text":"Solte as travas e flexione os joelhos até as coxas ficarem pelo menos paralelas, com as costas sempre no encosto."},{"title":"Subir","text":"Empurre com o pé inteiro sem travar os joelhos e acione as travas de novo depois da última repetição."}]}'::jsonb
where id = 'hack-squat';

update public.exercises set
  instructions = '{"en":[{"title":"Start","text":"Stand tall with the dumbbells at your sides, palms facing your body and elbows close to your torso."},{"title":"Curl","text":"Curl the dumbbells up with your thumbs on top until your forearms are nearly vertical. Don''t swing your torso."},{"title":"Lower","text":"Lower slowly, keeping the neutral grip, until your arms are straight again."}],"de":[{"title":"Start","text":"Steh aufrecht, die Kurzhanteln seitlich im Hammergriff, Handflächen zum Körper, Ellbogen nah am Oberkörper."},{"title":"Beugen","text":"Beug die Arme und heb die Hanteln mit den Daumen nach oben, bis die Unterarme fast senkrecht sind. Schwing nicht mit dem Oberkörper."},{"title":"Absenken","text":"Senk die Hanteln im Hammergriff langsam ab, bis die Arme wieder gestreckt sind."}],"pt-PT":[{"title":"Início","text":"Fica de pé com os halteres ao lado do corpo, palmas viradas para dentro e cotovelos junto ao tronco."},{"title":"Fletir","text":"Flete os cotovelos e sobe os halteres com os polegares para cima, até os antebraços ficarem quase na vertical. Não balances o tronco."},{"title":"Descida","text":"Desce devagar, sem rodar os pulsos, até os braços ficarem esticados outra vez."}],"pt-BR":[{"title":"Início","text":"Fique em pé com os halteres ao lado do corpo, palmas voltadas para dentro e cotovelos junto ao tronco."},{"title":"Flexionar","text":"Flexione os cotovelos e suba os halteres com os polegares para cima, até os antebraços ficarem quase na vertical. Não balance o tronco."},{"title":"Descida","text":"Desça devagar, sem girar os punhos, até os braços ficarem estendidos de novo."}]}'::jsonb
where id = 'hammer-curl';

update public.exercises set
  name = '{"en":"Incline Dumbbell Press","de":"Schrägbankdrücken mit Kurzhanteln","pt-PT":"Supino inclinado com halteres","pt-BR":"Supino inclinado com halteres"}'::jsonb
where id = 'incline-dumbbell-press';

update public.exercises set
  instructions = '{"en":[{"title":"Set up","text":"Adjust the thigh pads so your legs are locked in. Grip the bar overhand, slightly wider than your shoulders."},{"title":"Pull","text":"Lean back slightly and pull the bar to your upper chest, driving your elbows down towards your hips."},{"title":"Return","text":"Let the bar rise slowly until your arms are straight and your lats are stretched. Keep your torso still."}],"de":[{"title":"Aufbauen","text":"Stell die Beinpolster so ein, dass deine Oberschenkel fixiert sind. Greif die Stange im Obergriff etwas breiter als schulterbreit."},{"title":"Ziehen","text":"Lehn dich leicht zurück und zieh die Stange zur oberen Brust, die Ellbogen Richtung Hüfte."},{"title":"Zurück","text":"Lass die Stange langsam nach oben, bis die Arme gestreckt sind und du den Lat gedehnt spürst. Der Oberkörper bleibt ruhig."}],"pt-PT":[{"title":"Preparação","text":"Ajusta os rolos para prenderem bem as coxas. Agarra a barra em pronação, um pouco mais afastada do que os ombros."},{"title":"Puxar","text":"Inclina-te ligeiramente para trás e puxa a barra até à parte superior do peito, levando os cotovelos em direção à anca."},{"title":"Voltar","text":"Deixa a barra subir devagar até os braços ficarem esticados e sentires os dorsais alongar. Mantém o tronco imóvel."}],"pt-BR":[{"title":"Preparação","text":"Ajuste os apoios para prenderem bem as coxas. Segure a barra com pegada pronada, um pouco mais aberta que os ombros."},{"title":"Puxar","text":"Incline o tronco levemente para trás e puxe a barra até a parte de cima do peito, levando os cotovelos em direção ao quadril."},{"title":"Voltar","text":"Deixe a barra subir devagar até os braços ficarem estendidos e sentir o dorsal alongar. Mantenha o tronco parado."}]}'::jsonb
where id = 'lat-pulldown';

update public.exercises set
  instructions = '{"en":[{"title":"Set up","text":"Hinge at the hips until your torso is almost parallel to the floor, back flat. Let the dumbbells hang under your chest."},{"title":"Raise","text":"With slightly bent elbows, raise the weights out to the sides until your arms line up with your shoulders. Don''t swing."},{"title":"Lower","text":"Lower the dumbbells slowly back under your chest without rounding your back or standing up."}],"de":[{"title":"Position","text":"Beug dich mit geradem Rücken aus der Hüfte vor, bis der Oberkörper fast parallel zum Boden ist. Die Kurzhanteln hängen unter der Brust."},{"title":"Heben","text":"Heb die Gewichte mit leicht gebeugten Ellbogen seitlich an, bis die Arme auf Schulterhöhe sind. Nicht schwingen."},{"title":"Absenken","text":"Senk die Hanteln langsam wieder unter die Brust, ohne den Rücken rund zu machen oder dich aufzurichten."}],"pt-PT":[{"title":"Posição","text":"Inclina o tronco a partir da anca até ficar quase paralelo ao chão, costas direitas. Deixa os halteres pendurados por baixo do peito."},{"title":"Elevar","text":"Com os cotovelos ligeiramente fletidos, eleva os pesos para os lados até os braços ficarem alinhados com os ombros. Sem balançar."},{"title":"Descida","text":"Desce os halteres devagar até ficarem de novo por baixo do peito, sem arredondar as costas nem endireitar o tronco."}],"pt-BR":[{"title":"Posição","text":"Incline o tronco a partir do quadril até ficar quase paralelo ao chão, costas retas. Deixe os halteres pendurados embaixo do peito."},{"title":"Elevar","text":"Com os cotovelos levemente flexionados, eleve os pesos para os lados até os braços ficarem alinhados com os ombros. Sem balançar."},{"title":"Descida","text":"Desça os halteres devagar até ficarem de novo embaixo do peito, sem arredondar as costas nem levantar o tronco."}]}'::jsonb
where id = 'reverse-fly';

update public.exercises set
  instructions = '{"en":[{"title":"Set up","text":"Attach a V-handle to the low pulley. Sit with your feet on the platform, knees soft, and hold the handle with straight arms."},{"title":"Pull","text":"Sit upright and row the handle to your belly, keeping your elbows close to your body and squeezing your shoulder blades."},{"title":"Return","text":"Let your arms extend slowly until they''re straight. Lean forward only slightly and don''t round your back."}],"de":[{"title":"Aufbauen","text":"Häng einen V-Griff unten am Kabelzug ein. Setz dich, Füße auf die Plattform, Knie leicht gebeugt, und halt den Griff mit gestreckten Armen."},{"title":"Ziehen","text":"Setz dich aufrecht hin und zieh den Griff zum Bauch. Die Ellbogen bleiben eng am Körper, die Schulterblätter gehen zusammen."},{"title":"Zurück","text":"Lass die Arme langsam nach vorne, bis sie gestreckt sind. Lehn dich nur leicht vor, ohne den Rücken rund zu machen."}],"pt-PT":[{"title":"Preparação","text":"Coloca uma pega em V na polia baixa. Senta-te com os pés na plataforma, joelhos ligeiramente fletidos, e segura a pega com os braços esticados."},{"title":"Puxar","text":"Mantém o tronco direito e puxa a pega até à barriga, com os cotovelos junto ao corpo, juntando as omoplatas."},{"title":"Voltar","text":"Deixa os braços esticarem devagar. Inclina-te só ligeiramente para a frente, sem arredondar as costas."}],"pt-BR":[{"title":"Preparação","text":"Encaixe o triângulo na polia baixa. Sente com os pés na plataforma, joelhos levemente flexionados, e segure o triângulo com os braços estendidos."},{"title":"Puxar","text":"Mantenha o tronco ereto e puxe o triângulo até a barriga, com os cotovelos perto do corpo, juntando as escápulas."},{"title":"Voltar","text":"Deixe os braços estenderem devagar. Incline o tronco só um pouco à frente, sem arredondar as costas."}]}'::jsonb
where id = 'seated-cable-row';

update public.exercises set
  name = '{"en":"Shoulder Press Machine","de":"Schulterpresse","pt-PT":"Desenvolvimento na máquina","pt-BR":"Desenvolvimento na máquina"}'::jsonb,
  instructions = '{"en":[{"title":"Set up","text":"Adjust the seat so the handles are at shoulder height or slightly below. Sit with your back flat against the pad."},{"title":"Press","text":"Press the handles up until your arms are almost straight. Don''t shrug your shoulders or arch off the pad."},{"title":"Lower","text":"Lower the handles slowly to shoulder height and stop just before the weights touch down."}],"de":[{"title":"Einstellen","text":"Stell den Sitz so ein, dass die Griffe auf Schulterhöhe oder knapp darunter sind. Setz dich mit flachem Rücken an die Lehne."},{"title":"Drücken","text":"Drück die Griffe nach oben, bis die Arme fast gestreckt sind. Schultern nicht hochziehen, kein Hohlkreuz."},{"title":"Absenken","text":"Senk die Griffe langsam bis auf Schulterhöhe und stopp, kurz bevor die Gewichte aufsetzen."}],"pt-PT":[{"title":"Preparação","text":"Ajusta o assento para as pegas ficarem à altura dos ombros ou um pouco abaixo. Encosta bem as costas."},{"title":"Empurrar","text":"Empurra as pegas para cima até os braços ficarem quase esticados. Não encolhas os ombros nem arqueies a lombar."},{"title":"Descida","text":"Desce as pegas devagar até à altura dos ombros e para pouco antes de pousar as placas."}],"pt-BR":[{"title":"Preparação","text":"Ajuste o banco para os pegadores ficarem na altura dos ombros ou um pouco abaixo. Apoie bem as costas no encosto."},{"title":"Empurrar","text":"Empurre os pegadores para cima até os braços ficarem quase estendidos. Não encolha os ombros nem arqueie a lombar."},{"title":"Descida","text":"Desça os pegadores devagar até a altura dos ombros e pare pouco antes de encostar as placas."}]}'::jsonb
where id = 'seated-shoulder-press';

update public.exercises set
  instructions = '{"en":[{"title":"Set up","text":"Straddle the bar with one end anchored. Place a V-handle under it next to the plates and hinge to about 45° with a flat back."},{"title":"Pull","text":"Row the weight up towards your chest, driving your elbows back and squeezing your shoulder blades."},{"title":"Lower","text":"Lower the weight slowly until your arms are straight. Hold your torso angle and don''t jerk the weight up."}],"de":[{"title":"Aufbauen","text":"Stell dich breitbeinig über die Stange, deren Ende fixiert ist. Setz einen V-Griff direkt an den Scheiben unter die Stange und beug dich mit geradem Rücken auf etwa 45° vor."},{"title":"Ziehen","text":"Zieh das Gewicht Richtung Brust, Ellbogen nach hinten, Schulterblätter zusammen."},{"title":"Absenken","text":"Senk das Gewicht langsam, bis die Arme gestreckt sind. Halt den Oberkörperwinkel und reiß das Gewicht nicht mit Schwung hoch."}],"pt-PT":[{"title":"Preparação","text":"Fica com uma perna de cada lado da barra, que tem uma ponta fixa. Encaixa uma pega em V por baixo, junto aos discos, e inclina o tronco a cerca de 45°, costas direitas."},{"title":"Puxar","text":"Puxa o peso em direção ao peito, levando os cotovelos para trás e juntando as omoplatas."},{"title":"Descida","text":"Desce o peso devagar até os braços ficarem esticados. Mantém o ângulo do tronco e não dês esticões."}],"pt-BR":[{"title":"Preparação","text":"Fique com uma perna de cada lado da barra, que tem uma ponta fixa. Encaixe o triângulo embaixo dela, perto das anilhas, e incline o tronco a cerca de 45°, costas retas."},{"title":"Puxar","text":"Puxe o peso em direção ao peito, levando os cotovelos para trás e juntando as escápulas."},{"title":"Descida","text":"Desça o peso devagar até os braços ficarem estendidos. Mantenha o ângulo do tronco e não dê trancos."}]}'::jsonb
where id = 't-bar-row';

update public.exercises set
  instructions = '{"en":[{"title":"Set up","text":"Attach a straight bar to a high pulley. Grip it overhand about shoulder-width apart and pin your elbows to your sides."},{"title":"Push","text":"Push the bar down until your arms are fully straight. Squeeze your triceps at the bottom."},{"title":"Return","text":"Let the bar rise slowly until your forearms are just above parallel to the floor. Keep your elbows and torso still."}],"de":[{"title":"Aufbauen","text":"Häng eine gerade Stange oben am Kabelzug ein. Greif sie schulterbreit im Obergriff und leg die Ellbogen seitlich am Körper an."},{"title":"Drücken","text":"Drück die Stange nach unten, bis die Arme ganz gestreckt sind. Spann unten den Trizeps fest an."},{"title":"Zurück","text":"Lass die Stange langsam hoch, bis die Unterarme knapp über der Waagerechten sind. Ellbogen und Oberkörper bleiben ruhig."}],"pt-PT":[{"title":"Preparação","text":"Prende uma barra reta à polia alta. Agarra-a em pega pronada, à largura dos ombros, e cola os cotovelos ao corpo."},{"title":"Empurrar","text":"Empurra a barra para baixo até esticares totalmente os braços. Contrai o tríceps em baixo."},{"title":"Voltar","text":"Deixa a barra subir devagar até os antebraços ficarem um pouco acima da horizontal. Mantém os cotovelos e o tronco imóveis."}],"pt-BR":[{"title":"Preparação","text":"Prenda uma barra reta na polia alta. Segure com pegada pronada, na largura dos ombros, e cole os cotovelos ao corpo."},{"title":"Empurrar","text":"Empurre a barra para baixo até estender totalmente os braços. Contraia o tríceps embaixo."},{"title":"Voltar","text":"Deixe a barra subir devagar até os antebraços ficarem um pouco acima da linha horizontal. Mantenha os cotovelos e o tronco parados."}]}'::jsonb
where id = 'triceps-pushdown';

-- New exercises.
insert into public.exercises (id, name, instructions, equipment, measures, muscles, rest_seconds)
values
  ('paused-bench-press', '{"en":"Paused Bench Press","de":"Bankdrücken mit Pause","pt-PT":"Supino plano com pausa","pt-BR":"Supino reto com pausa"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Lie on the bench with your eyes under the bar. Squeeze your shoulder blades together and plant your feet."},{"title":"Pause","text":"Lower the bar under control to your lower chest and hold it there motionless for one to two seconds, staying tight."},{"title":"Press","text":"Drive the bar up from the dead stop without bouncing or sinking first. Keep your glutes on the bench."}],"de":[{"title":"Aufbauen","text":"Leg dich so auf die Bank, dass deine Augen unter der Stange sind. Schulterblätter zusammen, Füße fest am Boden."},{"title":"Pause","text":"Senk die Stange kontrolliert zur unteren Brust und halte sie dort ein bis zwei Sekunden ruhig. Bleib dabei auf Spannung."},{"title":"Drücken","text":"Drück die Stange aus dem Stillstand nach oben, ohne sie vorher abfedern oder einsinken zu lassen. Das Gesäß bleibt auf der Bank."}],"pt-PT":[{"title":"Preparação","text":"Deita-te no banco com os olhos por baixo da barra. Junta as omoplatas e apoia bem os pés."},{"title":"Pausa","text":"Desce a barra de forma controlada até à parte inferior do peito e mantém-na imóvel durante um a dois segundos, sem perder a tensão."},{"title":"Empurrar","text":"Empurra a barra a partir da paragem completa, sem a fazer ressaltar nem afundar antes. Mantém os glúteos no banco."}],"pt-BR":[{"title":"Preparação","text":"Deite no banco com os olhos embaixo da barra. Junte as escápulas e firme bem os pés."},{"title":"Pausa","text":"Desça a barra com controle até a parte baixa do peito e mantenha-a parada por um a dois segundos, sem perder a tensão."},{"title":"Empurrar","text":"Empurre a barra a partir da parada total, sem quicar nem afundar antes. Mantenha os glúteos no banco."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"chest":0.65,"triceps":0.2,"front_delts":0.15}'::jsonb, 150),
  ('larsen-press', '{"en":"Larsen Press","de":"Larsen Press","pt-PT":"Supino Larsen","pt-BR":"Supino Larsen"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Lie on the bench with your eyes under the bar. Straighten your legs and hold your feet just off the floor."},{"title":"Lower","text":"Unrack and lower the bar under control to your lower chest, elbows about 45° from your torso."},{"title":"Press","text":"Press the bar up with your upper body alone. Brace your abs so your hips stay level and don''t twist."}],"de":[{"title":"Aufbauen","text":"Leg dich so auf die Bank, dass deine Augen unter der Stange sind. Streck die Beine und halte die Füße knapp über dem Boden."},{"title":"Absenken","text":"Heb die Stange aus und senk sie kontrolliert zur unteren Brust. Die Ellbogen zeigen etwa 45° vom Oberkörper weg."},{"title":"Drücken","text":"Drück die Stange nur aus dem Oberkörper nach oben. Spann den Bauch an, damit die Hüfte ruhig bleibt und nicht kippt."}],"pt-PT":[{"title":"Preparação","text":"Deita-te no banco com os olhos por baixo da barra. Estica as pernas e mantém os pés ligeiramente acima do chão."},{"title":"Descida","text":"Tira a barra do suporte e desce-a de forma controlada até à parte inferior do peito, cotovelos a cerca de 45° do tronco."},{"title":"Empurrar","text":"Empurra a barra só com a parte superior do corpo. Contrai o abdómen para a anca ficar estável e não rodar."}],"pt-BR":[{"title":"Preparação","text":"Deite no banco com os olhos embaixo da barra. Estenda as pernas e mantenha os pés um pouco acima do chão."},{"title":"Descida","text":"Tire a barra do suporte e desça com controle até a parte baixa do peito, cotovelos a cerca de 45° do tronco."},{"title":"Empurrar","text":"Empurre a barra só com a parte de cima do corpo. Contraia o abdômen para o quadril ficar estável e não girar."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"chest":0.55,"triceps":0.25,"front_delts":0.15,"abs":0.05}'::jsonb, 150),
  ('spoto-press', '{"en":"Spoto Press","de":"Spoto Press","pt-PT":"Supino Spoto","pt-BR":"Supino Spoto"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Set up as for your regular bench press: eyes under the bar, shoulder blades squeezed together, feet planted."},{"title":"Pause","text":"Lower the bar under control and stop it 2–3 cm above your chest. Hold it there for one to two seconds without touching."},{"title":"Press","text":"Press back up from the hover without dipping first. Keep the same bar path and elbow position as on your regular bench."}],"de":[{"title":"Aufbauen","text":"Bau dich auf wie beim normalen Bankdrücken: Augen unter der Stange, Schulterblätter zusammen, Füße fest am Boden."},{"title":"Pause","text":"Senk die Stange kontrolliert und stopp sie 2–3 cm über der Brust. Halte sie dort ein bis zwei Sekunden, ohne die Brust zu berühren."},{"title":"Drücken","text":"Drück die Stange aus dieser Position nach oben, ohne vorher nachzugeben. Bahn und Ellbogenwinkel bleiben wie beim normalen Bankdrücken."}],"pt-PT":[{"title":"Preparação","text":"Prepara-te como no supino plano: olhos por baixo da barra, omoplatas juntas e pés bem apoiados."},{"title":"Pausa","text":"Desce a barra de forma controlada e para-a 2–3 cm acima do peito. Mantém-na aí um a dois segundos sem tocar no peito."},{"title":"Empurrar","text":"Empurra a partir dessa posição sem deixar a barra descer antes. Mantém o trajeto e a posição dos cotovelos do teu supino habitual."}],"pt-BR":[{"title":"Preparação","text":"Posicione-se como no supino reto: olhos embaixo da barra, escápulas juntas e pés firmes no chão."},{"title":"Pausa","text":"Desça a barra com controle e pare 2–3 cm acima do peito. Segure ali por um a dois segundos sem encostar no peito."},{"title":"Empurrar","text":"Empurre a partir dessa posição sem deixar a barra descer antes. Mantenha o trajeto e a posição dos cotovelos do seu supino de sempre."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"chest":0.6,"triceps":0.2,"front_delts":0.2}'::jsonb, 150),
  ('pin-press', '{"en":"Pin Press","de":"Pin Press","pt-PT":"Supino a partir dos pinos","pt-BR":"Supino partindo dos pinos"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Set the safety pins in a rack a few centimetres above your chest and rest the bar on them. Lie on the bench under it."},{"title":"Brace","text":"Squeeze your shoulder blades together, plant your feet and grip the bar. Get tight before the bar leaves the pins."},{"title":"Press","text":"Press from a dead stop to lockout, then lower the bar back onto the pins and let it settle fully before the next rep."}],"de":[{"title":"Aufbauen","text":"Stell die Sicherheitsablagen im Rack ein paar Zentimeter über Brusthöhe ein und leg die Stange darauf. Leg dich darunter auf die Bank."},{"title":"Anspannen","text":"Schulterblätter zusammen, Füße fest am Boden, Stange greifen. Bau die volle Spannung auf, bevor die Stange die Ablagen verlässt."},{"title":"Drücken","text":"Drück aus dem Stillstand bis zur vollen Streckung. Leg die Stange danach wieder auf den Ablagen ab und lass sie kurz ganz ruhen."}],"pt-PT":[{"title":"Preparação","text":"Coloca os pinos de segurança do rack uns centímetros acima da altura do peito e pousa a barra neles. Deita-te no banco por baixo."},{"title":"Contrair","text":"Junta as omoplatas, apoia bem os pés e agarra a barra. Ganha tensão antes de a barra sair dos pinos."},{"title":"Empurrar","text":"Empurra a partir da paragem até esticar os braços. Depois pousa a barra nos pinos e deixa-a assentar por completo antes da repetição seguinte."}],"pt-BR":[{"title":"Preparação","text":"Ajuste os pinos de segurança do rack alguns centímetros acima da altura do peito e apoie a barra neles. Deite no banco embaixo dela."},{"title":"Contraia","text":"Junte as escápulas, firme os pés e segure a barra. Gere tensão antes de a barra sair dos pinos."},{"title":"Empurrar","text":"Empurre a partir da parada total até estender os braços. Depois apoie a barra nos pinos e deixe-a assentar por completo antes da próxima repetição."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"chest":0.5,"triceps":0.35,"front_delts":0.15}'::jsonb, 150),
  ('floor-press', '{"en":"Floor Press","de":"Bodendrücken","pt-PT":"Supino no chão","pt-BR":"Supino no chão"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Lie on the floor in a rack with the bar over your shoulders, knees bent and feet flat. Grip slightly wider than shoulder width."},{"title":"Lower","text":"Unrack and lower the bar until your upper arms touch the floor, elbows about 45° from your torso. Pause briefly."},{"title":"Press","text":"Press the bar back up to lockout without bouncing your elbows off the floor. Keep your shoulder blades pinned back."}],"de":[{"title":"Aufbauen","text":"Leg dich im Rack auf den Boden, die Stange über den Schultern, Knie gebeugt, Füße flach. Greif etwas breiter als schulterbreit."},{"title":"Absenken","text":"Heb die Stange aus und senk sie ab, bis die Oberarme den Boden berühren. Ellbogen etwa 45° vom Oberkörper weg, kurz halten."},{"title":"Drücken","text":"Drück die Stange wieder bis zur Streckung hoch, ohne die Ellbogen vom Boden abfedern zu lassen. Die Schulterblätter bleiben zusammen."}],"pt-PT":[{"title":"Preparação","text":"Deita-te no chão dentro do rack com a barra por cima dos ombros, joelhos fletidos e pés assentes. Agarra a barra com as mãos um pouco mais afastadas do que os ombros."},{"title":"Descida","text":"Tira a barra do suporte e desce-a até os tríceps tocarem no chão, cotovelos a cerca de 45° do tronco. Faz uma breve pausa."},{"title":"Empurrar","text":"Empurra a barra até esticar os braços, sem fazer ressaltar os cotovelos no chão. Mantém as omoplatas juntas."}],"pt-BR":[{"title":"Preparação","text":"Deite no chão dentro do rack com a barra acima dos ombros, joelhos flexionados e pés apoiados. Segure a barra com as mãos um pouco mais abertas que os ombros."},{"title":"Descida","text":"Tire a barra do suporte e desça até os tríceps encostarem no chão, cotovelos a cerca de 45° do tronco. Faça uma pausa breve."},{"title":"Empurrar","text":"Empurre a barra até estender os braços, sem quicar os cotovelos no chão. Mantenha as escápulas juntas."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"chest":0.45,"triceps":0.4,"front_delts":0.15}'::jsonb, 150),
  ('dumbbell-bench-press', '{"en":"Dumbbell Bench Press","de":"Kurzhantel-Bankdrücken","pt-PT":"Supino plano com halteres","pt-BR":"Supino reto com halteres"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Sit on a flat bench with the dumbbells on your thighs, then lie back and bring them up over your chest."},{"title":"Lower","text":"Lower the dumbbells to the sides of your chest, elbows about 45° from your torso and wrists stacked over them."},{"title":"Press","text":"Press up and slightly inward until your arms are almost straight. Don''t clank the dumbbells together at the top."}],"de":[{"title":"Aufbauen","text":"Setz dich mit den Kurzhanteln auf den Oberschenkeln auf die Flachbank, leg dich zurück und bring sie über die Brust."},{"title":"Absenken","text":"Senk die Hanteln seitlich neben die Brust. Die Ellbogen zeigen etwa 45° vom Oberkörper weg, die Handgelenke bleiben darüber."},{"title":"Drücken","text":"Drück die Hanteln nach oben und leicht zusammen, bis die Arme fast gestreckt sind. Oben nicht aneinanderschlagen."}],"pt-PT":[{"title":"Preparação","text":"Senta-te num banco plano com os halteres apoiados nas coxas, deita-te e leva-os para cima do peito."},{"title":"Descida","text":"Desce os halteres até aos lados do peito, cotovelos a cerca de 45° do tronco e pulsos alinhados por cima deles."},{"title":"Empurrar","text":"Empurra para cima e ligeiramente para dentro até os braços ficarem quase esticados. Não batas com os halteres um no outro."}],"pt-BR":[{"title":"Preparação","text":"Sente em um banco reto com os halteres apoiados nas coxas, deite e leve-os para cima do peito."},{"title":"Descida","text":"Desça os halteres até as laterais do peito, cotovelos a cerca de 45° do tronco e punhos alinhados sobre eles."},{"title":"Empurrar","text":"Empurre para cima e levemente para dentro até os braços ficarem quase estendidos. Não bata um halter no outro em cima."}]}'::jsonb,
    'dumbbell', '{weight,reps}', '{"chest":0.65,"triceps":0.2,"front_delts":0.15}'::jsonb, 120),
  ('dumbbell-floor-press', '{"en":"Dumbbell Floor Press","de":"Bodendrücken mit Kurzhanteln","pt-PT":"Supino no chão com halteres","pt-BR":"Supino no chão com halteres"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Sit on the floor with the dumbbells on your thighs, then roll back and press them over your chest. Bend your knees, feet flat."},{"title":"Lower","text":"Lower the dumbbells until your upper arms rest on the floor, elbows about 45° from your torso. Pause for a second."},{"title":"Press","text":"Press the dumbbells back up over your chest without bouncing your elbows off the floor."}],"de":[{"title":"Aufbauen","text":"Setz dich mit den Kurzhanteln auf den Oberschenkeln auf den Boden, roll dich zurück und drück sie über die Brust. Knie gebeugt, Füße flach."},{"title":"Absenken","text":"Senk die Hanteln ab, bis die Oberarme auf dem Boden liegen. Ellbogen etwa 45° vom Oberkörper weg, eine Sekunde halten."},{"title":"Drücken","text":"Drück die Hanteln wieder über die Brust, ohne die Ellbogen vom Boden abfedern zu lassen."}],"pt-PT":[{"title":"Preparação","text":"Senta-te no chão com os halteres nas coxas, rola para trás e empurra-os por cima do peito. Joelhos fletidos, pés assentes."},{"title":"Descida","text":"Desce os halteres até os tríceps pousarem no chão, cotovelos a cerca de 45° do tronco. Faz uma pausa de um segundo."},{"title":"Empurrar","text":"Empurra os halteres de volta por cima do peito sem fazer ressaltar os cotovelos no chão."}],"pt-BR":[{"title":"Preparação","text":"Sente no chão com os halteres nas coxas, role para trás e empurre-os acima do peito. Joelhos flexionados, pés apoiados."},{"title":"Descida","text":"Desça os halteres até os tríceps apoiarem no chão, cotovelos a cerca de 45° do tronco. Faça uma pausa de um segundo."},{"title":"Empurrar","text":"Empurre os halteres de volta acima do peito sem quicar os cotovelos no chão."}]}'::jsonb,
    'dumbbell', '{weight,reps}', '{"chest":0.5,"triceps":0.35,"front_delts":0.15}'::jsonb, 90),
  ('smith-bench-press', '{"en":"Smith Machine Bench Press","de":"Bankdrücken an der Multipresse","pt-PT":"Supino plano na máquina Smith","pt-BR":"Supino reto no Smith"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Place a flat bench under the bar so it lines up with your lower chest. Set the safety stops just below chest height."},{"title":"Lower","text":"Grip slightly wider than shoulder width, rotate the bar off the hooks and lower it under control to your lower chest."},{"title":"Press","text":"Press the bar straight up until your arms are almost straight. Keep your shoulder blades back and glutes on the bench."}],"de":[{"title":"Aufbauen","text":"Stell eine Flachbank so unter die Multipresse, dass die Stange über deiner unteren Brust liegt. Sicherheitsstopper knapp unter Brusthöhe."},{"title":"Absenken","text":"Greif etwas breiter als schulterbreit, dreh die Stange aus den Haken und senk sie kontrolliert zur unteren Brust."},{"title":"Drücken","text":"Drück die Stange gerade nach oben, bis die Arme fast gestreckt sind. Schulterblätter bleiben zusammen, Gesäß auf der Bank."}],"pt-PT":[{"title":"Preparação","text":"Coloca um banco plano por baixo da máquina Smith, com a barra alinhada com a parte inferior do peito. Ajusta os batentes um pouco abaixo do peito."},{"title":"Descida","text":"Agarra a barra com as mãos um pouco mais afastadas do que os ombros, solta-a dos ganchos e desce-a devagar até à parte inferior do peito."},{"title":"Empurrar","text":"Empurra a barra a direito para cima até os braços ficarem quase esticados. Mantém as omoplatas juntas e os glúteos no banco."}],"pt-BR":[{"title":"Preparação","text":"Coloque um banco reto embaixo do Smith, com a barra alinhada com a parte baixa do peito. Ajuste as travas um pouco abaixo do peito."},{"title":"Descida","text":"Segure a barra com as mãos um pouco mais abertas que os ombros, solte-a dos ganchos e desça com controle até a parte baixa do peito."},{"title":"Empurrar","text":"Empurre a barra reto para cima até os braços ficarem quase estendidos. Mantenha as escápulas juntas e os glúteos no banco."}]}'::jsonb,
    'machine', '{weight,reps}', '{"chest":0.6,"triceps":0.25,"front_delts":0.15}'::jsonb, 120),
  ('chest-press-machine', '{"en":"Chest Press Machine","de":"Brustpresse","pt-PT":"Supino plano na máquina","pt-BR":"Supino reto na máquina"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Adjust the seat so the handles line up with your mid-chest. Sit with your back flat against the pad and feet on the floor."},{"title":"Press","text":"Press the handles forward until your arms are almost straight. Keep your shoulders back against the pad."},{"title":"Return","text":"Let the handles come back slowly until you feel a stretch in your chest. Don''t let the weights touch down."}],"de":[{"title":"Einstellen","text":"Stell den Sitz so ein, dass die Griffe auf Höhe der mittleren Brust sind. Rücken flach an die Lehne, Füße auf den Boden."},{"title":"Drücken","text":"Drück die Griffe nach vorne, bis die Arme fast gestreckt sind. Die Schultern bleiben hinten an der Lehne."},{"title":"Zurück","text":"Lass die Griffe langsam zurückkommen, bis du eine Dehnung in der Brust spürst. Die Gewichte setzen dabei nicht auf."}],"pt-PT":[{"title":"Preparação","text":"Ajusta o assento para as pegas ficarem à altura do meio do peito. Encosta bem as costas e apoia os pés no chão."},{"title":"Empurrar","text":"Empurra as pegas para a frente até os braços ficarem quase esticados. Mantém os ombros para trás, contra o encosto."},{"title":"Voltar","text":"Deixa as pegas voltarem devagar até sentires o peito alongar, sem pousar as placas."}],"pt-BR":[{"title":"Preparação","text":"Ajuste o banco para os pegadores ficarem na altura do meio do peito. Apoie bem as costas no encosto e os pés no chão."},{"title":"Empurrar","text":"Empurre os pegadores para a frente até os braços ficarem quase estendidos. Mantenha os ombros para trás, contra o encosto."},{"title":"Voltar","text":"Deixe os pegadores voltarem devagar até sentir o peito alongar, sem encostar as placas."}]}'::jsonb,
    'machine', '{weight,reps}', '{"chest":0.65,"triceps":0.2,"front_delts":0.15}'::jsonb, 90),
  ('cable-chest-press', '{"en":"Standing Cable Chest Press","de":"Brustpresse am Kabel","pt-PT":"Supino em pé com cabos","pt-BR":"Supino em pé na polia"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Set both pulleys at chest height, take a handle in each hand and step forward into a split stance, facing away."},{"title":"Press","text":"Press the handles forward and slightly together until your arms are almost straight. Keep your torso still."},{"title":"Return","text":"Let your hands come back slowly to chest level until you feel a stretch. Don''t let the cables pull you backwards."}],"de":[{"title":"Aufbauen","text":"Stell beide Seilzüge auf Brusthöhe, nimm je einen Griff und geh mit dem Rücken zum Kabelzug in eine Schrittstellung."},{"title":"Drücken","text":"Drück die Griffe nach vorne und leicht zusammen, bis die Arme fast gestreckt sind. Der Oberkörper bleibt ruhig."},{"title":"Zurück","text":"Führ die Hände langsam bis auf Brusthöhe zurück, bis du eine Dehnung spürst. Lass dich nicht von den Kabeln nach hinten ziehen."}],"pt-PT":[{"title":"Preparação","text":"Coloca as duas polias à altura do peito, segura uma pega em cada mão e dá um passo em frente, de costas para a máquina."},{"title":"Empurrar","text":"Empurra as pegas para a frente e ligeiramente para dentro até os braços ficarem quase esticados. Mantém o tronco imóvel."},{"title":"Voltar","text":"Traz as mãos de volta devagar até à altura do peito, até sentires o peito alongar. Não deixes os cabos puxarem-te para trás."}],"pt-BR":[{"title":"Preparação","text":"Ajuste as duas polias na altura do peito, segure um pegador em cada mão e dê um passo à frente, de costas para o aparelho."},{"title":"Empurrar","text":"Empurre os pegadores para a frente e levemente para dentro até os braços ficarem quase estendidos. Mantenha o tronco parado."},{"title":"Voltar","text":"Traga as mãos de volta devagar até a altura do peito, até sentir o peito alongar. Não deixe os cabos puxarem você para trás."}]}'::jsonb,
