  ('smith-incline-bench-press', '{"en":"Smith Machine Incline Bench Press","de":"Schrägbankdrücken an der Multipresse","pt-PT":"Supino inclinado na máquina Smith","pt-BR":"Supino inclinado no Smith"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Place an incline bench at 30–45° under the bar so it lines up with your upper chest. Set the safety stops just below chest height."},{"title":"Lower","text":"Rotate the bar off the hooks and lower it under control to your upper chest, just below your collarbones."},{"title":"Press","text":"Press the bar straight up until your arms are almost straight. Keep your shoulder blades back against the bench."}],"de":[{"title":"Aufbauen","text":"Stell eine Schrägbank auf 30–45° so unter die Multipresse, dass die Stange über der oberen Brust liegt. Sicherheitsstopper knapp unter Brusthöhe."},{"title":"Absenken","text":"Dreh die Stange aus den Haken und senk sie kontrolliert zur oberen Brust, knapp unter die Schlüsselbeine."},{"title":"Drücken","text":"Drück die Stange gerade nach oben, bis die Arme fast gestreckt sind. Die Schulterblätter bleiben hinten an der Bank."}],"pt-PT":[{"title":"Preparação","text":"Coloca um banco inclinado a 30–45° por baixo da máquina Smith, com a barra alinhada com a parte superior do peito. Ajusta os batentes um pouco abaixo do peito."},{"title":"Descida","text":"Roda a barra para a soltar dos ganchos e desce-a de forma controlada até à parte superior do peito, logo abaixo das clavículas."},{"title":"Empurrar","text":"Empurra a barra a direito para cima até os braços ficarem quase esticados. Mantém as omoplatas encostadas ao banco."}],"pt-BR":[{"title":"Preparação","text":"Coloque um banco inclinado entre 30 e 45° embaixo do Smith, com a barra alinhada com a parte alta do peito. Ajuste as travas um pouco abaixo do peito."},{"title":"Descida","text":"Gire a barra para soltar dos ganchos e desça com controle até a parte alta do peito, logo abaixo das clavículas."},{"title":"Empurrar","text":"Empurre a barra reto para cima até os braços ficarem quase estendidos. Mantenha as escápulas apoiadas no banco."}]}'::jsonb,
