  ('dumbbell-fly', '{"en":"Dumbbell Fly","de":"Kurzhantel-Flys","pt-PT":"Aberturas com halteres","pt-BR":"Crucifixo reto"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Lie on a flat bench and press the dumbbells over your chest, palms facing each other, elbows slightly bent."},{"title":"Open","text":"Lower the weights out to the sides in a wide arc until you feel a stretch in your chest. Keep the elbow bend fixed."},{"title":"Bring together","text":"Bring the dumbbells back up along the same arc, as if hugging a tree, and stop just before they touch."}],"de":[{"title":"Aufbauen","text":"Leg dich auf die Flachbank und drück die Kurzhanteln über die Brust. Handflächen zueinander, Ellbogen leicht gebeugt."},{"title":"Öffnen","text":"Senk die Hanteln in einem weiten Bogen seitlich ab, bis du eine Dehnung in der Brust spürst. Der Ellbogenwinkel bleibt gleich."},{"title":"Zusammenführen","text":"Führ die Hanteln im selben Bogen wieder nach oben, als würdest du einen Baum umarmen. Stopp, kurz bevor sie sich berühren."}],"pt-PT":[{"title":"Preparação","text":"Deita-te num banco plano e empurra os halteres por cima do peito, palmas viradas uma para a outra e cotovelos ligeiramente fletidos."},{"title":"Abrir","text":"Desce os pesos para os lados num arco largo até sentires o peito alongar. Mantém o mesmo ângulo nos cotovelos."},{"title":"Juntar","text":"Sobe os halteres pelo mesmo arco, como se abraçasses uma árvore, e para pouco antes de se tocarem."}],"pt-BR":[{"title":"Preparação","text":"Deite em um banco reto e empurre os halteres acima do peito, palmas voltadas uma para a outra e cotovelos levemente flexionados."},{"title":"Abrir","text":"Desça os pesos para os lados em um arco amplo até sentir o peito alongar. Mantenha o mesmo ângulo nos cotovelos."},{"title":"Juntar","text":"Suba os halteres pelo mesmo arco, como se abraçasse uma árvore, e pare pouco antes de eles se encostarem."}]}'::jsonb,
