    '{"en":[{"title":"Set up","text":"Set the bench to 30–45°, lie back and press the dumbbells over your upper chest, palms facing each other."},{"title":"Open","text":"Lower the weights out to the sides in a wide arc, elbows slightly bent, until you feel a stretch in your upper chest."},{"title":"Bring together","text":"Sweep the dumbbells back up over your upper chest along the same arc. Keep your shoulders down and back."}],"de":[{"title":"Aufbauen","text":"Stell die Bank auf 30–45°, leg dich zurück und drück die Kurzhanteln über die obere Brust, Handflächen zueinander."},{"title":"Öffnen","text":"Senk die Hanteln mit leicht gebeugten Ellbogen in einem weiten Bogen seitlich ab, bis du die Dehnung in der oberen Brust spürst."},{"title":"Zusammenführen","text":"Führ die Hanteln im selben Bogen zurück über die obere Brust. Die Schultern bleiben unten und hinten."}],"pt-PT":[{"title":"Preparação","text":"Coloca o banco a 30–45°, deita-te e empurra os halteres por cima da parte superior do peito, palmas viradas uma para a outra."},{"title":"Abrir","text":"Com os cotovelos ligeiramente fletidos, desce os pesos para os lados num arco largo até sentires a parte superior do peito alongar."},{"title":"Juntar","text":"Leva os halteres de volta por cima do peito pelo mesmo arco. Mantém os ombros em baixo e para trás."}],"pt-BR":[{"title":"Preparação","text":"Ajuste o banco entre 30 e 45°, deite e empurre os halteres acima da parte alta do peito, palmas voltadas uma para a outra."},{"title":"Abrir","text":"Com os cotovelos levemente flexionados, desça os pesos para os lados em um arco amplo até sentir a parte alta do peito alongar."},{"title":"Juntar","text":"Leve os halteres de volta acima do peito pelo mesmo arco. Mantenha os ombros para baixo e para trás."}]}'::jsonb,
    'dumbbell', '{weight,reps}', '{"chest":0.8,"front_delts":0.2}'::jsonb, 75),
  ('dumbbell-pullover', '{"en":"Dumbbell Pullover","de":"Überzüge mit Kurzhantel","pt-PT":"Pullover com halter","pt-BR":"Pullover com halter"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Lie on a flat bench and hold one dumbbell over your chest with both hands cupping the top plate, elbows slightly bent."},{"title":"Lower","text":"Lower the dumbbell back behind your head in an arc until you feel a stretch in your chest and lats."},{"title":"Pull","text":"Pull the dumbbell back over your chest along the same arc. Keep your ribs down so your lower back doesn''t arch."}],"de":[{"title":"Aufbauen","text":"Leg dich auf die Flachbank und halte eine Kurzhantel mit beiden Händen an der oberen Scheibe über der Brust, Ellbogen leicht gebeugt."},{"title":"Absenken","text":"Senk die Hantel im Bogen hinter den Kopf, bis du eine Dehnung in Brust und Latissimus spürst."},{"title":"Zurückziehen","text":"Zieh die Hantel im selben Bogen zurück über die Brust. Rippen unten lassen, damit du nicht ins Hohlkreuz gehst."}],"pt-PT":[{"title":"Preparação","text":"Deita-te num banco plano e segura um halter por cima do peito com as duas mãos no disco de cima, cotovelos ligeiramente fletidos."},{"title":"Descida","text":"Leva o halter para trás da cabeça em arco até sentires o peito e os dorsais alongarem."},{"title":"Puxar","text":"Puxa o halter de volta por cima do peito pelo mesmo arco. Mantém as costelas em baixo para não arqueares a lombar."}],"pt-BR":[{"title":"Preparação","text":"Deite em um banco reto e segure um halter acima do peito com as duas mãos na anilha de cima, cotovelos levemente flexionados."},{"title":"Descida","text":"Leve o halter para trás da cabeça em arco até sentir o peito e o dorsal alongarem."},{"title":"Puxar","text":"Puxe o halter de volta acima do peito pelo mesmo arco. Mantenha as costelas para baixo para não arquear a lombar."}]}'::jsonb,
    'dumbbell', '{weight,reps}', '{"chest":0.55,"lats":0.35,"triceps":0.1}'::jsonb, 75),
  ('knee-push-up', '{"en":"Knee Push-Up","de":"Liegestütz auf den Knien","pt-PT":"Flexão com joelhos apoiados","pt-BR":"Flexão de braço com joelhos apoiados"}'::jsonb,
    '{"en":[{"title":"Plank","text":"Kneel with your hands on the floor slightly wider than your shoulders. Form a straight line from head to knees."},{"title":"Lower","text":"Lower your chest towards the floor, elbows about 45° from your torso. Keep your hips in line, not pushed back."},{"title":"Push","text":"Push the floor away until your arms are straight. Keep your abs tight so your lower back doesn''t sag."}],"de":[{"title":"Stütz","text":"Knie dich hin, die Hände etwas breiter als schulterbreit am Boden. Der Körper bildet eine Linie von Kopf bis Knie."},{"title":"Absenken","text":"Senk die Brust Richtung Boden, die Ellbogen etwa 45° vom Oberkörper weg. Die Hüfte bleibt in der Linie und geht nicht nach hinten."},{"title":"Drücken","text":"Drück dich vom Boden weg, bis die Arme gestreckt sind. Bauch fest, damit der untere Rücken nicht durchhängt."}],"pt-PT":[{"title":"Prancha","text":"Apoia os joelhos e as mãos no chão, mãos um pouco mais afastadas do que os ombros. Corpo em linha reta da cabeça aos joelhos."},{"title":"Descida","text":"Desce o peito em direção ao chão, cotovelos a cerca de 45° do tronco. A anca fica alinhada, sem recuar."},{"title":"Empurrar","text":"Empurra o chão até os braços ficarem esticados. Contrai o abdómen para a lombar não descair."}],"pt-BR":[{"title":"Prancha","text":"Apoie os joelhos e as mãos no chão, mãos um pouco mais abertas que os ombros. Corpo em linha reta da cabeça aos joelhos."},{"title":"Descida","text":"Desça o peito em direção ao chão, cotovelos a cerca de 45° do tronco. O quadril fica alinhado, sem ir para trás."},{"title":"Empurrar","text":"Empurre o chão até estender os braços. Contraia o abdômen para a lombar não cair."}]}'::jsonb,
    'bodyweight', '{reps}', '{"chest":0.55,"triceps":0.25,"front_delts":0.2}'::jsonb, 60),
  ('incline-push-up', '{"en":"Incline Push-Up","de":"Liegestütz erhöht","pt-PT":"Flexão inclinada","pt-BR":"Flexão de braço inclinada"}'::jsonb,
    '{"en":[{"title":"Plank","text":"Place your hands on a bench, box or bar slightly wider than your shoulders. Walk your feet back until your body is straight."},{"title":"Lower","text":"Lower your chest towards the edge, elbows about 45° from your torso. Keep one straight line from head to heels."},{"title":"Push","text":"Push away until your arms are straight. Use a lower surface over time to make it harder."}],"de":[{"title":"Stütz","text":"Setz die Hände etwas breiter als schulterbreit auf eine Bank, Box oder Stange. Geh mit den Füßen zurück, bis dein Körper gerade ist."},{"title":"Absenken","text":"Senk die Brust Richtung Kante, die Ellbogen etwa 45° vom Oberkörper weg. Kopf bis Ferse bleiben in einer Linie."},{"title":"Drücken","text":"Drück dich weg, bis die Arme gestreckt sind. Nimm mit der Zeit eine niedrigere Unterlage, um es schwerer zu machen."}],"pt-PT":[{"title":"Prancha","text":"Apoia as mãos num banco, caixa ou barra, um pouco mais afastadas do que os ombros. Recua os pés até o corpo ficar em linha reta."},{"title":"Descida","text":"Desce o peito em direção ao apoio, cotovelos a cerca de 45° do tronco. Mantém o corpo alinhado da cabeça aos calcanhares."},{"title":"Empurrar","text":"Empurra até os braços ficarem esticados. Com o tempo, usa um apoio mais baixo para tornar o exercício mais difícil."}],"pt-BR":[{"title":"Prancha","text":"Apoie as mãos em um banco, caixote ou barra, um pouco mais abertas que os ombros. Afaste os pés até o corpo ficar reto."},{"title":"Descida","text":"Desça o peito em direção ao apoio, cotovelos a cerca de 45° do tronco. Mantenha o corpo alinhado da cabeça aos calcanhares."},{"title":"Empurrar","text":"Empurre até estender os braços. Com o tempo, use um apoio mais baixo para deixar o exercício mais difícil."}]}'::jsonb,
    'bodyweight', '{reps}', '{"chest":0.6,"triceps":0.25,"front_delts":0.15}'::jsonb, 60),
  ('decline-push-up', '{"en":"Decline Push-Up","de":"Liegestütz mit erhöhten Füßen","pt-PT":"Flexão declinada","pt-BR":"Flexão de braço declinada"}'::jsonb,
    '{"en":[{"title":"Plank","text":"Put your feet on a bench or box and your hands on the floor slightly wider than your shoulders. Body straight from head to heels."},{"title":"Lower","text":"Lower your chest towards the floor, elbows about 45° from your torso. Keep your neck neutral and your hips from piking up."},{"title":"Push","text":"Push the floor away until your arms are straight. Brace your abs and glutes so your hips don''t sag."}],"de":[{"title":"Stütz","text":"Stell die Füße auf eine Bank oder Box, die Hände etwas breiter als schulterbreit am Boden. Körper gerade von Kopf bis Ferse."},{"title":"Absenken","text":"Senk die Brust Richtung Boden, die Ellbogen etwa 45° vom Oberkörper weg. Nacken neutral, Hüfte nicht nach oben schieben."},{"title":"Drücken","text":"Drück dich vom Boden weg, bis die Arme gestreckt sind. Spann Bauch und Gesäß an, damit die Hüfte nicht durchhängt."}],"pt-PT":[{"title":"Prancha","text":"Põe os pés num banco ou caixa e as mãos no chão, um pouco mais afastadas do que os ombros. Corpo em linha reta da cabeça aos calcanhares."},{"title":"Descida","text":"Desce o peito em direção ao chão, cotovelos a cerca de 45° do tronco. Pescoço neutro e anca sem subir."},{"title":"Empurrar","text":"Empurra o chão até os braços ficarem esticados. Contrai o abdómen e os glúteos para a anca não descair."}],"pt-BR":[{"title":"Prancha","text":"Coloque os pés em um banco ou caixote e as mãos no chão, um pouco mais abertas que os ombros. Corpo reto da cabeça aos calcanhares."},{"title":"Descida","text":"Desça o peito em direção ao chão, cotovelos a cerca de 45° do tronco. Pescoço neutro e quadril sem subir."},{"title":"Empurrar","text":"Empurre o chão até estender os braços. Contraia abdômen e glúteos para o quadril não cair."}]}'::jsonb,
    'bodyweight', '{reps}', '{"chest":0.5,"front_delts":0.3,"triceps":0.2}'::jsonb, 90),
  ('deficit-push-up', '{"en":"Deficit Push-Up","de":"Defizit-Liegestütz","pt-PT":"Flexão em défice","pt-BR":"Flexão de braço com déficit"}'::jsonb,
    '{"en":[{"title":"Plank","text":"Place your hands on two plates, blocks or push-up handles slightly wider than your shoulders. Body straight from head to heels."},{"title":"Lower","text":"Lower your chest below the level of your hands until you feel a deep stretch in your chest, elbows about 45° out."},{"title":"Push","text":"Push back up until your arms are straight. Only go as deep as your shoulders comfortably allow."}],"de":[{"title":"Stütz","text":"Setz die Hände etwas breiter als schulterbreit auf zwei Hantelscheiben, Blöcke oder Liegestützgriffe. Körper gerade von Kopf bis Ferse."},{"title":"Absenken","text":"Senk die Brust unter das Niveau der Hände, bis du eine tiefe Dehnung in der Brust spürst. Ellbogen etwa 45° vom Körper weg."},{"title":"Drücken","text":"Drück dich wieder hoch, bis die Arme gestreckt sind. Geh nur so tief, wie es für deine Schultern angenehm ist."}],"pt-PT":[{"title":"Prancha","text":"Apoia as mãos em dois discos, blocos ou pegas de flexões, um pouco mais afastadas do que os ombros. Corpo em linha reta."},{"title":"Descida","text":"Desce o peito abaixo do nível das mãos até sentires um alongamento profundo no peito, cotovelos a cerca de 45° do tronco."},{"title":"Empurrar","text":"Empurra até os braços ficarem esticados. Desce só até onde os ombros se sentirem confortáveis."}],"pt-BR":[{"title":"Prancha","text":"Apoie as mãos em duas anilhas, blocos ou apoios de flexão, um pouco mais abertas que os ombros. Corpo reto da cabeça aos calcanhares."},{"title":"Descida","text":"Desça o peito abaixo do nível das mãos até sentir um alongamento profundo no peito, cotovelos a cerca de 45° do tronco."},{"title":"Empurrar","text":"Empurre até estender os braços. Desça só até onde os ombros ficarem confortáveis."}]}'::jsonb,
    'bodyweight', '{reps}', '{"chest":0.6,"triceps":0.2,"front_delts":0.2}'::jsonb, 90),
  ('overhead-press', '{"en":"Overhead Press","de":"Schulterdrücken stehend","pt-PT":"Press militar","pt-BR":"Desenvolvimento militar"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Unrack the bar at your collarbones, hands just outside your shoulders, forearms vertical. Squeeze your glutes and abs."},{"title":"Press","text":"Press straight up, moving your head back to clear your chin, then bring your head through once the bar passes your forehead."},{"title":"Lower","text":"Lock out with the bar over your mid-foot, then lower it under control to your collarbones without leaning back."}],"de":[{"title":"Aufbauen","text":"Heb die Stange auf Höhe der Schlüsselbeine aus, Hände knapp außerhalb der Schultern, Unterarme senkrecht. Gesäß und Bauch fest."},{"title":"Drücken","text":"Drück gerade nach oben und nimm den Kopf kurz zurück. Sobald die Stange an der Stirn vorbei ist, schieb den Kopf wieder darunter."},{"title":"Absenken","text":"Streck die Arme mit der Stange über der Fußmitte durch und senk sie kontrolliert zu den Schlüsselbeinen, ohne dich zurückzulehnen."}],"pt-PT":[{"title":"Preparação","text":"Tira a barra do suporte à altura das clavículas, mãos logo por fora dos ombros e antebraços na vertical. Contrai os glúteos e o abdómen."},{"title":"Empurrar","text":"Empurra a direito para cima, recuando a cabeça para a barra passar o queixo. Quando passar a testa, volta a pôr a cabeça por baixo dela."},{"title":"Descida","text":"Estica os braços com a barra por cima do meio do pé e desce-a de forma controlada até às clavículas, sem inclinar o tronco para trás."}],"pt-BR":[{"title":"Preparação","text":"Tire a barra do suporte na altura das clavículas, mãos logo por fora dos ombros e antebraços na vertical. Contraia glúteos e abdômen."},{"title":"Empurrar","text":"Empurre reto para cima, recuando a cabeça para a barra passar pelo queixo. Quando ela passar da testa, leve a cabeça de volta para baixo da barra."},{"title":"Descida","text":"Estenda os braços com a barra acima do meio do pé e desça com controle até as clavículas, sem jogar o tronco para trás."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"front_delts":0.5,"triceps":0.25,"side_delts":0.15,"abs":0.1}'::jsonb, 150),
  ('seated-barbell-press', '{"en":"Seated Barbell Shoulder Press","de":"Schulterdrücken sitzend mit Langhantel","pt-PT":"Desenvolvimento sentado com barra","pt-BR":"Desenvolvimento sentado com barra"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Set an upright bench in a rack with the bar just below shoulder height when seated. Sit with your back against the pad."},{"title":"Press","text":"Unrack with your hands just outside your shoulders and press straight up, moving your head back slightly to let the bar pass."},{"title":"Lower","text":"Lower the bar under control to your upper chest. Keep your back against the pad without arching away from it."}],"de":[{"title":"Aufbauen","text":"Stell eine Bank mit senkrechter Lehne ins Rack, die Stange knapp unter Schulterhöhe im Sitzen. Setz dich mit dem Rücken an die Lehne."},{"title":"Drücken","text":"Heb die Stange mit den Händen knapp außerhalb der Schultern aus und drück sie gerade hoch. Nimm den Kopf leicht zurück, damit sie vorbeikommt."},{"title":"Absenken","text":"Senk die Stange kontrolliert zur oberen Brust. Der Rücken bleibt an der Lehne, kein Hohlkreuz."}],"pt-PT":[{"title":"Preparação","text":"Coloca um banco com encosto vertical no rack, com a barra um pouco abaixo da altura dos ombros na posição sentada. Encosta bem as costas."},{"title":"Empurrar","text":"Tira a barra com as mãos logo por fora dos ombros e empurra a direito para cima, recuando ligeiramente a cabeça para a barra passar."},{"title":"Descida","text":"Desce a barra de forma controlada até à parte superior do peito. Mantém as costas no encosto, sem arquear a lombar."}],"pt-BR":[{"title":"Preparação","text":"Coloque um banco com encosto vertical no rack, com a barra um pouco abaixo da altura dos ombros na posição sentada. Apoie bem as costas."},{"title":"Empurrar","text":"Tire a barra com as mãos logo por fora dos ombros e empurre reto para cima, recuando a cabeça levemente para a barra passar."},{"title":"Descida","text":"Desça a barra com controle até a parte alta do peito. Mantenha as costas no encosto, sem arquear a lombar."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"front_delts":0.55,"triceps":0.25,"side_delts":0.2}'::jsonb, 120),
  ('behind-the-neck-press', '{"en":"Behind-the-Neck Press","de":"Nackendrücken","pt-PT":"Press atrás da nuca","pt-BR":"Desenvolvimento atrás da nuca"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Sit or stand with the bar resting on your upper back as for a squat, hands slightly wider than for an overhead press."},{"title":"Press","text":"Press the bar straight up from behind your head until your arms are locked out. Keep your head neutral, chin slightly tucked."},{"title":"Lower","text":"Lower the bar slowly to about ear height. Use a light weight and skip this exercise if your shoulders feel pinched."}],"de":[{"title":"Aufbauen","text":"Setz oder stell dich hin, die Stange liegt wie bei der Kniebeuge auf dem oberen Rücken. Greif etwas breiter als beim Schulterdrücken."},{"title":"Drücken","text":"Drück die Stange hinter dem Kopf gerade nach oben, bis die Arme gestreckt sind. Kopf neutral, Kinn leicht eingezogen."},{"title":"Absenken","text":"Senk die Stange langsam bis etwa auf Ohrhöhe. Nimm wenig Gewicht und lass die Übung weg, wenn es in der Schulter zwickt."}],"pt-PT":[{"title":"Preparação","text":"Senta-te ou fica de pé com a barra apoiada na parte superior das costas, como no agachamento, e as mãos um pouco mais afastadas do que no press militar."},{"title":"Empurrar","text":"Empurra a barra a direito para cima por trás da cabeça até esticar os braços. Cabeça neutra, queixo ligeiramente recolhido."},{"title":"Descida","text":"Desce a barra devagar até mais ou menos à altura das orelhas. Usa pouco peso e evita o exercício se sentires desconforto nos ombros."}],"pt-BR":[{"title":"Preparação","text":"Sente ou fique em pé com a barra apoiada na parte de cima das costas, como no agachamento, e as mãos um pouco mais abertas que no desenvolvimento militar."},{"title":"Empurrar","text":"Empurre a barra reto para cima por trás da cabeça até estender os braços. Cabeça neutra, queixo levemente recolhido."},{"title":"Descida","text":"Desça a barra devagar até mais ou menos a altura das orelhas. Use pouco peso e evite o exercício se sentir incômodo nos ombros."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"front_delts":0.45,"side_delts":0.3,"triceps":0.25}'::jsonb, 120),
  ('z-press', '{"en":"Z Press","de":"Z-Press","pt-PT":"Z press","pt-BR":"Z press"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Sit on the floor in a rack with your legs straight out in front of you. Set the hooks so you can unrack the bar at your collarbones."},{"title":"Brace","text":"Sit tall without leaning back and brace your abs hard. Nothing supports your back, so your trunk has to stay rigid."},{"title":"Press","text":"Press the bar straight up to lockout, moving your head back slightly to let it pass, then lower it under control."}],"de":[{"title":"Aufbauen","text":"Setz dich im Rack auf den Boden, die Beine gerade nach vorne gestreckt. Stell die Ablagen so ein, dass du die Stange auf Höhe der Schlüsselbeine aushebst."},{"title":"Anspannen","text":"Sitz aufrecht, ohne dich zurückzulehnen, und spann den Bauch fest an. Nichts stützt deinen Rücken, der Rumpf muss stabil bleiben."},{"title":"Drücken","text":"Drück die Stange gerade nach oben bis zur Streckung und nimm den Kopf dabei leicht zurück. Senk sie dann kontrolliert ab."}],"pt-PT":[{"title":"Preparação","text":"Senta-te no chão dentro do rack com as pernas esticadas à frente. Ajusta os suportes para tirares a barra à altura das clavículas."},{"title":"Contrair","text":"Senta-te direito, sem inclinar para trás, e contrai bem o abdómen. Nada apoia as costas, por isso o tronco tem de ficar firme."},{"title":"Empurrar","text":"Empurra a barra a direito para cima até esticar os braços, recuando ligeiramente a cabeça, e depois desce-a de forma controlada."}],"pt-BR":[{"title":"Preparação","text":"Sente no chão dentro do rack com as pernas estendidas à frente. Ajuste os suportes para tirar a barra na altura das clavículas."},{"title":"Contraia","text":"Sente com a coluna ereta, sem inclinar para trás, e contraia bem o abdômen. Nada apoia as costas, então o tronco precisa ficar firme."},{"title":"Empurrar","text":"Empurre a barra reto para cima até estender os braços, recuando a cabeça levemente, e depois desça com controle."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"front_delts":0.45,"triceps":0.25,"side_delts":0.15,"abs":0.15}'::jsonb, 120),
  ('push-press', '{"en":"Push Press","de":"Push Press","pt-PT":"Push press","pt-BR":"Push press"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Hold the bar on your collarbones, hands just outside your shoulders, feet hip-width apart. Brace your core."},{"title":"Dip and drive","text":"Dip a few centimetres by bending your knees with your torso upright, then drive up explosively through your legs."},{"title":"Press","text":"Use that momentum to press the bar to full lockout overhead. Lower it to your collarbones, cushioning it with your knees."}],"de":[{"title":"Aufbauen","text":"Die Stange liegt auf den Schlüsselbeinen, Hände knapp außerhalb der Schultern, Füße hüftbreit. Spann den Rumpf an."},{"title":"Schwung holen","text":"Geh mit aufrechtem Oberkörper ein paar Zentimeter in die Knie und streck die Beine dann explosiv."},{"title":"Drücken","text":"Nutz den Schwung und drück die Stange über dem Kopf ganz durch. Fang sie beim Absenken an den Schlüsselbeinen mit leicht gebeugten Knien ab."}],"pt-PT":[{"title":"Preparação","text":"Apoia a barra nas clavículas, mãos logo por fora dos ombros, pés à largura da anca. Contrai o abdómen."},{"title":"Impulso","text":"Flete os joelhos uns centímetros com o tronco direito e depois estende as pernas de forma explosiva."},{"title":"Empurrar","text":"Aproveita o impulso para empurrar a barra até esticar os braços acima da cabeça. Desce-a até às clavículas, amortecendo com os joelhos."}],"pt-BR":[{"title":"Preparação","text":"Apoie a barra nas clavículas, mãos logo por fora dos ombros, pés na largura do quadril. Contraia o abdômen."},{"title":"Impulso","text":"Flexione os joelhos alguns centímetros com o tronco reto e depois estenda as pernas de forma explosiva."},{"title":"Empurrar","text":"Aproveite o impulso para empurrar a barra até estender os braços acima da cabeça. Desça até as clavículas, amortecendo com os joelhos."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"front_delts":0.45,"triceps":0.3,"quads":0.15,"glutes":0.1}'::jsonb, 150),
  ('single-arm-dumbbell-press', '{"en":"Single-Arm Dumbbell Shoulder Press","de":"Kurzhantel-Schulterdrücken einarmig","pt-PT":"Desenvolvimento unilateral com halter","pt-BR":"Desenvolvimento unilateral com halter"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Stand or sit tall with one dumbbell at shoulder height, wrist stacked over your elbow. Brace your abs and glutes."},{"title":"Press","text":"Press the dumbbell straight up until your arm is fully extended. Don''t lean away to the other side."},{"title":"Lower","text":"Lower the weight back to shoulder height under control. Finish all reps on one side, then switch."}],"de":[{"title":"Aufbauen","text":"Steh oder sitz aufrecht, eine Kurzhantel auf Schulterhöhe, Handgelenk über dem Ellbogen. Bauch und Gesäß anspannen."},{"title":"Drücken","text":"Drück die Hantel gerade nach oben, bis der Arm gestreckt ist. Lehn dich dabei nicht zur anderen Seite."},{"title":"Absenken","text":"Senk die Hantel kontrolliert zurück auf Schulterhöhe. Mach alle Wiederholungen auf einer Seite, dann wechsle."}],"pt-PT":[{"title":"Preparação","text":"Fica de pé ou senta-te direito com um halter à altura do ombro, pulso alinhado sobre o cotovelo. Contrai o abdómen e os glúteos."},{"title":"Empurrar","text":"Empurra o halter a direito para cima até esticar o braço por completo. Não inclines o tronco para o outro lado."},{"title":"Descida","text":"Desce o peso de forma controlada até à altura do ombro. Faz todas as repetições de um lado e depois troca."}],"pt-BR":[{"title":"Preparação","text":"Fique em pé ou sente com a coluna ereta e um halter na altura do ombro, punho alinhado sobre o cotovelo. Contraia abdômen e glúteos."},{"title":"Empurrar","text":"Empurre o halter reto para cima até estender o braço por completo. Não incline o tronco para o outro lado."},{"title":"Descida","text":"Desça o peso com controle até a altura do ombro. Faça todas as repetições de um lado e depois troque."}]}'::jsonb,
    'dumbbell', '{weight,reps}', '{"front_delts":0.5,"side_delts":0.2,"triceps":0.2,"obliques":0.1}'::jsonb, 90),
  ('smith-shoulder-press', '{"en":"Smith Machine Shoulder Press","de":"Schulterdrücken an der Multipresse","pt-PT":"Desenvolvimento na máquina Smith","pt-BR":"Desenvolvimento no Smith"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Place an upright bench under the Smith machine so the bar travels just in front of your face. Sit with your back on the pad."},{"title":"Press","text":"Rotate the bar off the hooks, hands just outside your shoulders, and press up until your arms are almost straight."},{"title":"Lower","text":"Lower the bar under control to chin height or just below. Keep your back against the pad and your abs tight."}],"de":[{"title":"Aufbauen","text":"Stell eine Bank mit senkrechter Lehne so unter die Multipresse, dass die Stange knapp vor deinem Gesicht läuft. Rücken an die Lehne."},{"title":"Drücken","text":"Dreh die Stange aus den Haken, Hände knapp außerhalb der Schultern, und drück nach oben, bis die Arme fast gestreckt sind."},{"title":"Absenken","text":"Senk die Stange kontrolliert bis etwa auf Kinnhöhe oder knapp darunter. Rücken an der Lehne, Bauch fest."}],"pt-PT":[{"title":"Preparação","text":"Coloca um banco com encosto vertical por baixo da máquina Smith, de forma que a barra passe mesmo à frente da cara. Encosta as costas."},{"title":"Empurrar","text":"Roda a barra para a soltar dos ganchos, mãos logo por fora dos ombros, e empurra até os braços ficarem quase esticados."},{"title":"Descida","text":"Desce a barra de forma controlada até à altura do queixo ou um pouco abaixo. Mantém as costas encostadas e o abdómen contraído."}],"pt-BR":[{"title":"Preparação","text":"Coloque um banco com encosto vertical embaixo do Smith, de modo que a barra passe logo à frente do rosto. Apoie as costas no encosto."},{"title":"Empurrar","text":"Gire a barra para soltar dos ganchos, mãos logo por fora dos ombros, e empurre até os braços ficarem quase estendidos."},{"title":"Descida","text":"Desça a barra com controle até a altura do queixo ou um pouco abaixo. Mantenha as costas apoiadas e o abdômen contraído."}]}'::jsonb,
    'machine', '{weight,reps}', '{"front_delts":0.55,"triceps":0.3,"side_delts":0.15}'::jsonb, 120),
  ('landmine-press', '{"en":"Landmine Press","de":"Landmine Press","pt-PT":"Landmine press","pt-BR":"Landmine press"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Wedge one end of a barbell into a landmine or a corner. Hold the other end at shoulder height in one hand, feet staggered."},{"title":"Press","text":"Press the bar up and forward until your arm is straight, letting your shoulder blade glide forward at the top."},{"title":"Lower","text":"Lower the bar back to your shoulder under control. Keep your hips square and don''t lean back."}],"de":[{"title":"Aufbauen","text":"Steck ein Ende der Langhantel in eine Landmine oder klemm es in eine Ecke. Halte das andere Ende mit einer Hand auf Schulterhöhe, Füße versetzt."},{"title":"Drücken","text":"Drück die Stange nach oben und vorne, bis der Arm gestreckt ist. Lass das Schulterblatt oben mit nach vorne gleiten."},{"title":"Absenken","text":"Führ die Stange kontrolliert zurück zur Schulter. Die Hüfte bleibt gerade, nicht nach hinten lehnen."}],"pt-PT":[{"title":"Preparação","text":"Encaixa uma ponta da barra num landmine ou num canto. Segura a outra ponta à altura do ombro com uma mão, com um pé à frente do outro."},{"title":"Empurrar","text":"Empurra a barra para cima e para a frente até esticar o braço, deixando a omoplata deslizar para a frente no fim."},{"title":"Descida","text":"Traz a barra de volta ao ombro de forma controlada. Mantém a anca virada para a frente e não inclines o tronco para trás."}],"pt-BR":[{"title":"Preparação","text":"Encaixe uma ponta da barra em um landmine ou em um canto. Segure a outra ponta na altura do ombro com uma mão, com um pé à frente do outro."},{"title":"Empurrar","text":"Empurre a barra para cima e para a frente até estender o braço, deixando a escápula deslizar para a frente no final."},{"title":"Descida","text":"Traga a barra de volta ao ombro com controle. Mantenha o quadril de frente e não incline o tronco para trás."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"front_delts":0.45,"chest":0.25,"triceps":0.2,"obliques":0.1}'::jsonb, 90),
  ('pike-push-up', '{"en":"Pike Push-Up","de":"Pike-Liegestütz","pt-PT":"Flexão pike","pt-BR":"Flexão pike"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Start in a push-up position, then walk your feet in and raise your hips so your body forms an upside-down V."},{"title":"Lower","text":"Bend your elbows and lower the top of your head towards the floor just in front of your hands. Elbows point back, not out."},{"title":"Push","text":"Push back up until your arms are straight, keeping your hips high. Put your feet on a box to make it harder."}],"de":[{"title":"Aufbauen","text":"Geh in die Liegestützposition, geh mit den Füßen Richtung Hände und schieb die Hüfte hoch, bis dein Körper ein umgedrehtes V bildet."},{"title":"Absenken","text":"Beug die Ellbogen und senk den Kopf Richtung Boden, knapp vor den Händen. Die Ellbogen zeigen nach hinten, nicht zur Seite."},{"title":"Drücken","text":"Drück dich wieder hoch, bis die Arme gestreckt sind, die Hüfte bleibt oben. Mit den Füßen auf einer Box wird es schwerer."}],"pt-PT":[{"title":"Preparação","text":"Começa na posição de flexão, aproxima os pés das mãos e sobe a anca até o corpo formar um V invertido."},{"title":"Descida","text":"Flete os cotovelos e desce o topo da cabeça em direção ao chão, um pouco à frente das mãos. Cotovelos para trás, não para os lados."},{"title":"Empurrar","text":"Empurra até os braços ficarem esticados, mantendo a anca alta. Para dificultar, põe os pés numa caixa."}],"pt-BR":[{"title":"Preparação","text":"Comece na posição de flexão, aproxime os pés das mãos e suba o quadril até o corpo formar um V invertido."},{"title":"Descida","text":"Flexione os cotovelos e desça o topo da cabeça em direção ao chão, um pouco à frente das mãos. Cotovelos para trás, não para os lados."},{"title":"Empurrar","text":"Empurre até estender os braços, mantendo o quadril alto. Para dificultar, apoie os pés em um caixote."}]}'::jsonb,
    'bodyweight', '{reps}', '{"front_delts":0.55,"triceps":0.3,"side_delts":0.15}'::jsonb, 90),
  ('cable-lateral-raise', '{"en":"Cable Lateral Raise","de":"Seitheben am Kabel","pt-PT":"Elevação lateral no cabo","pt-BR":"Elevação lateral na polia"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Set a pulley at the lowest position and stand side-on to it. Hold the handle in your far hand in front of your thigh."},{"title":"Raise","text":"Lift your arm out to the side up to shoulder height, leading with your elbow and keeping a slight bend in it."},{"title":"Lower","text":"Lower slowly over two to three seconds, letting your hand drift in front of your body to keep the tension on."}],"de":[{"title":"Aufbauen","text":"Stell einen Seilzug ganz nach unten und stell dich seitlich daneben. Nimm den Griff in die äußere Hand, vor dem Oberschenkel."},{"title":"Heben","text":"Heb den Arm seitlich bis auf Schulterhöhe. Der Ellbogen führt und bleibt leicht gebeugt."},{"title":"Absenken","text":"Senk den Arm über zwei bis drei Sekunden ab und lass die Hand leicht vor den Körper wandern, damit die Spannung bleibt."}],"pt-PT":[{"title":"Preparação","text":"Coloca uma polia na posição mais baixa e fica de lado para ela. Segura a pega com a mão mais afastada, à frente da coxa."},{"title":"Elevar","text":"Eleva o braço para o lado até à altura do ombro, conduzindo com o cotovelo ligeiramente fletido."},{"title":"Descida","text":"Desce devagar, em dois a três segundos, deixando a mão passar à frente do corpo para manter a tensão."}],"pt-BR":[{"title":"Preparação","text":"Ajuste uma polia na posição mais baixa e fique de lado para ela. Segure o pegador com a mão mais distante, na frente da coxa."},{"title":"Elevar","text":"Eleve o braço para o lado até a altura do ombro, conduzindo com o cotovelo levemente flexionado."},{"title":"Descida","text":"Desça devagar, em dois a três segundos, deixando a mão passar na frente do corpo para manter a tensão."}]}'::jsonb,
    'cable', '{weight,reps}', '{"side_delts":0.9,"traps":0.1}'::jsonb, 60),
  ('machine-lateral-raise', '{"en":"Machine Lateral Raise","de":"Seitheben an der Maschine","pt-PT":"Elevação lateral na máquina","pt-BR":"Elevação lateral na máquina"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Adjust the seat so your shoulders line up with the machine''s pivot points. Rest your arms against the pads."},{"title":"Raise","text":"Lift your arms out to the sides up to shoulder height, leading with your elbows. Don''t shrug."},{"title":"Lower","text":"Lower the pads slowly over two to three seconds and stop before the weights touch down."}],"de":[{"title":"Einstellen","text":"Stell den Sitz so ein, dass deine Schultern auf Höhe der Drehpunkte der Maschine sind. Leg die Arme an die Polster."},{"title":"Heben","text":"Heb die Arme seitlich bis auf Schulterhöhe, die Ellbogen führen. Schultern nicht hochziehen."},{"title":"Absenken","text":"Senk die Polster über zwei bis drei Sekunden ab und stopp, bevor die Gewichte aufsetzen."}],"pt-PT":[{"title":"Preparação","text":"Ajusta o assento para os ombros ficarem alinhados com os eixos da máquina. Apoia os braços nas almofadas."},{"title":"Elevar","text":"Eleva os braços para os lados até à altura dos ombros, conduzindo com os cotovelos. Não encolhas os ombros."},{"title":"Descida","text":"Desce as almofadas devagar, em dois a três segundos, e para antes de pousar as placas."}],"pt-BR":[{"title":"Preparação","text":"Ajuste o banco para os ombros ficarem alinhados com os eixos do aparelho. Apoie os braços nas almofadas."},{"title":"Elevar","text":"Eleve os braços para os lados até a altura dos ombros, conduzindo com os cotovelos. Não encolha os ombros."},{"title":"Descida","text":"Desça as almofadas devagar, em dois a três segundos, e pare antes de encostar as placas."}]}'::jsonb,
    'machine', '{weight,reps}', '{"side_delts":0.9,"traps":0.1}'::jsonb, 60),
  ('y-raise', '{"en":"Y-Raise","de":"Y-Raises","pt-PT":"Elevação em Y","pt-BR":"Elevação em Y"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Lie face down on an incline bench set to 30–45°, a light dumbbell in each hand, arms hanging and thumbs pointing up."},{"title":"Raise","text":"Raise your arms forward and out into a Y until they line up with your body. Keep your shoulders down, away from your ears."},{"title":"Lower","text":"Lower the dumbbells slowly back down. Use light weights, as the long lever makes this harder than it looks."}],"de":[{"title":"Aufbauen","text":"Leg dich bäuchlings auf eine Schrägbank mit 30–45°, in jeder Hand eine leichte Kurzhantel, Arme hängen, Daumen zeigen nach oben."},{"title":"Heben","text":"Heb die Arme schräg nach vorne oben in ein Y, bis sie in Linie mit dem Körper sind. Die Schultern bleiben unten, weg von den Ohren."},{"title":"Absenken","text":"Senk die Hanteln langsam wieder ab. Nimm wenig Gewicht, der lange Hebel macht die Übung schwerer, als sie aussieht."}],"pt-PT":[{"title":"Preparação","text":"Deita-te de barriga para baixo num banco inclinado a 30–45°, com um halter leve em cada mão, braços pendurados e polegares para cima."},{"title":"Elevar","text":"Eleva os braços para a frente e para fora em forma de Y até ficarem alinhados com o corpo. Ombros em baixo, longe das orelhas."},{"title":"Descida","text":"Desce os halteres devagar. Usa pouco peso, porque o braço esticado torna o exercício mais difícil do que parece."}],"pt-BR":[{"title":"Preparação","text":"Deite de bruços em um banco inclinado entre 30 e 45°, com um halter leve em cada mão, braços soltos e polegares para cima."},{"title":"Elevar","text":"Eleve os braços para a frente e para fora em forma de Y até ficarem alinhados com o corpo. Ombros para baixo, longe das orelhas."},{"title":"Descida","text":"Desça os halteres devagar. Use pouco peso, porque o braço estendido deixa o exercício mais difícil do que parece."}]}'::jsonb,
    'dumbbell', '{weight,reps}', '{"side_delts":0.45,"traps":0.35,"rear_delts":0.2}'::jsonb, 60),
  ('cable-front-raise', '{"en":"Cable Front Raise","de":"Frontheben am Kabel","pt-PT":"Elevação frontal no cabo","pt-BR":"Elevação frontal na polia"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Stand with your back to a low pulley, the cable running between your legs. Hold the handle or rope in front of your thighs."},{"title":"Raise","text":"With a slight bend in your elbows, lift your arms straight in front of you to shoulder height. Don''t lean back."},{"title":"Lower","text":"Lower slowly over two to three seconds and stop just before the weights touch down."}],"de":[{"title":"Aufbauen","text":"Stell dich mit dem Rücken zu einem tiefen Seilzug, das Kabel läuft zwischen deinen Beinen. Halte Griff oder Seil vor den Oberschenkeln."},{"title":"Heben","text":"Heb die Arme mit leicht gebeugten Ellbogen gerade nach vorne bis auf Schulterhöhe. Nicht nach hinten lehnen."},{"title":"Absenken","text":"Senk die Arme über zwei bis drei Sekunden ab und stopp, kurz bevor die Gewichte aufsetzen."}],"pt-PT":[{"title":"Preparação","text":"Fica de costas para uma polia baixa, com o cabo a passar entre as pernas. Segura a pega ou a corda à frente das coxas."},{"title":"Elevar","text":"Com os cotovelos ligeiramente fletidos, eleva os braços a direito à tua frente até à altura dos ombros. Não inclines o tronco para trás."},{"title":"Descida","text":"Desce devagar, em dois a três segundos, e para pouco antes de pousar as placas."}],"pt-BR":[{"title":"Preparação","text":"Fique de costas para uma polia baixa, com o cabo passando entre as pernas. Segure o pegador ou a corda na frente das coxas."},{"title":"Elevar","text":"Com os cotovelos levemente flexionados, eleve os braços retos à sua frente até a altura dos ombros. Não jogue o tronco para trás."},{"title":"Descida","text":"Desça devagar, em dois a três segundos, e pare pouco antes de encostar as placas."}]}'::jsonb,
    'cable', '{weight,reps}', '{"front_delts":0.85,"side_delts":0.15}'::jsonb, 60),
  ('cable-rear-delt-fly', '{"en":"Cable Rear Delt Fly","de":"Reverse Flys am Kabel","pt-PT":"Aberturas invertidas no cabo","pt-BR":"Crucifixo invertido na polia"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Set both pulleys at shoulder height. Hold the left cable in your right hand and the right cable in your left, then step back."},{"title":"Pull apart","text":"With slightly bent elbows, pull your arms out and back in a wide arc until they line up with your shoulders."},{"title":"Return","text":"Let your hands come back slowly until they cross in front of you. Don''t shrug or lean back."}],"de":[{"title":"Aufbauen","text":"Stell beide Seilzüge auf Schulterhöhe. Nimm das linke Kabel in die rechte Hand und das rechte in die linke und geh einen Schritt zurück."},{"title":"Auseinanderziehen","text":"Zieh die Arme mit leicht gebeugten Ellbogen in einem weiten Bogen nach außen und hinten, bis sie auf Schulterhöhe in einer Linie sind."},{"title":"Zurück","text":"Lass die Hände langsam zurückkommen, bis sie sich vor dir kreuzen. Schultern nicht hochziehen, nicht nach hinten lehnen."}],"pt-PT":[{"title":"Preparação","text":"Coloca as duas polias à altura dos ombros. Segura o cabo esquerdo com a mão direita e o direito com a esquerda e dá um passo atrás."},{"title":"Abrir","text":"Com os cotovelos ligeiramente fletidos, puxa os braços para fora e para trás num arco largo até ficarem alinhados com os ombros."},{"title":"Voltar","text":"Deixa as mãos voltarem devagar até se cruzarem à tua frente. Não encolhas os ombros nem te inclines para trás."}],"pt-BR":[{"title":"Preparação","text":"Ajuste as duas polias na altura dos ombros. Segure o cabo esquerdo com a mão direita e o direito com a esquerda e dê um passo para trás."},{"title":"Abrir","text":"Com os cotovelos levemente flexionados, puxe os braços para fora e para trás em um arco amplo até ficarem alinhados com os ombros."},{"title":"Voltar","text":"Deixe as mãos voltarem devagar até se cruzarem na sua frente. Não encolha os ombros nem incline o corpo para trás."}]}'::jsonb,
    'cable', '{weight,reps}', '{"rear_delts":0.8,"upper_back":0.2}'::jsonb, 60),
  ('reverse-pec-deck', '{"en":"Reverse Pec Deck","de":"Reverse Butterfly","pt-PT":"Aberturas invertidas na máquina","pt-BR":"Voador invertido"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Sit facing the chest pad and adjust the seat so the handles are at shoulder height. Grip them with your arms straight in front of you."},{"title":"Pull apart","text":"With slightly bent elbows, sweep your arms out and back until they line up with your torso. Keep your chest on the pad."},{"title":"Return","text":"Bring the handles forward slowly until your hands are in front of you again, without letting the weights touch down."}],"de":[{"title":"Einstellen","text":"Setz dich mit der Brust zum Polster und stell den Sitz so ein, dass die Griffe auf Schulterhöhe sind. Fass sie mit gestreckten Armen vor dir."},{"title":"Auseinanderziehen","text":"Führ die Arme mit leicht gebeugten Ellbogen nach außen und hinten, bis sie in Linie mit dem Oberkörper sind. Die Brust bleibt am Polster."},{"title":"Zurück","text":"Führ die Griffe langsam wieder nach vorne, bis die Hände vor dir sind, ohne dass die Gewichte aufsetzen."}],"pt-PT":[{"title":"Preparação","text":"Senta-te de frente para o encosto e ajusta o assento para as pegas ficarem à altura dos ombros. Agarra-as com os braços esticados à frente."},{"title":"Abrir","text":"Com os cotovelos ligeiramente fletidos, leva os braços para fora e para trás até ficarem alinhados com o tronco. Mantém o peito apoiado."},{"title":"Voltar","text":"Traz as pegas devagar para a frente até as mãos voltarem à tua frente, sem pousar as placas."}],"pt-BR":[{"title":"Preparação","text":"Sente de frente para o encosto e ajuste o banco para os pegadores ficarem na altura dos ombros. Segure-os com os braços estendidos à frente."},{"title":"Abrir","text":"Com os cotovelos levemente flexionados, leve os braços para fora e para trás até ficarem alinhados com o tronco. Mantenha o peito apoiado."},{"title":"Voltar","text":"Traga os pegadores devagar para a frente até as mãos voltarem à sua frente, sem encostar as placas."}]}'::jsonb,
    'machine', '{weight,reps}', '{"rear_delts":0.8,"upper_back":0.2}'::jsonb, 60),
  ('cable-upright-row', '{"en":"Cable Upright Row","de":"Aufrechtes Rudern am Kabel","pt-PT":"Remada alta no cabo","pt-BR":"Remada alta na polia"}'::jsonb,
    '{"en":[{"title":"Grip","text":"Attach a straight bar or rope to a low pulley. Stand close and hold it in front of your thighs, hands about shoulder-width apart."},{"title":"Pull","text":"Lead with your elbows and pull up to lower-chest height. Your elbows stay above your hands."},{"title":"Lower","text":"Lower under control and keep the cable taut at the bottom. Stop earlier if your shoulders feel pinched."}],"de":[{"title":"Griff","text":"Häng eine gerade Stange oder ein Seil an einen tiefen Seilzug. Stell dich nah davor und greif etwa schulterbreit vor den Oberschenkeln."},{"title":"Ziehen","text":"Die Ellbogen führen: Zieh bis auf Höhe der unteren Brust. Die Ellbogen bleiben über den Händen."},{"title":"Absenken","text":"Senk kontrolliert ab und halte unten die Spannung im Kabel. Hör früher auf, wenn es in der Schulter zwickt."}],"pt-PT":[{"title":"Pega","text":"Prende uma barra reta ou uma corda a uma polia baixa. Fica perto e segura-a à frente das coxas, com as mãos à largura dos ombros."},{"title":"Puxar","text":"Conduz com os cotovelos e puxa até à parte inferior do peito. Os cotovelos ficam acima das mãos."},{"title":"Descida","text":"Desce de forma controlada e mantém o cabo em tensão em baixo. Para mais cedo se sentires desconforto nos ombros."}],"pt-BR":[{"title":"Pegada","text":"Prenda uma barra reta ou uma corda em uma polia baixa. Fique perto e segure na frente das coxas, com as mãos na largura dos ombros."},{"title":"Puxar","text":"Conduza com os cotovelos e puxe até a parte baixa do peito. Os cotovelos ficam acima das mãos."},{"title":"Descida","text":"Desça com controle e mantenha o cabo tensionado embaixo. Pare antes se sentir incômodo nos ombros."}]}'::jsonb,
    'cable', '{weight,reps}', '{"side_delts":0.55,"traps":0.45}'::jsonb, 90),
  ('cable-external-rotation', '{"en":"Cable External Rotation","de":"Außenrotation am Kabel","pt-PT":"Rotação externa no cabo","pt-BR":"Rotação externa na polia"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Set a pulley at elbow height and stand side-on to it. Hold the handle in your far hand, elbow bent 90° and tucked to your side."},{"title":"Rotate","text":"Rotate your forearm outward, away from your stomach, as far as is comfortable. Keep your elbow pinned to your side."},{"title":"Return","text":"Let your forearm come back slowly across your stomach. Use a light weight and move smoothly without jerking."}],"de":[{"title":"Aufbauen","text":"Stell einen Seilzug auf Ellbogenhöhe und stell dich seitlich daneben. Nimm den Griff in die äußere Hand, Ellbogen 90° gebeugt und am Körper."},{"title":"Rotieren","text":"Dreh den Unterarm nach außen vom Bauch weg, so weit es angenehm ist. Der Ellbogen bleibt fest an der Seite."},{"title":"Zurück","text":"Lass den Unterarm langsam zurück vor den Bauch kommen. Nimm wenig Gewicht und beweg dich gleichmäßig, ohne zu reißen."}],"pt-PT":[{"title":"Preparação","text":"Coloca uma polia à altura do cotovelo e fica de lado para ela. Segura a pega com a mão mais afastada, cotovelo a 90° e junto ao corpo."},{"title":"Rodar","text":"Roda o antebraço para fora, afastando-o da barriga até onde for confortável. O cotovelo fica colado ao corpo."},{"title":"Voltar","text":"Deixa o antebraço voltar devagar até à frente da barriga. Usa pouco peso e faz o movimento suave, sem esticões."}],"pt-BR":[{"title":"Preparação","text":"Ajuste uma polia na altura do cotovelo e fique de lado para ela. Segure o pegador com a mão mais distante, cotovelo a 90° e junto ao corpo."},{"title":"Girar","text":"Gire o antebraço para fora, afastando-o da barriga até onde for confortável. O cotovelo fica colado ao corpo."},{"title":"Voltar","text":"Deixe o antebraço voltar devagar até a frente da barriga. Use pouco peso e faça o movimento suave, sem trancos."}]}'::jsonb,
    'cable', '{weight,reps}', '{"rear_delts":0.8,"upper_back":0.2}'::jsonb, 60),
  ('neutral-grip-pull-up', '{"en":"Neutral-Grip Pull-Up","de":"Klimmzüge mit Neutralgriff","pt-PT":"Elevações com pega neutra","pt-BR":"Barra fixa pegada neutra"}'::jsonb,
    '{"en":[{"title":"Grip","text":"Grab the parallel handles with your palms facing each other and hang with straight arms."},{"title":"Pull","text":"Drive your elbows down close to your body until your chin clears the handles."},{"title":"Lower","text":"Lower yourself slowly to straight arms. Keep your legs still and avoid swinging."}],"de":[{"title":"Griff","text":"Greif die parallelen Griffe so, dass die Handflächen zueinander zeigen, und häng dich mit gestreckten Armen hin."},{"title":"Ziehen","text":"Zieh die Ellbogen eng am Körper nach unten, bis dein Kinn über den Griffen ist."},{"title":"Absenken","text":"Lass dich langsam bis zu gestreckten Armen ab. Die Beine bleiben ruhig, kein Schwung."}],"pt-PT":[{"title":"Pega","text":"Agarra as pegas paralelas com as palmas viradas uma para a outra e fica suspenso com os braços esticados."},{"title":"Puxar","text":"Leva os cotovelos para baixo, junto ao corpo, até o queixo passar as pegas."},{"title":"Descida","text":"Desce devagar até os braços ficarem esticados. Mantém as pernas quietas, sem balanço."}],"pt-BR":[{"title":"Pegada","text":"Segure os pegadores paralelos com as palmas voltadas uma para a outra e fique pendurado com os braços estendidos."},{"title":"Puxar","text":"Leve os cotovelos para baixo, perto do corpo, até o queixo passar dos pegadores."},{"title":"Descida","text":"Desça devagar até os braços ficarem estendidos. Mantenha as pernas paradas, sem balançar."}]}'::jsonb,
    'bodyweight', '{weight,reps}', '{"lats":0.55,"biceps":0.25,"upper_back":0.2}'::jsonb, 120),
  ('negative-pull-up', '{"en":"Negative Pull-Up","de":"Negative Klimmzüge","pt-PT":"Elevações negativas","pt-BR":"Barra fixa negativa"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Step up on a box or jump so your chin starts above the bar, palms facing away, hands shoulder-width."},{"title":"Lower","text":"Lower yourself as slowly as you can, aiming for 3–5 seconds, until your arms are straight."},{"title":"Reset","text":"Step back onto the box and start the next rep from the top. Stay tight at the bottom instead of dropping."}],"de":[{"title":"Aufbauen","text":"Stell dich auf eine Box oder spring hoch, sodass dein Kinn über der Stange ist. Obergriff, etwa schulterbreit."},{"title":"Absenken","text":"Lass dich so langsam wie möglich ab, etwa 3–5 Sekunden, bis die Arme gestreckt sind."},{"title":"Neu ansetzen","text":"Steig zurück auf die Box und starte die nächste Wiederholung oben. Bleib unten unter Spannung, statt dich fallen zu lassen."}],"pt-PT":[{"title":"Preparação","text":"Sobe para uma caixa ou salta para começares com o queixo acima da barra, palmas viradas para a frente e mãos à largura dos ombros."},{"title":"Descida","text":"Desce o mais devagar possível, cerca de 3 a 5 segundos, até os braços ficarem esticados."},{"title":"Repetir","text":"Volta a subir para a caixa e começa a repetição seguinte em cima. Mantém a tensão em baixo, sem te deixares cair."}],"pt-BR":[{"title":"Preparação","text":"Suba em uma caixa ou dê um impulso para começar com o queixo acima da barra, palmas voltadas para a frente e mãos na largura dos ombros."},{"title":"Descida","text":"Desça o mais devagar que conseguir, cerca de 3 a 5 segundos, até os braços ficarem estendidos."},{"title":"Repetir","text":"Suba de novo na caixa e comece a próxima repetição em cima. Mantenha a tensão embaixo, sem se soltar."}]}'::jsonb,
    'bodyweight', '{reps}', '{"lats":0.55,"upper_back":0.25,"biceps":0.2}'::jsonb, 90),
  ('assisted-pull-up-machine', '{"en":"Assisted Pull-Up Machine","de":"Klimmzüge an der Maschine (unterstützt)","pt-PT":"Elevações assistidas na máquina","pt-BR":"Barra fixa assistida (graviton)"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Select the counterweight: more weight means more help. Kneel on the pad or stand on the platform and grip the handles."},{"title":"Pull","text":"Pull your elbows down towards your hips until your chin is over the handles."},{"title":"Lower","text":"Lower slowly to straight arms. Reduce the counterweight over time as you get stronger."}],"de":[{"title":"Aufbauen","text":"Wähl das Gegengewicht: Je mehr Gewicht, desto mehr Unterstützung. Knie dich aufs Polster oder stell dich auf die Plattform und greif die Griffe."},{"title":"Ziehen","text":"Zieh die Ellbogen Richtung Hüfte, bis dein Kinn über den Griffen ist."},{"title":"Absenken","text":"Lass dich langsam bis zu gestreckten Armen ab. Reduziere das Gegengewicht nach und nach, wenn du stärker wirst."}],"pt-PT":[{"title":"Preparação","text":"Escolhe o contrapeso: quanto mais peso, mais ajuda. Ajoelha-te na almofada ou põe-te de pé na plataforma e agarra as pegas."},{"title":"Puxar","text":"Leva os cotovelos em direção à anca até o queixo passar as pegas."},{"title":"Descida","text":"Desce devagar até os braços ficarem esticados. Reduz o contrapeso à medida que ficas mais forte."}],"pt-BR":[{"title":"Preparação","text":"Escolha o contrapeso: quanto mais peso, mais ajuda. Ajoelhe no apoio ou fique em pé na plataforma e segure os pegadores."},{"title":"Puxar","text":"Leve os cotovelos em direção ao quadril até o queixo passar dos pegadores."},{"title":"Descida","text":"Desça devagar até os braços ficarem estendidos. Diminua o contrapeso conforme ficar mais forte."}]}'::jsonb,
    'machine', '{weight,reps}', '{"lats":0.55,"upper_back":0.25,"biceps":0.2}'::jsonb, 90),
  ('close-grip-lat-pulldown', '{"en":"Close-Grip Lat Pulldown","de":"Latziehen eng","pt-PT":"Puxada à frente com pega fechada","pt-BR":"Puxada frontal pegada fechada"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Attach a V-handle, sit with your thighs under the pads and hold the handle with straight arms."},{"title":"Pull","text":"Lean back slightly and pull the handle to your upper chest, driving your elbows down and back."},{"title":"Return","text":"Let the handle rise slowly until your arms are straight and your lats are stretched."}],"de":[{"title":"Aufbauen","text":"Häng einen V-Griff ein, setz dich mit den Oberschenkeln unter die Polster und halt ihn mit gestreckten Armen."},{"title":"Ziehen","text":"Lehn dich leicht zurück und zieh den Griff zur oberen Brust. Die Ellbogen gehen nach unten und hinten."},{"title":"Zurück","text":"Lass den Griff langsam nach oben, bis die Arme gestreckt sind und du den Lat gedehnt spürst."}],"pt-PT":[{"title":"Preparação","text":"Coloca uma pega em V, senta-te com as coxas por baixo dos rolos e segura a pega com os braços esticados."},{"title":"Puxar","text":"Inclina-te ligeiramente para trás e puxa a pega até à parte superior do peito, levando os cotovelos para baixo e para trás."},{"title":"Voltar","text":"Deixa a pega subir devagar até os braços ficarem esticados e sentires os dorsais alongar."}],"pt-BR":[{"title":"Preparação","text":"Encaixe o triângulo, sente com as coxas embaixo dos apoios e segure-o com os braços estendidos."},{"title":"Puxar","text":"Incline o tronco levemente para trás e puxe o triângulo até a parte de cima do peito, levando os cotovelos para baixo e para trás."},{"title":"Voltar","text":"Deixe o triângulo subir devagar até os braços ficarem estendidos e sentir o dorsal alongar."}]}'::jsonb,
    'cable', '{weight,reps}', '{"lats":0.6,"biceps":0.25,"upper_back":0.15}'::jsonb, 90),
  ('underhand-lat-pulldown', '{"en":"Underhand Lat Pulldown","de":"Latziehen im Untergriff","pt-PT":"Puxada à frente em supinação","pt-BR":"Puxada frontal supinada"}'::jsonb,
    '{"en":[{"title":"Grip","text":"Take the bar with your palms facing you, about shoulder-width apart, and sit with your thighs under the pads."},{"title":"Pull","text":"Pull the bar to your upper chest, keeping your elbows close and in front of your body."},{"title":"Return","text":"Let the bar rise slowly until your arms are fully straight. Don''t rock your torso back to move the weight."}],"de":[{"title":"Griff","text":"Greif die Stange etwa schulterbreit im Untergriff und setz dich mit den Oberschenkeln unter die Polster."},{"title":"Ziehen","text":"Zieh die Stange zur oberen Brust. Die Ellbogen bleiben eng und vor dem Körper."},{"title":"Zurück","text":"Lass die Stange langsam nach oben, bis die Arme ganz gestreckt sind. Schwing nicht mit dem Oberkörper nach hinten."}],"pt-PT":[{"title":"Pega","text":"Agarra a barra com as palmas viradas para ti, à largura dos ombros, e senta-te com as coxas por baixo dos rolos."},{"title":"Puxar","text":"Puxa a barra até à parte superior do peito, com os cotovelos junto ao corpo e à frente do tronco."},{"title":"Voltar","text":"Deixa a barra subir devagar até os braços ficarem totalmente esticados. Não balances o tronco para trás."}],"pt-BR":[{"title":"Pegada","text":"Segure a barra com as palmas voltadas para você, na largura dos ombros, e sente com as coxas embaixo dos apoios."},{"title":"Puxar","text":"Puxe a barra até a parte de cima do peito, com os cotovelos perto do corpo e à frente do tronco."},{"title":"Voltar","text":"Deixe a barra subir devagar até os braços ficarem totalmente estendidos. Não jogue o tronco para trás."}]}'::jsonb,
    'cable', '{weight,reps}', '{"lats":0.55,"biceps":0.3,"upper_back":0.15}'::jsonb, 90),
  ('single-arm-lat-pulldown', '{"en":"Single-Arm Lat Pulldown","de":"Latziehen einarmig","pt-PT":"Puxada à frente unilateral","pt-BR":"Puxada unilateral"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Attach a single handle to a high pulley. Sit or kneel and hold it with one arm straight overhead."},{"title":"Pull","text":"Drive your elbow down to your side until your hand is beside your shoulder. Don''t twist your torso."},{"title":"Return","text":"Let your arm rise slowly and feel the stretch along your side. Finish all reps, then switch arms."}],"de":[{"title":"Aufbauen","text":"Häng einen Einzelgriff oben am Kabelzug ein. Setz oder knie dich hin und halt ihn mit gestrecktem Arm über dem Kopf."},{"title":"Ziehen","text":"Zieh den Ellbogen seitlich nach unten, bis die Hand neben der Schulter ist. Dreh den Oberkörper nicht mit."},{"title":"Zurück","text":"Lass den Arm langsam nach oben und spür die Dehnung an der Seite. Nach allen Wiederholungen Arm wechseln."}],"pt-PT":[{"title":"Preparação","text":"Coloca uma pega simples na polia alta. Senta-te ou ajoelha-te e segura-a com um braço esticado acima da cabeça."},{"title":"Puxar","text":"Leva o cotovelo para baixo, junto ao tronco, até a mão ficar ao lado do ombro. Não rodes o tronco."},{"title":"Voltar","text":"Deixa o braço subir devagar e sente o alongamento na lateral. Faz todas as repetições e troca de braço."}],"pt-BR":[{"title":"Preparação","text":"Encaixe uma alça simples na polia alta. Sente ou ajoelhe e segure com um braço estendido acima da cabeça."},{"title":"Puxar","text":"Leve o cotovelo para baixo, junto ao tronco, até a mão ficar ao lado do ombro. Não gire o tronco."},{"title":"Voltar","text":"Deixe o braço subir devagar e sinta o alongamento na lateral. Faça todas as repetições e troque de braço."}]}'::jsonb,
    'cable', '{weight,reps}', '{"lats":0.7,"upper_back":0.15,"biceps":0.15}'::jsonb, 90),
  ('machine-lat-pulldown', '{"en":"Machine Lat Pulldown","de":"Latziehen an der Maschine","pt-PT":"Puxada à frente na máquina","pt-BR":"Puxada articulada"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Adjust the seat so the thigh pads hold you down firmly. Grab the handles with your arms straight."},{"title":"Pull","text":"Pull the handles down to shoulder level, driving your elbows towards your hips. Keep your chest up."},{"title":"Return","text":"Let the handles rise slowly until your arms are straight. Don''t let the weight rest between reps."}],"de":[{"title":"Aufbauen","text":"Stell den Sitz so ein, dass die Beinpolster dich fest fixieren. Greif die Griffe mit gestreckten Armen."},{"title":"Ziehen","text":"Zieh die Griffe bis auf Schulterhöhe nach unten, die Ellbogen Richtung Hüfte. Die Brust bleibt oben."},{"title":"Zurück","text":"Lass die Griffe langsam nach oben, bis die Arme gestreckt sind. Setz das Gewicht zwischen den Wiederholungen nicht ab."}],"pt-PT":[{"title":"Preparação","text":"Ajusta o banco para que os rolos fixem bem as coxas. Agarra as pegas com os braços esticados."},{"title":"Puxar","text":"Puxa as pegas até à altura dos ombros, levando os cotovelos em direção à anca. Mantém o peito aberto."},{"title":"Voltar","text":"Deixa as pegas subirem devagar até os braços ficarem esticados. Não pouses o peso entre repetições."}],"pt-BR":[{"title":"Preparação","text":"Ajuste o banco para que os apoios prendam bem as coxas. Segure os pegadores com os braços estendidos."},{"title":"Puxar","text":"Puxe os pegadores até a altura dos ombros, levando os cotovelos em direção ao quadril. Mantenha o peito aberto."},{"title":"Voltar","text":"Deixe os pegadores subirem devagar até os braços ficarem estendidos. Não apoie o peso entre as repetições."}]}'::jsonb,
    'machine', '{weight,reps}', '{"lats":0.6,"upper_back":0.2,"biceps":0.2}'::jsonb, 90),
  ('straight-arm-pulldown', '{"en":"Straight-Arm Pulldown","de":"Latziehen mit gestreckten Armen","pt-PT":"Puxada com braços esticados","pt-BR":"Pulldown na polia"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Attach a straight bar or rope to a high pulley. Step back, hinge slightly and hold it at eye level with straight arms."},{"title":"Pull","text":"Keep your elbows almost locked and sweep the bar down in an arc to your thighs. Squeeze your lats."},{"title":"Return","text":"Let the bar rise slowly back to eye level without bending your elbows or shrugging."}],"de":[{"title":"Aufbauen","text":"Häng eine gerade Stange oben am Kabelzug ein, alternativ ein Seil. Tritt einen Schritt zurück, beug dich leicht vor und halt sie mit gestreckten Armen auf Augenhöhe."},{"title":"Ziehen","text":"Lass die Ellbogen fast gestreckt und zieh die Stange im Bogen bis zu den Oberschenkeln. Spann den Lat fest an."},{"title":"Zurück","text":"Lass die Stange langsam bis auf Augenhöhe zurück, ohne die Ellbogen zu beugen oder die Schultern hochzuziehen."}],"pt-PT":[{"title":"Preparação","text":"Coloca uma barra reta ou uma corda na polia alta. Dá um passo atrás, inclina-te ligeiramente e segura-a à altura dos olhos com os braços esticados."},{"title":"Puxar","text":"Mantém os cotovelos quase esticados e leva a barra num arco até às coxas. Contrai os dorsais."},{"title":"Voltar","text":"Deixa a barra subir devagar até à altura dos olhos, sem dobrar os cotovelos nem encolher os ombros."}],"pt-BR":[{"title":"Preparação","text":"Encaixe uma barra reta ou corda na polia alta. Dê um passo para trás, incline o tronco levemente e segure na altura dos olhos com os braços estendidos."},{"title":"Puxar","text":"Mantenha os cotovelos quase travados e leve a barra em arco até as coxas. Contraia o dorsal."},{"title":"Voltar","text":"Deixe a barra subir devagar até a altura dos olhos, sem dobrar os cotovelos nem encolher os ombros."}]}'::jsonb,
    'cable', '{weight,reps}', '{"lats":0.8,"upper_back":0.1,"triceps":0.1}'::jsonb, 60),
  ('barbell-row', '{"en":"Barbell Row","de":"Langhantelrudern","pt-PT":"Remada curvada com barra","pt-BR":"Remada curvada"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Hold the bar overhand just outside your knees. Hinge forward to about 45° with a flat back and soft knees."},{"title":"Pull","text":"Row the bar to your lower ribs, driving your elbows back and squeezing your shoulder blades."},{"title":"Lower","text":"Lower the bar under control to straight arms. Keep your torso angle fixed and don''t jerk with your hips."}],"de":[{"title":"Aufbauen","text":"Greif die Stange im Obergriff knapp außerhalb der Knie. Beug dich mit geradem Rücken und leicht gebeugten Knien auf etwa 45° vor."},{"title":"Ziehen","text":"Zieh die Stange zu den unteren Rippen, Ellbogen nach hinten, Schulterblätter zusammen."},{"title":"Absenken","text":"Senk die Stange kontrolliert, bis die Arme gestreckt sind. Halt den Oberkörperwinkel und hol keinen Schwung aus der Hüfte."}],"pt-PT":[{"title":"Preparação","text":"Agarra a barra em pronação, logo por fora dos joelhos. Inclina o tronco até cerca de 45°, costas direitas e joelhos ligeiramente fletidos."},{"title":"Puxar","text":"Puxa a barra até às costelas inferiores, levando os cotovelos para trás e juntando as omoplatas."},{"title":"Descida","text":"Desce a barra de forma controlada até os braços ficarem esticados. Mantém o ângulo do tronco e não dês balanço com a anca."}],"pt-BR":[{"title":"Preparação","text":"Segure a barra com pegada pronada, logo por fora dos joelhos. Incline o tronco até cerca de 45°, costas retas e joelhos levemente flexionados."},{"title":"Puxar","text":"Puxe a barra até as costelas de baixo, levando os cotovelos para trás e juntando as escápulas."},{"title":"Descida","text":"Desça a barra com controle até os braços ficarem estendidos. Mantenha o ângulo do tronco e não dê impulso com o quadril."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"upper_back":0.4,"lats":0.3,"biceps":0.15,"lower_back":0.15}'::jsonb, 120),
  ('underhand-barbell-row', '{"en":"Underhand Barbell Row","de":"Langhantelrudern im Untergriff","pt-PT":"Remada curvada em supinação","pt-BR":"Remada curvada supinada"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Take a shoulder-width underhand grip and hinge forward to about 45° with a flat back and soft knees."},{"title":"Pull","text":"Row the bar to your belly button, keeping your elbows close to your sides."},{"title":"Lower","text":"Lower the bar slowly to straight arms. Keep your wrists straight and don''t turn it into a curl."}],"de":[{"title":"Aufbauen","text":"Greif die Stange schulterbreit im Untergriff und beug dich mit geradem Rücken und leicht gebeugten Knien auf etwa 45° vor."},{"title":"Ziehen","text":"Zieh die Stange Richtung Bauchnabel, die Ellbogen bleiben eng am Körper."},{"title":"Absenken","text":"Senk die Stange langsam, bis die Arme gestreckt sind. Halt die Handgelenke gerade und mach keinen Bizepscurl daraus."}],"pt-PT":[{"title":"Preparação","text":"Agarra a barra em supinação, à largura dos ombros, e inclina o tronco até cerca de 45° com as costas direitas e os joelhos fletidos."},{"title":"Puxar","text":"Puxa a barra em direção ao umbigo, com os cotovelos junto ao corpo."},{"title":"Descida","text":"Desce a barra devagar até os braços ficarem esticados. Mantém os pulsos direitos e não transformes o movimento num curl."}],"pt-BR":[{"title":"Preparação","text":"Segure a barra com pegada supinada, na largura dos ombros, e incline o tronco até cerca de 45° com as costas retas e os joelhos flexionados."},{"title":"Puxar","text":"Puxe a barra em direção ao umbigo, com os cotovelos perto do corpo."},{"title":"Descida","text":"Desça a barra devagar até os braços ficarem estendidos. Mantenha os punhos retos e não transforme o movimento em rosca."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"lats":0.4,"upper_back":0.3,"biceps":0.2,"lower_back":0.1}'::jsonb, 120),
  ('pendlay-row', '{"en":"Pendlay Row","de":"Pendlay-Rudern","pt-PT":"Remada Pendlay","pt-BR":"Remada Pendlay"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Bar on the floor over mid-foot. Hinge until your torso is almost parallel to the floor and grip it overhand, back flat."},{"title":"Pull","text":"Pull the bar explosively from the floor to your lower chest without raising your torso."},{"title":"Reset","text":"Lower the bar back to the floor and let it come to a dead stop. Reset your brace before every rep."}],"de":[{"title":"Aufbauen","text":"Die Stange liegt über dem Mittelfuß. Beug dich mit geradem Rücken vor, bis der Oberkörper fast parallel zum Boden ist, und greif im Obergriff."},{"title":"Ziehen","text":"Zieh die Stange explosiv vom Boden zur unteren Brust, ohne den Oberkörper aufzurichten."},{"title":"Ablegen","text":"Leg die Stange wieder auf dem Boden ab, bis sie komplett ruht. Spann vor jeder Wiederholung neu an."}],"pt-PT":[{"title":"Preparação","text":"Barra no chão sobre o meio do pé. Inclina o tronco até ficar quase paralelo ao chão e agarra a barra em pronação, costas direitas."},{"title":"Puxar","text":"Puxa a barra de forma explosiva do chão até à parte inferior do peito, sem levantar o tronco."},{"title":"Pousar","text":"Pousa a barra no chão e deixa-a parar por completo. Volta a contrair o tronco antes de cada repetição."}],"pt-BR":[{"title":"Preparação","text":"Barra no chão sobre o meio do pé. Incline o tronco até ficar quase paralelo ao chão e segure a barra com pegada pronada, costas retas."},{"title":"Puxar","text":"Puxe a barra de forma explosiva do chão até a parte baixa do peito, sem levantar o tronco."},{"title":"Apoiar","text":"Apoie a barra no chão e deixe que ela pare por completo. Contraia o core de novo antes de cada repetição."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"upper_back":0.45,"lats":0.3,"lower_back":0.15,"biceps":0.1}'::jsonb, 120),
  ('seal-row', '{"en":"Seal Row","de":"Seal Row","pt-PT":"Remada seal","pt-BR":"Remada seal"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Lie face down on a bench raised high enough that the bar hangs below you at arm''s length. Grip it overhand, shoulder-width."},{"title":"Pull","text":"Row the bar up to the underside of the bench, driving your elbows back. Keep your chest and hips on the pad."},{"title":"Lower","text":"Lower the bar slowly to straight arms and let your shoulder blades spread. No kicking or swinging."}],"de":[{"title":"Aufbauen","text":"Leg dich bäuchlings auf eine hohe Bank, sodass die Stange bei gestreckten Armen frei unter dir hängt. Greif sie schulterbreit im Obergriff."},{"title":"Ziehen","text":"Zieh die Stange bis an die Unterseite der Bank, Ellbogen nach hinten. Brust und Hüfte bleiben auf dem Polster."},{"title":"Absenken","text":"Senk die Stange langsam, bis die Arme gestreckt sind, und lass die Schulterblätter auseinandergehen. Kein Schwung mit den Beinen."}],"pt-PT":[{"title":"Preparação","text":"Deita-te de barriga para baixo num banco alto, de forma que a barra fique suspensa por baixo de ti com os braços esticados. Agarra-a em pronação."},{"title":"Puxar","text":"Puxa a barra até à parte de baixo do banco, levando os cotovelos para trás. Mantém o peito e a anca apoiados."},{"title":"Descida","text":"Desce a barra devagar até os braços ficarem esticados e deixa as omoplatas afastarem-se. Sem balanço com as pernas."}],"pt-BR":[{"title":"Preparação","text":"Deite de bruços em um banco alto, de forma que a barra fique suspensa embaixo de você com os braços estendidos. Segure com pegada pronada."},{"title":"Puxar","text":"Puxe a barra até a parte de baixo do banco, levando os cotovelos para trás. Mantenha o peito e o quadril apoiados."},{"title":"Descida","text":"Desça a barra devagar até os braços ficarem estendidos e deixe as escápulas se afastarem. Sem impulso com as pernas."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"upper_back":0.5,"lats":0.25,"biceps":0.15,"rear_delts":0.1}'::jsonb, 90),
  ('meadows-row', '{"en":"Meadows Row","de":"Meadows-Rudern","pt-PT":"Remada Meadows","pt-BR":"Remada Meadows"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Stand side-on to a landmine bar in a staggered stance and grab the end of the sleeve overhand. Rest your other forearm on your front knee."},{"title":"Pull","text":"Row the bar towards your hip, driving your elbow up and slightly out."},{"title":"Lower","text":"Lower the bar until your arm is straight and you feel a stretch in your lat. Finish the set, then switch sides."}],"de":[{"title":"Aufbauen","text":"Stell dich in Schrittstellung seitlich zur Landmine-Stange und greif das Hantelende im Obergriff. Den anderen Unterarm legst du aufs vordere Knie."},{"title":"Ziehen","text":"Zieh die Stange Richtung Hüfte, der Ellbogen geht nach oben und leicht nach außen."},{"title":"Absenken","text":"Senk die Stange, bis der Arm gestreckt ist und du den Lat gedehnt spürst. Nach dem Satz Seite wechseln."}],"pt-PT":[{"title":"Preparação","text":"Fica de lado para a barra no landmine, com um pé à frente do outro, e agarra a ponta da barra em pronação. Apoia o outro antebraço no joelho da frente."},{"title":"Puxar","text":"Puxa a barra em direção à anca, levando o cotovelo para cima e ligeiramente para fora."},{"title":"Descida","text":"Desce a barra até o braço ficar esticado e sentires o dorsal alongar. Termina a série e troca de lado."}],"pt-BR":[{"title":"Preparação","text":"Fique de lado para a barra no landmine, com um pé à frente do outro, e segure a ponta da barra com pegada pronada. Apoie o outro antebraço no joelho da frente."},{"title":"Puxar","text":"Puxe a barra em direção ao quadril, levando o cotovelo para cima e levemente para fora."},{"title":"Descida","text":"Desça a barra até o braço ficar estendido e sentir o dorsal alongar. Termine a série e troque de lado."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"lats":0.5,"upper_back":0.3,"rear_delts":0.1,"biceps":0.1}'::jsonb, 90),
  ('one-arm-dumbbell-row', '{"en":"One-Arm Dumbbell Row","de":"Kurzhantelrudern einarmig","pt-PT":"Remada unilateral com haltere","pt-BR":"Remada serrote"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Put one knee and the same-side hand on a flat bench. Hold the dumbbell in your other hand with your back flat."},{"title":"Pull","text":"Row the dumbbell towards your hip, keeping your elbow close to your body. Don''t rotate your torso."},{"title":"Lower","text":"Lower the dumbbell until your arm is straight and you feel a stretch in your lat. Finish the set, then switch sides."}],"de":[{"title":"Aufbauen","text":"Stütz ein Knie und die Hand derselben Seite auf eine Flachbank. Halt die Kurzhantel in der anderen Hand, Rücken gerade."},{"title":"Ziehen","text":"Zieh die Kurzhantel Richtung Hüfte, der Ellbogen bleibt nah am Körper. Dreh den Oberkörper nicht auf."},{"title":"Absenken","text":"Senk die Hantel, bis der Arm gestreckt ist und du den Lat gedehnt spürst. Nach dem Satz Seite wechseln."}],"pt-PT":[{"title":"Preparação","text":"Apoia um joelho e a mão do mesmo lado num banco plano. Segura o haltere com a outra mão, costas direitas."},{"title":"Puxar","text":"Puxa o haltere em direção à anca, com o cotovelo junto ao corpo. Não rodes o tronco."},{"title":"Descida","text":"Desce o haltere até o braço ficar esticado e sentires o dorsal alongar. Termina a série e troca de lado."}],"pt-BR":[{"title":"Preparação","text":"Apoie um joelho e a mão do mesmo lado em um banco reto. Segure o halter com a outra mão, costas retas."},{"title":"Puxar","text":"Puxe o halter em direção ao quadril, com o cotovelo perto do corpo. Não gire o tronco."},{"title":"Descida","text":"Desça o halter até o braço ficar estendido e sentir o dorsal alongar. Termine a série e troque de lado."}]}'::jsonb,
    'dumbbell', '{weight,reps}', '{"lats":0.5,"upper_back":0.3,"biceps":0.2}'::jsonb, 90),
  ('bent-over-dumbbell-row', '{"en":"Bent-Over Dumbbell Row","de":"Kurzhantelrudern vorgebeugt","pt-PT":"Remada curvada com halteres","pt-BR":"Remada curvada com halteres"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Hold a dumbbell in each hand, palms facing in. Hinge forward to about 45° with soft knees and a flat back."},{"title":"Pull","text":"Row both dumbbells towards your hips, driving your elbows back and squeezing your shoulder blades."},{"title":"Lower","text":"Lower the dumbbells slowly to straight arms. Keep your torso still throughout the set."}],"de":[{"title":"Aufbauen","text":"Nimm in jede Hand eine Kurzhantel, die Handflächen zeigen zueinander. Beug dich mit leicht gebeugten Knien und geradem Rücken auf etwa 45° vor."},{"title":"Ziehen","text":"Zieh beide Hanteln Richtung Hüfte, Ellbogen nach hinten, Schulterblätter zusammen."},{"title":"Absenken","text":"Senk die Hanteln langsam, bis die Arme gestreckt sind. Der Oberkörper bleibt den ganzen Satz über ruhig."}],"pt-PT":[{"title":"Preparação","text":"Segura um haltere em cada mão, palmas viradas para dentro. Inclina o tronco até cerca de 45°, joelhos ligeiramente fletidos e costas direitas."},{"title":"Puxar","text":"Puxa os dois halteres em direção à anca, levando os cotovelos para trás e juntando as omoplatas."},{"title":"Descida","text":"Desce os halteres devagar até os braços ficarem esticados. Mantém o tronco imóvel durante toda a série."}],"pt-BR":[{"title":"Preparação","text":"Segure um halter em cada mão, palmas voltadas para dentro. Incline o tronco até cerca de 45°, joelhos levemente flexionados e costas retas."},{"title":"Puxar","text":"Puxe os dois halteres em direção ao quadril, levando os cotovelos para trás e juntando as escápulas."},{"title":"Descida","text":"Desça os halteres devagar até os braços ficarem estendidos. Mantenha o tronco parado durante toda a série."}]}'::jsonb,
    'dumbbell', '{weight,reps}', '{"upper_back":0.4,"lats":0.35,"biceps":0.15,"lower_back":0.1}'::jsonb, 90),
  ('chest-supported-dumbbell-row', '{"en":"Chest-Supported Dumbbell Row","de":"Kurzhantelrudern auf der Schrägbank","pt-PT":"Remada com halteres no banco inclinado","pt-BR":"Remada apoiada com halteres"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Set an incline bench to 30–45° and lie face down with your chest on the pad, a dumbbell in each hand."},{"title":"Pull","text":"Row the dumbbells up beside your ribs and squeeze your shoulder blades. Keep your chest on the pad."},{"title":"Lower","text":"Lower slowly until your arms are straight and your shoulders reach forward."}],"de":[{"title":"Aufbauen","text":"Stell die Schrägbank auf 30–45° und leg dich bäuchlings mit der Brust aufs Polster, in jeder Hand eine Kurzhantel."},{"title":"Ziehen","text":"Zieh die Hanteln seitlich neben die Rippen und drück die Schulterblätter zusammen. Die Brust bleibt auf dem Polster."},{"title":"Absenken","text":"Senk die Hanteln langsam, bis die Arme gestreckt sind und die Schultern nach vorne gehen."}],"pt-PT":[{"title":"Preparação","text":"Coloca o banco inclinado a 30–45° e deita-te de barriga para baixo, com o peito apoiado e um haltere em cada mão."},{"title":"Puxar","text":"Puxa os halteres até ao lado das costelas e junta as omoplatas. Mantém o peito apoiado no banco."},{"title":"Descida","text":"Desce devagar até os braços ficarem esticados e os ombros irem para a frente."}],"pt-BR":[{"title":"Preparação","text":"Ajuste o banco inclinado a 30–45° e deite de bruços, com o peito apoiado e um halter em cada mão."},{"title":"Puxar","text":"Puxe os halteres até o lado das costelas e junte as escápulas. Mantenha o peito apoiado no banco."},{"title":"Descida","text":"Desça devagar até os braços ficarem estendidos e os ombros irem para a frente."}]}'::jsonb,
    'dumbbell', '{weight,reps}', '{"upper_back":0.45,"lats":0.3,"biceps":0.15,"rear_delts":0.1}'::jsonb, 90),
  ('wide-grip-cable-row', '{"en":"Wide-Grip Cable Row","de":"Kabelrudern breit","pt-PT":"Remada sentada no cabo com pega larga","pt-BR":"Remada baixa pegada aberta"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Attach a long bar to the low pulley. Sit with your feet on the platform, knees soft, and grip the bar wide and overhand."},{"title":"Pull","text":"Row the bar to your lower chest with your elbows pointing out to the sides. Squeeze your upper back."},{"title":"Return","text":"Let your arms extend slowly until they''re straight, keeping your torso upright and still."}],"de":[{"title":"Aufbauen","text":"Häng eine lange Stange unten am Kabelzug ein. Setz dich, Füße auf die Plattform, Knie leicht gebeugt, und greif die Stange breit im Obergriff."},{"title":"Ziehen","text":"Zieh die Stange zur unteren Brust, die Ellbogen zeigen nach außen. Spann den oberen Rücken fest an."},{"title":"Zurück","text":"Lass die Arme langsam nach vorne, bis sie gestreckt sind. Der Oberkörper bleibt aufrecht und ruhig."}],"pt-PT":[{"title":"Preparação","text":"Coloca uma barra comprida na polia baixa. Senta-te com os pés na plataforma, joelhos ligeiramente fletidos, e agarra a barra com pega larga em pronação."},{"title":"Puxar","text":"Puxa a barra até à parte inferior do peito, com os cotovelos abertos para os lados. Aperta a parte superior das costas."},{"title":"Voltar","text":"Deixa os braços esticarem devagar, mantendo o tronco direito e imóvel."}],"pt-BR":[{"title":"Preparação","text":"Encaixe uma barra longa na polia baixa. Sente com os pés na plataforma, joelhos levemente flexionados, e segure a barra com pegada aberta e pronada."},{"title":"Puxar","text":"Puxe a barra até a parte baixa do peito, com os cotovelos abertos para os lados. Contraia a parte de cima das costas."},{"title":"Voltar","text":"Deixe os braços estenderem devagar, mantendo o tronco ereto e parado."}]}'::jsonb,
    'cable', '{weight,reps}', '{"upper_back":0.5,"rear_delts":0.2,"lats":0.2,"biceps":0.1}'::jsonb, 90),
  ('single-arm-cable-row', '{"en":"Single-Arm Cable Row","de":"Kabelrudern einarmig","pt-PT":"Remada unilateral no cabo","pt-BR":"Remada unilateral na polia"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Attach a single handle to a low or chest-height pulley. Sit or stand facing it and hold the handle with one arm straight."},{"title":"Pull","text":"Row the handle to your side, driving your elbow back past your torso. Keep your shoulders square."},{"title":"Return","text":"Let your arm reach forward slowly for a full stretch. Finish the set, then switch arms."}],"de":[{"title":"Aufbauen","text":"Häng einen Einzelgriff unten oder auf Brusthöhe am Kabelzug ein. Setz oder stell dich davor und halt den Griff mit gestrecktem Arm."},{"title":"Ziehen","text":"Zieh den Griff seitlich an den Körper, bis der Ellbogen hinter dem Oberkörper ist. Die Schultern bleiben gerade."},{"title":"Zurück","text":"Lass den Arm langsam nach vorne, bis er voll gedehnt ist. Nach dem Satz Arm wechseln."}],"pt-PT":[{"title":"Preparação","text":"Coloca uma pega simples na polia baixa ou à altura do peito. Senta-te ou fica de pé de frente para ela e segura a pega com um braço esticado."},{"title":"Puxar","text":"Puxa a pega até ao lado do corpo, levando o cotovelo para trás do tronco. Mantém os ombros alinhados."},{"title":"Voltar","text":"Deixa o braço ir à frente devagar até alongar por completo. Termina a série e troca de braço."}],"pt-BR":[{"title":"Preparação","text":"Encaixe uma alça simples na polia baixa ou na altura do peito. Sente ou fique em pé de frente para ela e segure a alça com um braço estendido."},{"title":"Puxar","text":"Puxe a alça até a lateral do corpo, levando o cotovelo para trás do tronco. Mantenha os ombros alinhados."},{"title":"Voltar","text":"Deixe o braço ir à frente devagar até alongar por completo. Termine a série e troque de braço."}]}'::jsonb,
    'cable', '{weight,reps}', '{"lats":0.45,"upper_back":0.35,"biceps":0.2}'::jsonb, 90),
  ('machine-row', '{"en":"Seated Machine Row","de":"Rudern an der Maschine","pt-PT":"Remada sentada na máquina","pt-BR":"Remada sentada na máquina"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Adjust the seat so the handles are at chest height and press your chest against the pad."},{"title":"Pull","text":"Pull the handles towards your torso, driving your elbows back and squeezing your shoulder blades."},{"title":"Return","text":"Let the handles move forward slowly until your arms are straight. Keep your chest on the pad."}],"de":[{"title":"Aufbauen","text":"Stell den Sitz so ein, dass die Griffe auf Brusthöhe sind, und leg die Brust ans Polster."},{"title":"Ziehen","text":"Zieh die Griffe zum Oberkörper, Ellbogen nach hinten, Schulterblätter zusammen."},{"title":"Zurück","text":"Lass die Griffe langsam nach vorne, bis die Arme gestreckt sind. Die Brust bleibt am Polster."}],"pt-PT":[{"title":"Preparação","text":"Ajusta o banco para que as pegas fiquem à altura do peito e encosta o peito ao apoio."},{"title":"Puxar","text":"Puxa as pegas em direção ao tronco, levando os cotovelos para trás e juntando as omoplatas."},{"title":"Voltar","text":"Deixa as pegas irem para a frente devagar até os braços ficarem esticados. Mantém o peito encostado."}],"pt-BR":[{"title":"Preparação","text":"Ajuste o banco para que os pegadores fiquem na altura do peito e encoste o peito no apoio."},{"title":"Puxar","text":"Puxe os pegadores em direção ao tronco, levando os cotovelos para trás e juntando as escápulas."},{"title":"Voltar","text":"Deixe os pegadores irem à frente devagar até os braços ficarem estendidos. Mantenha o peito encostado."}]}'::jsonb,
    'machine', '{weight,reps}', '{"upper_back":0.5,"lats":0.3,"biceps":0.2}'::jsonb, 90),
  ('machine-high-row', '{"en":"Machine High Row","de":"High Row an der Maschine","pt-PT":"High row na máquina","pt-BR":"High row na máquina"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Adjust the seat so you reach up to the handles with straight arms. Lock your thighs under the pad."},{"title":"Pull","text":"Pull the handles down and back towards your lower chest until your elbows pass your torso."},{"title":"Return","text":"Let the handles rise slowly until your arms are straight and your lats stretch."}],"de":[{"title":"Aufbauen","text":"Stell den Sitz so ein, dass du die Griffe mit gestreckten Armen schräg über dir erreichst. Fixier die Oberschenkel unter dem Polster."},{"title":"Ziehen","text":"Zieh die Griffe schräg nach unten und hinten Richtung untere Brust, bis die Ellbogen hinter dem Oberkörper sind."},{"title":"Zurück","text":"Lass die Griffe langsam nach oben, bis die Arme gestreckt sind und du den Lat gedehnt spürst."}],"pt-PT":[{"title":"Preparação","text":"Ajusta o banco para chegares às pegas acima de ti com os braços esticados. Fixa as coxas por baixo do rolo."},{"title":"Puxar","text":"Puxa as pegas para baixo e para trás em direção à parte inferior do peito, até os cotovelos passarem o tronco."},{"title":"Voltar","text":"Deixa as pegas subirem devagar até os braços ficarem esticados e sentires os dorsais alongar."}],"pt-BR":[{"title":"Preparação","text":"Ajuste o banco para alcançar os pegadores acima de você com os braços estendidos. Prenda as coxas embaixo do apoio."},{"title":"Puxar","text":"Puxe os pegadores para baixo e para trás em direção à parte baixa do peito, até os cotovelos passarem do tronco."},{"title":"Voltar","text":"Deixe os pegadores subirem devagar até os braços ficarem estendidos e sentir o dorsal alongar."}]}'::jsonb,
    'machine', '{weight,reps}', '{"lats":0.5,"upper_back":0.3,"rear_delts":0.1,"biceps":0.1}'::jsonb, 90),
  ('chest-supported-t-bar-row', '{"en":"Chest-Supported T-Bar Row","de":"T-Bar-Rudern mit Brustauflage","pt-PT":"Remada T com apoio no peito","pt-BR":"Remada cavalinho com apoio"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Stand on the foot plates and lie with your chest on the pad. Grab the handles with straight arms."},{"title":"Pull","text":"Row the handles up towards your chest, driving your elbows back. Keep your chest on the pad."},{"title":"Lower","text":"Lower slowly until your arms are straight and your shoulder blades spread apart."}],"de":[{"title":"Aufbauen","text":"Stell dich auf die Fußplatten und leg die Brust aufs Polster. Greif die Griffe mit gestreckten Armen."},{"title":"Ziehen","text":"Zieh die Griffe Richtung Brust, Ellbogen nach hinten. Die Brust bleibt auf dem Polster."},{"title":"Absenken","text":"Senk das Gewicht langsam, bis die Arme gestreckt sind und die Schulterblätter auseinandergehen."}],"pt-PT":[{"title":"Preparação","text":"Sobe para as plataformas e apoia o peito na almofada. Agarra as pegas com os braços esticados."},{"title":"Puxar","text":"Puxa as pegas em direção ao peito, levando os cotovelos para trás. Mantém o peito apoiado."},{"title":"Descida","text":"Desce devagar até os braços ficarem esticados e as omoplatas se afastarem."}],"pt-BR":[{"title":"Preparação","text":"Suba nas plataformas e apoie o peito na almofada. Segure os pegadores com os braços estendidos."},{"title":"Puxar","text":"Puxe os pegadores em direção ao peito, levando os cotovelos para trás. Mantenha o peito apoiado."},{"title":"Descida","text":"Desça devagar até os braços ficarem estendidos e as escápulas se afastarem."}]}'::jsonb,
    'machine', '{weight,reps}', '{"upper_back":0.5,"lats":0.3,"biceps":0.2}'::jsonb, 90),
  ('inverted-row', '{"en":"Inverted Row","de":"Umgekehrtes Rudern","pt-PT":"Remada invertida","pt-BR":"Remada invertida"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Set a bar at about waist height in a rack or Smith machine. Lie under it, grip it overhand and straighten your body."},{"title":"Pull","text":"Pull your chest to the bar with your body in one straight line from head to heels. Squeeze your shoulder blades."},{"title":"Lower","text":"Lower yourself until your arms are straight without letting your hips sag. Bend your knees to make it easier."}],"de":[{"title":"Aufbauen","text":"Stell eine Stange im Rack oder in der Multipresse auf Hüfthöhe ein. Leg dich darunter, greif im Obergriff und streck den Körper."},{"title":"Ziehen","text":"Zieh die Brust zur Stange, der Körper bildet eine gerade Linie von Kopf bis Ferse. Schulterblätter zusammen."},{"title":"Absenken","text":"Lass dich ab, bis die Arme gestreckt sind, ohne dass die Hüfte durchhängt. Mit gebeugten Knien wird es leichter."}],"pt-PT":[{"title":"Preparação","text":"Coloca uma barra à altura da cintura num rack ou na máquina Smith. Deita-te por baixo, agarra-a em pronação e estica o corpo."},{"title":"Puxar","text":"Puxa o peito até à barra com o corpo em linha reta da cabeça aos calcanhares. Junta as omoplatas."},{"title":"Descida","text":"Desce até os braços ficarem esticados, sem deixar a anca descair. Fletir os joelhos torna o exercício mais fácil."}],"pt-BR":[{"title":"Preparação","text":"Coloque uma barra na altura da cintura em um rack ou no Smith. Deite embaixo dela, segure com pegada pronada e estique o corpo."},{"title":"Puxar","text":"Puxe o peito até a barra com o corpo em linha reta da cabeça aos calcanhares. Junte as escápulas."},{"title":"Descida","text":"Desça até os braços ficarem estendidos, sem deixar o quadril cair. Flexionar os joelhos deixa o exercício mais fácil."}]}'::jsonb,
    'bodyweight', '{reps}', '{"upper_back":0.45,"lats":0.25,"rear_delts":0.15,"biceps":0.15}'::jsonb, 90),
  ('sumo-deadlift', '{"en":"Sumo Deadlift","de":"Sumo-Kreuzheben","pt-PT":"Peso morto sumo","pt-BR":"Levantamento terra sumô"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Take a wide stance with your toes turned out and shins close to the bar. Grip it inside your knees, arms hanging straight down."},{"title":"Brace","text":"Push your knees out over your toes, chest up, back flat. Take a deep breath and pull the slack out of the bar."},{"title":"Lift","text":"Push the floor apart with your feet and stand up, driving your hips forward. Lower the bar the same way, close to your legs."}],"de":[{"title":"Aufbauen","text":"Stell dich breit hin, Fußspitzen nach außen, Schienbeine nah an der Stange. Greif innerhalb der Knie, die Arme hängen senkrecht."},{"title":"Anspannen","text":"Drück die Knie nach außen über die Füße, Brust raus, Rücken gerade. Tief einatmen und die Stange auf Spannung bringen."},{"title":"Heben","text":"Drück den Boden mit den Füßen auseinander und richte dich auf, indem du die Hüfte nach vorne schiebst. Genauso nah an den Beinen wieder ablassen."}],"pt-PT":[{"title":"Preparação","text":"Afasta bem os pés, com as pontas viradas para fora e as canelas junto à barra. Agarra-a por dentro dos joelhos, braços esticados na vertical."},{"title":"Contrair","text":"Empurra os joelhos para fora, alinhados com os pés, peito para cima, costas direitas. Inspira fundo e tira a folga da barra."},{"title":"Levantar","text":"Empurra o chão para os lados e endireita-te, levando a anca à frente. Desce a barra da mesma forma, junto às pernas."}],"pt-BR":[{"title":"Preparação","text":"Abra bem os pés, com as pontas viradas para fora e as canelas perto da barra. Segure por dentro dos joelhos, braços estendidos na vertical."},{"title":"Contraia","text":"Empurre os joelhos para fora, alinhados com os pés, peito para cima, costas retas. Inspire fundo e tire a folga da barra."},{"title":"Levantar","text":"Empurre o chão para os lados e fique em pé, levando o quadril à frente. Desça a barra do mesmo jeito, perto das pernas."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"glutes":0.35,"quads":0.25,"adductors":0.2,"hamstrings":0.2}'::jsonb, 180),
  ('trap-bar-deadlift', '{"en":"Trap Bar Deadlift","de":"Kreuzheben mit Trap Bar","pt-PT":"Peso morto com barra hexagonal","pt-BR":"Levantamento terra com barra hexagonal"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Stand in the centre of the trap bar, feet hip-width. Grip the middle of the handles, arms straight at your sides."},{"title":"Brace","text":"Bend your hips and knees, chest up, back flat. Take a deep breath and brace your core."},{"title":"Lift","text":"Push through your whole foot and extend your hips and knees together until you stand tall. Lower the bar under control."}],"de":[{"title":"Aufbauen","text":"Stell dich mittig in die Trap Bar, Füße hüftbreit. Greif die Griffe in der Mitte, die Arme hängen gestreckt neben dem Körper."},{"title":"Anspannen","text":"Beug Hüfte und Knie, Brust raus, Rücken gerade. Tief einatmen und den Rumpf fest anspannen."},{"title":"Heben","text":"Drück dich über den ganzen Fuß nach oben und streck Hüfte und Knie gleichzeitig. Lass die Stange kontrolliert wieder ab."}],"pt-PT":[{"title":"Preparação","text":"Coloca-te no centro da barra hexagonal, pés à largura da anca. Agarra as pegas a meio, braços esticados ao lado do corpo."},{"title":"Contrair","text":"Dobra a anca e os joelhos, peito para cima, costas direitas. Inspira fundo e contrai o tronco."},{"title":"Levantar","text":"Empurra o chão com o pé inteiro e estende a anca e os joelhos ao mesmo tempo até ficares direito. Desce de forma controlada."}],"pt-BR":[{"title":"Preparação","text":"Fique no centro da barra hexagonal, pés na largura do quadril. Segure os pegadores no meio, braços estendidos ao lado do corpo."},{"title":"Contraia","text":"Flexione o quadril e os joelhos, peito para cima, costas retas. Inspire fundo e contraia o core."},{"title":"Levantar","text":"Empurre o chão com o pé inteiro e estenda o quadril e os joelhos ao mesmo tempo até ficar em pé. Desça com controle."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"quads":0.35,"glutes":0.3,"hamstrings":0.2,"lower_back":0.15}'::jsonb, 180),
  ('rack-pull', '{"en":"Rack Pull","de":"Rack Pulls","pt-PT":"Rack pull","pt-BR":"Rack pull"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Set the bar on the safety pins or blocks just below or above your knees. Feet hip-width, grip just outside your legs."},{"title":"Brace","text":"Hinge with a flat back and your shoulders slightly in front of the bar. Breathe in and pull the slack out."},{"title":"Lift","text":"Drive your hips forward and stand tall, squeezing your glutes at the top. Lower the bar back to the pins under control."}],"de":[{"title":"Aufbauen","text":"Leg die Stange knapp unter oder über Kniehöhe auf die Sicherheitsablagen oder Blöcke. Füße hüftbreit, Griff direkt außerhalb der Beine."},{"title":"Anspannen","text":"Beug dich mit geradem Rücken vor, die Schultern leicht vor der Stange. Einatmen und die Stange auf Spannung bringen."},{"title":"Heben","text":"Schieb die Hüfte nach vorne und richte dich auf, oben das Gesäß anspannen. Leg die Stange kontrolliert wieder ab."}],"pt-PT":[{"title":"Preparação","text":"Coloca a barra nos apoios de segurança ou em blocos, logo abaixo ou acima dos joelhos. Pés à largura da anca, pega logo por fora das pernas."},{"title":"Contrair","text":"Inclina o tronco com as costas direitas e os ombros ligeiramente à frente da barra. Inspira e tira a folga da barra."},{"title":"Levantar","text":"Leva a anca à frente e endireita-te, contraindo os glúteos em cima. Pousa a barra nos apoios de forma controlada."}],"pt-BR":[{"title":"Preparação","text":"Apoie a barra nos pinos de segurança ou em blocos, logo abaixo ou acima dos joelhos. Pés na largura do quadril, pegada logo por fora das pernas."},{"title":"Contraia","text":"Incline o tronco com as costas retas e os ombros levemente à frente da barra. Inspire e tire a folga da barra."},{"title":"Levantar","text":"Leve o quadril à frente e fique em pé, contraindo os glúteos no alto. Apoie a barra de volta nos pinos com controle."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"glutes":0.3,"lower_back":0.3,"traps":0.25,"hamstrings":0.15}'::jsonb, 150),
  ('deficit-deadlift', '{"en":"Deficit Deadlift","de":"Defizit-Kreuzheben","pt-PT":"Peso morto com défice","pt-BR":"Levantamento terra com déficit"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Stand on a 2–5 cm plate or platform with the bar over mid-foot. Grip just outside your legs."},{"title":"Brace","text":"Hips lower than in a regular deadlift, chest up, back flat. Breathe in and pull the slack out of the bar."},{"title":"Lift","text":"Push the floor away and keep the bar close as it breaks from the floor. Stand tall, then lower it the same way."}],"de":[{"title":"Aufbauen","text":"Stell dich auf eine 2–5 cm hohe Scheibe oder Plattform, die Stange über dem Mittelfuß. Greif direkt außerhalb der Beine."},{"title":"Anspannen","text":"Hüfte tiefer als beim normalen Kreuzheben, Brust raus, Rücken gerade. Einatmen und die Stange auf Spannung bringen."},{"title":"Heben","text":"Drück dich vom Boden weg und halt die Stange beim Abheben nah am Körper. Richte dich auf und lass sie genauso wieder ab."}],"pt-PT":[{"title":"Preparação","text":"Sobe para um disco ou plataforma de 2–5 cm, com a barra sobre o meio do pé. Agarra a barra logo por fora das pernas."},{"title":"Contrair","text":"Anca mais baixa do que no peso morto normal, peito para cima, costas direitas. Inspira e tira a folga da barra."},{"title":"Levantar","text":"Empurra o chão e mantém a barra junto ao corpo quando sai do chão. Endireita-te e desce-a da mesma forma."}],"pt-BR":[{"title":"Preparação","text":"Suba em uma anilha ou plataforma de 2–5 cm, com a barra sobre o meio do pé. Segure logo por fora das pernas."},{"title":"Contraia","text":"Quadril mais baixo do que no levantamento terra normal, peito para cima, costas retas. Inspire e tire a folga da barra."},{"title":"Levantar","text":"Empurre o chão e mantenha a barra perto do corpo quando ela sair do chão. Fique em pé e desça do mesmo jeito."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"hamstrings":0.3,"glutes":0.3,"lower_back":0.25,"quads":0.15}'::jsonb, 180),
  ('paused-deadlift', '{"en":"Paused Deadlift","de":"Kreuzheben mit Pause","pt-PT":"Peso morto com pausa","pt-BR":"Levantamento terra com pausa"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Set up as for a regular deadlift: feet hip-width, bar over mid-foot, grip just outside your legs, back flat."},{"title":"Pause","text":"Lift the bar just off the floor or to just below your knees and hold for 1–2 seconds. Keep your back flat and the bar close."},{"title":"Finish","text":"Continue up until you stand tall, then lower the bar to the floor under control."}],"de":[{"title":"Aufbauen","text":"Bau dich wie beim normalen Kreuzheben auf: Füße hüftbreit, Stange über dem Mittelfuß, Griff außerhalb der Beine, Rücken gerade."},{"title":"Pause","text":"Heb die Stange knapp vom Boden oder bis kurz unter die Knie und halte sie 1–2 Sekunden. Rücken gerade, Stange nah am Körper."},{"title":"Beenden","text":"Zieh weiter, bis du aufrecht stehst, und senk die Stange dann kontrolliert auf den Boden ab."}],"pt-PT":[{"title":"Preparação","text":"Prepara-te como no peso morto normal: pés à largura da anca, barra sobre o meio do pé, pega por fora das pernas, costas direitas."},{"title":"Pausa","text":"Levanta a barra um pouco do chão ou até logo abaixo dos joelhos e mantém 1–2 segundos. Costas direitas e barra junto ao corpo."},{"title":"Terminar","text":"Continua a subir até ficares direito e depois desce a barra até ao chão de forma controlada."}],"pt-BR":[{"title":"Preparação","text":"Prepare-se como no levantamento terra normal: pés na largura do quadril, barra sobre o meio do pé, pegada por fora das pernas, costas retas."},{"title":"Pausa","text":"Tire a barra um pouco do chão ou leve até logo abaixo dos joelhos e segure por 1–2 segundos. Costas retas e barra perto do corpo."},{"title":"Finalizar","text":"Continue subindo até ficar em pé e depois desça a barra até o chão com controle."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"hamstrings":0.3,"lower_back":0.3,"glutes":0.25,"traps":0.15}'::jsonb, 180),
  ('back-extension', '{"en":"Back Extension","de":"Rückenstrecker","pt-PT":"Extensão lombar","pt-BR":"Hiperextensão lombar"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Set the pad just below your hip bones on a 45° or horizontal bench and hook your heels under the foot pads."},{"title":"Lower","text":"Hinge at the hips and lower your torso with a flat back until you feel a stretch in your hamstrings."},{"title":"Raise","text":"Squeeze your glutes and lift until your body is straight, without overarching. Hold a plate to your chest for extra load."}],"de":[{"title":"Aufbauen","text":"Stell das Polster so ein, dass es knapp unter den Hüftknochen liegt, und hak die Fersen unter die Fußpolster."},{"title":"Absenken","text":"Beug dich mit geradem Rücken aus der Hüfte nach vorne, bis du die Beinbeuger spürst."},{"title":"Aufrichten","text":"Spann das Gesäß an und richte dich auf, bis dein Körper gerade ist, ohne ins Hohlkreuz zu gehen. Für mehr Gewicht eine Scheibe vor die Brust halten."}],"pt-PT":[{"title":"Preparação","text":"Ajusta a almofada para ficar logo abaixo dos ossos da anca e prende os calcanhares por baixo dos rolos."},{"title":"Descida","text":"Inclina-te a partir da anca com as costas direitas até sentires os isquiotibiais alongar."},{"title":"Subir","text":"Contrai os glúteos e sobe até o corpo ficar em linha reta, sem arquear demasiado. Para mais carga, segura um disco junto ao peito."}],"pt-BR":[{"title":"Preparação","text":"Ajuste o apoio para ficar logo abaixo dos ossos do quadril e prenda os calcanhares embaixo dos rolos."},{"title":"Descida","text":"Incline o tronco a partir do quadril com as costas retas até sentir os posteriores alongarem."},{"title":"Subir","text":"Contraia os glúteos e suba até o corpo ficar em linha reta, sem arquear demais. Para mais carga, segure uma anilha junto ao peito."}]}'::jsonb,
    'bodyweight', '{weight,reps}', '{"lower_back":0.45,"glutes":0.3,"hamstrings":0.25}'::jsonb, 75),
  ('back-extension-machine', '{"en":"Back Extension Machine","de":"Rückenstrecker an der Maschine","pt-PT":"Extensão lombar na máquina","pt-BR":"Extensão lombar na máquina"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Adjust the seat so the back pad sits across your shoulder blades. Fasten the thigh strap and plant your feet."},{"title":"Extend","text":"Push back against the pad until your torso is slightly behind vertical. Move smoothly, without jerking."},{"title":"Return","text":"Let the pad bring your torso forward slowly. Keep your abs braced and don''t lose tension at the front."}],"de":[{"title":"Aufbauen","text":"Stell den Sitz so ein, dass das Rückenpolster auf Höhe der Schulterblätter liegt. Schließ den Beingurt und stell die Füße fest auf."},{"title":"Strecken","text":"Drück dich gegen das Polster nach hinten, bis der Oberkörper leicht hinter der Senkrechten ist. Gleichmäßig bewegen, ohne Ruck."},{"title":"Zurück","text":"Lass dich vom Polster langsam nach vorne bringen. Halt den Bauch fest und bleib auch vorne unter Spannung."}],"pt-PT":[{"title":"Preparação","text":"Ajusta o banco para que a almofada fique à altura das omoplatas. Aperta o cinto das coxas e apoia bem os pés."},{"title":"Estender","text":"Empurra a almofada para trás até o tronco passar ligeiramente a vertical. Move-te de forma fluida, sem esticões."},{"title":"Voltar","text":"Deixa a almofada levar o tronco à frente devagar. Mantém o abdómen contraído e não percas a tensão."}],"pt-BR":[{"title":"Preparação","text":"Ajuste o banco para que o apoio fique na altura das escápulas. Prenda o cinto das coxas e firme bem os pés."},{"title":"Estender","text":"Empurre o apoio para trás até o tronco passar levemente da vertical. Faça o movimento fluido, sem trancos."},{"title":"Voltar","text":"Deixe o apoio levar o tronco à frente devagar. Mantenha o abdômen contraído e não perca a tensão."}]}'::jsonb,
    'machine', '{weight,reps}', '{"lower_back":0.8,"glutes":0.15,"hamstrings":0.05}'::jsonb, 60),
  ('superman', '{"en":"Superman","de":"Superman","pt-PT":"Superman","pt-BR":"Superman"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Lie face down with your arms stretched out in front of you and your legs straight."},{"title":"Lift","text":"Squeeze your glutes and lower back to lift your arms, chest and thighs off the floor. Hold for 1–2 seconds."},{"title":"Lower","text":"Lower back down slowly and relax briefly. Look at the floor to keep your neck neutral."}],"de":[{"title":"Aufbauen","text":"Leg dich auf den Bauch, die Arme nach vorne ausgestreckt, die Beine gestreckt."},{"title":"Abheben","text":"Spann Gesäß und unteren Rücken an und heb Arme, Brust und Oberschenkel vom Boden ab. Halte 1–2 Sekunden."},{"title":"Ablegen","text":"Senk dich langsam wieder ab und entspann kurz. Blick zum Boden, damit der Nacken neutral bleibt."}],"pt-PT":[{"title":"Preparação","text":"Deita-te de barriga para baixo, com os braços esticados à frente e as pernas esticadas."},{"title":"Elevar","text":"Contrai os glúteos e a zona lombar para levantar os braços, o peito e as coxas do chão. Mantém 1–2 segundos."},{"title":"Descida","text":"Desce devagar e relaxa um instante. Olha para o chão para manter o pescoço neutro."}],"pt-BR":[{"title":"Preparação","text":"Deite de bruços, com os braços estendidos à frente e as pernas estendidas."},{"title":"Elevar","text":"Contraia os glúteos e a lombar para tirar os braços, o peito e as coxas do chão. Segure por 1–2 segundos."},{"title":"Descida","text":"Desça devagar e relaxe por um instante. Olhe para o chão para manter o pescoço neutro."}]}'::jsonb,
    'bodyweight', '{reps}', '{"lower_back":0.6,"glutes":0.25,"hamstrings":0.15}'::jsonb, 45),
  ('reverse-hyperextension', '{"en":"Reverse Hyperextension","de":"Reverse Hyperextension","pt-PT":"Hiperextensão invertida","pt-BR":"Hiperextensão reversa"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Lie face down on the pad with your hips at the edge and hold the handles. Hook your ankles into the strap or roller."},{"title":"Lift","text":"Squeeze your glutes to lift your legs until they''re in line with your torso. Don''t arch hard at the top."},{"title":"Lower","text":"Lower your legs under control until they hang straight down. Control the swing instead of letting momentum take over."}],"de":[{"title":"Aufbauen","text":"Leg dich bäuchlings aufs Polster, die Hüfte an der Kante, und halt dich an den Griffen fest. Fixier die Knöchel im Gurt oder an der Rolle."},{"title":"Heben","text":"Spann das Gesäß an und heb die Beine, bis sie in Linie mit dem Oberkörper sind. Oben nicht ins Hohlkreuz drücken."},{"title":"Absenken","text":"Senk die Beine kontrolliert ab, bis sie senkrecht nach unten hängen. Brems den Schwung, statt dich von ihm ziehen zu lassen."}],"pt-PT":[{"title":"Preparação","text":"Deita-te de barriga para baixo na almofada, com a anca na borda, e segura as pegas. Prende os tornozelos na correia ou no rolo."},{"title":"Elevar","text":"Contrai os glúteos e levanta as pernas até ficarem alinhadas com o tronco. Não arqueies demasiado em cima."},{"title":"Descida","text":"Desce as pernas de forma controlada até ficarem penduradas na vertical. Controla o balanço em vez de te deixares levar pelo embalo."}],"pt-BR":[{"title":"Preparação","text":"Deite de bruços no apoio, com o quadril na borda, e segure os pegadores. Prenda os tornozelos na faixa ou no rolo."},{"title":"Elevar","text":"Contraia os glúteos e levante as pernas até ficarem alinhadas com o tronco. Não arqueie demais no alto."},{"title":"Descida","text":"Desça as pernas com controle até ficarem penduradas na vertical. Controle o balanço em vez de deixar o embalo dominar."}]}'::jsonb,
    'machine', '{weight,reps}', '{"glutes":0.45,"hamstrings":0.3,"lower_back":0.25}'::jsonb, 75),
  ('dumbbell-shrug', '{"en":"Dumbbell Shrug","de":"Shrugs mit Kurzhanteln","pt-PT":"Encolhimento de ombros com halteres","pt-BR":"Encolhimento com halteres"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Stand tall with a dumbbell in each hand at your sides, palms facing in, arms straight."},{"title":"Shrug","text":"Lift your shoulders straight up towards your ears as high as you can. Don''t roll them or bend your elbows."},{"title":"Lower","text":"Pause briefly at the top, then lower your shoulders slowly to a full stretch."}],"de":[{"title":"Aufbauen","text":"Steh aufrecht, in jeder Hand eine Kurzhantel neben dem Körper, Handflächen nach innen, Arme gestreckt."},{"title":"Hochziehen","text":"Zieh die Schultern so hoch wie möglich senkrecht Richtung Ohren. Nicht kreisen und die Ellbogen nicht beugen."},{"title":"Absenken","text":"Halt oben kurz und senk die Schultern dann langsam bis in die volle Dehnung."}],"pt-PT":[{"title":"Preparação","text":"Fica de pé, com um haltere em cada mão ao lado do corpo, palmas viradas para dentro e braços esticados."},{"title":"Encolher","text":"Sobe os ombros na vertical em direção às orelhas, o mais alto possível. Não rodes os ombros nem dobres os cotovelos."},{"title":"Descida","text":"Faz uma pausa curta em cima e depois desce os ombros devagar até alongar por completo."}],"pt-BR":[{"title":"Preparação","text":"Fique em pé, com um halter em cada mão ao lado do corpo, palmas voltadas para dentro e braços estendidos."},{"title":"Encolher","text":"Suba os ombros na vertical em direção às orelhas, o mais alto possível. Não gire os ombros nem dobre os cotovelos."},{"title":"Descida","text":"Faça uma pausa curta no alto e depois desça os ombros devagar até alongar por completo."}]}'::jsonb,
    'dumbbell', '{weight,reps}', '{"traps":0.9,"forearms":0.1}'::jsonb, 60),
  ('barbell-shrug', '{"en":"Barbell Shrug","de":"Shrugs mit Langhantel","pt-PT":"Encolhimento de ombros com barra","pt-BR":"Encolhimento com barra"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Hold the bar in front of your thighs with an overhand grip just outside shoulder width. Stand tall, arms straight."},{"title":"Shrug","text":"Lift your shoulders straight up towards your ears, keeping the bar close to your body. Don''t use your legs."},{"title":"Lower","text":"Hold the top for a moment, then lower slowly until your shoulders are fully down. Use straps if your grip gives out first."}],"de":[{"title":"Aufbauen","text":"Halt die Stange im Obergriff knapp breiter als schulterbreit vor den Oberschenkeln. Steh aufrecht, Arme gestreckt."},{"title":"Hochziehen","text":"Zieh die Schultern senkrecht Richtung Ohren, die Stange bleibt nah am Körper. Kein Schwung aus den Beinen."},{"title":"Absenken","text":"Halt oben kurz und senk die Schultern langsam ganz ab. Nimm Zughilfen, wenn der Griff zuerst nachgibt."}],"pt-PT":[{"title":"Preparação","text":"Segura a barra à frente das coxas em pronação, um pouco mais afastada do que os ombros. Fica direito, braços esticados."},{"title":"Encolher","text":"Sobe os ombros na vertical em direção às orelhas, com a barra junto ao corpo. Não dês impulso com as pernas."},{"title":"Descida","text":"Mantém um instante em cima e desce devagar até os ombros ficarem totalmente em baixo. Usa straps se a pega falhar primeiro."}],"pt-BR":[{"title":"Preparação","text":"Segure a barra à frente das coxas com pegada pronada, um pouco mais aberta que os ombros. Fique ereto, braços estendidos."},{"title":"Encolher","text":"Suba os ombros na vertical em direção às orelhas, com a barra perto do corpo. Não dê impulso com as pernas."},{"title":"Descida","text":"Segure um instante no alto e desça devagar até os ombros ficarem totalmente embaixo. Use straps se a pegada falhar antes."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"traps":0.9,"forearms":0.1}'::jsonb, 75),
  ('kelso-shrug', '{"en":"Kelso Shrug","de":"Kelso Shrugs","pt-PT":"Encolhimento Kelso","pt-BR":"Encolhimento Kelso"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Lie face down on an incline bench set to 30–45° with a dumbbell in each hand, arms hanging straight."},{"title":"Squeeze","text":"Pull your shoulder blades back and together without bending your elbows. Hold the squeeze for a second."},{"title":"Release","text":"Let your shoulder blades spread apart slowly until your shoulders reach forward."}],"de":[{"title":"Aufbauen","text":"Leg dich bäuchlings auf eine Schrägbank mit 30–45°, in jeder Hand eine Kurzhantel, die Arme hängen gestreckt."},{"title":"Zusammenziehen","text":"Zieh die Schulterblätter nach hinten zusammen, ohne die Ellbogen zu beugen. Halte die Spannung eine Sekunde."},{"title":"Lösen","text":"Lass die Schulterblätter langsam auseinandergehen, bis die Schultern nach vorne kommen."}],"pt-PT":[{"title":"Preparação","text":"Deita-te de barriga para baixo num banco inclinado a 30–45°, com um haltere em cada mão e os braços pendurados."},{"title":"Juntar","text":"Puxa as omoplatas para trás e junta-as sem dobrar os cotovelos. Mantém a contração durante um segundo."},{"title":"Soltar","text":"Deixa as omoplatas afastarem-se devagar até os ombros irem para a frente."}],"pt-BR":[{"title":"Preparação","text":"Deite de bruços em um banco inclinado a 30–45°, com um halter em cada mão e os braços pendurados."},{"title":"Juntar","text":"Puxe as escápulas para trás e junte-as sem dobrar os cotovelos. Segure a contração por um segundo."},{"title":"Soltar","text":"Deixe as escápulas se afastarem devagar até os ombros irem para a frente."}]}'::jsonb,
    'dumbbell', '{weight,reps}', '{"traps":0.6,"upper_back":0.4}'::jsonb, 60),
  ('wrist-curl', '{"en":"Wrist Curl","de":"Unterarmcurls","pt-PT":"Curl de pulso","pt-BR":"Rosca punho"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Sit on a bench and rest your forearms on your thighs, palms up, with your wrists just past your knees."},{"title":"Curl","text":"Hold the dumbbells and curl your wrists up as far as you can. Keep your forearms on your thighs."},{"title":"Lower","text":"Lower the dumbbells slowly and let them roll down to your fingertips for a full stretch."}],"de":[{"title":"Aufbauen","text":"Setz dich auf eine Bank und leg die Unterarme mit den Handflächen nach oben auf die Oberschenkel. Die Handgelenke ragen über die Knie."},{"title":"Beugen","text":"Halt die Kurzhanteln fest und beug die Handgelenke so weit wie möglich nach oben. Die Unterarme bleiben liegen."},{"title":"Absenken","text":"Senk die Hanteln langsam ab und lass sie für die volle Dehnung bis in die Fingerspitzen rollen."}],"pt-PT":[{"title":"Preparação","text":"Senta-te num banco e apoia os antebraços nas coxas, palmas para cima, com os pulsos logo depois dos joelhos."},{"title":"Subir","text":"Segura os halteres e dobra os pulsos para cima o máximo possível. Mantém os antebraços apoiados nas coxas."},{"title":"Descida","text":"Desce os halteres devagar e deixa-os rolar até às pontas dos dedos para alongar por completo."}],"pt-BR":[{"title":"Preparação","text":"Sente em um banco e apoie os antebraços nas coxas, palmas para cima, com os punhos logo depois dos joelhos."},{"title":"Subir","text":"Segure os halteres e dobre os punhos para cima o máximo possível. Mantenha os antebraços apoiados nas coxas."},{"title":"Descida","text":"Desça devagar e deixe os halteres rolarem até a ponta dos dedos para alongar por completo."}]}'::jsonb,
    'dumbbell', '{weight,reps}', '{"forearms":1.0}'::jsonb, 60),
  ('reverse-curl', '{"en":"Reverse Curl","de":"Reverse Curls","pt-PT":"Curl inverso","pt-BR":"Rosca inversa"}'::jsonb,
    '{"en":[{"title":"Grip","text":"Hold the bar with an overhand grip, hands shoulder-width apart, arms straight in front of your thighs."},{"title":"Curl","text":"Curl the bar up to your shoulders, keeping your elbows pinned to your sides and your wrists straight."},{"title":"Lower","text":"Lower the bar slowly to straight arms without swinging your torso."}],"de":[{"title":"Griff","text":"Greif die Stange schulterbreit im Obergriff, die Arme hängen gestreckt vor den Oberschenkeln."},{"title":"Curlen","text":"Curl die Stange bis zu den Schultern. Die Ellbogen bleiben am Körper, die Handgelenke gerade."},{"title":"Absenken","text":"Senk die Stange langsam, bis die Arme gestreckt sind, ohne mit dem Oberkörper zu schwingen."}],"pt-PT":[{"title":"Pega","text":"Agarra a barra em pronação, mãos à largura dos ombros, braços esticados à frente das coxas."},{"title":"Subir","text":"Leva a barra até aos ombros com os cotovelos colados ao corpo e os pulsos direitos."},{"title":"Descida","text":"Desce a barra devagar até os braços ficarem esticados, sem balançar o tronco."}],"pt-BR":[{"title":"Pegada","text":"Segure a barra com pegada pronada, mãos na largura dos ombros, braços estendidos à frente das coxas."},{"title":"Subir","text":"Leve a barra até os ombros com os cotovelos colados ao corpo e os punhos retos."},{"title":"Descida","text":"Desça a barra devagar até os braços ficarem estendidos, sem balançar o tronco."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"forearms":0.55,"biceps":0.45}'::jsonb, 60),
  ('dead-hang', '{"en":"Dead Hang","de":"Hängen an der Stange","pt-PT":"Suspensão na barra","pt-BR":"Suspensão na barra fixa"}'::jsonb,
    '{"en":[{"title":"Grip","text":"Grab a pull-up bar with an overhand grip at shoulder width and lift your feet off the floor."},{"title":"Hang","text":"Hang with straight arms and let your body stretch out. Keep your legs still and breathe slowly."},{"title":"Hold","text":"Keep squeezing the bar and stay still for the full time. Step down under control when your grip starts to fail."}],"de":[{"title":"Griff","text":"Greif die Klimmzugstange schulterbreit im Obergriff und nimm die Füße vom Boden."},{"title":"Hängen","text":"Häng mit gestreckten Armen und lass den Körper lang werden. Halt die Beine ruhig und atme langsam."},{"title":"Halten","text":"Greif die ganze Zeit fest zu und bleib ruhig hängen. Geh kontrolliert runter, wenn der Griff nachlässt."}],"pt-PT":[{"title":"Pega","text":"Agarra a barra de elevações em pronação, à largura dos ombros, e tira os pés do chão."},{"title":"Suspensão","text":"Fica suspenso com os braços esticados e deixa o corpo alongar. Mantém as pernas quietas e respira devagar."},{"title":"Manter","text":"Aperta bem a barra durante todo o tempo e não balances. Desce de forma controlada quando a pega começar a falhar."}],"pt-BR":[{"title":"Pegada","text":"Segure a barra fixa com pegada pronada, na largura dos ombros, e tire os pés do chão."},{"title":"Suspensão","text":"Fique pendurado com os braços estendidos e deixe o corpo alongar. Mantenha as pernas paradas e respire devagar."},{"title":"Segure","text":"Aperte bem a barra o tempo todo e não balance. Desça com controle quando a pegada começar a falhar."}]}'::jsonb,
    'bodyweight', '{seconds}', '{"forearms":0.75,"lats":0.15,"upper_back":0.1}'::jsonb, 60),
  ('power-clean', '{"en":"Power Clean","de":"Power Clean","pt-PT":"Power clean","pt-BR":"Power clean"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Bar over mid-foot, feet hip-width, grip just outside your legs. Hips above knees, chest up, back flat, arms straight."},{"title":"Pull","text":"Lift the bar smoothly past your knees, then extend your hips, knees and ankles explosively and shrug, keeping the bar close."},{"title":"Catch","text":"Pull yourself under, whip your elbows forward and catch the bar on your shoulders in a quarter squat. Stand up tall."}],"de":[{"title":"Aufbauen","text":"Stange über dem Mittelfuß, Füße hüftbreit, Griff direkt außerhalb der Beine. Hüfte über den Knien, Brust raus, Rücken gerade, Arme lang."},{"title":"Zug","text":"Heb die Stange ruhig über die Knie, dann streck Hüfte, Knie und Sprunggelenke explosiv und zieh die Schultern hoch. Die Stange bleibt nah am Körper."},{"title":"Fangen","text":"Zieh dich unter die Stange, bring die Ellbogen schnell nach vorne und fang sie in einer Viertelkniebeuge auf den Schultern. Dann aufrichten."}],"pt-PT":[{"title":"Preparação","text":"Barra sobre o meio do pé, pés à largura da anca, pega logo por fora das pernas. Anca acima dos joelhos, peito para cima, costas direitas."},{"title":"Puxada","text":"Levanta a barra de forma controlada até passar os joelhos e depois estende a anca, os joelhos e os tornozelos de forma explosiva, encolhendo os ombros."},{"title":"Receção","text":"Puxa-te para baixo da barra, roda os cotovelos à frente e recebe-a nos ombros num agachamento parcial. Endireita-te."}],"pt-BR":[{"title":"Preparação","text":"Barra sobre o meio do pé, pés na largura do quadril, pegada logo por fora das pernas. Quadril acima dos joelhos, peito para cima, costas retas."},{"title":"Puxada","text":"Levante a barra com controle até passar dos joelhos e então estenda quadril, joelhos e tornozelos de forma explosiva, encolhendo os ombros."},{"title":"Recepção","text":"Puxe o corpo para baixo da barra, gire os cotovelos à frente e receba a barra nos ombros em um agachamento parcial. Fique em pé."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"traps":0.3,"glutes":0.25,"hamstrings":0.25,"quads":0.2}'::jsonb, 150),
  ('hang-power-clean', '{"en":"Hang Power Clean","de":"Hang Power Clean","pt-PT":"Hang power clean","pt-BR":"Hang power clean"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Stand tall holding the bar overhand just outside your thighs. Hinge with a flat back until the bar is just above your knees."},{"title":"Pull","text":"Jump explosively by extending your hips, knees and ankles, then shrug and pull the bar up close to your body."},{"title":"Catch","text":"Drop under, whip your elbows forward and catch the bar on your shoulders in a quarter squat. Stand up, then lower back to the hang."}],"de":[{"title":"Aufbauen","text":"Steh aufrecht, die Stange im Obergriff knapp außerhalb der Oberschenkel. Beug dich mit geradem Rücken vor, bis sie knapp über den Knien ist."},{"title":"Zug","text":"Streck Hüfte, Knie und Sprunggelenke explosiv wie bei einem Sprung, zieh die Schultern hoch und führ die Stange nah am Körper nach oben."},{"title":"Fangen","text":"Tauch unter die Stange, bring die Ellbogen schnell nach vorne und fang sie in einer Viertelkniebeuge auf den Schultern. Aufrichten und zurück in die Ausgangsposition."}],"pt-PT":[{"title":"Preparação","text":"Fica de pé com a barra em pronação, mãos logo por fora das coxas. Inclina o tronco com as costas direitas até a barra ficar logo acima dos joelhos."},{"title":"Puxada","text":"Estende a anca, os joelhos e os tornozelos de forma explosiva, como num salto, encolhe os ombros e puxa a barra junto ao corpo."},{"title":"Receção","text":"Mete-te por baixo da barra, roda os cotovelos à frente e recebe-a nos ombros num agachamento parcial. Endireita-te e volta à posição inicial."}],"pt-BR":[{"title":"Preparação","text":"Fique em pé com a barra em pegada pronada, mãos logo por fora das coxas. Incline o tronco com as costas retas até a barra ficar logo acima dos joelhos."},{"title":"Puxada","text":"Estenda quadril, joelhos e tornozelos de forma explosiva, como em um salto, encolha os ombros e puxe a barra perto do corpo."},{"title":"Recepção","text":"Entre embaixo da barra, gire os cotovelos à frente e receba a barra nos ombros em um agachamento parcial. Fique em pé e volte à posição inicial."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"traps":0.35,"glutes":0.25,"hamstrings":0.25,"quads":0.15}'::jsonb, 150),
  ('clean', '{"en":"Clean","de":"Umsetzen","pt-PT":"Clean","pt-BR":"Clean"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Bar over mid-foot, feet hip-width, grip just outside your legs. Hips above knees, chest up, back flat."},{"title":"Pull","text":"Lift the bar past your knees with a steady push, then extend your hips, knees and ankles explosively, keeping it close."},{"title":"Catch","text":"Pull yourself into a full front squat, catching the bar on your shoulders with your elbows high. Stand up out of the squat."}],"de":[{"title":"Aufbauen","text":"Stange über dem Mittelfuß, Füße hüftbreit, Griff direkt außerhalb der Beine. Hüfte über den Knien, Brust raus, Rücken gerade."},{"title":"Zug","text":"Drück die Stange gleichmäßig über die Knie, dann streck Hüfte, Knie und Sprunggelenke explosiv. Die Stange bleibt nah am Körper."},{"title":"Fangen","text":"Zieh dich in eine tiefe Frontkniebeuge unter die Stange und fang sie mit hohen Ellbogen auf den Schultern. Steh aus der Hocke auf."}],"pt-PT":[{"title":"Preparação","text":"Barra sobre o meio do pé, pés à largura da anca, pega logo por fora das pernas. Anca acima dos joelhos, peito para cima, costas direitas."},{"title":"Puxada","text":"Levanta a barra até passar os joelhos com um empurrão constante e depois estende a anca, os joelhos e os tornozelos de forma explosiva, com a barra junto ao corpo."},{"title":"Receção","text":"Puxa-te para um agachamento frontal completo e recebe a barra nos ombros com os cotovelos altos. Levanta-te do agachamento."}],"pt-BR":[{"title":"Preparação","text":"Barra sobre o meio do pé, pés na largura do quadril, pegada logo por fora das pernas. Quadril acima dos joelhos, peito para cima, costas retas."},{"title":"Puxada","text":"Levante a barra até passar dos joelhos com um empurrão constante e então estenda quadril, joelhos e tornozelos de forma explosiva, com a barra perto do corpo."},{"title":"Recepção","text":"Puxe o corpo para um agachamento frontal completo e receba a barra nos ombros com os cotovelos altos. Levante do agachamento."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"quads":0.35,"glutes":0.25,"traps":0.25,"hamstrings":0.15}'::jsonb, 180),
  ('snatch', '{"en":"Snatch","de":"Reißen","pt-PT":"Arranque","pt-BR":"Arranco"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Take a wide grip so the bar sits in your hip crease when standing. Bar over mid-foot, hips low, chest up, back flat."},{"title":"Pull","text":"Lift the bar past your knees, then extend your hips, knees and ankles explosively and pull the bar up close to your body."},{"title":"Catch","text":"Pull yourself under and punch the bar overhead, catching it in a deep squat with locked arms. Stand up with the bar overhead."}],"de":[{"title":"Aufbauen","text":"Greif so breit, dass die Stange im Stand in der Hüftbeuge liegt. Stange über dem Mittelfuß, Hüfte tief, Brust raus, Rücken gerade."},{"title":"Zug","text":"Heb die Stange über die Knie, dann streck Hüfte, Knie und Sprunggelenke explosiv und zieh sie nah am Körper hoch."},{"title":"Fangen","text":"Zieh dich unter die Stange, stoß sie über den Kopf und fang sie mit gestreckten Armen in der tiefen Hocke. Steh mit der Stange über dem Kopf auf."}],"pt-PT":[{"title":"Preparação","text":"Faz uma pega larga, para que a barra fique na dobra da anca quando estás de pé. Barra sobre o meio do pé, anca baixa, peito para cima, costas direitas."},{"title":"Puxada","text":"Levanta a barra até passar os joelhos e depois estende a anca, os joelhos e os tornozelos de forma explosiva, puxando a barra junto ao corpo."},{"title":"Receção","text":"Puxa-te para baixo da barra e empurra-a acima da cabeça, recebendo-a num agachamento profundo com os braços bloqueados. Levanta-te com a barra acima da cabeça."}],"pt-BR":[{"title":"Preparação","text":"Use uma pegada aberta, para que a barra fique na dobra do quadril quando você está em pé. Barra sobre o meio do pé, quadril baixo, peito para cima, costas retas."},{"title":"Puxada","text":"Levante a barra até passar dos joelhos e então estenda quadril, joelhos e tornozelos de forma explosiva, puxando a barra perto do corpo."},{"title":"Recepção","text":"Puxe o corpo para baixo da barra e empurre-a acima da cabeça, recebendo em um agachamento profundo com os braços travados. Fique em pé com a barra acima da cabeça."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"quads":0.3,"glutes":0.25,"traps":0.25,"front_delts":0.2}'::jsonb, 180),
  ('clean-and-jerk', '{"en":"Clean and Jerk","de":"Umsetzen und Stoßen","pt-PT":"Arremesso","pt-BR":"Arremesso"}'::jsonb,
    '{"en":[{"title":"Clean","text":"Pull the bar from the floor and catch it on your shoulders in a front squat with your elbows high. Stand up and reset your grip."},{"title":"Dip","text":"With the bar on your shoulders, dip a few centimetres by bending your knees, torso upright, then drive up explosively."},{"title":"Jerk","text":"Push yourself under the bar into a split, catching it overhead with locked arms. Bring your feet together, then lower the bar."}],"de":[{"title":"Umsetzen","text":"Zieh die Stange vom Boden und fang sie mit hohen Ellbogen in der Frontkniebeuge auf den Schultern. Steh auf und korrigier den Griff."},{"title":"Dip","text":"Mit der Stange auf den Schultern beugst du die Knie ein paar Zentimeter, Oberkörper aufrecht, und drückst dich explosiv hoch."},{"title":"Stoßen","text":"Drück dich im Ausfallschritt unter die Stange und fang sie mit gestreckten Armen über dem Kopf. Füße zusammen, dann absetzen."}],"pt-PT":[{"title":"Clean","text":"Puxa a barra do chão e recebe-a nos ombros num agachamento frontal, com os cotovelos altos. Levanta-te e ajusta a pega."},{"title":"Impulso","text":"Com a barra nos ombros, dobra os joelhos alguns centímetros com o tronco direito e empurra para cima de forma explosiva."},{"title":"Jerk","text":"Mete-te por baixo da barra em afundo, recebendo-a com os braços bloqueados acima da cabeça. Junta os pés e depois baixa a barra."}],"pt-BR":[{"title":"Clean","text":"Puxe a barra do chão e receba nos ombros em um agachamento frontal, com os cotovelos altos. Levante e ajuste a pegada."},{"title":"Impulso","text":"Com a barra nos ombros, flexione os joelhos alguns centímetros com o tronco ereto e empurre para cima de forma explosiva."},{"title":"Jerk","text":"Entre embaixo da barra em tesoura, recebendo com os braços travados acima da cabeça. Junte os pés e depois abaixe a barra."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"quads":0.35,"glutes":0.25,"traps":0.2,"front_delts":0.2}'::jsonb, 180),
  ('dumbbell-thruster', '{"en":"Dumbbell Thruster","de":"Thrusters mit Kurzhanteln","pt-PT":"Thruster com halteres","pt-BR":"Thruster com halteres"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Hold a dumbbell in each hand at your shoulders, palms facing in, feet shoulder-width apart."},{"title":"Squat","text":"Squat down until your thighs are at least parallel, keeping your chest up and elbows forward."},{"title":"Press","text":"Drive up out of the squat and use that momentum to press the dumbbells overhead in one smooth motion. Lower them back to your shoulders."}],"de":[{"title":"Aufbauen","text":"Halt in jeder Hand eine Kurzhantel auf Schulterhöhe, Handflächen zueinander, Füße schulterbreit."},{"title":"Kniebeuge","text":"Geh in die Hocke, bis die Oberschenkel mindestens parallel zum Boden sind. Brust raus, Ellbogen nach vorne."},{"title":"Drücken","text":"Drück dich explosiv aus der Hocke hoch und nutz den Schwung, um die Hanteln in einer flüssigen Bewegung über den Kopf zu drücken. Dann zurück auf die Schultern."}],"pt-PT":[{"title":"Preparação","text":"Segura um haltere em cada mão junto aos ombros, palmas viradas para dentro, pés à largura dos ombros."},{"title":"Agachar","text":"Agacha até as coxas ficarem pelo menos paralelas ao chão, com o peito para cima e os cotovelos à frente."},{"title":"Empurrar","text":"Sai do agachamento com força e usa esse impulso para empurrar os halteres acima da cabeça num só movimento. Volta a baixá-los até aos ombros."}],"pt-BR":[{"title":"Preparação","text":"Segure um halter em cada mão na altura dos ombros, palmas voltadas para dentro, pés na largura dos ombros."},{"title":"Agachar","text":"Agache até as coxas ficarem pelo menos paralelas ao chão, com o peito para cima e os cotovelos à frente."},{"title":"Empurrar","text":"Saia do agachamento com força e use esse impulso para empurrar os halteres acima da cabeça em um só movimento. Volte a descê-los até os ombros."}]}'::jsonb,
    'dumbbell', '{weight,reps}', '{"quads":0.4,"front_delts":0.25,"glutes":0.2,"triceps":0.15}'::jsonb, 90),
  ('box-jump', '{"en":"Box Jump","de":"Box Jumps","pt-PT":"Salto para a caixa","pt-BR":"Salto na caixa"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Stand about 30 cm from a sturdy box, feet hip-width apart."},{"title":"Jump","text":"Swing your arms back, dip into a quarter squat and jump onto the box. Land softly with both feet flat and knees bent."},{"title":"Step down","text":"Stand up fully on the box, then step down one foot at a time. Reset before the next jump."}],"de":[{"title":"Aufbauen","text":"Stell dich etwa 30 cm vor eine stabile Box, Füße hüftbreit."},{"title":"Springen","text":"Schwing die Arme nach hinten, geh leicht in die Knie und spring auf die Box. Lande weich mit ganzen Füßen und gebeugten Knien."},{"title":"Absteigen","text":"Richte dich auf der Box ganz auf und steig dann Fuß für Fuß herunter. Stell dich vor jedem Sprung neu hin."}],"pt-PT":[{"title":"Preparação","text":"Fica a cerca de 30 cm de uma caixa estável, com os pés à largura da anca."},{"title":"Saltar","text":"Leva os braços atrás, dobra ligeiramente os joelhos e salta para a caixa. Aterra suavemente com os pés inteiros e os joelhos fletidos."},{"title":"Descer","text":"Endireita-te em cima da caixa e desce um pé de cada vez. Reposiciona-te antes do salto seguinte."}],"pt-BR":[{"title":"Preparação","text":"Fique a cerca de 30 cm de uma caixa firme, com os pés na largura do quadril."},{"title":"Saltar","text":"Leve os braços para trás, flexione levemente os joelhos e salte para cima da caixa. Aterrisse com suavidade, pés inteiros e joelhos flexionados."},{"title":"Descer","text":"Fique totalmente em pé sobre a caixa e desça um pé de cada vez. Reposicione-se antes do próximo salto."}]}'::jsonb,
    'bodyweight', '{reps}', '{"quads":0.45,"glutes":0.3,"calves":0.25}'::jsonb, 60),
  ('kettlebell-swing', '{"en":"Kettlebell Swing","de":"Kettlebell Swing","pt-PT":"Swing com kettlebell","pt-BR":"Swing com kettlebell"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Stand with feet slightly wider than hips, the kettlebell a little in front of you. Hinge, grab the handle with both hands and tilt it towards you."},{"title":"Swing","text":"Hike the bell back between your legs, then snap your hips forward to swing it to chest height. Arms stay straight and relaxed."},{"title":"Control","text":"Let the bell fall back and hinge as it passes between your legs. Keep your back flat and your heels down."}],"de":[{"title":"Aufbauen","text":"Füße etwas breiter als hüftbreit, die Kettlebell leicht vor dir. Beug dich aus der Hüfte vor, greif sie mit beiden Händen und kipp sie zu dir."},{"title":"Schwingen","text":"Schwing die Kettlebell zwischen den Beinen nach hinten und streck dann explosiv die Hüfte, sodass sie bis auf Brusthöhe schwingt. Arme gestreckt und locker."},{"title":"Kontrolle","text":"Lass die Kettlebell zurückfallen und schieb die Hüfte nach hinten, sobald sie zwischen die Beine kommt. Rücken gerade, Fersen am Boden."}],"pt-PT":[{"title":"Preparação","text":"Pés um pouco mais afastados do que a anca, kettlebell ligeiramente à frente. Leva a anca atrás, agarra a pega com as duas mãos e inclina-o na tua direção."},{"title":"Balanço","text":"Leva o kettlebell para trás entre as pernas e depois estende a anca de forma explosiva para o balançar até à altura do peito. Braços esticados e soltos."},{"title":"Controlo","text":"Deixa o kettlebell cair e leva a anca atrás quando ele passar entre as pernas. Costas direitas e calcanhares no chão."}],"pt-BR":[{"title":"Preparação","text":"Pés um pouco mais abertos que o quadril, kettlebell levemente à frente. Leve o quadril para trás, segure a alça com as duas mãos e incline-o na sua direção."},{"title":"Balanço","text":"Leve o kettlebell para trás entre as pernas e depois estenda o quadril de forma explosiva para balançá-lo até a altura do peito. Braços estendidos e soltos."},{"title":"Controle","text":"Deixe o kettlebell descer e leve o quadril para trás quando ele passar entre as pernas. Costas retas e calcanhares no chão."}]}'::jsonb,
    'kettlebell', '{weight,reps}', '{"glutes":0.45,"hamstrings":0.3,"lower_back":0.15,"forearms":0.1}'::jsonb, 60),
  ('farmers-walk', '{"en":"Farmer''s Walk","de":"Farmer''s Walk","pt-PT":"Caminhada do agricultor","pt-BR":"Caminhada do fazendeiro"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Deadlift a heavy dumbbell in each hand up to your sides. Stand tall with your shoulders back and down."},{"title":"Walk","text":"Walk with short, quick steps for the set time, keeping your torso upright and the weights still."},{"title":"Hold form","text":"Grip hard, brace your abs and don''t lean to either side. When time is up, set the weights down with a flat back."}],"de":[{"title":"Aufbauen","text":"Heb in jeder Hand eine schwere Kurzhantel mit geradem Rücken vom Boden auf. Steh aufrecht, Schultern zurück und unten."},{"title":"Gehen","text":"Geh mit kurzen, schnellen Schritten für die vorgegebene Zeit. Oberkörper aufrecht, die Hanteln schwingen nicht."},{"title":"Haltung","text":"Greif fest zu, spann den Bauch an und lehn dich zu keiner Seite. Stell die Hanteln am Ende mit geradem Rücken ab."}],"pt-PT":[{"title":"Preparação","text":"Levanta do chão um haltere pesado em cada mão, com as costas direitas. Fica direito, ombros para trás e para baixo."},{"title":"Caminhar","text":"Caminha com passos curtos e rápidos durante o tempo definido, com o tronco direito e os halteres sem balançar."},{"title":"Postura","text":"Aperta bem as pegas, contrai o abdómen e não te inclines para nenhum lado. No fim, pousa os halteres com as costas direitas."}],"pt-BR":[{"title":"Preparação","text":"Levante do chão um halter pesado em cada mão, com as costas retas. Fique ereto, ombros para trás e para baixo."},{"title":"Caminhar","text":"Caminhe com passos curtos e rápidos durante o tempo definido, com o tronco ereto e os halteres sem balançar."},{"title":"Postura","text":"Aperte bem os halteres, contraia o abdômen e não incline para nenhum lado. No fim, apoie os halteres no chão com as costas retas."}]}'::jsonb,
    'dumbbell', '{weight,seconds}', '{"forearms":0.4,"traps":0.3,"abs":0.15,"obliques":0.15}'::jsonb, 90),
  ('burpee', '{"en":"Burpee","de":"Burpees","pt-PT":"Burpee","pt-BR":"Burpee"}'::jsonb,
    '{"en":[{"title":"Drop","text":"From standing, squat down and place your hands on the floor in front of your feet."},{"title":"Push-up","text":"Jump your feet back into a plank, do a push-up with your body in a straight line, then jump your feet back to your hands."},{"title":"Jump","text":"Stand up and jump explosively, clapping overhead. Land softly and go straight into the next rep."}],"de":[{"title":"Runter","text":"Geh aus dem Stand in die Hocke und setz die Hände vor den Füßen auf den Boden."},{"title":"Liegestütz","text":"Spring mit den Füßen nach hinten in den Stütz, mach einen Liegestütz mit geradem Körper und spring mit den Füßen zurück zu den Händen."},{"title":"Springen","text":"Richte dich auf, spring explosiv nach oben und klatsch über dem Kopf in die Hände. Lande weich und geh direkt in die nächste Wiederholung."}],"pt-PT":[{"title":"Descer","text":"De pé, agacha-te e apoia as mãos no chão à frente dos pés."},{"title":"Flexão","text":"Salta com os pés para trás até à posição de prancha, faz uma flexão com o corpo em linha reta e volta a saltar com os pés até às mãos."},{"title":"Saltar","text":"Levanta-te e salta de forma explosiva, batendo as palmas acima da cabeça. Aterra suavemente e passa logo à repetição seguinte."}],"pt-BR":[{"title":"Descer","text":"Em pé, agache e apoie as mãos no chão à frente dos pés."},{"title":"Flexão","text":"Jogue os pés para trás até a posição de prancha, faça uma flexão com o corpo em linha reta e traga os pés de volta até as mãos com um salto."},{"title":"Saltar","text":"Levante e salte de forma explosiva, batendo palmas acima da cabeça. Aterrisse com suavidade e já comece a próxima repetição."}]}'::jsonb,
    'bodyweight', '{reps}', '{"quads":0.35,"chest":0.25,"glutes":0.2,"abs":0.2}'::jsonb, 45),
  ('jumping-jack', '{"en":"Jumping Jack","de":"Hampelmänner","pt-PT":"Jumping jacks","pt-BR":"Polichinelo"}'::jsonb,
    '{"en":[{"title":"Start","text":"Stand tall with your feet together and your arms by your sides."},{"title":"Jump","text":"Jump your feet out wider than your shoulders while swinging your arms overhead, then jump back to the start."},{"title":"Keep going","text":"Stay light on the balls of your feet and keep a steady rhythm for the whole time. Breathe evenly."}],"de":[{"title":"Start","text":"Steh aufrecht, die Füße zusammen, die Arme neben dem Körper."},{"title":"Springen","text":"Spring mit den Füßen breiter als schulterbreit auseinander und schwing die Arme über den Kopf. Dann zurück in die Ausgangsposition springen."},{"title":"Dranbleiben","text":"Bleib leicht auf den Fußballen und halte die ganze Zeit einen gleichmäßigen Rhythmus. Atme ruhig weiter."}],"pt-PT":[{"title":"Início","text":"Fica de pé, com os pés juntos e os braços ao lado do corpo."},{"title":"Saltar","text":"Salta abrindo os pés para além da largura dos ombros e leva os braços acima da cabeça. Depois salta de volta à posição inicial."},{"title":"Ritmo","text":"Mantém-te leve na parte da frente dos pés e com um ritmo constante durante todo o tempo. Respira de forma regular."}],"pt-BR":[{"title":"Início","text":"Fique em pé, com os pés juntos e os braços ao lado do corpo."},{"title":"Saltar","text":"Salte abrindo os pés além da largura dos ombros e leve os braços acima da cabeça. Depois salte de volta à posição inicial."},{"title":"Ritmo","text":"Fique leve na ponta dos pés e mantenha um ritmo constante durante todo o tempo. Respire de forma regular."}]}'::jsonb,
    'bodyweight', '{seconds}', '{"calves":0.4,"glutes":0.2,"side_delts":0.2,"adductors":0.2}'::jsonb, 30),
  ('high-knees', '{"en":"High Knees","de":"Kniehebelauf","pt-PT":"Skipping alto","pt-BR":"Skipping alto"}'::jsonb,
    '{"en":[{"title":"Start","text":"Stand tall with your feet hip-width apart and your arms bent at 90°."},{"title":"Run","text":"Run on the spot, driving each knee up to hip height while pumping your arms."},{"title":"Keep going","text":"Stay on the balls of your feet with your torso upright. Keep the pace high for the whole time without leaning back."}],"de":[{"title":"Start","text":"Steh aufrecht, Füße hüftbreit, die Arme im 90°-Winkel gebeugt."},{"title":"Laufen","text":"Lauf auf der Stelle und zieh die Knie abwechselnd bis auf Hüfthöhe. Die Arme schwingen aktiv mit."},{"title":"Dranbleiben","text":"Bleib auf den Fußballen, der Oberkörper bleibt aufrecht. Halte das Tempo die ganze Zeit hoch, ohne dich nach hinten zu lehnen."}],"pt-PT":[{"title":"Início","text":"Fica de pé, com os pés à largura da anca e os braços fletidos a 90°."},{"title":"Correr","text":"Corre no mesmo sítio, levando cada joelho até à altura da anca e balançando os braços."},{"title":"Ritmo","text":"Mantém-te na parte da frente dos pés com o tronco direito. Mantém o ritmo alto durante todo o tempo, sem te inclinares para trás."}],"pt-BR":[{"title":"Início","text":"Fique em pé, com os pés na largura do quadril e os braços flexionados a 90°."},{"title":"Correr","text":"Corra parado no lugar, levando cada joelho até a altura do quadril e balançando os braços."},{"title":"Ritmo","text":"Fique na ponta dos pés com o tronco ereto. Mantenha o ritmo alto durante todo o tempo, sem inclinar o corpo para trás."}]}'::jsonb,
    'bodyweight', '{seconds}', '{"quads":0.35,"calves":0.3,"abs":0.2,"glutes":0.15}'::jsonb, 30),
  ('jump-rope', '{"en":"Jump Rope","de":"Seilspringen","pt-PT":"Saltar à corda","pt-BR":"Pular corda"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Hold a handle in each hand with the rope behind your heels. Elbows close to your sides, hands at hip height."},{"title":"Jump","text":"Turn the rope with your wrists and jump just high enough to clear it, landing softly on the balls of your feet."},{"title":"Keep going","text":"Keep a steady rhythm for the whole time, knees slightly bent and shoulders relaxed. If you trip, start again right away."}],"de":[{"title":"Aufbauen","text":"Nimm in jede Hand einen Griff, das Seil liegt hinter den Fersen. Ellbogen nah am Körper, Hände auf Hüfthöhe."},{"title":"Springen","text":"Dreh das Seil aus den Handgelenken und spring nur so hoch, dass es durchpasst. Lande weich auf den Fußballen."},{"title":"Dranbleiben","text":"Halte die ganze Zeit einen gleichmäßigen Rhythmus, Knie leicht gebeugt, Schultern locker. Wenn du hängen bleibst, mach sofort weiter."}],"pt-PT":[{"title":"Preparação","text":"Segura uma pega em cada mão, com a corda atrás dos calcanhares. Cotovelos junto ao corpo, mãos à altura da anca."},{"title":"Saltar","text":"Roda a corda com os pulsos e salta só o suficiente para ela passar, aterrando suavemente na parte da frente dos pés."},{"title":"Ritmo","text":"Mantém um ritmo constante durante todo o tempo, joelhos ligeiramente fletidos e ombros relaxados. Se falhares, recomeça logo."}],"pt-BR":[{"title":"Preparação","text":"Segure um pegador em cada mão, com a corda atrás dos calcanhares. Cotovelos perto do corpo, mãos na altura do quadril."},{"title":"Pular","text":"Gire a corda com os punhos e pule só o suficiente para ela passar, aterrissando com suavidade na ponta dos pés."},{"title":"Ritmo","text":"Mantenha um ritmo constante durante todo o tempo, joelhos levemente flexionados e ombros relaxados. Se errar, recomece na hora."}]}'::jsonb,
    'bodyweight', '{seconds}', '{"calves":0.65,"quads":0.2,"forearms":0.15}'::jsonb, 45),
  ('barbell-curl', '{"en":"Barbell Curl","de":"Langhantel-Curls","pt-PT":"Curl com barra","pt-BR":"Rosca direta"}'::jsonb,
    '{"en":[{"title":"Grip","text":"Stand tall and hold the bar with an underhand grip, hands shoulder-width apart, arms straight."},{"title":"Curl","text":"Curl the bar towards your shoulders, keeping your elbows at your sides and your torso still."},{"title":"Lower","text":"Lower the bar slowly until your arms are fully straight. Don''t lean back to start the next rep."}],"de":[{"title":"Greifen","text":"Steh aufrecht und greif die Stange schulterbreit im Untergriff, die Arme gestreckt."},{"title":"Beugen","text":"Beug die Arme und heb die Stange Richtung Schultern. Die Ellbogen bleiben am Körper, der Oberkörper ruhig."},{"title":"Absenken","text":"Senk die Stange langsam ab, bis die Arme ganz gestreckt sind. Hol keinen Schwung mit dem Rücken."}],"pt-PT":[{"title":"Pega","text":"Fica de pé e agarra a barra em pega supinada, com as mãos à largura dos ombros e os braços esticados."},{"title":"Fletir","text":"Flete os cotovelos e leva a barra até aos ombros, com os cotovelos junto ao corpo e o tronco imóvel."},{"title":"Descida","text":"Desce a barra devagar até esticares os braços por completo. Não balances o tronco para trás."}],"pt-BR":[{"title":"Pegada","text":"Fique em pé e segure a barra com pegada supinada, mãos na largura dos ombros e braços estendidos."},{"title":"Flexionar","text":"Flexione os cotovelos e leve a barra até os ombros, com os cotovelos colados ao corpo e o tronco parado."},{"title":"Descida","text":"Desça a barra devagar até estender totalmente os braços. Não jogue o tronco para trás."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"biceps":0.85,"forearms":0.15}'::jsonb, 75),
  ('ez-bar-curl', '{"en":"EZ-Bar Curl","de":"SZ-Curls","pt-PT":"Curl com barra EZ","pt-BR":"Rosca direta com barra W"}'::jsonb,
    '{"en":[{"title":"Grip","text":"Hold the EZ bar on the inner angled grips, palms facing up and slightly in, arms straight."},{"title":"Curl","text":"Curl the bar up to shoulder height with your elbows pinned to your sides. Keep your wrists neutral."},{"title":"Lower","text":"Lower the bar over about two seconds until your arms are straight again."}],"de":[{"title":"Greifen","text":"Greif die SZ-Stange an den inneren Knicken im Untergriff, die Arme hängen gestreckt vor dem Körper."},{"title":"Beugen","text":"Beug die Arme und heb die Stange bis auf Schulterhöhe. Die Ellbogen bleiben am Körper, die Handgelenke gerade."},{"title":"Absenken","text":"Senk die Stange in etwa zwei Sekunden ab, bis die Arme wieder gestreckt sind."}],"pt-PT":[{"title":"Pega","text":"Agarra a barra EZ nas curvas interiores, palmas para cima e ligeiramente viradas para dentro, braços esticados."},{"title":"Fletir","text":"Flete os cotovelos e sobe a barra até à altura dos ombros, com os cotovelos junto ao corpo e os pulsos alinhados."},{"title":"Descida","text":"Desce a barra em cerca de dois segundos até os braços ficarem esticados outra vez."}],"pt-BR":[{"title":"Pegada","text":"Segure a barra W nas curvas internas, palmas para cima e levemente voltadas para dentro, braços estendidos."},{"title":"Flexionar","text":"Flexione os cotovelos e suba a barra até a altura dos ombros, com os cotovelos colados ao corpo e os punhos alinhados."},{"title":"Descida","text":"Desça a barra em cerca de dois segundos até os braços ficarem estendidos de novo."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"biceps":0.8,"forearms":0.2}'::jsonb, 75),
  ('incline-dumbbell-curl', '{"en":"Incline Dumbbell Curl","de":"Schrägbank-Curls","pt-PT":"Curl inclinado com halteres","pt-BR":"Rosca inclinada com halteres"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Sit back on a bench set to about 45–60°. Let your arms hang straight down with your palms facing forward."},{"title":"Curl","text":"Curl the dumbbells up without letting your elbows drift forward. Keep your head and back on the bench."},{"title":"Lower","text":"Lower slowly until your arms hang straight down again and you feel a stretch in your biceps."}],"de":[{"title":"Aufbauen","text":"Setz dich auf eine Schrägbank mit etwa 45–60° und lehn dich an. Die Arme hängen gestreckt nach unten, Handflächen nach vorn."},{"title":"Beugen","text":"Beug die Arme und heb die Hanteln, ohne die Ellbogen nach vorn zu schieben. Kopf und Rücken bleiben an der Bank."},{"title":"Absenken","text":"Senk die Hanteln langsam ab, bis die Arme wieder gestreckt nach unten hängen und du die Dehnung im Bizeps spürst."}],"pt-PT":[{"title":"Preparação","text":"Senta-te num banco inclinado a 45–60° e encosta as costas. Deixa os braços pendurados, com as palmas viradas para a frente."},{"title":"Fletir","text":"Flete os cotovelos e sobe os halteres sem levar os cotovelos para a frente. Mantém a cabeça e as costas no banco."},{"title":"Descida","text":"Desce devagar até os braços voltarem a ficar esticados e sentires o alongamento no bíceps."}],"pt-BR":[{"title":"Preparação","text":"Sente em um banco inclinado a 45–60° e apoie as costas. Deixe os braços pendurados, com as palmas voltadas para a frente."},{"title":"Flexionar","text":"Flexione os cotovelos e suba os halteres sem levar os cotovelos para a frente. Mantenha a cabeça e as costas no banco."},{"title":"Descida","text":"Desça devagar até os braços ficarem estendidos de novo e você sentir o alongamento no bíceps."}]}'::jsonb,
    'dumbbell', '{weight,reps}', '{"biceps":0.9,"forearms":0.1}'::jsonb, 60),
  ('concentration-curl', '{"en":"Concentration Curl","de":"Konzentrationscurls","pt-PT":"Curl concentrado","pt-BR":"Rosca concentrada"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Sit on a bench, lean forward and brace the back of your upper arm against your inner thigh."},{"title":"Curl","text":"Curl the dumbbell towards your shoulder without moving your upper arm. Squeeze your biceps at the top."},{"title":"Lower","text":"Lower slowly until your arm is straight. Finish all reps before switching arms."}],"de":[{"title":"Aufbauen","text":"Setz dich auf eine Bank, beug dich vor und stütz die Rückseite des Oberarms an der Innenseite des Oberschenkels ab."},{"title":"Beugen","text":"Beug den Arm und führ die Hantel zur Schulter, ohne den Oberarm zu bewegen. Oben den Bizeps fest anspannen."},{"title":"Absenken","text":"Senk die Hantel langsam ab, bis der Arm gestreckt ist. Mach alle Wiederholungen, bevor du die Seite wechselst."}],"pt-PT":[{"title":"Preparação","text":"Senta-te num banco, inclina-te para a frente e apoia a parte de trás do braço na face interna da coxa."},{"title":"Fletir","text":"Flete o cotovelo e leva o haltere ao ombro sem mexer o braço. Contrai bem o bíceps em cima."},{"title":"Descida","text":"Desce devagar até o braço ficar esticado. Faz todas as repetições antes de trocar de braço."}],"pt-BR":[{"title":"Preparação","text":"Sente em um banco, incline o tronco para a frente e apoie a parte de trás do braço na parte interna da coxa."},{"title":"Flexionar","text":"Flexione o cotovelo e leve o halter até o ombro sem mexer o braço. Contraia bem o bíceps no alto."},{"title":"Descida","text":"Desça devagar até estender o braço. Faça todas as repetições antes de trocar de lado."}]}'::jsonb,
    'dumbbell', '{weight,reps}', '{"biceps":0.9,"forearms":0.1}'::jsonb, 60),
  ('spider-curl', '{"en":"Spider Curl","de":"Spider Curls","pt-PT":"Curl spider","pt-BR":"Rosca spider"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Lie chest down on an incline bench set to about 45°, chest at the top edge, arms hanging straight down."},{"title":"Curl","text":"Curl the dumbbells up while your upper arms stay vertical. Squeeze hard at the top."},{"title":"Lower","text":"Lower slowly until your arms are straight again. Keep your chest on the pad for the whole set."}],"de":[{"title":"Aufbauen","text":"Leg dich bäuchlings auf eine Schrägbank mit etwa 45°, die Brust an der oberen Kante. Die Arme hängen senkrecht nach unten."},{"title":"Beugen","text":"Beug die Arme und heb die Hanteln, während die Oberarme senkrecht bleiben. Oben fest anspannen."},{"title":"Absenken","text":"Senk die Hanteln langsam ab, bis die Arme wieder gestreckt sind. Die Brust bleibt den ganzen Satz auf dem Polster."}],"pt-PT":[{"title":"Preparação","text":"Deita-te de barriga para baixo num banco inclinado a cerca de 45°, peito na borda de cima e braços pendurados na vertical."},{"title":"Fletir","text":"Flete os cotovelos e sobe os halteres mantendo os braços na vertical. Contrai bem em cima."},{"title":"Descida","text":"Desce devagar até esticares os braços. Mantém o peito apoiado no banco durante toda a série."}],"pt-BR":[{"title":"Preparação","text":"Deite de bruços em um banco inclinado a cerca de 45°, com o peito na borda de cima e os braços pendurados na vertical."},{"title":"Flexionar","text":"Flexione os cotovelos e suba os halteres mantendo os braços na vertical. Contraia bem no alto."},{"title":"Descida","text":"Desça devagar até estender os braços. Mantenha o peito apoiado no banco durante toda a série."}]}'::jsonb,
    'dumbbell', '{weight,reps}', '{"biceps":0.9,"forearms":0.1}'::jsonb, 60),
  ('drag-curl', '{"en":"Drag Curl","de":"Drag Curls","pt-PT":"Curl drag","pt-BR":"Rosca drag"}'::jsonb,
    '{"en":[{"title":"Grip","text":"Stand tall and hold the bar with an underhand grip, hands shoulder-width apart, bar against your thighs."},{"title":"Drag","text":"Pull your elbows back and drag the bar up along your torso to your lower chest. Keep the bar touching your body."},{"title":"Lower","text":"Slide the bar back down your body under control until your arms are straight."}],"de":[{"title":"Greifen","text":"Steh aufrecht und greif die Stange schulterbreit im Untergriff. Die Stange liegt an den Oberschenkeln."},{"title":"Hochziehen","text":"Zieh die Ellbogen nach hinten und führ die Stange am Körper entlang bis zur unteren Brust. Die Stange bleibt am Körper."},{"title":"Absenken","text":"Führ die Stange kontrolliert am Körper entlang zurück, bis die Arme gestreckt sind."}],"pt-PT":[{"title":"Pega","text":"Fica de pé e agarra a barra em pega supinada, mãos à largura dos ombros, com a barra encostada às coxas."},{"title":"Arrastar","text":"Leva os cotovelos para trás e sobe a barra rente ao tronco até à parte inferior do peito, sem a afastar do corpo."},{"title":"Descida","text":"Desce a barra rente ao corpo, de forma controlada, até os braços ficarem esticados."}],"pt-BR":[{"title":"Pegada","text":"Fique em pé e segure a barra com pegada supinada, mãos na largura dos ombros e barra encostada nas coxas."},{"title":"Arrastar","text":"Leve os cotovelos para trás e suba a barra rente ao tronco até a parte baixa do peito, sem afastá-la do corpo."},{"title":"Descida","text":"Desça a barra rente ao corpo, com controle, até estender os braços."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"biceps":0.85,"forearms":0.15}'::jsonb, 60),
  ('zottman-curl', '{"en":"Zottman Curl","de":"Zottman Curls","pt-PT":"Curl Zottman","pt-BR":"Rosca Zottman"}'::jsonb,
    '{"en":[{"title":"Curl up","text":"Hold the dumbbells at your sides, palms facing forward. Curl them up to your shoulders, elbows at your sides."},{"title":"Rotate","text":"At the top, turn your wrists so your palms face down. Keep your elbows still."},{"title":"Lower","text":"Lower slowly with your palms down until your arms are straight, then turn your palms forward again."}],"de":[{"title":"Beugen","text":"Halt die Kurzhanteln seitlich, Handflächen nach vorn. Beug die Arme und führ die Hanteln zu den Schultern."},{"title":"Drehen","text":"Dreh oben die Handgelenke, sodass die Handflächen nach unten zeigen. Die Ellbogen bleiben ruhig."},{"title":"Absenken","text":"Senk die Hanteln im Obergriff langsam ab, bis die Arme gestreckt sind. Dreh dann die Handflächen wieder nach vorn."}],"pt-PT":[{"title":"Fletir","text":"Segura os halteres ao lado do corpo, palmas para a frente. Flete os cotovelos e leva os halteres até aos ombros."},{"title":"Rodar","text":"Em cima, roda os pulsos para que as palmas fiquem viradas para baixo. Mantém os cotovelos imóveis."},{"title":"Descida","text":"Desce devagar com as palmas para baixo até esticares os braços. Depois volta a rodar as palmas para a frente."}],"pt-BR":[{"title":"Flexionar","text":"Segure os halteres ao lado do corpo, palmas para a frente. Flexione os cotovelos e leve os pesos até os ombros."},{"title":"Girar","text":"No alto, gire os punhos para que as palmas fiquem voltadas para baixo. Mantenha os cotovelos parados."},{"title":"Descida","text":"Desça devagar com as palmas para baixo até estender os braços. Depois gire as palmas para a frente de novo."}]}'::jsonb,
    'dumbbell', '{weight,reps}', '{"biceps":0.65,"forearms":0.35}'::jsonb, 60),
  ('preacher-curl', '{"en":"Preacher Curl","de":"Scottcurls","pt-PT":"Curl Scott","pt-BR":"Rosca Scott"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Sit at the preacher bench with your armpits snug against the top of the pad. Hold the bar with an underhand grip."},{"title":"Curl","text":"Curl the bar up until your forearms are nearly vertical. Keep the backs of your arms on the pad."},{"title":"Lower","text":"Lower slowly to an almost straight arm. Don''t let the bar drop into the bottom position."}],"de":[{"title":"Aufbauen","text":"Setz dich an die Scottbank, die Achseln liegen eng am oberen Rand des Polsters. Greif die Stange im Untergriff."},{"title":"Beugen","text":"Beug die Arme, bis die Unterarme fast senkrecht stehen. Die Oberarme bleiben flach auf dem Polster."},{"title":"Absenken","text":"Senk die Stange langsam ab, bis die Arme fast gestreckt sind. Lass sie unten nicht durchfallen."}],"pt-PT":[{"title":"Preparação","text":"Senta-te no banco Scott com as axilas encostadas ao topo da almofada. Agarra a barra em pega supinada."},{"title":"Fletir","text":"Flete os cotovelos até os antebraços ficarem quase na vertical. Mantém a parte de trás dos braços na almofada."},{"title":"Descida","text":"Desce devagar até os braços ficarem quase esticados. Não deixes a barra cair no fim."}],"pt-BR":[{"title":"Preparação","text":"Sente no banco Scott com as axilas encostadas no topo do apoio. Segure a barra com pegada supinada."},{"title":"Flexionar","text":"Flexione os cotovelos até os antebraços ficarem quase na vertical. Mantenha a parte de trás dos braços no apoio."},{"title":"Descida","text":"Desça devagar até os braços ficarem quase estendidos. Não deixe a barra despencar no final."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"biceps":0.9,"forearms":0.1}'::jsonb, 60),
  ('dumbbell-preacher-curl', '{"en":"Dumbbell Preacher Curl","de":"Scottcurls mit Kurzhantel","pt-PT":"Curl Scott com haltere","pt-BR":"Rosca Scott com halter"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Sit at the preacher bench and rest the back of one upper arm flat on the pad, dumbbell in hand, palm up."},{"title":"Curl","text":"Curl the dumbbell up until your forearm is nearly vertical. Keep your upper arm and shoulder still."},{"title":"Lower","text":"Lower slowly to an almost straight arm, then repeat. Switch arms after the set."}],"de":[{"title":"Aufbauen","text":"Setz dich an die Scottbank und leg einen Oberarm flach aufs Polster. Halt die Kurzhantel im Untergriff."},{"title":"Beugen","text":"Beug den Arm, bis der Unterarm fast senkrecht steht. Oberarm und Schulter bleiben ruhig."},{"title":"Absenken","text":"Senk die Hantel langsam ab, bis der Arm fast gestreckt ist. Wechsle nach dem Satz die Seite."}],"pt-PT":[{"title":"Preparação","text":"Senta-te no banco Scott e apoia a parte de trás de um braço na almofada, com o haltere na mão e a palma para cima."},{"title":"Fletir","text":"Flete o cotovelo até o antebraço ficar quase na vertical. Mantém o braço e o ombro imóveis."},{"title":"Descida","text":"Desce devagar até o braço ficar quase esticado. Troca de braço no fim da série."}],"pt-BR":[{"title":"Preparação","text":"Sente no banco Scott e apoie a parte de trás de um braço na almofada, com o halter na mão e a palma para cima."},{"title":"Flexionar","text":"Flexione o cotovelo até o antebraço ficar quase na vertical. Mantenha o braço e o ombro parados."},{"title":"Descida","text":"Desça devagar até o braço ficar quase estendido. Troque de lado no fim da série."}]}'::jsonb,
    'dumbbell', '{weight,reps}', '{"biceps":0.9,"forearms":0.1}'::jsonb, 60),
  ('machine-curl', '{"en":"Biceps Curl Machine","de":"Bizepsmaschine","pt-PT":"Curl de bíceps na máquina","pt-BR":"Rosca bíceps na máquina"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Adjust the seat so your elbows line up with the machine''s pivot and your upper arms rest flat on the pad."},{"title":"Curl","text":"Grip the handles and curl them towards your shoulders without lifting your elbows off the pad."},{"title":"Lower","text":"Lower slowly until your arms are almost straight, keeping tension on your biceps."}],"de":[{"title":"Einstellen","text":"Stell den Sitz so ein, dass deine Ellbogen auf Höhe der Drehachse sind und die Oberarme flach auf dem Polster liegen."},{"title":"Beugen","text":"Greif die Griffe und beug die Arme Richtung Schultern, ohne die Ellbogen vom Polster zu heben."},{"title":"Absenken","text":"Lass die Griffe langsam zurück, bis die Arme fast gestreckt sind. Die Spannung im Bizeps bleibt."}],"pt-PT":[{"title":"Ajustar","text":"Ajusta o banco para que os cotovelos fiquem alinhados com o eixo da máquina e os braços assentes na almofada."},{"title":"Fletir","text":"Agarra as pegas e flete os cotovelos em direção aos ombros, sem levantar os cotovelos da almofada."},{"title":"Descida","text":"Volta devagar até os braços ficarem quase esticados, sem perder a tensão no bíceps."}],"pt-BR":[{"title":"Ajuste","text":"Ajuste o banco para que os cotovelos fiquem alinhados com o eixo da máquina e os braços apoiados na almofada."},{"title":"Flexionar","text":"Segure as manoplas e flexione os cotovelos em direção aos ombros, sem tirar os cotovelos da almofada."},{"title":"Descida","text":"Volte devagar até os braços ficarem quase estendidos, sem perder a tensão no bíceps."}]}'::jsonb,
    'machine', '{weight,reps}', '{"biceps":0.9,"forearms":0.1}'::jsonb, 60),
  ('cable-curl', '{"en":"Cable Curl","de":"Kabelcurls","pt-PT":"Curl no cabo","pt-BR":"Rosca direta na polia"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Attach a straight or EZ bar to a low pulley. Face the stack and grip the bar underhand, arms straight."},{"title":"Curl","text":"Curl the bar towards your shoulders with your elbows at your sides. Don''t lean back."},{"title":"Lower","text":"Lower slowly until your arms are straight, keeping the cable under tension."}],"de":[{"title":"Aufbauen","text":"Häng eine gerade Stange oder SZ-Stange unten am Kabelzug ein. Steh zum Turm und greif im Untergriff, die Arme gestreckt."},{"title":"Beugen","text":"Beug die Arme und zieh die Stange Richtung Schultern. Die Ellbogen bleiben am Körper, lehn dich nicht zurück."},{"title":"Absenken","text":"Lass die Stange langsam ab, bis die Arme gestreckt sind. Das Kabel bleibt dabei unter Spannung."}],"pt-PT":[{"title":"Preparação","text":"Prende uma barra reta ou EZ à polia baixa. Fica de frente para a máquina e agarra a barra em pega supinada, braços esticados."},{"title":"Fletir","text":"Flete os cotovelos e leva a barra até aos ombros, com os cotovelos junto ao corpo. Não te inclines para trás."},{"title":"Descida","text":"Desce devagar até esticares os braços, mantendo o cabo sempre em tensão."}],"pt-BR":[{"title":"Preparação","text":"Prenda uma barra reta ou W na polia baixa. Fique de frente para a máquina e segure a barra com pegada supinada, braços estendidos."},{"title":"Flexionar","text":"Flexione os cotovelos e leve a barra até os ombros, com os cotovelos colados ao corpo. Não incline o tronco para trás."},{"title":"Descida","text":"Desça devagar até estender os braços, mantendo o cabo sempre tensionado."}]}'::jsonb,
    'cable', '{weight,reps}', '{"biceps":0.85,"forearms":0.15}'::jsonb, 60),
  ('rope-hammer-curl', '{"en":"Rope Hammer Curl","de":"Hammercurls am Seil","pt-PT":"Curl martelo com corda","pt-BR":"Rosca martelo na corda"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Attach a rope to a low pulley. Hold the ends with your palms facing each other, arms straight, elbows at your sides."},{"title":"Curl","text":"Curl the rope up towards your shoulders, keeping your thumbs on top and your upper arms still."},{"title":"Lower","text":"Lower slowly until your arms are straight, keeping the cable under tension."}],"de":[{"title":"Aufbauen","text":"Häng ein Seil unten am Kabelzug ein. Greif die Enden im Hammergriff, die Arme gestreckt, die Ellbogen am Körper."},{"title":"Beugen","text":"Beug die Arme und zieh das Seil Richtung Schultern. Die Daumen zeigen nach oben, die Oberarme bleiben ruhig."},{"title":"Absenken","text":"Lass das Seil langsam ab, bis die Arme gestreckt sind. Das Kabel bleibt unter Spannung."}],"pt-PT":[{"title":"Preparação","text":"Prende uma corda à polia baixa. Agarra as pontas com as palmas viradas uma para a outra, braços esticados e cotovelos junto ao corpo."},{"title":"Fletir","text":"Flete os cotovelos e leva a corda até aos ombros, com os polegares para cima e os braços imóveis."},{"title":"Descida","text":"Desce devagar até esticares os braços, mantendo o cabo em tensão."}],"pt-BR":[{"title":"Preparação","text":"Prenda uma corda na polia baixa. Segure as pontas com as palmas voltadas uma para a outra, braços estendidos e cotovelos colados ao corpo."},{"title":"Flexionar","text":"Flexione os cotovelos e leve a corda até os ombros, com os polegares para cima e os braços parados."},{"title":"Descida","text":"Desça devagar até estender os braços, mantendo o cabo tensionado."}]}'::jsonb,
    'cable', '{weight,reps}', '{"biceps":0.6,"forearms":0.4}'::jsonb, 60),
  ('bayesian-curl', '{"en":"Bayesian Cable Curl","de":"Bayesian Curls","pt-PT":"Curl bayesiano","pt-BR":"Rosca bayesiana"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Attach a D-handle to the lowest pulley and grab it in one hand. Face away from the machine and step forward until your arm is pulled behind your body."},{"title":"Curl","text":"Curl the handle forward and up, keeping your elbow slightly behind your torso. Don''t let your shoulder roll forward."},{"title":"Lower","text":"Lower slowly until your arm is straight and you feel a stretch in your biceps. Switch arms after the set."}],"de":[{"title":"Aufbauen","text":"Häng einen Einzelgriff ganz unten am Kabelzug ein und greif ihn mit einer Hand. Dreh dem Turm den Rücken zu und geh einen Schritt vor, bis der Arm hinter den Körper gezogen wird."},{"title":"Beugen","text":"Beug den Arm und führ den Griff nach vorn oben. Der Ellbogen bleibt leicht hinter dem Oberkörper, die Schulter kippt nicht nach vorn."},{"title":"Absenken","text":"Lass den Arm langsam zurück, bis er gestreckt ist und du die Dehnung im Bizeps spürst. Wechsle nach dem Satz die Seite."}],"pt-PT":[{"title":"Preparação","text":"Prende uma pega simples à polia mais baixa e agarra-a com uma mão. Fica de costas para a máquina e dá um passo em frente até o braço ficar puxado para trás do corpo."},{"title":"Fletir","text":"Flete o cotovelo e leva a pega para a frente e para cima, com o cotovelo ligeiramente atrás do tronco. Não deixes o ombro rodar para a frente."},{"title":"Descida","text":"Desce devagar até esticares o braço e sentires o alongamento no bíceps. Troca de braço no fim da série."}],"pt-BR":[{"title":"Preparação","text":"Prenda um puxador simples na polia mais baixa e segure com uma mão. Fique de costas para a máquina e dê um passo à frente até o braço ser puxado para trás do corpo."},{"title":"Flexionar","text":"Flexione o cotovelo e leve o puxador para a frente e para cima, com o cotovelo levemente atrás do tronco. Não deixe o ombro ir para a frente."},{"title":"Descida","text":"Desça devagar até estender o braço e sentir o alongamento no bíceps. Troque de lado no fim da série."}]}'::jsonb,
    'cable', '{weight,reps}', '{"biceps":0.9,"forearms":0.1}'::jsonb, 60),
  ('rope-pushdown', '{"en":"Rope Pushdown","de":"Trizepsdrücken am Seil","pt-PT":"Extensão de tríceps com corda","pt-BR":"Tríceps corda"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Attach a rope to a high pulley. Hold the ends with your palms facing each other and pin your elbows to your sides."},{"title":"Push","text":"Push the rope down until your arms are straight, spreading the ends apart at the bottom."},{"title":"Return","text":"Let the rope rise slowly until your forearms are just above parallel to the floor. Keep your elbows still."}],"de":[{"title":"Aufbauen","text":"Häng ein Seil oben am Kabelzug ein. Greif die Enden im Hammergriff und leg die Ellbogen seitlich am Körper an."},{"title":"Drücken","text":"Drück das Seil nach unten, bis die Arme gestreckt sind, und zieh die Enden unten leicht auseinander."},{"title":"Zurück","text":"Lass das Seil langsam hoch, bis die Unterarme knapp über der Waagerechten sind. Die Ellbogen bleiben fixiert."}],"pt-PT":[{"title":"Preparação","text":"Prende uma corda à polia alta. Agarra as pontas com as palmas viradas uma para a outra e cola os cotovelos ao corpo."},{"title":"Empurrar","text":"Empurra a corda para baixo até esticares os braços e afasta as pontas no fim do movimento."},{"title":"Voltar","text":"Deixa a corda subir devagar até os antebraços ficarem um pouco acima da horizontal. Mantém os cotovelos fixos."}],"pt-BR":[{"title":"Preparação","text":"Prenda uma corda na polia alta. Segure as pontas com as palmas voltadas uma para a outra e cole os cotovelos ao corpo."},{"title":"Empurrar","text":"Empurre a corda para baixo até estender os braços e abra as pontas no final do movimento."},{"title":"Voltar","text":"Deixe a corda subir devagar até os antebraços ficarem um pouco acima da linha horizontal. Mantenha os cotovelos fixos."}]}'::jsonb,
    'cable', '{weight,reps}', '{"triceps":1.0}'::jsonb, 60),
  ('single-arm-pushdown', '{"en":"Single-Arm Cable Pushdown","de":"Trizepsdrücken einarmig","pt-PT":"Extensão de tríceps unilateral no cabo","pt-BR":"Tríceps unilateral na polia"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Attach a D-handle to a high pulley. Grip it with one hand and pin that elbow to your side."},{"title":"Push","text":"Push the handle down until your arm is fully straight. Squeeze your triceps at the bottom."},{"title":"Return","text":"Let the handle rise slowly until your forearm is just above parallel. Switch arms after the set."}],"de":[{"title":"Aufbauen","text":"Häng einen Einzelgriff oben am Kabelzug ein. Greif ihn mit einer Hand und leg den Ellbogen seitlich am Körper an."},{"title":"Drücken","text":"Drück den Griff nach unten, bis der Arm ganz gestreckt ist. Spann unten den Trizeps fest an."},{"title":"Zurück","text":"Lass den Griff langsam hoch, bis der Unterarm knapp über der Waagerechten ist. Wechsle nach dem Satz die Seite."}],"pt-PT":[{"title":"Preparação","text":"Prende uma pega simples à polia alta. Agarra-a com uma mão e cola esse cotovelo ao corpo."},{"title":"Empurrar","text":"Empurra a pega para baixo até o braço ficar totalmente esticado. Contrai o tríceps em baixo."},{"title":"Voltar","text":"Deixa a pega subir devagar até o antebraço ficar um pouco acima da horizontal. Troca de braço no fim da série."}],"pt-BR":[{"title":"Preparação","text":"Prenda um puxador simples na polia alta. Segure com uma mão e cole esse cotovelo ao corpo."},{"title":"Empurrar","text":"Empurre o puxador para baixo até estender totalmente o braço. Contraia o tríceps embaixo."},{"title":"Voltar","text":"Deixe o puxador subir devagar até o antebraço ficar um pouco acima da linha horizontal. Troque de lado no fim da série."}]}'::jsonb,
    'cable', '{weight,reps}', '{"triceps":1.0}'::jsonb, 60),
  ('overhead-cable-extension', '{"en":"Overhead Cable Triceps Extension","de":"Trizepsstrecken über Kopf am Kabel","pt-PT":"Extensão de tríceps acima da cabeça no cabo","pt-BR":"Tríceps francês na polia"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Attach a rope to a low or mid pulley. Face away from the stack in a split stance, lean forward slightly and hold the rope behind your head."},{"title":"Extend","text":"Extend your arms forward and up until they are straight. Keep your elbows close to your head."},{"title":"Return","text":"Bend your elbows slowly until your hands are behind your head and you feel a stretch in your triceps."}],"de":[{"title":"Aufbauen","text":"Häng ein Seil unten oder mittig am Kabelzug ein. Stell dich mit dem Rücken zum Turm in Schrittstellung, beug dich leicht vor und halt das Seil hinter dem Kopf."},{"title":"Strecken","text":"Streck die Arme nach vorn oben, bis sie ganz gestreckt sind. Die Ellbogen bleiben nah am Kopf."},{"title":"Zurück","text":"Beug die Ellbogen langsam, bis die Hände hinter dem Kopf sind und du die Dehnung im Trizeps spürst."}],"pt-PT":[{"title":"Preparação","text":"Prende uma corda à polia baixa ou média. Fica de costas para a máquina, com um pé à frente, inclina-te um pouco e segura a corda atrás da cabeça."},{"title":"Estender","text":"Estende os braços para a frente e para cima até ficarem totalmente esticados. Mantém os cotovelos junto à cabeça."},{"title":"Voltar","text":"Flete os cotovelos devagar até as mãos ficarem atrás da cabeça e sentires o alongamento no tríceps."}],"pt-BR":[{"title":"Preparação","text":"Prenda uma corda na polia baixa ou média. Fique de costas para a máquina, com um pé à frente, incline o tronco um pouco e segure a corda atrás da cabeça."},{"title":"Estender","text":"Estenda os braços para a frente e para cima até ficarem totalmente estendidos. Mantenha os cotovelos perto da cabeça."},{"title":"Voltar","text":"Flexione os cotovelos devagar até as mãos ficarem atrás da cabeça e você sentir o alongamento no tríceps."}]}'::jsonb,
    'cable', '{weight,reps}', '{"triceps":1.0}'::jsonb, 60),
  ('katana-extension', '{"en":"Katana Extension","de":"Katana Extensions","pt-PT":"Extensão de tríceps katana","pt-BR":"Tríceps katana"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Attach a D-handle to a low pulley and stand side-on to it. Grab it with the hand farther from the machine so the cable runs across your body, and bring it behind your head, elbow up."},{"title":"Extend","text":"Extend your arm diagonally up and out until it is straight. Keep your upper arm still beside your head."},{"title":"Return","text":"Bend your elbow slowly until the handle is back behind your head, near your opposite shoulder. Switch sides after the set."}],"de":[{"title":"Aufbauen","text":"Häng einen Einzelgriff unten am Kabelzug ein und stell dich seitlich dazu. Greif ihn mit der Hand, die weiter vom Turm weg ist, sodass das Kabel quer über den Körper läuft, und führ den Griff hinter den Kopf, Ellbogen nach oben."},{"title":"Strecken","text":"Streck den Arm schräg nach oben außen, bis er ganz gestreckt ist. Der Oberarm bleibt dabei ruhig neben dem Kopf."},{"title":"Zurück","text":"Beug den Ellbogen langsam, bis der Griff wieder hinter dem Kopf nahe der anderen Schulter ist. Wechsle nach dem Satz die Seite."}],"pt-PT":[{"title":"Preparação","text":"Prende uma pega simples à polia baixa e fica de lado para a máquina. Agarra-a com a mão mais afastada da máquina, com o cabo a cruzar o corpo, e leva-a para trás da cabeça, cotovelo para cima."},{"title":"Estender","text":"Estende o braço na diagonal, para cima e para fora, até ficar esticado. Mantém o braço imóvel junto à cabeça."},{"title":"Voltar","text":"Flete o cotovelo devagar até a pega voltar para trás da cabeça, perto do ombro oposto. Troca de lado no fim da série."}],"pt-BR":[{"title":"Preparação","text":"Prenda um puxador simples na polia baixa e fique de lado para a máquina. Segure com a mão mais distante da máquina, com o cabo cruzando o corpo, e leve o puxador para trás da cabeça, cotovelo para cima."},{"title":"Estender","text":"Estenda o braço na diagonal, para cima e para fora, até ficar reto. Mantenha o braço parado ao lado da cabeça."},{"title":"Voltar","text":"Flexione o cotovelo devagar até o puxador voltar para trás da cabeça, perto do ombro oposto. Troque de lado no fim da série."}]}'::jsonb,
    'cable', '{weight,reps}', '{"triceps":1.0}'::jsonb, 60),
  ('overhead-dumbbell-extension', '{"en":"Overhead Dumbbell Triceps Extension","de":"Kurzhantel-Trizepsstrecken über Kopf","pt-PT":"Extensão de tríceps acima da cabeça com haltere","pt-BR":"Tríceps francês com halter"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Sit on a bench with back support and hold one dumbbell vertically overhead, both hands cupping the top end, arms straight."},{"title":"Lower","text":"Bend your elbows to lower the dumbbell behind your head. Keep your elbows pointing forward and close to your head."},{"title":"Extend","text":"Straighten your arms to bring the dumbbell back overhead. Brace your abs so your lower back doesn''t arch."}],"de":[{"title":"Aufbauen","text":"Setz dich auf eine Bank mit Lehne und halt eine Kurzhantel senkrecht über dem Kopf, beide Hände unter der oberen Scheibe, Arme gestreckt."},{"title":"Absenken","text":"Beug die Ellbogen und senk die Hantel hinter den Kopf. Die Ellbogen zeigen nach vorn und bleiben nah am Kopf."},{"title":"Strecken","text":"Streck die Arme, bis die Hantel wieder über dem Kopf ist. Spann den Bauch an, damit du kein Hohlkreuz machst."}],"pt-PT":[{"title":"Preparação","text":"Senta-te num banco com encosto e segura um haltere na vertical acima da cabeça, com as duas mãos sob a extremidade de cima e os braços esticados."},{"title":"Descida","text":"Flete os cotovelos e desce o haltere por trás da cabeça. Mantém os cotovelos virados para a frente e junto à cabeça."},{"title":"Estender","text":"Estica os braços até o haltere voltar a ficar acima da cabeça. Contrai o abdómen para não arqueares a lombar."}],"pt-BR":[{"title":"Preparação","text":"Sente em um banco com encosto e segure um halter na vertical acima da cabeça, com as duas mãos sob a parte de cima e os braços estendidos."},{"title":"Descida","text":"Flexione os cotovelos e desça o halter por trás da cabeça. Mantenha os cotovelos apontados para a frente e perto da cabeça."},{"title":"Estender","text":"Estenda os braços até o halter voltar para cima da cabeça. Contraia o abdômen para não arquear a lombar."}]}'::jsonb,
    'dumbbell', '{weight,reps}', '{"triceps":1.0}'::jsonb, 60),
  ('dumbbell-skull-crusher', '{"en":"Dumbbell Skull Crusher","de":"French Press mit Kurzhanteln","pt-PT":"Extensão francesa com halteres","pt-BR":"Tríceps testa com halteres"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Lie on a flat bench and press two dumbbells up over your shoulders, palms facing each other."},{"title":"Lower","text":"Bend only your elbows to lower the dumbbells beside your head. Keep your upper arms still and pointing up."},{"title":"Extend","text":"Straighten your arms to bring the dumbbells back over your shoulders. Squeeze your triceps at the top."}],"de":[{"title":"Aufbauen","text":"Leg dich auf eine Flachbank und drück zwei Kurzhanteln über die Schultern, die Handflächen zeigen zueinander."},{"title":"Absenken","text":"Beug nur die Ellbogen und senk die Hanteln neben den Kopf. Die Oberarme bleiben ruhig und zeigen nach oben."},{"title":"Strecken","text":"Streck die Arme, bis die Hanteln wieder über den Schultern sind. Oben den Trizeps fest anspannen."}],"pt-PT":[{"title":"Preparação","text":"Deita-te num banco plano e sobe dois halteres acima dos ombros, com as palmas viradas uma para a outra."},{"title":"Descida","text":"Flete só os cotovelos e desce os halteres para os lados da cabeça. Mantém os braços imóveis e apontados para cima."},{"title":"Estender","text":"Estica os braços até os halteres voltarem a ficar por cima dos ombros. Contrai o tríceps em cima."}],"pt-BR":[{"title":"Preparação","text":"Deite em um banco reto e suba dois halteres acima dos ombros, com as palmas voltadas uma para a outra."},{"title":"Descida","text":"Flexione só os cotovelos e desça os halteres ao lado da cabeça. Mantenha os braços parados e apontados para cima."},{"title":"Estender","text":"Estenda os braços até os halteres voltarem para cima dos ombros. Contraia o tríceps no alto."}]}'::jsonb,
    'dumbbell', '{weight,reps}', '{"triceps":1.0}'::jsonb, 60),
  ('jm-press', '{"en":"JM Press","de":"JM Press","pt-PT":"Press JM","pt-BR":"JM press"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Lie on a flat bench and hold the bar slightly narrower than shoulder width, arms straight over your shoulders."},{"title":"Lower","text":"Lower the bar in a straight line towards your chin, elbows tucked and pointing towards your feet. Stop just above your chin, when your forearms meet your biceps."},{"title":"Press","text":"Press the bar back up along the same path until your arms are straight over your shoulders."}],"de":[{"title":"Aufbauen","text":"Leg dich auf eine Flachbank und greif die Stange etwas enger als schulterbreit, die Arme gestreckt über den Schultern."},{"title":"Absenken","text":"Senk die Stange gerade Richtung Kinn, die Ellbogen bleiben eng und zeigen zu den Füßen. Halt kurz über dem Kinn an, wenn die Unterarme den Bizeps berühren."},{"title":"Drücken","text":"Drück die Stange auf derselben Bahn zurück, bis die Arme gestreckt über den Schultern sind."}],"pt-PT":[{"title":"Preparação","text":"Deita-te num banco plano e agarra a barra com uma pega um pouco mais estreita que os ombros, braços esticados por cima dos ombros."},{"title":"Descida","text":"Desce a barra a direito em direção ao queixo, com os cotovelos fechados e apontados para os pés. Trava a barra pouco acima do queixo, quando os antebraços tocarem nos bíceps."},{"title":"Empurrar","text":"Empurra a barra pelo mesmo caminho até os braços ficarem esticados por cima dos ombros."}],"pt-BR":[{"title":"Preparação","text":"Deite em um banco reto e segure a barra com pegada um pouco mais fechada que os ombros, braços estendidos acima dos ombros."},{"title":"Descida","text":"Desça a barra em linha reta em direção ao queixo, com os cotovelos fechados e apontados para os pés. Pare um pouco acima do queixo, quando os antebraços encostarem nos bíceps."},{"title":"Empurrar","text":"Empurre a barra pelo mesmo caminho até os braços ficarem estendidos acima dos ombros."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"triceps":0.75,"chest":0.15,"front_delts":0.1}'::jsonb, 90),
  ('dip-machine', '{"en":"Seated Dip Machine","de":"Dips an der Maschine","pt-PT":"Fundos na máquina","pt-BR":"Mergulho na máquina"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Adjust the seat so the handles start level with your lower chest. Sit tall and grip the handles."},{"title":"Press","text":"Push the handles down until your arms are straight, keeping your elbows close to your body."},{"title":"Return","text":"Let the handles rise slowly until your elbows are bent about 90°. Keep your shoulders down, away from your ears."}],"de":[{"title":"Einstellen","text":"Stell den Sitz so ein, dass die Griffe etwa auf Höhe der unteren Brust starten. Setz dich aufrecht hin und greif die Griffe."},{"title":"Drücken","text":"Drück die Griffe nach unten, bis die Arme gestreckt sind. Die Ellbogen bleiben nah am Körper."},{"title":"Zurück","text":"Lass die Griffe langsam hoch, bis die Ellbogen etwa 90° gebeugt sind. Zieh die Schultern dabei nicht zu den Ohren."}],"pt-PT":[{"title":"Ajustar","text":"Ajusta o banco para que as pegas comecem à altura da parte inferior do peito. Senta-te com o tronco direito e agarra as pegas."},{"title":"Empurrar","text":"Empurra as pegas para baixo até esticares os braços, com os cotovelos junto ao corpo."},{"title":"Voltar","text":"Deixa as pegas subir devagar até os cotovelos ficarem fletidos a cerca de 90°. Não encolhas os ombros em direção às orelhas."}],"pt-BR":[{"title":"Ajuste","text":"Ajuste o banco para que as manoplas comecem na altura da parte baixa do peito. Sente com o tronco ereto e segure as manoplas."},{"title":"Empurrar","text":"Empurre as manoplas para baixo até estender os braços, com os cotovelos perto do corpo."},{"title":"Voltar","text":"Deixe as manoplas subirem devagar até os cotovelos ficarem flexionados a cerca de 90°. Não encolha os ombros em direção às orelhas."}]}'::jsonb,
    'machine', '{weight,reps}', '{"triceps":0.7,"chest":0.2,"front_delts":0.1}'::jsonb, 90),
  ('bench-dip', '{"en":"Bench Dip","de":"Bankdips","pt-PT":"Fundos no banco","pt-BR":"Tríceps banco"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Sit on the edge of a bench with your hands next to your hips, fingers forward. Slide your hips off and walk your feet out."},{"title":"Lower","text":"Bend your elbows straight back to lower your hips until your upper arms are about parallel to the floor."},{"title":"Press","text":"Push through your palms until your arms are straight. Keep your back close to the bench and your shoulders down."}],"de":[{"title":"Aufbauen","text":"Setz dich auf die Bankkante, die Hände neben der Hüfte, Finger nach vorn. Schieb die Hüfte von der Bank und stell die Füße nach vorn."},{"title":"Absenken","text":"Beug die Ellbogen nach hinten und senk die Hüfte, bis die Oberarme etwa waagerecht sind."},{"title":"Drücken","text":"Drück dich über die Handflächen hoch, bis die Arme gestreckt sind. Der Rücken bleibt nah an der Bank, die Schultern unten."}],"pt-PT":[{"title":"Preparação","text":"Senta-te na borda de um banco, com as mãos ao lado da anca e os dedos para a frente. Tira a anca do banco e afasta os pés."},{"title":"Descida","text":"Flete os cotovelos para trás e desce a anca até os braços ficarem mais ou menos paralelos ao chão."},{"title":"Empurrar","text":"Empurra com as palmas das mãos até esticares os braços. Mantém as costas perto do banco e os ombros em baixo."}],"pt-BR":[{"title":"Preparação","text":"Sente na beirada de um banco, com as mãos ao lado do quadril e os dedos para a frente. Tire o quadril do banco e afaste os pés."},{"title":"Descida","text":"Flexione os cotovelos para trás e desça o quadril até os braços ficarem mais ou menos paralelos ao chão."},{"title":"Empurrar","text":"Empurre com as palmas das mãos até estender os braços. Mantenha as costas perto do banco e os ombros baixos."}]}'::jsonb,
    'bodyweight', '{reps}', '{"triceps":0.75,"front_delts":0.15,"chest":0.1}'::jsonb, 60),
  ('diamond-push-up', '{"en":"Diamond Push-Up","de":"Diamant-Liegestütz","pt-PT":"Flexão diamante","pt-BR":"Flexão diamante"}'::jsonb,
    '{"en":[{"title":"Hands","text":"Place your hands under your chest, thumbs and index fingers touching in a diamond shape. Body in one straight line."},{"title":"Lower","text":"Lower your chest towards your hands, keeping your elbows close to your body."},{"title":"Push","text":"Push back up until your arms are straight. Squeeze your glutes so your hips don''t sag."}],"de":[{"title":"Hände","text":"Setz die Hände unter der Brust auf, Daumen und Zeigefinger bilden eine Raute. Der Körper bildet eine gerade Linie."},{"title":"Absenken","text":"Senk die Brust Richtung Hände, die Ellbogen bleiben eng am Körper."},{"title":"Drücken","text":"Drück dich hoch, bis die Arme gestreckt sind. Spann das Gesäß an, damit die Hüfte nicht durchhängt."}],"pt-PT":[{"title":"Mãos","text":"Coloca as mãos por baixo do peito, com os polegares e os indicadores a tocar-se em forma de diamante. Corpo em linha reta."},{"title":"Descida","text":"Desce o peito em direção às mãos, com os cotovelos junto ao corpo."},{"title":"Empurrar","text":"Empurra o chão até esticares os braços. Contrai os glúteos para a anca não descair."}],"pt-BR":[{"title":"Mãos","text":"Coloque as mãos embaixo do peito, com polegares e indicadores se tocando em forma de diamante. Corpo em linha reta."},{"title":"Descida","text":"Desça o peito em direção às mãos, com os cotovelos colados ao corpo."},{"title":"Empurrar","text":"Empurre o chão até estender os braços. Contraia os glúteos para o quadril não cair."}]}'::jsonb,
    'bodyweight', '{reps}', '{"triceps":0.5,"chest":0.35,"front_delts":0.15}'::jsonb, 60),
  ('dumbbell-kickback', '{"en":"Dumbbell Triceps Kickback","de":"Trizeps-Kickbacks","pt-PT":"Kickback de tríceps","pt-BR":"Tríceps coice"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Place one knee and one hand on a bench, back flat. Hold the dumbbell with your upper arm against your side, parallel to the floor."},{"title":"Extend","text":"Straighten your elbow until your whole arm is in line with your torso. Only your forearm moves."},{"title":"Return","text":"Bend your elbow slowly back to 90° without letting your upper arm drop. Switch arms after the set."}],"de":[{"title":"Aufbauen","text":"Stütz ein Knie und eine Hand auf der Bank ab, der Rücken ist gerade. Der Oberarm liegt waagerecht am Körper, der Ellbogen ist 90° gebeugt."},{"title":"Strecken","text":"Streck den Ellbogen, bis der ganze Arm eine Linie mit dem Oberkörper bildet. Nur der Unterarm bewegt sich."},{"title":"Zurück","text":"Beug den Ellbogen langsam zurück auf 90°, ohne dass der Oberarm absinkt. Wechsle nach dem Satz die Seite."}],"pt-PT":[{"title":"Preparação","text":"Apoia um joelho e uma mão no banco, com as costas direitas. Mantém o braço junto ao tronco e paralelo ao chão, cotovelo fletido a 90°."},{"title":"Estender","text":"Estica o cotovelo até o braço inteiro ficar em linha com o tronco. Só o antebraço se mexe."},{"title":"Voltar","text":"Flete o cotovelo devagar até voltar aos 90°, sem deixar o braço descer. Troca de braço no fim da série."}],"pt-BR":[{"title":"Preparação","text":"Apoie um joelho e uma mão no banco, com as costas retas. Mantenha o braço colado ao tronco e paralelo ao chão, cotovelo flexionado a 90°."},{"title":"Estender","text":"Estenda o cotovelo até o braço inteiro ficar alinhado com o tronco. Só o antebraço se move."},{"title":"Voltar","text":"Flexione o cotovelo devagar de volta aos 90°, sem deixar o braço cair. Troque de lado no fim da série."}]}'::jsonb,
    'dumbbell', '{weight,reps}', '{"triceps":1.0}'::jsonb, 60),
  ('cable-kickback', '{"en":"Cable Triceps Kickback","de":"Trizeps-Kickbacks am Kabel","pt-PT":"Kickback de tríceps no cabo","pt-BR":"Tríceps coice na polia"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Hold the cable from a low pulley in one hand. Hinge forward with a flat back and pin your upper arm to your side, parallel to the floor."},{"title":"Extend","text":"Straighten your elbow until your arm points straight back. Keep your upper arm still."},{"title":"Return","text":"Bend your elbow slowly until your forearm hangs straight down, without letting the cable go slack. Switch arms after the set."}],"de":[{"title":"Aufbauen","text":"Greif das Kabel unten am Kabelzug mit einer Hand. Beug den Oberkörper mit geradem Rücken vor und halt den Oberarm waagerecht am Körper."},{"title":"Strecken","text":"Streck den Ellbogen, bis der Arm gerade nach hinten zeigt. Der Oberarm bleibt dabei ruhig."},{"title":"Zurück","text":"Beug den Ellbogen langsam, bis der Unterarm senkrecht hängt, ohne dass das Kabel locker wird. Wechsle nach dem Satz die Seite."}],"pt-PT":[{"title":"Preparação","text":"Agarra o cabo da polia baixa com uma mão. Inclina o tronco para a frente com as costas direitas e mantém o braço junto ao corpo, paralelo ao chão."},{"title":"Estender","text":"Estende o cotovelo até o braço inteiro apontar para trás. Mantém a parte de cima do braço imóvel."},{"title":"Voltar","text":"Flete o cotovelo devagar até o antebraço ficar na vertical, sem deixar o cabo folgar. Troca de braço no fim da série."}],"pt-BR":[{"title":"Preparação","text":"Segure o cabo da polia baixa com uma mão. Incline o tronco para a frente com as costas retas e mantenha o braço colado ao corpo, paralelo ao chão."},{"title":"Estender","text":"Estenda o cotovelo até o braço inteiro apontar para trás. Mantenha a parte de cima do braço parada."},{"title":"Voltar","text":"Flexione o cotovelo devagar até o antebraço ficar na vertical, sem deixar o cabo afrouxar. Troque de lado no fim da série."}]}'::jsonb,
    'cable', '{weight,reps}', '{"triceps":1.0}'::jsonb, 60),
  ('triceps-extension-machine', '{"en":"Triceps Extension Machine","de":"Trizepsmaschine","pt-PT":"Extensão de tríceps na máquina","pt-BR":"Tríceps na máquina"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Adjust the seat so your elbows line up with the machine''s pivot and rest your upper arms on the pad."},{"title":"Extend","text":"Push the handles until your arms are straight. Keep your elbows on the pad."},{"title":"Return","text":"Let the handles come back slowly until your elbows are bent about 90°, keeping tension on your triceps."}],"de":[{"title":"Einstellen","text":"Stell den Sitz so ein, dass deine Ellbogen auf Höhe der Drehachse sind, und leg die Oberarme aufs Polster."},{"title":"Strecken","text":"Drück die Griffe, bis die Arme gestreckt sind. Die Ellbogen bleiben auf dem Polster."},{"title":"Zurück","text":"Lass die Griffe langsam zurück, bis die Ellbogen etwa 90° gebeugt sind. Die Spannung im Trizeps bleibt."}],"pt-PT":[{"title":"Ajustar","text":"Ajusta o banco para que os cotovelos fiquem alinhados com o eixo da máquina e pousa os braços na almofada."},{"title":"Estender","text":"Empurra as pegas até esticares os braços. Mantém os cotovelos na almofada."},{"title":"Voltar","text":"Deixa as pegas voltar devagar até os cotovelos ficarem fletidos a cerca de 90°, sem perder a tensão no tríceps."}],"pt-BR":[{"title":"Ajuste","text":"Ajuste o banco para que os cotovelos fiquem alinhados com o eixo da máquina e apoie os braços na almofada."},{"title":"Estender","text":"Empurre as manoplas até estender os braços. Mantenha os cotovelos na almofada."},{"title":"Voltar","text":"Deixe as manoplas voltarem devagar até os cotovelos ficarem flexionados a cerca de 90°, sem perder a tensão no tríceps."}]}'::jsonb,
    'machine', '{weight,reps}', '{"triceps":1.0}'::jsonb, 60),
  ('side-plank', '{"en":"Side Plank","de":"Seitstütz","pt-PT":"Prancha lateral","pt-BR":"Prancha lateral"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Lie on your side with your elbow under your shoulder and your feet stacked."},{"title":"Lift","text":"Lift your hips until your body forms a straight line from head to heels. Keep your hips stacked, not rolled forward."},{"title":"Hold","text":"Breathe steadily and hold without letting your hips drop. Then switch sides and hold for the same time."}],"de":[{"title":"Aufbauen","text":"Leg dich auf die Seite, der Ellbogen unter der Schulter, die Füße übereinander."},{"title":"Anheben","text":"Heb die Hüfte, bis dein Körper eine gerade Linie von Kopf bis Ferse bildet. Die Hüfte kippt nicht nach vorn."},{"title":"Halten","text":"Atme ruhig weiter und halte, ohne dass die Hüfte absinkt. Wechsle dann die Seite und halte gleich lang."}],"pt-PT":[{"title":"Preparação","text":"Deita-te de lado, com o cotovelo por baixo do ombro e os pés um em cima do outro."},{"title":"Elevar","text":"Levanta a anca até o corpo ficar em linha reta da cabeça aos calcanhares. Não deixes a anca rodar para a frente."},{"title":"Manter","text":"Respira com calma e mantém a posição sem deixar a anca descair. Depois troca de lado e aguenta o mesmo tempo."}],"pt-BR":[{"title":"Preparação","text":"Deite de lado, com o cotovelo embaixo do ombro e os pés um sobre o outro."},{"title":"Elevar","text":"Levante o quadril até o corpo ficar em linha reta da cabeça aos calcanhares. Não deixe o quadril girar para a frente."},{"title":"Segure","text":"Respire com calma e segure a posição sem deixar o quadril cair. Depois troque de lado e segure pelo mesmo tempo."}]}'::jsonb,
    'bodyweight', '{seconds}', '{"obliques":0.65,"abs":0.2,"glutes":0.15}'::jsonb, 45),
  ('hollow-hold', '{"en":"Hollow Hold","de":"Hollow Hold","pt-PT":"Hollow hold","pt-BR":"Abdominal canoa"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Lie on your back with your arms overhead. Press your lower back firmly into the floor."},{"title":"Lift","text":"Lift your shoulders, arms and straight legs a few centimetres off the floor so your body forms a shallow banana shape."},{"title":"Hold","text":"Breathe steadily and hold. If your lower back lifts, bend your knees or bring your arms forward."}],"de":[{"title":"Aufbauen","text":"Leg dich auf den Rücken, die Arme über dem Kopf. Drück den unteren Rücken fest in den Boden."},{"title":"Anheben","text":"Heb Schultern, Arme und gestreckte Beine ein paar Zentimeter vom Boden ab, sodass dein Körper eine flache Banane bildet."},{"title":"Halten","text":"Atme ruhig weiter und halte. Hebt sich der untere Rücken, beug die Knie oder nimm die Arme nach vorn."}],"pt-PT":[{"title":"Preparação","text":"Deita-te de costas com os braços esticados acima da cabeça. Pressiona bem a lombar contra o chão."},{"title":"Elevar","text":"Levanta os ombros, os braços e as pernas esticadas alguns centímetros do chão, com o corpo em forma de banana."},{"title":"Manter","text":"Respira com calma e aguenta. Se a lombar sair do chão, flete os joelhos ou traz os braços para a frente."}],"pt-BR":[{"title":"Preparação","text":"Deite de costas com os braços estendidos acima da cabeça. Pressione bem a lombar contra o chão."},{"title":"Elevar","text":"Tire os ombros, os braços e as pernas estendidas alguns centímetros do chão, com o corpo em forma de canoa."},{"title":"Segure","text":"Respire com calma e segure. Se a lombar sair do chão, flexione os joelhos ou traga os braços para a frente."}]}'::jsonb,
    'bodyweight', '{seconds}', '{"abs":0.8,"obliques":0.2}'::jsonb, 60),
  ('l-sit', '{"en":"L-Sit","de":"L-Sit","pt-PT":"L-sit","pt-BR":"L-sit"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Place your hands on parallettes, dip bars or the floor beside your hips. Lock your arms and push your shoulders down."},{"title":"Lift","text":"Lift your straight legs in front of you until they are parallel to the floor. Point your toes and squeeze your thighs."},{"title":"Hold","text":"Breathe steadily and hold with your chest up. If your legs drop, bend your knees to keep the position."}],"de":[{"title":"Aufbauen","text":"Stütz dich mit den Händen auf Parallettes, Dipbarren oder den Boden neben der Hüfte. Arme durchstrecken, Schultern nach unten drücken."},{"title":"Anheben","text":"Heb die gestreckten Beine nach vorn, bis sie waagerecht sind. Zehen strecken, Oberschenkel anspannen."},{"title":"Halten","text":"Atme ruhig weiter und halte mit aufrechter Brust. Sinken die Beine ab, zieh lieber die Knie an."}],"pt-PT":[{"title":"Preparação","text":"Apoia as mãos em paralelas baixas, nas barras de fundos ou no chão ao lado da anca. Bloqueia os braços e baixa os ombros."},{"title":"Elevar","text":"Levanta as pernas esticadas à tua frente até ficarem paralelas ao chão. Estica as pontas dos pés e contrai as coxas."},{"title":"Manter","text":"Respira com calma e aguenta com o peito aberto. Se as pernas descerem, flete os joelhos para manter a posição."}],"pt-BR":[{"title":"Preparação","text":"Apoie as mãos em paralelas baixas, nas barras paralelas ou no chão ao lado do quadril. Trave os braços e abaixe os ombros."},{"title":"Elevar","text":"Levante as pernas estendidas à sua frente até ficarem paralelas ao chão. Estique as pontas dos pés e contraia as coxas."},{"title":"Segure","text":"Respire com calma e segure com o peito aberto. Se as pernas caírem, flexione os joelhos para manter a posição."}]}'::jsonb,
    'bodyweight', '{seconds}', '{"abs":0.6,"quads":0.25,"triceps":0.15}'::jsonb, 60),
  ('crunch', '{"en":"Crunch","de":"Crunches","pt-PT":"Crunch abdominal","pt-BR":"Abdominal supra"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Lie on your back with your knees bent and feet flat. Rest your fingertips lightly behind your ears."},{"title":"Crunch","text":"Curl your shoulders off the floor by contracting your abs. Keep your lower back down and don''t pull on your neck."},{"title":"Lower","text":"Lower slowly until your shoulder blades touch the floor, then start the next rep."}],"de":[{"title":"Aufbauen","text":"Leg dich auf den Rücken, Knie gebeugt, Füße flach am Boden. Die Fingerspitzen liegen locker hinter den Ohren."},{"title":"Einrollen","text":"Roll den Oberkörper mit der Bauchmuskulatur ein, bis die Schultern abheben. Der untere Rücken bleibt am Boden, zieh nicht am Nacken."},{"title":"Absenken","text":"Senk dich langsam ab, bis die Schulterblätter den Boden berühren, und starte direkt die nächste Wiederholung."}],"pt-PT":[{"title":"Preparação","text":"Deita-te de costas com os joelhos fletidos e os pés no chão. Pousa as pontas dos dedos atrás das orelhas."},{"title":"Enrolar","text":"Contrai o abdómen e enrola o tronco até os ombros saírem do chão. Mantém a lombar no chão e não puxes pelo pescoço."},{"title":"Descida","text":"Desce devagar até as omoplatas tocarem no chão e começa logo a repetição seguinte."}],"pt-BR":[{"title":"Preparação","text":"Deite de costas com os joelhos flexionados e os pés no chão. Apoie as pontas dos dedos atrás das orelhas."},{"title":"Subida","text":"Contraia o abdômen e tire os ombros do chão, enrolando o tronco. Mantenha a lombar no chão e não puxe o pescoço."},{"title":"Descida","text":"Desça devagar até as escápulas encostarem no chão e já comece a próxima repetição."}]}'::jsonb,
    'bodyweight', '{reps}', '{"abs":0.9,"obliques":0.1}'::jsonb, 45),
  ('sit-up', '{"en":"Sit-Up","de":"Sit-ups","pt-PT":"Sit-up","pt-BR":"Abdominal completo"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Lie on your back with your knees bent and feet flat, anchored under a pad if needed. Cross your arms over your chest."},{"title":"Sit up","text":"Curl your torso up one vertebra at a time until your chest is close to your thighs."},{"title":"Lower","text":"Roll back down slowly until your shoulders touch the floor. Don''t bounce off the floor for momentum."}],"de":[{"title":"Aufbauen","text":"Leg dich auf den Rücken, Knie gebeugt, Füße flach am Boden und bei Bedarf fixiert. Verschränk die Arme vor der Brust."},{"title":"Aufrichten","text":"Roll den Oberkörper Wirbel für Wirbel hoch, bis die Brust nah an den Oberschenkeln ist."},{"title":"Absenken","text":"Roll dich langsam wieder ab, bis die Schultern den Boden berühren. Hol keinen Schwung vom Boden."}],"pt-PT":[{"title":"Preparação","text":"Deita-te de costas com os joelhos fletidos e os pés no chão, presos sob um apoio se precisares. Cruza os braços sobre o peito."},{"title":"Subir","text":"Enrola o tronco para cima, vértebra a vértebra, até o peito ficar perto das coxas."},{"title":"Descida","text":"Desce devagar, a desenrolar a coluna, até os ombros tocarem no chão. Não uses o chão para ganhar balanço."}],"pt-BR":[{"title":"Preparação","text":"Deite de costas com os joelhos flexionados e os pés no chão, presos sob um apoio se precisar. Cruze os braços sobre o peito."},{"title":"Subida","text":"Enrole o tronco para cima, vértebra por vértebra, até o peito ficar perto das coxas."},{"title":"Descida","text":"Desça devagar, desenrolando a coluna, até os ombros encostarem no chão. Não use o chão para pegar impulso."}]}'::jsonb,
    'bodyweight', '{reps}', '{"abs":0.7,"obliques":0.15,"quads":0.15}'::jsonb, 45),
  ('decline-sit-up', '{"en":"Decline Sit-Up","de":"Negativ-Sit-ups","pt-PT":"Sit-up no banco declinado","pt-BR":"Abdominal declinado"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Hook your feet under the pads of a decline bench and lie back. Cross your arms or hold a weight plate against your chest."},{"title":"Sit up","text":"Curl your torso up until it is roughly upright, keeping the plate tight to your chest."},{"title":"Lower","text":"Lower yourself slowly until your lower back touches the bench. Don''t drop back into the next rep."}],"de":[{"title":"Aufbauen","text":"Hak die Füße unter den Polstern einer Negativbank ein und leg dich zurück. Verschränk die Arme oder halt eine Hantelscheibe vor der Brust."},{"title":"Aufrichten","text":"Roll den Oberkörper hoch, bis er etwa aufrecht ist. Die Scheibe bleibt fest an der Brust."},{"title":"Absenken","text":"Senk dich langsam ab, bis der untere Rücken die Bank berührt. Lass dich nicht in die nächste Wiederholung fallen."}],"pt-PT":[{"title":"Preparação","text":"Prende os pés sob os rolos de um banco declinado e deita-te para trás. Cruza os braços ou segura um disco junto ao peito."},{"title":"Subir","text":"Enrola o tronco para cima até ficares quase na vertical, com o disco bem junto ao peito."},{"title":"Descida","text":"Desce devagar até a lombar tocar no banco. Não te deixes cair para a repetição seguinte."}],"pt-BR":[{"title":"Preparação","text":"Prenda os pés sob os rolos de um banco declinado e deite para trás. Cruze os braços ou segure uma anilha junto ao peito."},{"title":"Subida","text":"Enrole o tronco para cima até ficar quase na vertical, com a anilha bem junto ao peito."},{"title":"Descida","text":"Desça devagar até a lombar encostar no banco. Não se jogue para a próxima repetição."}]}'::jsonb,
    'bodyweight', '{weight,reps}', '{"abs":0.7,"obliques":0.15,"quads":0.15}'::jsonb, 60),
  ('bicycle-crunch', '{"en":"Bicycle Crunch","de":"Fahrrad-Crunches","pt-PT":"Crunch bicicleta","pt-BR":"Abdominal bicicleta"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Lie on your back with your hands lightly behind your head, and lift your shoulders and feet off the floor."},{"title":"Twist","text":"Bring one knee towards your chest while rotating the opposite elbow towards it, and extend the other leg."},{"title":"Alternate","text":"Switch sides in a slow pedalling motion, rotating from your torso rather than pulling with your arms. Keep your lower back down."}],"de":[{"title":"Aufbauen","text":"Leg dich auf den Rücken, die Hände locker am Hinterkopf, und heb Schultern und Füße vom Boden ab."},{"title":"Drehen","text":"Zieh ein Knie zur Brust und dreh den gegenüberliegenden Ellbogen dazu, während du das andere Bein streckst."},{"title":"Wechseln","text":"Wechsle langsam die Seiten wie beim Radfahren und dreh aus dem Oberkörper, nicht aus den Armen. Der untere Rücken bleibt am Boden."}],"pt-PT":[{"title":"Preparação","text":"Deita-te de costas, com as mãos atrás da cabeça, e levanta os ombros e os pés do chão."},{"title":"Rodar","text":"Leva um joelho ao peito e roda o cotovelo oposto na direção dele, enquanto esticas a outra perna."},{"title":"Alternar","text":"Troca de lado devagar, como se pedalasses, rodando o tronco sem puxar com os braços. Mantém a lombar no chão."}],"pt-BR":[{"title":"Preparação","text":"Deite de costas, com as mãos atrás da cabeça, e tire os ombros e os pés do chão."},{"title":"Girar","text":"Leve um joelho ao peito e gire o cotovelo oposto em direção a ele, enquanto estende a outra perna."},{"title":"Alternar","text":"Troque de lado devagar, como se estivesse pedalando, girando o tronco sem puxar com os braços. Mantenha a lombar no chão."}]}'::jsonb,
    'bodyweight', '{reps}', '{"obliques":0.55,"abs":0.45}'::jsonb, 45),
  ('reverse-crunch', '{"en":"Reverse Crunch","de":"Reverse Crunches","pt-PT":"Crunch invertido","pt-BR":"Abdominal infra"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Lie on your back with your arms at your sides, hips and knees bent 90° and shins parallel to the floor."},{"title":"Curl","text":"Use your abs to curl your hips off the floor, bringing your knees towards your chest. Don''t swing your legs."},{"title":"Lower","text":"Lower your hips slowly back to the floor until your shins are parallel again."}],"de":[{"title":"Aufbauen","text":"Leg dich auf den Rücken, die Arme neben dem Körper. Hüfte und Knie sind 90° gebeugt, die Schienbeine waagerecht."},{"title":"Einrollen","text":"Roll das Becken mit der Bauchmuskulatur vom Boden und zieh die Knie Richtung Brust. Schwing nicht mit den Beinen."},{"title":"Absenken","text":"Senk das Becken langsam wieder ab, bis die Schienbeine waagerecht sind."}],"pt-PT":[{"title":"Preparação","text":"Deita-te de costas com os braços ao lado do corpo, a anca e os joelhos fletidos a 90° e as canelas paralelas ao chão."},{"title":"Enrolar","text":"Usa o abdómen para levantar a anca do chão e levar os joelhos ao peito. Não balances as pernas."},{"title":"Descida","text":"Desce a anca devagar até ao chão, até as canelas voltarem a ficar paralelas ao chão."}],"pt-BR":[{"title":"Preparação","text":"Deite de costas com os braços ao lado do corpo, o quadril e os joelhos flexionados a 90° e as canelas paralelas ao chão."},{"title":"Subida","text":"Use o abdômen para tirar o quadril do chão e levar os joelhos ao peito. Não balance as pernas."},{"title":"Descida","text":"Desça o quadril devagar até o chão, até as canelas ficarem paralelas ao chão de novo."}]}'::jsonb,
    'bodyweight', '{reps}', '{"abs":0.85,"obliques":0.15}'::jsonb, 45),
  ('ab-crunch-machine', '{"en":"Ab Crunch Machine","de":"Bauchmaschine","pt-PT":"Máquina de abdominais","pt-BR":"Abdominal na máquina"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Adjust the seat so the pads rest on your chest or shoulders. Hold the handles and fix your feet."},{"title":"Crunch","text":"Curl your torso forward and down by contracting your abs. Don''t pull with your arms or push with your legs."},{"title":"Return","text":"Let the weight come back slowly until you are upright again, without letting the plates touch down."}],"de":[{"title":"Einstellen","text":"Stell den Sitz so ein, dass die Polster auf Brust oder Schultern liegen. Greif die Griffe und fixier die Füße."},{"title":"Einrollen","text":"Roll den Oberkörper mit der Bauchmuskulatur nach vorn unten ein. Zieh nicht mit den Armen und drück nicht mit den Beinen."},{"title":"Zurück","text":"Lass das Gewicht langsam zurück, bis du aufrecht sitzt. Die Gewichtsplatten setzen dabei nicht ab."}],"pt-PT":[{"title":"Ajustar","text":"Ajusta o banco para que as almofadas fiquem no peito ou nos ombros. Agarra as pegas e fixa os pés."},{"title":"Enrolar","text":"Contrai o abdómen e enrola o tronco para a frente e para baixo. Não puxes com os braços nem empurres com as pernas."},{"title":"Voltar","text":"Volta devagar até o tronco ficar direito, sem deixar os pesos pousarem."}],"pt-BR":[{"title":"Ajuste","text":"Ajuste o banco para que as almofadas fiquem no peito ou nos ombros. Segure as manoplas e prenda os pés."},{"title":"Enrolar","text":"Contraia o abdômen e enrole o tronco para a frente e para baixo. Não puxe com os braços nem empurre com as pernas."},{"title":"Voltar","text":"Volte devagar até o tronco ficar ereto, sem deixar as placas de peso encostarem."}]}'::jsonb,
    'machine', '{weight,reps}', '{"abs":0.9,"obliques":0.1}'::jsonb, 60),
  ('cable-crunch', '{"en":"Cable Crunch","de":"Kabel-Crunches","pt-PT":"Crunch no cabo","pt-BR":"Abdominal na polia"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Attach a rope to a high pulley and kneel facing the machine. Hold the rope ends beside your head."},{"title":"Crunch","text":"Round your spine and pull your ribs towards your hips. Keep your hips still and don''t sit back on your heels."},{"title":"Return","text":"Uncurl slowly until your back is straight again, keeping tension on the cable."}],"de":[{"title":"Aufbauen","text":"Häng ein Seil oben am Kabelzug ein und knie dich vor den Turm. Halt die Seilenden neben dem Kopf."},{"title":"Einrollen","text":"Roll den Oberkörper ein und zieh die Rippen Richtung Becken. Die Hüfte bleibt ruhig, setz dich nicht auf die Fersen."},{"title":"Zurück","text":"Roll dich langsam wieder auf, bis der Rücken gerade ist. Das Kabel bleibt unter Spannung."}],"pt-PT":[{"title":"Preparação","text":"Prende uma corda à polia alta e ajoelha-te de frente para a máquina. Segura as pontas da corda junto à cabeça."},{"title":"Enrolar","text":"Enrola a coluna e leva as costelas em direção à anca. Mantém a anca imóvel e não te sentes nos calcanhares."},{"title":"Voltar","text":"Desenrola devagar até as costas ficarem direitas, mantendo o cabo em tensão."}],"pt-BR":[{"title":"Preparação","text":"Prenda uma corda na polia alta e ajoelhe de frente para a máquina. Segure as pontas da corda ao lado da cabeça."},{"title":"Enrolar","text":"Enrole a coluna e leve as costelas em direção ao quadril. Mantenha o quadril parado e não sente nos calcanhares."},{"title":"Voltar","text":"Desenrole devagar até as costas ficarem retas, mantendo o cabo tensionado."}]}'::jsonb,
    'cable', '{weight,reps}', '{"abs":0.85,"obliques":0.15}'::jsonb, 60),
  ('hanging-leg-raise', '{"en":"Hanging Leg Raise","de":"Beinheben hängend","pt-PT":"Elevação de pernas em suspensão","pt-BR":"Elevação de pernas na barra"}'::jsonb,
    '{"en":[{"title":"Hang","text":"Hang from a pull-up bar with an overhand grip, arms straight and shoulders slightly engaged."},{"title":"Raise","text":"Raise your straight legs until they are at least parallel to the floor, tilting your pelvis up at the top."},{"title":"Lower","text":"Lower your legs slowly without swinging. Pause briefly at the bottom before the next rep."}],"de":[{"title":"Hängen","text":"Häng dich im Obergriff an die Klimmzugstange, die Arme gestreckt, die Schultern leicht aktiv."},{"title":"Anheben","text":"Heb die gestreckten Beine mindestens bis in die Waagerechte und roll oben das Becken ein."},{"title":"Absenken","text":"Senk die Beine langsam ab, ohne zu schwingen. Halt unten kurz an, bevor die nächste Wiederholung kommt."}],"pt-PT":[{"title":"Suspensão","text":"Pendura-te na barra de elevações em pega pronada, com os braços esticados e os ombros ligeiramente ativos."},{"title":"Elevar","text":"Eleva as pernas esticadas até ficarem pelo menos paralelas ao chão e enrola a bacia em cima."},{"title":"Descida","text":"Desce as pernas devagar, sem balançar. Faz uma pausa curta em baixo antes da repetição seguinte."}],"pt-BR":[{"title":"Suspensão","text":"Pendure-se na barra fixa com pegada pronada, braços estendidos e ombros levemente ativos."},{"title":"Elevar","text":"Eleve as pernas estendidas até ficarem pelo menos paralelas ao chão e incline a pelve para cima no final."},{"title":"Descida","text":"Desça as pernas devagar, sem balançar. Faça uma pausa curta embaixo antes da próxima repetição."}]}'::jsonb,
    'bodyweight', '{reps}', '{"abs":0.65,"quads":0.15,"obliques":0.1,"forearms":0.1}'::jsonb, 60),
  ('hanging-knee-raise', '{"en":"Hanging Knee Raise","de":"Knieheben hängend","pt-PT":"Elevação de joelhos em suspensão","pt-BR":"Elevação de joelhos na barra"}'::jsonb,
    '{"en":[{"title":"Hang","text":"Hang from a pull-up bar with an overhand grip, arms straight and legs together."},{"title":"Raise","text":"Pull your knees up towards your chest, rolling your pelvis up at the top. Avoid swinging."},{"title":"Lower","text":"Lower your legs slowly until they hang straight again before the next rep."}],"de":[{"title":"Hängen","text":"Häng dich im Obergriff an die Klimmzugstange, die Arme gestreckt, die Beine geschlossen."},{"title":"Anheben","text":"Zieh die Knie Richtung Brust und roll oben das Becken ein. Vermeide Schwung."},{"title":"Absenken","text":"Senk die Beine langsam ab, bis sie wieder gerade hängen, bevor die nächste Wiederholung kommt."}],"pt-PT":[{"title":"Suspensão","text":"Pendura-te na barra de elevações em pega pronada, com os braços esticados e as pernas juntas."},{"title":"Elevar","text":"Leva os joelhos ao peito e enrola a bacia em cima. Evita balançar."},{"title":"Descida","text":"Desce as pernas devagar até voltarem a ficar penduradas antes da repetição seguinte."}],"pt-BR":[{"title":"Suspensão","text":"Pendure-se na barra fixa com pegada pronada, braços estendidos e pernas juntas."},{"title":"Elevar","text":"Leve os joelhos ao peito e incline a pelve para cima no final. Evite balançar."},{"title":"Descida","text":"Desça as pernas devagar até ficarem penduradas de novo antes da próxima repetição."}]}'::jsonb,
    'bodyweight', '{reps}', '{"abs":0.7,"quads":0.1,"obliques":0.1,"forearms":0.1}'::jsonb, 60),
  ('toes-to-bar', '{"en":"Toes-to-Bar","de":"Toes to Bar","pt-PT":"Toes to bar","pt-BR":"Toes to bar"}'::jsonb,
    '{"en":[{"title":"Hang","text":"Hang from a pull-up bar with an overhand grip slightly wider than shoulder width, arms straight."},{"title":"Raise","text":"Press the bar down with straight arms, brace your abs and lift your feet until your toes touch the bar between your hands."},{"title":"Lower","text":"Lower your legs under control and stop the swing before the next rep."}],"de":[{"title":"Hängen","text":"Häng dich im Obergriff etwas breiter als schulterbreit an die Klimmzugstange, die Arme gestreckt."},{"title":"Hochziehen","text":"Drück die Stange mit gestreckten Armen nach unten, spann den Bauch an und heb die Füße, bis die Zehen die Stange zwischen den Händen berühren."},{"title":"Absenken","text":"Senk die Beine kontrolliert ab und fang den Schwung ab, bevor du die nächste Wiederholung startest."}],"pt-PT":[{"title":"Suspensão","text":"Pendura-te na barra de elevações em pega pronada, um pouco mais larga que os ombros, com os braços esticados."},{"title":"Subir","text":"Empurra a barra para baixo com os braços esticados, contrai o abdómen e sobe os pés até os dedos tocarem na barra entre as mãos."},{"title":"Descida","text":"Desce as pernas de forma controlada e trava o balanço antes da repetição seguinte."}],"pt-BR":[{"title":"Suspensão","text":"Pendure-se na barra fixa com pegada pronada, um pouco mais aberta que os ombros, braços estendidos."},{"title":"Subida","text":"Empurre a barra para baixo com os braços estendidos, contraia o abdômen e suba os pés até os dedos encostarem na barra entre as mãos."},{"title":"Descida","text":"Desça as pernas com controle e freie o balanço antes da próxima repetição."}]}'::jsonb,
    'bodyweight', '{reps}', '{"abs":0.6,"lats":0.15,"quads":0.15,"forearms":0.1}'::jsonb, 60),
  ('captains-chair-leg-raise', '{"en":"Captain''s Chair Leg Raise","de":"Beinheben im Stütz","pt-PT":"Elevação de pernas em apoio","pt-BR":"Elevação de pernas na paralela"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Rest your forearms on the pads of the captain''s chair, grip the handles and press your back against the backrest."},{"title":"Raise","text":"Raise your straight legs until they are parallel to the floor, keeping your back against the pad."},{"title":"Lower","text":"Lower your legs slowly until they hang straight down. Don''t swing into the next rep."}],"de":[{"title":"Aufbauen","text":"Leg die Unterarme auf die Polster der Beinhebestation, greif die Griffe und drück den Rücken gegen das Rückenpolster."},{"title":"Anheben","text":"Heb die gestreckten Beine bis in die Waagerechte. Der Rücken bleibt am Polster."},{"title":"Absenken","text":"Senk die Beine langsam ab, bis sie senkrecht hängen. Nimm keinen Schwung in die nächste Wiederholung mit."}],"pt-PT":[{"title":"Preparação","text":"Apoia os antebraços nas almofadas da estação, agarra as pegas e encosta bem as costas ao encosto."},{"title":"Elevar","text":"Eleva as pernas esticadas até ficarem paralelas ao chão, com as costas sempre encostadas."},{"title":"Descida","text":"Desce as pernas devagar até ficarem na vertical. Não ganhes balanço para a repetição seguinte."}],"pt-BR":[{"title":"Preparação","text":"Apoie os antebraços nas almofadas do aparelho, segure as manoplas e encoste bem as costas no encosto."},{"title":"Elevar","text":"Eleve as pernas estendidas até ficarem paralelas ao chão, com as costas sempre encostadas."},{"title":"Descida","text":"Desça as pernas devagar até ficarem na vertical. Não pegue impulso para a próxima repetição."}]}'::jsonb,
    'bodyweight', '{reps}', '{"abs":0.7,"quads":0.15,"obliques":0.15}'::jsonb, 60),
  ('lying-leg-raise', '{"en":"Lying Leg Raise","de":"Beinheben liegend","pt-PT":"Elevação de pernas deitado","pt-BR":"Elevação de pernas deitado"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Lie on your back with your legs straight and your hands under your hips or by your sides."},{"title":"Raise","text":"Keep your legs straight and lift them until they point at the ceiling. Press your lower back into the floor."},{"title":"Lower","text":"Lower your legs slowly and stop just before your heels touch the floor."}],"de":[{"title":"Aufbauen","text":"Leg dich auf den Rücken, die Beine gestreckt, die Hände unter dem Gesäß oder neben dem Körper."},{"title":"Anheben","text":"Heb die gestreckten Beine, bis sie zur Decke zeigen. Drück den unteren Rücken in den Boden."},{"title":"Absenken","text":"Senk die Beine langsam ab und halt kurz an, bevor die Fersen den Boden berühren."}],"pt-PT":[{"title":"Preparação","text":"Deita-te de costas com as pernas esticadas e as mãos por baixo dos glúteos ou ao lado do corpo."},{"title":"Elevar","text":"Eleva as pernas esticadas até apontarem para o teto. Pressiona a lombar contra o chão."},{"title":"Descida","text":"Desce as pernas devagar e trava-as pouco antes de os calcanhares tocarem no chão."}],"pt-BR":[{"title":"Preparação","text":"Deite de costas com as pernas estendidas e as mãos embaixo dos glúteos ou ao lado do corpo."},{"title":"Elevar","text":"Eleve as pernas estendidas até apontarem para o teto. Pressione a lombar contra o chão."},{"title":"Descida","text":"Desça as pernas devagar e pare pouco antes de os calcanhares encostarem no chão."}]}'::jsonb,
    'bodyweight', '{reps}', '{"abs":0.7,"quads":0.2,"obliques":0.1}'::jsonb, 45),
  ('russian-twist', '{"en":"Russian Twist","de":"Russian Twists","pt-PT":"Russian twist","pt-BR":"Russian twist"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Sit with your knees bent and heels on the floor, lean back to about 45° and hold your hands together in front of your chest."},{"title":"Twist","text":"Rotate your torso to one side until your hands are beside your hip, then to the other. Turn from your ribs, not just your arms."},{"title":"Control","text":"Keep your chest up and your back straight. Lift your feet off the floor to make it harder."}],"de":[{"title":"Aufbauen","text":"Setz dich mit gebeugten Knien hin, Fersen am Boden, lehn dich auf etwa 45° zurück und halt die Hände vor der Brust zusammen."},{"title":"Drehen","text":"Dreh den Oberkörper zur einen Seite, bis die Hände neben der Hüfte sind, dann zur anderen. Dreh aus dem Rumpf, nicht nur mit den Armen."},{"title":"Kontrolle","text":"Brust raus, Rücken gerade. Heb die Füße vom Boden ab, um es schwerer zu machen."}],"pt-PT":[{"title":"Preparação","text":"Senta-te com os joelhos fletidos e os calcanhares no chão, inclina o tronco para trás a cerca de 45° e junta as mãos à frente do peito."},{"title":"Rodar","text":"Roda o tronco para um lado até as mãos ficarem junto à anca e depois para o outro. Roda a partir do tronco, não só com os braços."},{"title":"Controlo","text":"Mantém o peito aberto e as costas direitas. Para dificultar, levanta os pés do chão."}],"pt-BR":[{"title":"Preparação","text":"Sente com os joelhos flexionados e os calcanhares no chão, incline o tronco para trás a cerca de 45° e junte as mãos na frente do peito."},{"title":"Girar","text":"Gire o tronco para um lado até as mãos ficarem ao lado do quadril e depois para o outro. Gire a partir do tronco, não só com os braços."},{"title":"Controle","text":"Mantenha o peito aberto e as costas retas. Para dificultar, tire os pés do chão."}]}'::jsonb,
    'bodyweight', '{reps}', '{"obliques":0.65,"abs":0.35}'::jsonb, 45),
  ('dumbbell-side-bend', '{"en":"Dumbbell Side Bend","de":"Seitbeugen mit Kurzhantel","pt-PT":"Inclinação lateral com haltere","pt-BR":"Flexão lateral com halter"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Stand tall with a dumbbell in one hand at your side, feet hip-width apart, other hand on your hip."},{"title":"Bend","text":"Bend sideways towards the dumbbell, sliding it down your thigh. Don''t lean forward or back."},{"title":"Return","text":"Pull yourself back upright using the obliques on the other side. Switch sides after the set."}],"de":[{"title":"Aufbauen","text":"Steh aufrecht, eine Kurzhantel seitlich in einer Hand, Füße hüftbreit, die andere Hand an der Hüfte."},{"title":"Neigen","text":"Neig den Oberkörper zur Seite der Hantel und lass sie am Oberschenkel entlang nach unten gleiten. Kipp nicht nach vorn oder hinten."},{"title":"Aufrichten","text":"Richte dich mit den seitlichen Bauchmuskeln der Gegenseite wieder auf. Wechsle nach dem Satz die Seite."}],"pt-PT":[{"title":"Preparação","text":"Fica de pé com um haltere numa mão ao lado do corpo, pés à largura da anca e a outra mão na cintura."},{"title":"Inclinar","text":"Inclina o tronco para o lado do haltere, deslizando-o ao longo da coxa. Não te inclines para a frente nem para trás."},{"title":"Voltar","text":"Volta à posição inicial usando os oblíquos do lado oposto. Troca de lado no fim da série."}],"pt-BR":[{"title":"Preparação","text":"Fique em pé com um halter em uma mão ao lado do corpo, pés na largura do quadril e a outra mão na cintura."},{"title":"Inclinar","text":"Incline o tronco para o lado do halter, deslizando o peso ao longo da coxa. Não incline para a frente nem para trás."},{"title":"Voltar","text":"Volte à posição inicial usando os oblíquos do lado oposto. Troque de lado no fim da série."}]}'::jsonb,
    'dumbbell', '{weight,reps}', '{"obliques":0.8,"abs":0.1,"lower_back":0.1}'::jsonb, 60),
  ('torso-rotation-machine', '{"en":"Torso Rotation Machine","de":"Rumpfrotation an der Maschine","pt-PT":"Rotação do tronco na máquina","pt-BR":"Rotação de tronco na máquina"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Sit on the machine with your hips locked in place and your chest against the pad. Set the starting angle to one side."},{"title":"Rotate","text":"Rotate your torso to the other side using your obliques, keeping your hips facing forward."},{"title":"Return","text":"Turn back slowly to the start position. Finish all reps, then set the machine up for the other side."}],"de":[{"title":"Einstellen","text":"Setz dich auf die Maschine, fixier die Hüfte und leg die Brust ans Polster. Stell den Startwinkel auf eine Seite ein."},{"title":"Drehen","text":"Dreh den Oberkörper mit den seitlichen Bauchmuskeln zur anderen Seite. Die Hüfte zeigt dabei nach vorn."},{"title":"Zurück","text":"Dreh langsam zurück in die Startposition. Mach alle Wiederholungen und stell die Maschine dann auf die andere Seite um."}],"pt-PT":[{"title":"Ajustar","text":"Senta-te na máquina com a anca fixa e o peito contra a almofada. Ajusta o ângulo inicial para um dos lados."},{"title":"Rodar","text":"Roda o tronco para o outro lado com os oblíquos, mantendo a anca virada para a frente."},{"title":"Voltar","text":"Volta devagar à posição inicial. Faz todas as repetições e depois muda a máquina para o outro lado."}],"pt-BR":[{"title":"Ajuste","text":"Sente na máquina com o quadril fixo e o peito apoiado na almofada. Ajuste o ângulo inicial para um dos lados."},{"title":"Girar","text":"Gire o tronco para o outro lado usando os oblíquos, mantendo o quadril voltado para a frente."},{"title":"Voltar","text":"Volte devagar à posição inicial. Faça todas as repetições e depois ajuste a máquina para o outro lado."}]}'::jsonb,
    'machine', '{weight,reps}', '{"obliques":0.75,"abs":0.25}'::jsonb, 60),
  ('cable-woodchop', '{"en":"Cable Woodchop","de":"Holzhacker am Kabel","pt-PT":"Lenhador no cabo","pt-BR":"Lenhador na polia"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Attach a D-handle to a high pulley and stand side-on to the machine. Hold the handle with both hands, arms extended towards the pulley."},{"title":"Chop","text":"Pull the handle diagonally down and across to your opposite hip, rotating your torso and pivoting your back foot."},{"title":"Return","text":"Let the handle travel slowly back up along the same path. Switch sides after the set."}],"de":[{"title":"Aufbauen","text":"Häng einen Einzelgriff oben am Kabelzug ein und stell dich seitlich dazu. Greif ihn mit beiden Händen, die Arme Richtung Rolle gestreckt."},{"title":"Hacken","text":"Zieh den Griff diagonal nach unten zur gegenüberliegenden Hüfte. Dreh dabei den Oberkörper mit und lass den hinteren Fuß mitdrehen."},{"title":"Zurück","text":"Führ den Griff langsam auf derselben Bahn zurück nach oben. Wechsle nach dem Satz die Seite."}],"pt-PT":[{"title":"Preparação","text":"Prende uma pega simples à polia alta e fica de lado para a máquina. Agarra-a com as duas mãos, braços esticados na direção da polia."},{"title":"Cortar","text":"Puxa a pega na diagonal, para baixo, até à anca oposta, rodando o tronco e o pé de trás."},{"title":"Voltar","text":"Deixa a pega subir devagar pelo mesmo caminho. Troca de lado no fim da série."}],"pt-BR":[{"title":"Preparação","text":"Prenda um puxador simples na polia alta e fique de lado para a máquina. Segure com as duas mãos, braços estendidos em direção à polia."},{"title":"Cortar","text":"Leve o puxador na diagonal, para baixo, até o quadril oposto, girando o tronco e o pé de trás."},{"title":"Voltar","text":"Deixe o puxador subir devagar pelo mesmo caminho. Troque de lado no fim da série."}]}'::jsonb,
    'cable', '{weight,reps}', '{"obliques":0.6,"abs":0.25,"front_delts":0.15}'::jsonb, 60),
  ('pallof-press', '{"en":"Pallof Press","de":"Pallof Press","pt-PT":"Pallof press","pt-BR":"Pallof press"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Attach a D-handle at chest height and stand side-on to the machine. Hold the handle at your chest with both hands, feet shoulder-width apart."},{"title":"Press","text":"Press the handle straight out in front of your chest and resist the cable pulling you round. Hold for a second."},{"title":"Return","text":"Bring the handle back to your chest under control, hips and shoulders square. Switch sides after the set."}],"de":[{"title":"Aufbauen","text":"Häng einen Einzelgriff auf Brusthöhe am Kabelzug ein und stell dich seitlich dazu. Halt ihn mit beiden Händen vor der Brust, Füße schulterbreit."},{"title":"Drücken","text":"Drück den Griff gerade nach vorn und lass dich vom Kabel nicht verdrehen. Halte die Position eine Sekunde."},{"title":"Zurück","text":"Führ den Griff kontrolliert zurück zur Brust, Hüfte und Schultern bleiben gerade. Wechsle nach dem Satz die Seite."}],"pt-PT":[{"title":"Preparação","text":"Prende uma pega simples à altura do peito e fica de lado para a máquina. Segura-a com as duas mãos junto ao peito, pés à largura dos ombros."},{"title":"Empurrar","text":"Empurra a pega a direito para a frente e não deixes o cabo rodar-te o tronco. Aguenta um segundo."},{"title":"Voltar","text":"Traz a pega de volta ao peito com controlo, com a anca e os ombros virados para a frente. Troca de lado no fim da série."}],"pt-BR":[{"title":"Preparação","text":"Prenda um puxador simples na altura do peito e fique de lado para a máquina. Segure com as duas mãos junto ao peito, pés na largura dos ombros."},{"title":"Empurrar","text":"Empurre o puxador em linha reta para a frente sem deixar o cabo girar seu tronco. Segure por um segundo."},{"title":"Voltar","text":"Traga o puxador de volta ao peito com controle, com o quadril e os ombros voltados para a frente. Troque de lado no fim da série."}]}'::jsonb,
    'cable', '{weight,reps}', '{"obliques":0.6,"abs":0.4}'::jsonb, 45),
  ('ab-wheel-rollout', '{"en":"Ab Wheel Rollout","de":"Bauchroller","pt-PT":"Roda abdominal","pt-BR":"Rodinha abdominal"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Kneel on a mat and hold the ab wheel under your shoulders. Brace your abs and tuck your pelvis slightly."},{"title":"Roll out","text":"Roll the wheel forward slowly as far as you can without your lower back sagging."},{"title":"Roll back","text":"Pull the wheel back towards your knees using your abs, not your hips. Keep your arms straight."}],"de":[{"title":"Aufbauen","text":"Knie dich auf eine Matte und halt den Bauchroller unter den Schultern. Spann den Bauch an und roll das Becken leicht ein."},{"title":"Ausrollen","text":"Roll langsam so weit nach vorn, wie du kannst, ohne ins Hohlkreuz zu fallen."},{"title":"Zurückrollen","text":"Zieh den Roller mit der Bauchmuskulatur zurück zu den Knien, nicht aus der Hüfte. Die Arme bleiben gestreckt."}],"pt-PT":[{"title":"Preparação","text":"Ajoelha-te num tapete e segura a roda por baixo dos ombros. Contrai o abdómen e enrola ligeiramente a bacia."},{"title":"Avançar","text":"Rola a roda para a frente devagar, até onde conseguires sem deixar a lombar arquear."},{"title":"Recuar","text":"Puxa a roda de volta aos joelhos com o abdómen, não com a anca. Mantém os braços esticados."}],"pt-BR":[{"title":"Preparação","text":"Ajoelhe em um colchonete e segure a rodinha embaixo dos ombros. Contraia o abdômen e encaixe levemente o quadril."},{"title":"Avançar","text":"Role a rodinha para a frente devagar, até onde conseguir sem deixar a lombar arquear."},{"title":"Voltar","text":"Puxe a rodinha de volta até os joelhos com o abdômen, não com o quadril. Mantenha os braços estendidos."}]}'::jsonb,
    'bodyweight', '{reps}', '{"abs":0.7,"lats":0.15,"obliques":0.15}'::jsonb, 60),
  ('mountain-climber', '{"en":"Mountain Climber","de":"Mountain Climbers","pt-PT":"Escalador","pt-BR":"Escalador"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Start in a high plank with your hands under your shoulders and your body in a straight line."},{"title":"Drive","text":"Drive one knee towards your chest, then switch legs quickly in a running rhythm."},{"title":"Keep form","text":"Keep your hips level with your shoulders and your hands planted. Slow down rather than letting your hips pike up."}],"de":[{"title":"Aufbauen","text":"Geh in den hohen Stütz, die Hände unter den Schultern, der Körper in einer geraden Linie."},{"title":"Laufen","text":"Zieh ein Knie Richtung Brust und wechsle die Beine zügig im Laufrhythmus."},{"title":"Form halten","text":"Die Hüfte bleibt auf Schulterhöhe, die Hände fest am Boden. Werde lieber langsamer, statt die Hüfte hochzuschieben."}],"pt-PT":[{"title":"Preparação","text":"Começa em prancha alta, com as mãos por baixo dos ombros e o corpo em linha reta."},{"title":"Correr","text":"Leva um joelho ao peito e troca de perna rapidamente, como se estivesses a correr."},{"title":"Manter a forma","text":"Mantém a anca à altura dos ombros e as mãos bem apoiadas. Abranda em vez de deixar a anca subir."}],"pt-BR":[{"title":"Preparação","text":"Comece em prancha alta, com as mãos embaixo dos ombros e o corpo em linha reta."},{"title":"Correr","text":"Leve um joelho ao peito e troque de perna rápido, como se estivesse correndo."},{"title":"Manter a postura","text":"Mantenha o quadril na altura dos ombros e as mãos firmes no chão. Diminua o ritmo em vez de deixar o quadril subir."}]}'::jsonb,
    'bodyweight', '{seconds}', '{"abs":0.5,"quads":0.2,"front_delts":0.15,"obliques":0.15}'::jsonb, 45),
  ('dead-bug', '{"en":"Dead Bug","de":"Dead Bug","pt-PT":"Dead bug","pt-BR":"Dead bug"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Lie on your back with your arms pointing at the ceiling and your hips and knees bent 90°. Press your lower back into the floor."},{"title":"Extend","text":"Slowly lower one arm overhead and straighten the opposite leg until both hover just above the floor."},{"title":"Switch","text":"Return to the start and repeat on the other side. Keep your lower back flat and breathe out as you extend."}],"de":[{"title":"Aufbauen","text":"Leg dich auf den Rücken, die Arme zur Decke gestreckt, Hüfte und Knie 90° gebeugt. Drück den unteren Rücken in den Boden."},{"title":"Strecken","text":"Senk langsam einen Arm nach hinten über den Kopf und streck das gegenüberliegende Bein, bis beide knapp über dem Boden schweben."},{"title":"Wechseln","text":"Geh zurück in die Startposition und wechsle die Seite. Der untere Rücken bleibt flach, beim Strecken ausatmen."}],"pt-PT":[{"title":"Preparação","text":"Deita-te de costas com os braços apontados para o teto e a anca e os joelhos fletidos a 90°. Pressiona a lombar contra o chão."},{"title":"Estender","text":"Leva devagar um braço para trás da cabeça e estica a perna oposta até ambos ficarem um pouco acima do chão."},{"title":"Alternar","text":"Volta ao início e repete do outro lado. Mantém a lombar colada ao chão e expira ao estender."}],"pt-BR":[{"title":"Preparação","text":"Deite de costas com os braços apontados para o teto e o quadril e os joelhos flexionados a 90°. Pressione a lombar contra o chão."},{"title":"Estender","text":"Leve devagar um braço para trás da cabeça e estenda a perna oposta até os dois ficarem um pouco acima do chão."},{"title":"Alternar","text":"Volte ao início e repita do outro lado. Mantenha a lombar colada no chão e solte o ar ao estender."}]}'::jsonb,
    'bodyweight', '{reps}', '{"abs":0.75,"obliques":0.25}'::jsonb, 45),
  ('bird-dog', '{"en":"Bird Dog","de":"Bird Dog","pt-PT":"Bird dog","pt-BR":"Perdigueiro"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Kneel on all fours with your hands under your shoulders and your knees under your hips. Keep your back flat."},{"title":"Extend","text":"Reach one arm forward and the opposite leg back until both are in line with your torso. Hold for a second."},{"title":"Switch","text":"Return slowly and repeat on the other side. Keep your hips level and don''t arch your lower back."}],"de":[{"title":"Aufbauen","text":"Geh in den Vierfüßlerstand, Hände unter den Schultern, Knie unter der Hüfte. Der Rücken ist gerade."},{"title":"Strecken","text":"Streck einen Arm nach vorn und das gegenüberliegende Bein nach hinten, bis beide eine Linie mit dem Oberkörper bilden. Halte kurz."},{"title":"Wechseln","text":"Komm langsam zurück und wechsle die Seite. Die Hüfte bleibt waagerecht, kein Hohlkreuz."}],"pt-PT":[{"title":"Preparação","text":"Põe-te de quatro, com as mãos por baixo dos ombros e os joelhos por baixo da anca. Mantém as costas direitas."},{"title":"Estender","text":"Estica um braço para a frente e a perna oposta para trás até ficarem alinhados com o tronco. Aguenta um segundo."},{"title":"Alternar","text":"Volta devagar e repete do outro lado. Mantém a anca nivelada e não arqueies a lombar."}],"pt-BR":[{"title":"Preparação","text":"Fique em quatro apoios, com as mãos embaixo dos ombros e os joelhos embaixo do quadril. Mantenha as costas retas."},{"title":"Estender","text":"Estenda um braço para a frente e a perna oposta para trás até ficarem alinhados com o tronco. Segure por um segundo."},{"title":"Alternar","text":"Volte devagar e repita do outro lado. Mantenha o quadril nivelado e não arqueie a lombar."}]}'::jsonb,
    'bodyweight', '{reps}', '{"lower_back":0.4,"glutes":0.3,"abs":0.2,"obliques":0.1}'::jsonb, 45),
  ('paused-squat', '{"en":"Paused Squat","de":"Kniebeugen mit Pause","pt-PT":"Agachamento com pausa","pt-BR":"Agachamento com pausa"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Unrack the bar onto your upper back, feet shoulder-width apart, toes slightly out. Brace hard."},{"title":"Pause","text":"Squat to at least parallel and hold still in the bottom for 2 seconds without losing tension."},{"title":"Drive","text":"Drive up out of the hole without bouncing, pushing through your whole foot."}],"de":[{"title":"Aufbau","text":"Nimm die Stange auf den oberen Rücken, Füße schulterbreit, Zehen leicht nach außen. Rumpf fest anspannen."},{"title":"Pause","text":"Geh mindestens bis parallel runter und halte unten 2 Sekunden still, ohne die Spannung zu verlieren."},{"title":"Hoch","text":"Drück dich ohne Schwung aus der Hocke hoch, über den ganzen Fuß."}],"pt-PT":[{"title":"Preparação","text":"Tira a barra do suporte e apoia-a na parte de cima das costas, pés à largura dos ombros. Contrai bem o core."},{"title":"Pausa","text":"Desce pelo menos até à paralela e fica parado em baixo 2 segundos, sem perder a tensão."},{"title":"Subir","text":"Sobe sem fazer ressalto, a empurrar com o pé todo."}],"pt-BR":[{"title":"Preparação","text":"Tire a barra do suporte e apoie no alto das costas, pés na largura dos ombros. Contraia bem o core."},{"title":"Pausa","text":"Desça pelo menos até a paralela e fique parado embaixo por 2 segundos, sem perder a tensão."},{"title":"Subir","text":"Suba sem quicar, empurrando com o pé inteiro."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"quads":0.55,"glutes":0.3,"adductors":0.15}'::jsonb, 180),
  ('box-squat', '{"en":"Box Squat","de":"Box Squats","pt-PT":"Agachamento na caixa","pt-BR":"Agachamento no caixote"}'::jsonb,
    '{"en":[{"title":"Box height","text":"Set a box behind you at a height where your thighs are about parallel when seated. Stand a little wider than usual."},{"title":"Sit back","text":"Push your hips back and lower under control until you sit lightly on the box. Stay braced and don''t relax."},{"title":"Drive","text":"Without rocking or bouncing, drive your feet into the floor and stand up explosively."}],"de":[{"title":"Box","text":"Stell eine Box hinter dich, auf der deine Oberschenkel im Sitzen etwa parallel sind. Stand etwas breiter als sonst."},{"title":"Absetzen","text":"Schieb die Hüfte nach hinten und setz dich kontrolliert auf die Box. Bleib dabei voll angespannt und lass nicht locker."},{"title":"Hoch","text":"Drück die Füße ohne Schaukeln oder Abprallen in den Boden und steh explosiv auf."}],"pt-PT":[{"title":"Caixa","text":"Coloca uma caixa atrás de ti, à altura em que as coxas ficam paralelas quando te sentas. Afasta os pés um pouco mais do que o habitual."},{"title":"Sentar","text":"Leva a anca para trás e desce com controlo até te sentares ao de leve na caixa. Mantém a tensão, não relaxes."},{"title":"Subir","text":"Sem balançar nem fazer ressalto, empurra o chão com os pés e levanta-te com força."}],"pt-BR":[{"title":"Caixote","text":"Coloque um caixote atrás de você, na altura em que as coxas ficam paralelas ao sentar. Abra os pés um pouco mais que o normal."},{"title":"Sentar","text":"Leve o quadril para trás e desça com controle até sentar de leve no caixote. Mantenha a tensão, não relaxe."},{"title":"Subir","text":"Sem balançar nem quicar, empurre o chão com os pés e levante com força."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"quads":0.45,"glutes":0.35,"adductors":0.1,"hamstrings":0.1}'::jsonb, 150),
  ('front-squat', '{"en":"Front Squat","de":"Frontkniebeugen","pt-PT":"Agachamento frontal","pt-BR":"Agachamento frontal"}'::jsonb,
    '{"en":[{"title":"Rack","text":"Rest the bar on your front delts close to your throat, elbows high, fingertips under the bar or arms crossed."},{"title":"Descend","text":"Sit straight down with your torso upright and elbows up, letting your knees travel forward over your toes."},{"title":"Drive","text":"Push up through your whole foot and lead with your elbows so the bar doesn''t roll forward."}],"de":[{"title":"Ablage","text":"Leg die Stange vorne auf die Schultern nah am Hals, Ellbogen hoch, Finger unter der Stange oder Arme gekreuzt."},{"title":"Runter","text":"Setz dich mit aufrechtem Oberkörper gerade nach unten, Ellbogen oben. Die Knie wandern über die Zehen."},{"title":"Hoch","text":"Drück dich über den ganzen Fuß hoch und führ mit den Ellbogen, damit die Stange nicht nach vorne rollt."}],"pt-PT":[{"title":"Barra","text":"Apoia a barra na frente dos ombros, junto ao pescoço, cotovelos altos e dedos por baixo da barra ou braços cruzados."},{"title":"Descer","text":"Desce a direito com o tronco vertical e os cotovelos altos, com os joelhos a avançar sobre os pés."},{"title":"Subir","text":"Empurra com o pé todo e sobe a levar os cotovelos para cima, para a barra não rolar para a frente."}],"pt-BR":[{"title":"Barra","text":"Apoie a barra na frente dos ombros, perto do pescoço, cotovelos altos e dedos embaixo da barra ou braços cruzados."},{"title":"Descer","text":"Desça reto com o tronco ereto e os cotovelos altos, com os joelhos avançando sobre os pés."},{"title":"Subir","text":"Empurre com o pé inteiro e suba levando os cotovelos para cima, para a barra não rolar para frente."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"quads":0.65,"glutes":0.2,"adductors":0.1,"upper_back":0.05}'::jsonb, 150),
  ('safety-bar-squat', '{"en":"Safety Bar Squat","de":"Safety-Bar-Kniebeugen","pt-PT":"Agachamento com safety bar","pt-BR":"Agachamento com safety bar"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Rest the padded yoke on your upper back and hold the handles in front of you. Feet shoulder-width apart."},{"title":"Descend","text":"Sit down between your hips with your chest up. Pull down on the handles so the bar doesn''t tip you forward."},{"title":"Drive","text":"Push through your whole foot back to standing, keeping your upper back tight against the pads."}],"de":[{"title":"Aufbau","text":"Leg die Polster der Safety Bar auf den oberen Rücken und greif die Griffe vor dir. Füße schulterbreit."},{"title":"Runter","text":"Setz dich zwischen die Hüften, Brust oben. Zieh die Griffe nach unten, damit die Stange dich nicht nach vorne kippt."},{"title":"Hoch","text":"Drück dich über den ganzen Fuß hoch und halt den oberen Rücken fest gegen die Polster."}],"pt-PT":[{"title":"Preparação","text":"Coloca a barra almofadada na parte de cima das costas e agarra as pegas à tua frente. Pés à largura dos ombros."},{"title":"Descer","text":"Senta-te entre as ancas com o peito para cima. Puxa as pegas para baixo para a barra não te inclinar para a frente."},{"title":"Subir","text":"Empurra com o pé todo até ficares de pé, com a parte de cima das costas firme contra as almofadas."}],"pt-BR":[{"title":"Preparação","text":"Coloque a barra acolchoada no alto das costas e segure os pegadores à sua frente. Pés na largura dos ombros."},{"title":"Descer","text":"Sente entre os quadris com o peito para cima. Puxe os pegadores para baixo para a barra não jogar você para frente."},{"title":"Subir","text":"Empurre com o pé inteiro até ficar em pé, mantendo o alto das costas firme contra as almofadas."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"quads":0.55,"glutes":0.25,"upper_back":0.1,"adductors":0.1}'::jsonb, 150),
  ('smith-squat', '{"en":"Smith Machine Squat","de":"Kniebeugen an der Multipresse","pt-PT":"Agachamento na máquina Smith","pt-BR":"Agachamento no Smith"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Set the bar on your upper back and place your feet shoulder-width apart, slightly in front of the bar."},{"title":"Descend","text":"Rotate the bar off the hooks and lower until your thighs are at least parallel, back flat."},{"title":"Drive","text":"Press up through your whole foot and twist the bar back onto the hooks after your last rep."}],"de":[{"title":"Aufbau","text":"Leg die Stange auf den oberen Rücken und stell die Füße schulterbreit, leicht vor der Stange."},{"title":"Runter","text":"Dreh die Stange aus den Haken und geh runter, bis die Oberschenkel mindestens parallel sind, Rücken gerade."},{"title":"Hoch","text":"Drück dich über den ganzen Fuß hoch und häng die Stange nach der letzten Wiederholung wieder ein."}],"pt-PT":[{"title":"Preparação","text":"Apoia a barra na parte de cima das costas e coloca os pés à largura dos ombros, um pouco à frente da barra."},{"title":"Descer","text":"Roda a barra para a soltar dos ganchos e desce até as coxas ficarem pelo menos paralelas, costas direitas."},{"title":"Subir","text":"Empurra com o pé todo e, depois da última repetição, roda a barra para a prender nos ganchos."}],"pt-BR":[{"title":"Preparação","text":"Apoie a barra no alto das costas e coloque os pés na largura dos ombros, um pouco à frente da barra."},{"title":"Descer","text":"Gire a barra para soltar dos ganchos e desça até as coxas ficarem pelo menos paralelas, costas retas."},{"title":"Subir","text":"Empurre com o pé inteiro e, depois da última repetição, gire a barra para travar nos ganchos."}]}'::jsonb,
    'machine', '{weight,reps}', '{"quads":0.65,"glutes":0.25,"adductors":0.1}'::jsonb, 120),
  ('goblet-squat', '{"en":"Goblet Squat","de":"Goblet Squat","pt-PT":"Agachamento goblet","pt-BR":"Agachamento goblet"}'::jsonb,
    '{"en":[{"title":"Hold","text":"Hold one dumbbell vertically against your chest with both hands, elbows pointing down."},{"title":"Descend","text":"Sit down between your heels with your chest up until your elbows brush the inside of your knees."},{"title":"Drive","text":"Push through your whole foot back to standing, keeping the dumbbell close to your chest."}],"de":[{"title":"Halten","text":"Halt eine Kurzhantel senkrecht mit beiden Händen vor der Brust, die Ellbogen zeigen nach unten."},{"title":"Runter","text":"Setz dich mit aufrechter Brust zwischen die Fersen, bis die Ellbogen die Innenseite der Knie berühren."},{"title":"Hoch","text":"Drück dich über den ganzen Fuß hoch, die Kurzhantel bleibt nah an der Brust."}],"pt-PT":[{"title":"Pega","text":"Segura um halter na vertical junto ao peito com as duas mãos, cotovelos virados para baixo."},{"title":"Descer","text":"Senta-te entre os calcanhares com o peito para cima até os cotovelos tocarem no interior dos joelhos."},{"title":"Subir","text":"Empurra com o pé todo até ficares de pé, com o halter sempre junto ao peito."}],"pt-BR":[{"title":"Pegada","text":"Segure um halter na vertical junto ao peito com as duas mãos, cotovelos apontando para baixo."},{"title":"Descer","text":"Sente entre os calcanhares com o peito para cima até os cotovelos encostarem na parte interna dos joelhos."},{"title":"Subir","text":"Empurre com o pé inteiro até ficar em pé, mantendo o halter colado ao peito."}]}'::jsonb,
    'dumbbell', '{weight,reps}', '{"quads":0.6,"glutes":0.25,"adductors":0.1,"abs":0.05}'::jsonb, 90),
  ('sumo-squat', '{"en":"Sumo Squat","de":"Sumo-Kniebeugen","pt-PT":"Agachamento sumo","pt-BR":"Agachamento sumô"}'::jsonb,
    '{"en":[{"title":"Stance","text":"Stand with your feet well beyond shoulder-width, toes turned out about 45°. Hold one dumbbell between your legs."},{"title":"Descend","text":"Lower straight down with your torso upright, pushing your knees out in line with your toes."},{"title":"Drive","text":"Stand back up by driving through your heels and squeezing your glutes at the top."}],"de":[{"title":"Stand","text":"Stell die Füße deutlich breiter als schulterbreit, Zehen etwa 45° nach außen. Halt eine Kurzhantel zwischen den Beinen."},{"title":"Runter","text":"Geh mit aufrechtem Oberkörper gerade nach unten und drück die Knie in Richtung der Zehen nach außen."},{"title":"Hoch","text":"Drück dich über die Fersen wieder hoch und spann oben das Gesäß an."}],"pt-PT":[{"title":"Posição","text":"Afasta bem os pés, para lá da largura dos ombros, com as pontas a 45° para fora. Segura um halter entre as pernas."},{"title":"Descer","text":"Desce a direito com o tronco vertical, a empurrar os joelhos para fora na direção dos pés."},{"title":"Subir","text":"Sobe a empurrar com os calcanhares e contrai os glúteos em cima."}],"pt-BR":[{"title":"Base","text":"Abra bem os pés, além da largura dos ombros, com as pontas a 45° para fora. Segure um halter entre as pernas."},{"title":"Descer","text":"Desça reto com o tronco ereto, empurrando os joelhos para fora na direção dos pés."},{"title":"Subir","text":"Suba empurrando com os calcanhares e contraia os glúteos em cima."}]}'::jsonb,
    'dumbbell', '{weight,reps}', '{"quads":0.4,"glutes":0.3,"adductors":0.3}'::jsonb, 90),
  ('bodyweight-squat', '{"en":"Bodyweight Squat","de":"Kniebeugen ohne Gewicht","pt-PT":"Agachamento sem peso","pt-BR":"Agachamento sem peso"}'::jsonb,
    '{"en":[{"title":"Stance","text":"Feet shoulder-width apart, toes slightly out. Hold your arms out in front of you for balance."},{"title":"Descend","text":"Sit back and down until your thighs are at least parallel, heels flat and chest up."},{"title":"Stand","text":"Push through your whole foot to stand up and squeeze your glutes at the top. Keep a steady rhythm."}],"de":[{"title":"Stand","text":"Füße schulterbreit, Zehen leicht nach außen. Streck die Arme zum Ausbalancieren nach vorne."},{"title":"Runter","text":"Setz dich nach hinten unten, bis die Oberschenkel mindestens parallel sind, Fersen am Boden, Brust oben."},{"title":"Hoch","text":"Drück dich über den ganzen Fuß hoch und spann oben das Gesäß an. Halte einen gleichmäßigen Rhythmus."}],"pt-PT":[{"title":"Posição","text":"Pés à largura dos ombros, pontas ligeiramente para fora. Estica os braços à frente para te equilibrares."},{"title":"Descer","text":"Leva a anca para trás e para baixo até as coxas ficarem pelo menos paralelas, calcanhares no chão."},{"title":"Subir","text":"Empurra com o pé todo até ficares de pé e contrai os glúteos em cima. Mantém um ritmo constante."}],"pt-BR":[{"title":"Base","text":"Pés na largura dos ombros, pontas levemente para fora. Estenda os braços à frente para se equilibrar."},{"title":"Descer","text":"Leve o quadril para trás e para baixo até as coxas ficarem pelo menos paralelas, calcanhares no chão."},{"title":"Subir","text":"Empurre com o pé inteiro até ficar em pé e contraia os glúteos em cima. Mantenha um ritmo constante."}]}'::jsonb,
    'bodyweight', '{reps}', '{"quads":0.6,"glutes":0.3,"adductors":0.1}'::jsonb, 60),
  ('jump-squat', '{"en":"Jump Squat","de":"Sprungkniebeugen","pt-PT":"Agachamento com salto","pt-BR":"Agachamento com salto"}'::jsonb,
    '{"en":[{"title":"Stance","text":"Stand with your feet shoulder-width apart and your hands at your chest or behind your head."},{"title":"Load","text":"Drop quickly into a quarter to half squat, swinging your arms back if you like."},{"title":"Jump","text":"Explode straight up, land softly on the balls of your feet and sink straight into the next rep."}],"de":[{"title":"Stand","text":"Stell die Füße schulterbreit, die Hände vor der Brust oder hinter dem Kopf."},{"title":"Ausholen","text":"Geh schnell in eine Viertel- bis halbe Kniebeuge, die Arme kannst du dabei nach hinten schwingen."},{"title":"Springen","text":"Spring explosiv nach oben, lande weich auf den Fußballen und geh direkt in die nächste Wiederholung."}],"pt-PT":[{"title":"Posição","text":"Fica com os pés à largura dos ombros e as mãos junto ao peito ou atrás da cabeça."},{"title":"Balanço","text":"Desce depressa até meio agachamento e, se quiseres, balança os braços para trás."},{"title":"Salto","text":"Salta com força para cima, aterra suavemente na ponta dos pés e passa logo à repetição seguinte."}],"pt-BR":[{"title":"Base","text":"Fique com os pés na largura dos ombros e as mãos junto ao peito ou atrás da cabeça."},{"title":"Impulso","text":"Desça rápido até meio agachamento e, se quiser, jogue os braços para trás."},{"title":"Salto","text":"Salte com força para cima, aterrisse de leve na ponta dos pés e emende na próxima repetição."}]}'::jsonb,
    'bodyweight', '{reps}', '{"quads":0.55,"glutes":0.3,"calves":0.15}'::jsonb, 90),
  ('reverse-hack-squat', '{"en":"Reverse Hack Squat","de":"Reverse Hack Squat","pt-PT":"Agachamento hack invertido","pt-BR":"Agachamento hack invertido"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Face the machine with your chest against the back pad and shoulders under the pads. Feet hip-width on the platform."},{"title":"Descend","text":"Release the safeties and sit your hips back and down, letting your torso lean forward with the pad."},{"title":"Drive","text":"Drive through your heels and squeeze your glutes to come up, without locking your knees at the top."}],"de":[{"title":"Aufbau","text":"Stell dich mit dem Gesicht zur Maschine, Brust am Rückenpolster, Schultern unter den Polstern. Füße hüftbreit."},{"title":"Runter","text":"Löse die Sicherung und schieb die Hüfte nach hinten unten. Der Oberkörper neigt sich mit dem Polster nach vorne."},{"title":"Hoch","text":"Drück dich über die Fersen hoch und spann das Gesäß an, ohne oben die Knie durchzustrecken."}],"pt-PT":[{"title":"Preparação","text":"Fica de frente para a máquina, peito contra o encosto e ombros por baixo das almofadas. Pés à largura da anca."},{"title":"Descer","text":"Solta o travão, leva a anca para trás e para baixo e deixa o tronco inclinar com o encosto."},{"title":"Subir","text":"Empurra com os calcanhares e contrai os glúteos para subir, sem bloquear os joelhos em cima."}],"pt-BR":[{"title":"Preparação","text":"Fique de frente para a máquina, peito contra o encosto e ombros embaixo das almofadas. Pés na largura do quadril."},{"title":"Descer","text":"Solte a trava e leve o quadril para trás e para baixo, deixando o tronco inclinar junto com o encosto."},{"title":"Subir","text":"Empurre com os calcanhares e contraia os glúteos para subir, sem travar os joelhos em cima."}]}'::jsonb,
    'machine', '{weight,reps}', '{"glutes":0.45,"quads":0.4,"hamstrings":0.15}'::jsonb, 120),
  ('pendulum-squat', '{"en":"Pendulum Squat","de":"Pendel-Kniebeugen","pt-PT":"Agachamento pêndulo","pt-BR":"Agachamento pêndulo"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Step onto the platform with your back flat against the pad and shoulders under the pads. Feet hip-width, mid-platform."},{"title":"Descend","text":"Release the stop and let the pad swing down in its arc. Sink as deep as you can with your heels down."},{"title":"Drive","text":"Push through your whole foot to swing back up, keeping a slight bend in your knees at the top."}],"de":[{"title":"Aufbau","text":"Steig auf die Plattform, Rücken flach am Polster, Schultern unter den Polstern. Füße hüftbreit in der Mitte."},{"title":"Runter","text":"Löse den Stopper und lass das Polster im Bogen nach unten schwingen. Geh so tief wie möglich, Fersen bleiben unten."},{"title":"Hoch","text":"Drück dich über den ganzen Fuß zurück nach oben und lass die Knie oben leicht gebeugt."}],"pt-PT":[{"title":"Preparação","text":"Sobe para a plataforma com as costas encostadas e os ombros por baixo das almofadas. Pés à largura da anca, a meio."},{"title":"Descer","text":"Solta o travão e deixa o encosto descer em arco. Desce o mais fundo que conseguires, com os calcanhares apoiados."},{"title":"Subir","text":"Empurra com o pé todo para voltar a subir e mantém os joelhos ligeiramente fletidos em cima."}],"pt-BR":[{"title":"Preparação","text":"Suba na plataforma com as costas apoiadas e os ombros embaixo das almofadas. Pés na largura do quadril, no meio."},{"title":"Descer","text":"Solte a trava e deixe o encosto descer em arco. Desça o mais fundo que conseguir, com os calcanhares apoiados."},{"title":"Subir","text":"Empurre com o pé inteiro para voltar a subir e mantenha os joelhos levemente flexionados em cima."}]}'::jsonb,
    'machine', '{weight,reps}', '{"quads":0.75,"glutes":0.2,"adductors":0.05}'::jsonb, 120),
  ('belt-squat', '{"en":"Belt Squat","de":"Belt Squat","pt-PT":"Belt squat","pt-BR":"Belt squat"}'::jsonb,
    '{"en":[{"title":"Belt","text":"Put on the hip belt and clip it to the machine''s chain or strap. Stand on the platform, feet shoulder-width."},{"title":"Descend","text":"Hold the handles lightly for balance, release the lever and squat down with your torso upright."},{"title":"Drive","text":"Push through your whole foot back to standing. The load hangs from your hips, so your spine stays unloaded."}],"de":[{"title":"Gurt","text":"Leg den Hüftgurt an und häng ihn an die Kette oder das Band der Maschine. Stell dich schulterbreit auf die Plattform."},{"title":"Runter","text":"Halt dich locker an den Griffen fest, löse den Hebel und geh mit aufrechtem Oberkörper in die Hocke."},{"title":"Hoch","text":"Drück dich über den ganzen Fuß hoch. Die Last hängt an der Hüfte, die Wirbelsäule bleibt entlastet."}],"pt-PT":[{"title":"Cinto","text":"Coloca o cinto na anca e prende-o à corrente ou à fita da máquina. Fica na plataforma com os pés à largura dos ombros."},{"title":"Descer","text":"Segura as pegas ao de leve para te equilibrares, solta a alavanca e agacha com o tronco direito."},{"title":"Subir","text":"Empurra com o pé todo até ficares de pé. A carga fica presa à anca, por isso a coluna fica livre de peso."}],"pt-BR":[{"title":"Cinto","text":"Coloque o cinto no quadril e prenda na corrente ou na fita da máquina. Fique na plataforma com os pés na largura dos ombros."},{"title":"Descer","text":"Segure os pegadores de leve para se equilibrar, solte a alavanca e agache com o tronco ereto."},{"title":"Subir","text":"Empurre com o pé inteiro até ficar em pé. A carga fica presa no quadril, então a coluna fica livre de peso."}]}'::jsonb,
    'machine', '{weight,reps}', '{"quads":0.55,"glutes":0.3,"adductors":0.15}'::jsonb, 120),
  ('single-leg-press', '{"en":"Single-Leg Leg Press","de":"Beinpresse einbeinig","pt-PT":"Prensa de pernas unilateral","pt-BR":"Leg press unilateral"}'::jsonb,
    '{"en":[{"title":"Foot","text":"Place one foot in the middle of the platform in line with your hip. Rest the other foot on the floor or frame."},{"title":"Lower","text":"Release the safety and bend your knee slowly to about 90°, keeping your hips on the seat."},{"title":"Press","text":"Push through your whole foot without locking your knee. Finish all reps, then switch legs."}],"de":[{"title":"Fuß","text":"Stell einen Fuß mittig auf die Plattform, in Linie mit der Hüfte. Den anderen stellst du auf den Boden oder den Rahmen."},{"title":"Absenken","text":"Löse die Sicherung und beug das Knie langsam bis etwa 90°. Das Becken bleibt am Sitz."},{"title":"Drücken","text":"Drück über den ganzen Fuß, ohne das Knie durchzustrecken. Erst alle Wiederholungen, dann Bein wechseln."}],"pt-PT":[{"title":"Pé","text":"Coloca um pé no meio da plataforma, alinhado com a anca. Apoia o outro pé no chão ou na estrutura."},{"title":"Descida","text":"Solta o travão e flete o joelho devagar até cerca de 90°, sem tirar a anca do assento."},{"title":"Empurrar","text":"Empurra com o pé todo sem bloquear o joelho. Faz todas as repetições e depois troca de perna."}],"pt-BR":[{"title":"Pé","text":"Coloque um pé no meio da plataforma, alinhado com o quadril. Apoie o outro pé no chão ou na estrutura."},{"title":"Descida","text":"Solte a trava e flexione o joelho devagar até cerca de 90°, sem tirar o quadril do banco."},{"title":"Empurrar","text":"Empurre com o pé inteiro sem travar o joelho. Faça todas as repetições e depois troque de perna."}]}'::jsonb,
    'machine', '{weight,reps}', '{"quads":0.6,"glutes":0.3,"adductors":0.1}'::jsonb, 90),
  ('walking-lunge', '{"en":"Walking Lunge","de":"Ausfallschritte gehend","pt-PT":"Afundo a caminhar","pt-BR":"Passada"}'::jsonb,
    '{"en":[{"title":"Stand","text":"Stand tall with a dumbbell in each hand at your sides and plenty of space in front of you."},{"title":"Step","text":"Take a long step forward and lower your back knee to just above the floor, front shin roughly vertical."},{"title":"Walk","text":"Push through your front heel and bring the back foot straight through into the next step. Alternate legs."}],"de":[{"title":"Stand","text":"Steh aufrecht, je eine Kurzhantel seitlich in der Hand, mit genug Platz vor dir."},{"title":"Schritt","text":"Mach einen großen Schritt nach vorne und senk das hintere Knie bis knapp über den Boden, vorderes Schienbein fast senkrecht."},{"title":"Gehen","text":"Drück dich über die vordere Ferse hoch und zieh das hintere Bein direkt in den nächsten Schritt durch. Beine abwechseln."}],"pt-PT":[{"title":"Posição","text":"Fica de pé com um halter em cada mão ao lado do corpo e espaço livre à tua frente."},{"title":"Passo","text":"Dá um passo largo em frente e baixa o joelho de trás até quase tocar no chão, canela da frente quase vertical."},{"title":"Avançar","text":"Empurra com o calcanhar da frente e leva o pé de trás diretamente para o passo seguinte. Alterna as pernas."}],"pt-BR":[{"title":"Posição","text":"Fique em pé com um halter em cada mão ao lado do corpo e espaço livre à sua frente."},{"title":"Passo","text":"Dê um passo longo à frente e desça o joelho de trás até quase encostar no chão, canela da frente quase vertical."},{"title":"Avançar","text":"Empurre com o calcanhar da frente e leve o pé de trás direto para o próximo passo. Alterne as pernas."}]}'::jsonb,
    'dumbbell', '{weight,reps}', '{"quads":0.45,"glutes":0.4,"adductors":0.15}'::jsonb, 90),
  ('reverse-lunge', '{"en":"Reverse Lunge","de":"Ausfallschritte rückwärts","pt-PT":"Afundo para trás","pt-BR":"Recuo"}'::jsonb,
    '{"en":[{"title":"Stand","text":"Stand tall with your feet hip-width apart and a dumbbell in each hand at your sides."},{"title":"Step back","text":"Take a long step backwards and lower your back knee towards the floor, torso upright."},{"title":"Return","text":"Push through your front heel to bring the back foot forward to the start. Alternate legs or do one side at a time."}],"de":[{"title":"Stand","text":"Steh aufrecht, Füße hüftbreit, je eine Kurzhantel seitlich in der Hand."},{"title":"Schritt zurück","text":"Mach einen großen Schritt nach hinten und senk das hintere Knie Richtung Boden, Oberkörper aufrecht."},{"title":"Hoch","text":"Drück dich über die vordere Ferse zurück in den Stand. Wechsle die Beine ab oder trainiere erst eine Seite."}],"pt-PT":[{"title":"Posição","text":"Fica de pé com os pés à largura da anca e um halter em cada mão ao lado do corpo."},{"title":"Passo atrás","text":"Dá um passo largo para trás e baixa o joelho de trás em direção ao chão, com o tronco direito."},{"title":"Voltar","text":"Empurra com o calcanhar da frente para voltar ao início. Alterna as pernas ou faz um lado de cada vez."}],"pt-BR":[{"title":"Posição","text":"Fique em pé com os pés na largura do quadril e um halter em cada mão ao lado do corpo."},{"title":"Passo atrás","text":"Dê um passo longo para trás e desça o joelho de trás em direção ao chão, com o tronco ereto."},{"title":"Voltar","text":"Empurre com o calcanhar da frente para voltar ao início. Alterne as pernas ou faça um lado de cada vez."}]}'::jsonb,
    'dumbbell', '{weight,reps}', '{"quads":0.45,"glutes":0.45,"adductors":0.1}'::jsonb, 90),
  ('smith-lunge', '{"en":"Smith Machine Lunge","de":"Ausfallschritte an der Multipresse","pt-PT":"Afundo na máquina Smith","pt-BR":"Afundo no Smith"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Set the bar on your upper back, unhook it and step into a split stance: one foot forward, back heel raised."},{"title":"Lower","text":"Drop your back knee straight down towards the floor until your front thigh is about parallel."},{"title":"Drive","text":"Push through your front foot back up without fully locking out. Finish all reps, then switch legs."}],"de":[{"title":"Aufbau","text":"Leg die Stange auf den oberen Rücken, häng sie aus und geh in die Schrittstellung: ein Fuß vorne, der hintere auf dem Ballen."},{"title":"Absenken","text":"Senk das hintere Knie gerade Richtung Boden, bis der vordere Oberschenkel etwa parallel ist."},{"title":"Hoch","text":"Drück dich über den vorderen Fuß hoch, ohne ganz durchzustrecken. Erst alle Wiederholungen, dann Bein wechseln."}],"pt-PT":[{"title":"Preparação","text":"Apoia a barra nas costas, solta-a dos ganchos e põe-te em passada: um pé à frente e o de trás apoiado na ponta."},{"title":"Descer","text":"Baixa o joelho de trás a direito em direção ao chão até a coxa da frente ficar quase paralela."},{"title":"Subir","text":"Empurra com o pé da frente para subir, sem esticar por completo. Faz todas as repetições e troca de perna."}],"pt-BR":[{"title":"Preparação","text":"Apoie a barra nas costas, solte dos ganchos e fique na base de afundo: um pé à frente e o de trás na ponta."},{"title":"Descer","text":"Desça o joelho de trás reto em direção ao chão até a coxa da frente ficar quase paralela."},{"title":"Subir","text":"Empurre com o pé da frente para subir, sem estender por completo. Faça todas as repetições e troque de perna."}]}'::jsonb,
    'machine', '{weight,reps}', '{"quads":0.55,"glutes":0.35,"adductors":0.1}'::jsonb, 90),
  ('bulgarian-split-squat', '{"en":"Bulgarian Split Squat","de":"Bulgarian Split Squats","pt-PT":"Agachamento búlgaro","pt-BR":"Agachamento búlgaro"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Stand about a stride in front of a bench and rest the top of your back foot on it. Hold a dumbbell in each hand."},{"title":"Lower","text":"Sink straight down until your front thigh is about parallel, keeping your front heel flat on the floor."},{"title":"Drive","text":"Push through your front foot back up. Finish all reps, then switch legs."}],"de":[{"title":"Aufbau","text":"Stell dich etwa eine Schrittlänge vor eine Bank und leg den hinteren Fußrücken darauf ab. Je eine Kurzhantel in der Hand."},{"title":"Absenken","text":"Geh gerade nach unten, bis der vordere Oberschenkel etwa parallel ist. Die vordere Ferse bleibt am Boden."},{"title":"Hoch","text":"Drück dich über den vorderen Fuß wieder hoch. Erst alle Wiederholungen, dann Bein wechseln."}],"pt-PT":[{"title":"Preparação","text":"Fica a cerca de um passo à frente de um banco e apoia o peito do pé de trás em cima dele. Um halter em cada mão."},{"title":"Descer","text":"Desce a direito até a coxa da frente ficar quase paralela, com o calcanhar da frente bem assente no chão."},{"title":"Subir","text":"Empurra com o pé da frente para subir. Faz todas as repetições e depois troca de perna."}],"pt-BR":[{"title":"Preparação","text":"Fique a mais ou menos um passo à frente de um banco e apoie o peito do pé de trás nele. Um halter em cada mão."},{"title":"Descer","text":"Desça reto até a coxa da frente ficar quase paralela, com o calcanhar da frente firme no chão."},{"title":"Subir","text":"Empurre com o pé da frente para subir. Faça todas as repetições e depois troque de perna."}]}'::jsonb,
    'dumbbell', '{weight,reps}', '{"quads":0.5,"glutes":0.4,"adductors":0.1}'::jsonb, 90),
  ('split-squat', '{"en":"Split Squat","de":"Split Squats","pt-PT":"Afundo estático","pt-BR":"Afundo"}'::jsonb,
    '{"en":[{"title":"Stance","text":"Step into a long split stance with a dumbbell in each hand: front foot flat, back heel raised."},{"title":"Lower","text":"Without moving your feet, drop your back knee straight down until it almost touches the floor."},{"title":"Drive","text":"Push through your front foot back up, torso upright. Finish all reps, then switch legs."}],"de":[{"title":"Stand","text":"Geh mit je einer Kurzhantel in der Hand in eine weite Schrittstellung: vorderer Fuß flach, hintere Ferse angehoben."},{"title":"Absenken","text":"Senk das hintere Knie, ohne die Füße zu bewegen, gerade nach unten, bis es fast den Boden berührt."},{"title":"Hoch","text":"Drück dich über den vorderen Fuß hoch, Oberkörper aufrecht. Erst alle Wiederholungen, dann Bein wechseln."}],"pt-PT":[{"title":"Posição","text":"Com um halter em cada mão, põe-te numa passada larga: pé da frente assente, calcanhar de trás levantado."},{"title":"Descer","text":"Sem mexer os pés, baixa o joelho de trás a direito até quase tocar no chão."},{"title":"Subir","text":"Empurra com o pé da frente para subir, com o tronco direito. Faz todas as repetições e troca de perna."}],"pt-BR":[{"title":"Base","text":"Com um halter em cada mão, fique em uma base longa: pé da frente apoiado, calcanhar de trás elevado."},{"title":"Descer","text":"Sem mexer os pés, desça o joelho de trás reto até quase encostar no chão."},{"title":"Subir","text":"Empurre com o pé da frente para subir, com o tronco ereto. Faça todas as repetições e troque de perna."}]}'::jsonb,
    'dumbbell', '{weight,reps}', '{"quads":0.55,"glutes":0.35,"adductors":0.1}'::jsonb, 90),
  ('step-up', '{"en":"Step-Up","de":"Step-ups","pt-PT":"Subida ao banco","pt-BR":"Subida no banco"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Stand facing a knee-high box or bench with a dumbbell in each hand. Place one whole foot on top."},{"title":"Step up","text":"Drive through the heel on the box to stand up on it, without pushing off with the back foot."},{"title":"Lower","text":"Step back down slowly with the same leg. Finish all reps, then switch sides."}],"de":[{"title":"Aufbau","text":"Stell dich mit je einer Kurzhantel vor eine kniehohe Box oder Bank und setz einen Fuß komplett darauf."},{"title":"Hochsteigen","text":"Drück dich über die Ferse auf der Box nach oben, ohne mit dem hinteren Fuß abzustoßen."},{"title":"Absteigen","text":"Steig mit demselben Bein langsam wieder runter. Erst alle Wiederholungen, dann Seite wechseln."}],"pt-PT":[{"title":"Preparação","text":"Fica de frente para uma caixa ou banco à altura do joelho, com um halter em cada mão. Põe um pé inteiro em cima."},{"title":"Subir","text":"Empurra com o calcanhar do pé que está em cima para subir, sem dar impulso com o pé de trás."},{"title":"Descer","text":"Desce devagar com a mesma perna. Faz todas as repetições e depois troca de lado."}],"pt-BR":[{"title":"Preparação","text":"Fique de frente para um caixote ou banco na altura do joelho, com um halter em cada mão. Apoie um pé inteiro em cima."},{"title":"Subir","text":"Empurre com o calcanhar do pé que está em cima para subir, sem dar impulso com o pé de trás."},{"title":"Descer","text":"Desça devagar com a mesma perna. Faça todas as repetições e depois troque de lado."}]}'::jsonb,
    'dumbbell', '{weight,reps}', '{"quads":0.5,"glutes":0.4,"hamstrings":0.1}'::jsonb, 90),
  ('sissy-squat', '{"en":"Sissy Squat","de":"Sissy Squats","pt-PT":"Sissy squat","pt-BR":"Sissy squat"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Hold a post or sissy squat bench for balance and rise onto the balls of your feet, feet hip-width apart."},{"title":"Lean back","text":"Push your knees forward and down while leaning back, keeping a straight line from knees to shoulders."},{"title":"Return","text":"Squeeze your quads to pull yourself back up, keeping your hips extended the whole time."}],"de":[{"title":"Aufbau","text":"Halt dich an einer Stange oder Sissy-Squat-Bank fest und geh auf die Fußballen, Füße hüftbreit."},{"title":"Zurücklehnen","text":"Schieb die Knie nach vorne unten und lehn dich dabei zurück. Knie, Hüfte und Schultern bilden eine Linie."},{"title":"Hoch","text":"Spann die Oberschenkel an und zieh dich wieder hoch. Die Hüfte bleibt die ganze Zeit gestreckt."}],"pt-PT":[{"title":"Preparação","text":"Segura-te a um poste ou a um banco de sissy squat e sobe para a ponta dos pés, pés à largura da anca."},{"title":"Inclinar","text":"Leva os joelhos para a frente e para baixo enquanto inclinas o corpo para trás, em linha reta dos joelhos aos ombros."},{"title":"Voltar","text":"Contrai os quadríceps para voltares a subir, sempre com a anca estendida."}],"pt-BR":[{"title":"Preparação","text":"Segure-se em um poste ou banco de sissy squat e suba na ponta dos pés, pés na largura do quadril."},{"title":"Inclinar","text":"Leve os joelhos para frente e para baixo enquanto inclina o corpo para trás, em linha reta dos joelhos aos ombros."},{"title":"Voltar","text":"Contraia o quadríceps para voltar a subir, sempre com o quadril estendido."}]}'::jsonb,
    'bodyweight', '{reps}', '{"quads":0.9,"abs":0.1}'::jsonb, 60),
  ('wall-sit', '{"en":"Wall Sit","de":"Wandsitzen","pt-PT":"Agachamento isométrico na parede","pt-BR":"Cadeirinha"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Stand with your back flat against a wall and walk your feet forward, hip-width apart."},{"title":"Hold","text":"Slide down until your thighs are parallel to the floor, knees over your ankles. Hold for the full time."},{"title":"Form","text":"Keep your back and head on the wall and your hands off your thighs. Breathe steadily."}],"de":[{"title":"Aufbau","text":"Lehn dich mit dem ganzen Rücken an eine Wand und geh mit den Füßen hüftbreit ein Stück nach vorne."},{"title":"Halten","text":"Rutsch nach unten, bis die Oberschenkel parallel zum Boden sind und die Knie über den Knöcheln stehen. Halte die volle Zeit."},{"title":"Haltung","text":"Lass Rücken und Kopf an der Wand und stütz die Hände nicht auf den Oberschenkeln ab. Atme ruhig weiter."}],"pt-PT":[{"title":"Preparação","text":"Encosta as costas a uma parede e afasta os pés para a frente, à largura da anca."},{"title":"Manter","text":"Desliza para baixo até as coxas ficarem paralelas ao chão, joelhos sobre os tornozelos. Aguenta o tempo todo."},{"title":"Postura","text":"Mantém as costas e a cabeça na parede e não apoies as mãos nas coxas. Respira com calma."}],"pt-BR":[{"title":"Preparação","text":"Encoste as costas em uma parede e afaste os pés para frente, na largura do quadril."},{"title":"Segure","text":"Deslize para baixo até as coxas ficarem paralelas ao chão, joelhos sobre os tornozelos. Segure o tempo todo."},{"title":"Postura","text":"Mantenha as costas e a cabeça na parede e não apoie as mãos nas coxas. Respire com calma."}]}'::jsonb,
    'bodyweight', '{seconds}', '{"quads":0.8,"glutes":0.15,"adductors":0.05}'::jsonb, 60),
  ('dumbbell-romanian-deadlift', '{"en":"Dumbbell Romanian Deadlift","de":"Rumänisches Kreuzheben mit Kurzhanteln","pt-PT":"Peso morto romeno com halteres","pt-BR":"Stiff com halteres"}'::jsonb,
    '{"en":[{"title":"Start","text":"Stand tall with a dumbbell in each hand in front of your thighs, knees slightly bent."},{"title":"Hinge","text":"Push your hips back and slide the dumbbells down close to your legs until you feel a stretch in your hamstrings."},{"title":"Return","text":"Drive your hips forward to stand up and squeeze your glutes. Your back stays flat throughout."}],"de":[{"title":"Start","text":"Steh aufrecht, je eine Kurzhantel vor den Oberschenkeln, die Knie leicht gebeugt."},{"title":"Hüfte zurück","text":"Schieb die Hüfte nach hinten und führ die Kurzhanteln nah an den Beinen nach unten, bis du die Beinbeuger spürst."},{"title":"Aufrichten","text":"Schieb die Hüfte nach vorne, richte dich auf und spann das Gesäß an. Der Rücken bleibt die ganze Zeit gerade."}],"pt-PT":[{"title":"Início","text":"Fica de pé com um halter em cada mão à frente das coxas e os joelhos ligeiramente fletidos."},{"title":"Inclinar","text":"Leva a anca para trás e desce os halteres junto às pernas até sentires os isquiotibiais alongar."},{"title":"Voltar","text":"Empurra a anca para a frente para te endireitares e contrai os glúteos. As costas ficam sempre direitas."}],"pt-BR":[{"title":"Início","text":"Fique em pé com um halter em cada mão à frente das coxas e os joelhos levemente flexionados."},{"title":"Inclinar","text":"Leve o quadril para trás e desça os halteres rentes às pernas até sentir os posteriores alongarem."},{"title":"Voltar","text":"Empurre o quadril à frente para ficar em pé e contraia os glúteos. As costas ficam retas o tempo todo."}]}'::jsonb,
    'dumbbell', '{weight,reps}', '{"hamstrings":0.55,"glutes":0.35,"lower_back":0.1}'::jsonb, 90),
  ('single-leg-romanian-deadlift', '{"en":"Single-Leg Romanian Deadlift","de":"Einbeiniges rumänisches Kreuzheben","pt-PT":"Peso morto romeno unilateral","pt-BR":"Stiff unilateral"}'::jsonb,
    '{"en":[{"title":"Start","text":"Stand on one leg with a soft knee, holding a dumbbell in the opposite hand."},{"title":"Hinge","text":"Tip forward from the hip as your free leg extends behind you, until your torso is nearly parallel to the floor. Keep your hips square."},{"title":"Return","text":"Drive the standing hip forward to stand tall again. Finish all reps, then switch legs."}],"de":[{"title":"Start","text":"Steh auf einem Bein mit leicht gebeugtem Knie und halte eine Kurzhantel in der gegenüberliegenden Hand."},{"title":"Kippen","text":"Kipp aus der Hüfte nach vorne, während sich das freie Bein nach hinten streckt, bis der Oberkörper fast waagerecht ist. Halte das Becken gerade."},{"title":"Aufrichten","text":"Schieb die Hüfte des Standbeins nach vorne und richte dich auf. Erst alle Wiederholungen, dann Bein wechseln."}],"pt-PT":[{"title":"Início","text":"Fica apoiado numa perna com o joelho ligeiramente fletido e um halter na mão do lado oposto."},{"title":"Inclinar","text":"Inclina o tronco a partir da anca enquanto a perna livre estica para trás, até o tronco ficar quase paralelo ao chão. Mantém a anca nivelada."},{"title":"Voltar","text":"Empurra a anca da perna de apoio para a frente para te endireitares. Faz todas as repetições e troca de perna."}],"pt-BR":[{"title":"Início","text":"Fique apoiado em uma perna com o joelho levemente flexionado e um halter na mão do lado oposto."},{"title":"Inclinar","text":"Incline o tronco a partir do quadril enquanto a perna livre estende para trás, até o tronco ficar quase paralelo ao chão. Mantenha o quadril alinhado."},{"title":"Voltar","text":"Empurre o quadril da perna de apoio à frente para ficar em pé. Faça todas as repetições e troque de perna."}]}'::jsonb,
    'dumbbell', '{weight,reps}', '{"hamstrings":0.5,"glutes":0.4,"lower_back":0.1}'::jsonb, 90),
  ('stiff-leg-deadlift', '{"en":"Stiff-Leg Deadlift","de":"Kreuzheben mit gestreckten Beinen","pt-PT":"Peso morto de pernas esticadas","pt-BR":"Levantamento terra com pernas estendidas"}'::jsonb,
    '{"en":[{"title":"Start","text":"Stand with the bar over your mid-foot and your legs almost straight, knees only slightly bent."},{"title":"Lower","text":"Hinge at the hips with a flat back and lower the bar towards the floor until your hamstrings are fully stretched."},{"title":"Lift","text":"Keep your knees nearly straight and drive your hips forward to stand up, bar close to your legs."}],"de":[{"title":"Start","text":"Stell dich so hin, dass die Stange über dem Mittelfuß ist. Beine fast gestreckt, Knie nur minimal gebeugt."},{"title":"Absenken","text":"Beug dich mit geradem Rücken aus der Hüfte vor und senk die Stange Richtung Boden, bis die Beinbeuger voll gedehnt sind."},{"title":"Aufrichten","text":"Lass die Knie fast gestreckt, schieb die Hüfte nach vorne und richte dich auf, die Stange nah an den Beinen."}],"pt-PT":[{"title":"Início","text":"Fica com a barra sobre o meio do pé e as pernas quase esticadas, com os joelhos só ligeiramente fletidos."},{"title":"Descer","text":"Inclina-te a partir da anca com as costas direitas e desce a barra em direção ao chão até os isquiotibiais alongarem bem."},{"title":"Subir","text":"Mantém os joelhos quase esticados e empurra a anca para a frente para te endireitares, com a barra junto às pernas."}],"pt-BR":[{"title":"Início","text":"Fique com a barra sobre o meio do pé e as pernas quase estendidas, com os joelhos só levemente flexionados."},{"title":"Descer","text":"Incline-se a partir do quadril com as costas retas e desça a barra em direção ao chão até alongar bem os posteriores."},{"title":"Subir","text":"Mantenha os joelhos quase estendidos e empurre o quadril à frente para ficar em pé, com a barra rente às pernas."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"hamstrings":0.6,"glutes":0.25,"lower_back":0.15}'::jsonb, 120),
  ('good-morning', '{"en":"Good Morning","de":"Good Mornings","pt-PT":"Good morning","pt-BR":"Good morning"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Rest the bar on your upper back as for a squat, feet hip-width apart, knees slightly bent."},{"title":"Hinge","text":"Push your hips back and lower your torso with a flat back until it''s nearly parallel or your hamstrings pull hard."},{"title":"Return","text":"Drive your hips forward to stand back up. Start light, since the long lever puts a lot of load on your lower back."}],"de":[{"title":"Aufbau","text":"Leg die Stange wie bei Kniebeugen auf den oberen Rücken, Füße hüftbreit, Knie leicht gebeugt."},{"title":"Vorbeugen","text":"Schieb die Hüfte nach hinten und senk den Oberkörper mit geradem Rücken, bis er fast waagerecht ist oder die Beinbeuger stark ziehen."},{"title":"Aufrichten","text":"Schieb die Hüfte nach vorne und richte dich auf. Fang mit wenig Gewicht an, denn der Hebel auf den unteren Rücken ist lang."}],"pt-PT":[{"title":"Preparação","text":"Apoia a barra na parte de cima das costas como no agachamento, pés à largura da anca, joelhos ligeiramente fletidos."},{"title":"Inclinar","text":"Leva a anca para trás e baixa o tronco com as costas direitas até ficar quase paralelo ou sentires os isquiotibiais a puxar."},{"title":"Voltar","text":"Empurra a anca para a frente para te endireitares. Começa com pouco peso, porque a lombar trabalha com uma alavanca longa."}],"pt-BR":[{"title":"Preparação","text":"Apoie a barra no alto das costas como no agachamento, pés na largura do quadril, joelhos levemente flexionados."},{"title":"Inclinar","text":"Leve o quadril para trás e abaixe o tronco com as costas retas até ficar quase paralelo ou sentir os posteriores puxando."},{"title":"Voltar","text":"Empurre o quadril à frente para ficar em pé. Comece leve, porque a lombar trabalha com uma alavanca longa."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"hamstrings":0.45,"glutes":0.3,"lower_back":0.25}'::jsonb, 120),
  ('cable-pull-through', '{"en":"Cable Pull-Through","de":"Pull-Through am Kabel","pt-PT":"Pull-through no cabo","pt-BR":"Pull-through na polia"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Attach a rope to a low pulley, face away and grab it between your legs. Walk out a few steps, feet wider than your hips."},{"title":"Hinge","text":"Push your hips back and let the rope pull your hands back between your legs, knees slightly bent and back flat."},{"title":"Drive","text":"Drive your hips forward to stand tall and squeeze your glutes hard at the top. Don''t pull with your arms."}],"de":[{"title":"Aufbau","text":"Häng ein Seil unten am Kabelzug ein, dreh dich weg und greif es zwischen den Beinen. Geh ein paar Schritte vor, Füße breiter als hüftbreit."},{"title":"Hüfte zurück","text":"Schieb die Hüfte nach hinten und lass das Seil die Hände zwischen die Beine ziehen, Knie leicht gebeugt, Rücken gerade."},{"title":"Strecken","text":"Schieb die Hüfte kräftig nach vorne, bis du aufrecht stehst, und spann oben das Gesäß fest an. Zieh nicht mit den Armen."}],"pt-PT":[{"title":"Preparação","text":"Prende uma corda na polia baixa, fica de costas para o cabo e agarra-a entre as pernas. Afasta-te uns passos, pés além da largura da anca."},{"title":"Inclinar","text":"Leva a anca para trás e deixa a corda puxar as mãos por entre as pernas, joelhos ligeiramente fletidos e costas direitas."},{"title":"Estender","text":"Empurra a anca para a frente até ficares direito e contrai bem os glúteos em cima. Não puxes com os braços."}],"pt-BR":[{"title":"Preparação","text":"Prenda uma corda na polia baixa, fique de costas para o cabo e segure a corda entre as pernas. Dê alguns passos à frente, pés além da largura do quadril."},{"title":"Inclinar","text":"Leve o quadril para trás e deixe a corda puxar as mãos por entre as pernas, joelhos levemente flexionados e costas retas."},{"title":"Estender","text":"Empurre o quadril à frente até ficar ereto e contraia bem os glúteos em cima. Não puxe com os braços."}]}'::jsonb,
    'cable', '{weight,reps}', '{"glutes":0.6,"hamstrings":0.35,"lower_back":0.05}'::jsonb, 90),
  ('lying-leg-curl', '{"en":"Lying Leg Curl","de":"Beinbeuger liegend","pt-PT":"Curl femoral deitado","pt-BR":"Mesa flexora"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Lie face down with your knees just past the pad edge, in line with the pivot, and the roller just above your heels."},{"title":"Curl","text":"Curl your heels towards your glutes as far as you can while keeping your hips pressed into the pad."},{"title":"Lower","text":"Lower the weight slowly until your legs are almost straight, without letting the stack touch down."}],"de":[{"title":"Einstellen","text":"Leg dich bäuchlings hin, sodass die Knie knapp über die Polsterkante ragen und auf Höhe der Drehachse sind. Die Rolle liegt knapp über den Fersen."},{"title":"Beugen","text":"Zieh die Fersen so weit wie möglich Richtung Gesäß und drück dabei die Hüfte ins Polster."},{"title":"Absenken","text":"Senk das Gewicht langsam ab, bis die Beine fast gestreckt sind, ohne es abzulegen."}],"pt-PT":[{"title":"Ajustar","text":"Deita-te de barriga para baixo com os joelhos logo fora do banco, alinhados com o eixo, e o rolo acima dos calcanhares."},{"title":"Fletir","text":"Puxa os calcanhares em direção aos glúteos o máximo que conseguires, com a anca bem encostada ao banco."},{"title":"Descida","text":"Desce o peso devagar até as pernas ficarem quase esticadas, sem pousar as placas."}],"pt-BR":[{"title":"Ajuste","text":"Deite de bruços com os joelhos logo fora do banco, alinhados com o eixo, e o rolo logo acima dos calcanhares."},{"title":"Flexionar","text":"Puxe os calcanhares em direção aos glúteos o máximo que conseguir, com o quadril bem apoiado no banco."},{"title":"Descida","text":"Desça o peso devagar até as pernas ficarem quase estendidas, sem apoiar as placas."}]}'::jsonb,
    'machine', '{weight,reps}', '{"hamstrings":0.9,"calves":0.1}'::jsonb, 60),
  ('seated-leg-curl', '{"en":"Seated Leg Curl","de":"Beinbeuger sitzend","pt-PT":"Curl femoral sentado","pt-BR":"Cadeira flexora"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Sit with your knees in line with the pivot, the lower roller just above your heels and the thigh pad locked firmly down."},{"title":"Curl","text":"Pull your heels down and back under the seat as far as you can, leaning your torso slightly forward."},{"title":"Return","text":"Let the roller rise slowly until your legs are almost straight, keeping tension at the top."}],"de":[{"title":"Einstellen","text":"Setz dich so hin, dass die Knie auf Höhe der Drehachse sind. Die Rolle liegt knapp über den Fersen, das Polster fixiert die Oberschenkel."},{"title":"Beugen","text":"Zieh die Fersen so weit wie möglich nach unten und hinten unter den Sitz, Oberkörper leicht nach vorne geneigt."},{"title":"Zurück","text":"Lass die Rolle langsam nach oben kommen, bis die Beine fast gestreckt sind, und halte dabei die Spannung."}],"pt-PT":[{"title":"Ajustar","text":"Senta-te com os joelhos alinhados com o eixo, o rolo de baixo acima dos calcanhares e o apoio das coxas bem preso."},{"title":"Fletir","text":"Puxa os calcanhares para baixo e para trás, por baixo do assento, o máximo que conseguires, com o tronco um pouco inclinado."},{"title":"Voltar","text":"Deixa o rolo subir devagar até as pernas ficarem quase esticadas, sem perder a tensão."}],"pt-BR":[{"title":"Ajuste","text":"Sente com os joelhos alinhados com o eixo, o rolo de baixo acima dos calcanhares e o apoio das coxas bem travado."},{"title":"Flexionar","text":"Puxe os calcanhares para baixo e para trás, embaixo do banco, o máximo que conseguir, com o tronco um pouco inclinado."},{"title":"Voltar","text":"Deixe o rolo subir devagar até as pernas ficarem quase estendidas, sem perder a tensão."}]}'::jsonb,
    'machine', '{weight,reps}', '{"hamstrings":0.95,"calves":0.05}'::jsonb, 60),
  ('standing-leg-curl', '{"en":"Standing Leg Curl","de":"Beinbeuger stehend","pt-PT":"Curl femoral em pé","pt-BR":"Flexora em pé"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Stand facing the machine with your hips against the pad and the roller just above the heel of your working leg."},{"title":"Curl","text":"Curl your heel up towards your glutes while your thigh stays vertical and your hips stay on the pad."},{"title":"Lower","text":"Lower slowly until the leg is almost straight. Finish all reps, then switch legs."}],"de":[{"title":"Einstellen","text":"Stell dich mit der Hüfte ans Polster und leg die Rolle knapp über die Ferse des Trainingsbeins."},{"title":"Beugen","text":"Zieh die Ferse Richtung Gesäß. Der Oberschenkel bleibt senkrecht und die Hüfte am Polster."},{"title":"Absenken","text":"Senk das Bein langsam ab, bis es fast gestreckt ist. Erst alle Wiederholungen, dann Bein wechseln."}],"pt-PT":[{"title":"Ajustar","text":"Fica de frente para a máquina, anca encostada ao apoio, e coloca o rolo logo acima do calcanhar da perna que trabalha."},{"title":"Fletir","text":"Puxa o calcanhar em direção aos glúteos, com a coxa na vertical e a anca encostada ao apoio."},{"title":"Descida","text":"Desce devagar até a perna ficar quase esticada. Faz todas as repetições e depois troca de perna."}],"pt-BR":[{"title":"Ajuste","text":"Fique de frente para a máquina, quadril apoiado, e coloque o rolo logo acima do calcanhar da perna que vai trabalhar."},{"title":"Flexionar","text":"Puxe o calcanhar em direção aos glúteos, com a coxa na vertical e o quadril apoiado."},{"title":"Descida","text":"Desça devagar até a perna ficar quase estendida. Faça todas as repetições e depois troque de perna."}]}'::jsonb,
    'machine', '{weight,reps}', '{"hamstrings":0.9,"calves":0.1}'::jsonb, 60),
  ('nordic-curl', '{"en":"Nordic Hamstring Curl","de":"Nordic Curls","pt-PT":"Curl nórdico","pt-BR":"Flexão nórdica"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Kneel on a pad with a partner or a fixed pad holding your heels down. Keep your body straight from knees to head."},{"title":"Lower","text":"Lean forward as slowly as you can, braking with your hamstrings and keeping your hips extended."},{"title":"Return","text":"Catch yourself with your hands when you can''t hold any longer, then push off lightly and curl back up."}],"de":[{"title":"Aufbau","text":"Knie dich auf ein Polster und lass die Fersen von einem Partner oder einer Fixierung festhalten. Körper gerade von Knie bis Kopf."},{"title":"Absenken","text":"Lehn dich so langsam wie möglich nach vorne und brems mit den Beinbeugern. Die Hüfte bleibt gestreckt."},{"title":"Zurück","text":"Fang dich mit den Händen ab, wenn du nicht mehr halten kannst, stoß dich leicht ab und zieh dich wieder hoch."}],"pt-PT":[{"title":"Preparação","text":"Ajoelha-te num tapete com um parceiro ou um apoio a prender os calcanhares. Corpo em linha reta dos joelhos à cabeça."},{"title":"Descer","text":"Inclina-te para a frente o mais devagar possível, a travar com os isquiotibiais e com a anca sempre estendida."},{"title":"Voltar","text":"Apara a queda com as mãos quando já não aguentares, dá um pequeno impulso e volta a subir com os isquiotibiais."}],"pt-BR":[{"title":"Preparação","text":"Ajoelhe em um colchonete com um parceiro ou um apoio segurando os calcanhares. Corpo reto dos joelhos à cabeça."},{"title":"Descer","text":"Incline o corpo à frente o mais devagar possível, freando com os posteriores e com o quadril sempre estendido."},{"title":"Voltar","text":"Apoie as mãos no chão quando não aguentar mais, dê um leve impulso e volte a subir com os posteriores."}]}'::jsonb,
    'bodyweight', '{reps}', '{"hamstrings":0.85,"glutes":0.1,"calves":0.05}'::jsonb, 90),
  ('glute-ham-raise', '{"en":"Glute-Ham Raise","de":"Glute-Ham Raise","pt-PT":"Glute-ham raise","pt-BR":"Glute-ham raise"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Lock your feet between the rollers with your knees just behind the pad. Start upright with your body straight."},{"title":"Lower","text":"Lower your body forward under control until it''s parallel to the floor, keeping your hips extended."},{"title":"Curl up","text":"Press your toes into the footplate and pull yourself back up with your hamstrings, glutes squeezed."}],"de":[{"title":"Aufbau","text":"Klemm die Füße zwischen die Rollen, die Knie knapp hinter dem Polster. Starte aufrecht mit geradem Körper."},{"title":"Absenken","text":"Senk den Körper kontrolliert nach vorne, bis er parallel zum Boden ist. Die Hüfte bleibt gestreckt."},{"title":"Hochziehen","text":"Drück die Zehen gegen die Fußplatte und zieh dich mit den Beinbeugern wieder hoch, Gesäß angespannt."}],"pt-PT":[{"title":"Preparação","text":"Prende os pés entre os rolos com os joelhos logo atrás da almofada. Começa direito, com o corpo em linha."},{"title":"Descer","text":"Desce o corpo para a frente com controlo até ficar paralelo ao chão, com a anca estendida."},{"title":"Subir","text":"Pressiona as pontas dos pés contra a plataforma e puxa-te para cima com os isquiotibiais, glúteos contraídos."}],"pt-BR":[{"title":"Preparação","text":"Prenda os pés entre os rolos com os joelhos logo atrás da almofada. Comece ereto, com o corpo alinhado."},{"title":"Descer","text":"Desça o corpo à frente com controle até ficar paralelo ao chão, com o quadril estendido."},{"title":"Subir","text":"Pressione as pontas dos pés contra a plataforma e puxe o corpo para cima com os posteriores, glúteos contraídos."}]}'::jsonb,
    'machine', '{reps}', '{"hamstrings":0.65,"glutes":0.2,"lower_back":0.1,"calves":0.05}'::jsonb, 90),
  ('hip-thrust', '{"en":"Barbell Hip Thrust","de":"Hip Thrust","pt-PT":"Hip thrust com barra","pt-BR":"Elevação pélvica"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Sit with your upper back against a bench and roll a padded bar over your hips. Feet flat, hip-width apart."},{"title":"Drive","text":"Drive through your heels and lift your hips until your body is straight from shoulders to knees, shins vertical."},{"title":"Lock out","text":"Squeeze your glutes hard at the top with your chin tucked, then lower under control."}],"de":[{"title":"Aufbau","text":"Setz dich mit dem oberen Rücken an eine Bank und roll eine gepolsterte Langhantel über die Hüfte. Füße hüftbreit flach am Boden."},{"title":"Hochdrücken","text":"Drück dich über die Fersen hoch, bis der Körper von Schultern bis Knie eine Linie bildet, Schienbeine senkrecht."},{"title":"Anspannen","text":"Spann oben das Gesäß fest an, Kinn zur Brust, und senk die Hüfte kontrolliert ab."}],"pt-PT":[{"title":"Preparação","text":"Senta-te com a parte de cima das costas encostada a um banco e rola a barra com almofada até à anca. Pés assentes à largura da anca."},{"title":"Subir","text":"Empurra com os calcanhares e sobe a anca até o corpo ficar em linha dos ombros aos joelhos, canelas na vertical."},{"title":"Contrair","text":"Contrai bem os glúteos em cima, com o queixo recolhido, e desce com controlo."}],"pt-BR":[{"title":"Preparação","text":"Sente com o alto das costas apoiado em um banco e role a barra com protetor até o quadril. Pés apoiados na largura do quadril."},{"title":"Subir","text":"Empurre com os calcanhares e eleve o quadril até o corpo ficar alinhado dos ombros aos joelhos, canelas na vertical."},{"title":"Contrair","text":"Contraia bem os glúteos em cima, com o queixo recolhido, e desça com controle."}]}'::jsonb,
    'barbell', '{weight,reps}', '{"glutes":0.7,"hamstrings":0.15,"quads":0.15}'::jsonb, 120),
  ('hip-thrust-machine', '{"en":"Hip Thrust Machine","de":"Hip Thrust an der Maschine","pt-PT":"Hip thrust na máquina","pt-BR":"Elevação pélvica na máquina"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Sit in the machine with your upper back on the pad and the belt or pad across your hips. Feet flat, hip-width apart."},{"title":"Drive","text":"Push through your heels and extend your hips until your body is straight from shoulders to knees."},{"title":"Lower","text":"Squeeze your glutes for a second at the top, then lower slowly without letting the weight rest."}],"de":[{"title":"Einstellen","text":"Setz dich in die Maschine, oberer Rücken am Polster, Gurt oder Polster über der Hüfte. Füße hüftbreit flach auf der Plattform."},{"title":"Hochdrücken","text":"Drück dich über die Fersen hoch und streck die Hüfte, bis Schultern, Hüfte und Knie eine Linie bilden."},{"title":"Absenken","text":"Halte oben eine Sekunde mit angespanntem Gesäß und senk dann langsam ab, ohne das Gewicht abzulegen."}],"pt-PT":[{"title":"Ajustar","text":"Senta-te na máquina com a parte de cima das costas no apoio e o cinto ou rolo sobre a anca. Pés assentes à largura da anca."},{"title":"Subir","text":"Empurra com os calcanhares e estende a anca até o corpo ficar em linha dos ombros aos joelhos."},{"title":"Descida","text":"Contrai os glúteos um segundo em cima e desce devagar, sem pousar o peso."}],"pt-BR":[{"title":"Ajuste","text":"Sente na máquina com o alto das costas no apoio e o cinto ou rolo sobre o quadril. Pés apoiados na largura do quadril."},{"title":"Subir","text":"Empurre com os calcanhares e estenda o quadril até o corpo ficar alinhado dos ombros aos joelhos."},{"title":"Descida","text":"Contraia os glúteos por um segundo em cima e desça devagar, sem apoiar o peso."}]}'::jsonb,
    'machine', '{weight,reps}', '{"glutes":0.75,"hamstrings":0.15,"quads":0.1}'::jsonb, 90),
  ('glute-bridge', '{"en":"Glute Bridge","de":"Glute Bridge","pt-PT":"Ponte de glúteos","pt-BR":"Ponte de glúteo"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Lie on your back with your knees bent and feet flat, hip-width apart. Rest a weight on your hips if you like."},{"title":"Lift","text":"Drive through your heels and lift your hips until your body is straight from shoulders to knees."},{"title":"Lower","text":"Squeeze your glutes at the top for a second, then lower slowly until your hips almost touch the floor."}],"de":[{"title":"Aufbau","text":"Leg dich auf den Rücken, Knie gebeugt, Füße hüftbreit flach am Boden. Wenn du willst, leg dir ein Gewicht auf die Hüfte."},{"title":"Hochdrücken","text":"Drück dich über die Fersen hoch, bis Schultern, Hüfte und Knie eine Linie bilden."},{"title":"Absenken","text":"Spann oben eine Sekunde das Gesäß an und senk die Hüfte langsam ab, bis sie fast den Boden berührt."}],"pt-PT":[{"title":"Preparação","text":"Deita-te de costas com os joelhos fletidos e os pés assentes à largura da anca. Se quiseres, apoia um peso na anca."},{"title":"Subir","text":"Empurra com os calcanhares e sobe a anca até o corpo ficar em linha dos ombros aos joelhos."},{"title":"Descida","text":"Contrai os glúteos um segundo em cima e desce devagar até a anca quase tocar no chão."}],"pt-BR":[{"title":"Preparação","text":"Deite de costas com os joelhos flexionados e os pés apoiados na largura do quadril. Se quiser, apoie um peso no quadril."},{"title":"Subir","text":"Empurre com os calcanhares e eleve o quadril até o corpo ficar alinhado dos ombros aos joelhos."},{"title":"Descida","text":"Contraia os glúteos por um segundo em cima e desça devagar até o quadril quase encostar no chão."}]}'::jsonb,
    'bodyweight', '{weight,reps}', '{"glutes":0.7,"hamstrings":0.2,"quads":0.1}'::jsonb, 60),
  ('single-leg-glute-bridge', '{"en":"Single-Leg Glute Bridge","de":"Einbeinige Glute Bridge","pt-PT":"Ponte de glúteos unilateral","pt-BR":"Ponte de glúteo unilateral"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Lie on your back with one foot flat near your glutes and the other leg straight or pulled to your chest."},{"title":"Lift","text":"Drive through the heel on the floor and lift your hips until they''re level and in line with your knee."},{"title":"Lower","text":"Lower slowly without letting your hips tilt. Finish all reps, then switch legs."}],"de":[{"title":"Aufbau","text":"Leg dich auf den Rücken, ein Fuß flach nah am Gesäß, das andere Bein gestreckt oder zur Brust gezogen."},{"title":"Hochdrücken","text":"Drück dich über die Ferse am Boden hoch, bis die Hüfte gerade und in Linie mit dem Knie ist."},{"title":"Absenken","text":"Senk die Hüfte langsam ab, ohne dass sie zur Seite kippt. Erst alle Wiederholungen, dann Bein wechseln."}],"pt-PT":[{"title":"Preparação","text":"Deita-te de costas com um pé assente perto dos glúteos e a outra perna esticada ou puxada ao peito."},{"title":"Subir","text":"Empurra com o calcanhar no chão e sobe a anca até ficar nivelada e alinhada com o joelho."},{"title":"Descida","text":"Desce devagar sem deixar a anca inclinar para o lado. Faz todas as repetições e troca de perna."}],"pt-BR":[{"title":"Preparação","text":"Deite de costas com um pé apoiado perto dos glúteos e a outra perna estendida ou puxada ao peito."},{"title":"Subir","text":"Empurre com o calcanhar no chão e eleve o quadril até ficar nivelado e alinhado com o joelho."},{"title":"Descida","text":"Desça devagar sem deixar o quadril inclinar para o lado. Faça todas as repetições e troque de perna."}]}'::jsonb,
    'bodyweight', '{reps}', '{"glutes":0.7,"hamstrings":0.25,"abs":0.05}'::jsonb, 60),
  ('cable-glute-kickback', '{"en":"Cable Glute Kickback","de":"Gluteus-Kickbacks am Kabel","pt-PT":"Kickback de glúteos no cabo","pt-BR":"Coice na polia"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Strap an ankle cuff to one leg at a low pulley. Face the machine, hold the frame and hinge slightly forward."},{"title":"Kick back","text":"Drive your leg back and slightly up by squeezing your glute, without arching your lower back."},{"title":"Return","text":"Bring the leg forward slowly and under control. Finish all reps, then switch legs."}],"de":[{"title":"Aufbau","text":"Leg dir eine Fußmanschette an und häng sie unten am Kabelzug ein. Halt dich mit dem Gesicht zur Maschine am Rahmen fest und neig dich leicht vor."},{"title":"Kickback","text":"Drück das Bein aus dem Gesäß heraus nach hinten und leicht nach oben, ohne ins Hohlkreuz zu gehen."},{"title":"Zurück","text":"Führ das Bein langsam und kontrolliert wieder nach vorne. Erst alle Wiederholungen, dann Bein wechseln."}],"pt-PT":[{"title":"Preparação","text":"Prende uma tornozeleira à polia baixa. Fica de frente para a máquina, segura-te à estrutura e inclina-te um pouco."},{"title":"Extensão","text":"Leva a perna para trás e ligeiramente para cima a contrair o glúteo, sem arquear a lombar."},{"title":"Voltar","text":"Traz a perna para a frente devagar e com controlo. Faz todas as repetições e depois troca de perna."}],"pt-BR":[{"title":"Preparação","text":"Prenda uma tornozeleira na polia baixa. Fique de frente para o aparelho, segure na estrutura e incline um pouco o tronco."},{"title":"Coice","text":"Leve a perna para trás e levemente para cima contraindo o glúteo, sem arquear a lombar."},{"title":"Voltar","text":"Traga a perna à frente devagar e com controle. Faça todas as repetições e depois troque de perna."}]}'::jsonb,
    'cable', '{weight,reps}', '{"glutes":0.85,"hamstrings":0.15}'::jsonb, 60),
  ('glute-kickback-machine', '{"en":"Glute Kickback Machine","de":"Gluteus-Maschine","pt-PT":"Máquina de glúteos","pt-BR":"Coice na máquina"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Rest your chest or forearms on the pad and place one foot flat on the footplate, standing leg slightly bent."},{"title":"Push back","text":"Press the plate back and up by squeezing your glute until your hip is fully extended, without arching your back."},{"title":"Return","text":"Let the plate come forward slowly until your knee is near your chest. Finish all reps, then switch legs."}],"de":[{"title":"Einstellen","text":"Leg Brust oder Unterarme auf das Polster und stell einen Fuß flach auf die Fußplatte, Standbein leicht gebeugt."},{"title":"Wegdrücken","text":"Drück die Platte mit dem Gesäß nach hinten oben, bis die Hüfte gestreckt ist, ohne ins Hohlkreuz zu gehen."},{"title":"Zurück","text":"Lass die Platte langsam zurückkommen, bis das Knie nah an der Brust ist. Erst alle Wiederholungen, dann Bein wechseln."}],"pt-PT":[{"title":"Ajustar","text":"Apoia o peito ou os antebraços na almofada e põe um pé assente na plataforma, perna de apoio ligeiramente fletida."},{"title":"Empurrar","text":"Empurra a plataforma para trás e para cima a contrair o glúteo até estenderes a anca, sem arquear as costas."},{"title":"Voltar","text":"Deixa a plataforma voltar devagar até o joelho ficar perto do peito. Faz todas as repetições e troca de perna."}],"pt-BR":[{"title":"Ajuste","text":"Apoie o peito ou os antebraços na almofada e coloque um pé na plataforma, perna de apoio levemente flexionada."},{"title":"Empurrar","text":"Empurre a plataforma para trás e para cima contraindo o glúteo até estender o quadril, sem arquear as costas."},{"title":"Voltar","text":"Deixe a plataforma voltar devagar até o joelho ficar perto do peito. Faça todas as repetições e troque de perna."}]}'::jsonb,
    'machine', '{weight,reps}', '{"glutes":0.85,"hamstrings":0.15}'::jsonb, 60),
  ('donkey-kick', '{"en":"Donkey Kick","de":"Donkey Kicks","pt-PT":"Donkey kick","pt-BR":"Glúteo quatro apoios"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Get on all fours with your hands under your shoulders and knees under your hips. Brace your core."},{"title":"Kick","text":"Keeping the knee bent at 90°, push one foot up towards the ceiling until your thigh is in line with your back."},{"title":"Lower","text":"Lower the knee without touching the floor and don''t arch your lower back. Switch legs after the set."}],"de":[{"title":"Aufbau","text":"Geh in den Vierfüßlerstand, Hände unter den Schultern, Knie unter der Hüfte. Bauch anspannen."},{"title":"Kick","text":"Drück einen Fuß mit 90° gebeugtem Knie Richtung Decke, bis der Oberschenkel in Linie mit dem Rücken ist."},{"title":"Absenken","text":"Senk das Knie wieder ab, ohne den Boden zu berühren, und geh nicht ins Hohlkreuz. Nach dem Satz Bein wechseln."}],"pt-PT":[{"title":"Preparação","text":"Põe-te em quatro apoios com as mãos por baixo dos ombros e os joelhos por baixo da anca. Contrai o core."},{"title":"Elevar","text":"Com o joelho fletido a 90°, empurra um pé em direção ao teto até a coxa ficar alinhada com as costas."},{"title":"Descida","text":"Baixa o joelho sem tocar no chão e não arqueies a lombar. No fim da série, troca de perna."}],"pt-BR":[{"title":"Preparação","text":"Fique em quatro apoios com as mãos embaixo dos ombros e os joelhos embaixo do quadril. Contraia o core."},{"title":"Coice","text":"Com o joelho flexionado a 90°, empurre um pé em direção ao teto até a coxa ficar alinhada com as costas."},{"title":"Descida","text":"Abaixe o joelho sem encostar no chão e não arqueie a lombar. No fim da série, troque de perna."}]}'::jsonb,
    'bodyweight', '{reps}', '{"glutes":0.85,"hamstrings":0.1,"abs":0.05}'::jsonb, 60),
  ('fire-hydrant', '{"en":"Fire Hydrant","de":"Fire Hydrants","pt-PT":"Fire hydrant","pt-BR":"Abdução quatro apoios"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Get on all fours with your hands under your shoulders and knees under your hips. Brace your core."},{"title":"Lift","text":"Keeping the knee bent, raise one leg out to the side until your thigh is about level with your hip."},{"title":"Lower","text":"Lower slowly without shifting your weight or rotating your torso. Switch legs after the set."}],"de":[{"title":"Aufbau","text":"Geh in den Vierfüßlerstand, Hände unter den Schultern, Knie unter der Hüfte. Bauch anspannen."},{"title":"Abspreizen","text":"Heb ein Bein mit gebeugtem Knie seitlich an, bis der Oberschenkel etwa auf Hüfthöhe ist."},{"title":"Absenken","text":"Senk das Bein langsam ab, ohne das Gewicht zu verlagern oder den Oberkörper zu drehen. Nach dem Satz Bein wechseln."}],"pt-PT":[{"title":"Preparação","text":"Põe-te em quatro apoios com as mãos por baixo dos ombros e os joelhos por baixo da anca. Contrai o core."},{"title":"Elevar","text":"Com o joelho fletido, levanta uma perna para o lado até a coxa ficar mais ou menos à altura da anca."},{"title":"Descida","text":"Desce devagar sem transferir o peso nem rodar o tronco. No fim da série, troca de perna."}],"pt-BR":[{"title":"Preparação","text":"Fique em quatro apoios com as mãos embaixo dos ombros e os joelhos embaixo do quadril. Contraia o core."},{"title":"Elevar","text":"Com o joelho flexionado, eleve uma perna para o lado até a coxa ficar mais ou menos na altura do quadril."},{"title":"Descida","text":"Desça devagar sem jogar o peso para o lado nem girar o tronco. No fim da série, troque de perna."}]}'::jsonb,
    'bodyweight', '{reps}', '{"glutes":0.9,"obliques":0.1}'::jsonb, 60),
  ('curtsy-lunge', '{"en":"Curtsy Lunge","de":"Curtsy Lunges","pt-PT":"Afundo cruzado","pt-BR":"Afundo cruzado"}'::jsonb,
    '{"en":[{"title":"Stand","text":"Stand tall with your feet hip-width apart and a dumbbell in each hand at your sides."},{"title":"Cross back","text":"Step one leg diagonally behind the other, as in a curtsy, and lower until your front thigh is about parallel."},{"title":"Return","text":"Push through your front heel back to the start, front knee in line with your toes. Alternate legs."}],"de":[{"title":"Stand","text":"Steh aufrecht, Füße hüftbreit, je eine Kurzhantel seitlich in der Hand."},{"title":"Überkreuzen","text":"Setz ein Bein diagonal hinter das andere, wie bei einem Knicks, und geh runter, bis der vordere Oberschenkel etwa parallel ist."},{"title":"Zurück","text":"Drück dich über die vordere Ferse zurück in den Stand, das vordere Knie bleibt über den Zehen. Beine abwechseln."}],"pt-PT":[{"title":"Posição","text":"Fica de pé com os pés à largura da anca e um halter em cada mão ao lado do corpo."},{"title":"Cruzar","text":"Leva uma perna na diagonal para trás da outra, como numa vénia, e desce até a coxa da frente ficar quase paralela."},{"title":"Voltar","text":"Empurra com o calcanhar da frente para voltar ao início, com o joelho da frente alinhado com o pé. Alterna as pernas."}],"pt-BR":[{"title":"Posição","text":"Fique em pé com os pés na largura do quadril e um halter em cada mão ao lado do corpo."},{"title":"Cruzar","text":"Leve uma perna na diagonal para trás da outra, como em uma reverência, e desça até a coxa da frente ficar quase paralela."},{"title":"Voltar","text":"Empurre com o calcanhar da frente para voltar ao início, com o joelho da frente alinhado com o pé. Alterne as pernas."}]}'::jsonb,
    'dumbbell', '{weight,reps}', '{"glutes":0.45,"quads":0.4,"adductors":0.15}'::jsonb, 90),
  ('lateral-lunge', '{"en":"Lateral Lunge","de":"Seitliche Ausfallschritte","pt-PT":"Afundo lateral","pt-BR":"Afundo lateral"}'::jsonb,
    '{"en":[{"title":"Stand","text":"Stand with your feet together, holding a dumbbell in each hand or one at your chest."},{"title":"Step out","text":"Take a wide step to the side and sit your hips back over that leg. The other leg stays straight, both feet flat."},{"title":"Return","text":"Push off the bent leg back to the start. Alternate sides or finish one side first."}],"de":[{"title":"Stand","text":"Stell die Füße zusammen und halt je eine Kurzhantel in der Hand oder eine vor der Brust."},{"title":"Seitschritt","text":"Mach einen weiten Schritt zur Seite und schieb die Hüfte über diesem Bein nach hinten. Das andere Bein bleibt gestreckt, beide Füße flach."},{"title":"Zurück","text":"Drück dich vom gebeugten Bein zurück in den Stand. Wechsle die Seiten ab oder mach erst eine Seite fertig."}],"pt-PT":[{"title":"Posição","text":"Fica com os pés juntos e um halter em cada mão ou um só junto ao peito."},{"title":"Passo lateral","text":"Dá um passo largo para o lado e leva a anca para trás sobre essa perna. A outra perna fica esticada, pés assentes."},{"title":"Voltar","text":"Empurra com a perna fletida para voltar ao início. Alterna os lados ou termina primeiro um lado."}],"pt-BR":[{"title":"Posição","text":"Fique com os pés juntos e um halter em cada mão ou um só junto ao peito."},{"title":"Passo lateral","text":"Dê um passo largo para o lado e leve o quadril para trás sobre essa perna. A outra perna fica estendida, pés apoiados."},{"title":"Voltar","text":"Empurre com a perna flexionada para voltar ao início. Alterne os lados ou termine um lado primeiro."}]}'::jsonb,
    'dumbbell', '{weight,reps}', '{"quads":0.4,"adductors":0.35,"glutes":0.25}'::jsonb, 90),
  ('hip-abduction-machine', '{"en":"Hip Abduction Machine","de":"Abduktorenmaschine","pt-PT":"Máquina de abdutores","pt-BR":"Cadeira abdutora"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Sit with your back against the pad and the thigh pads against the outside of your knees."},{"title":"Push out","text":"Push your knees apart as far as you can by squeezing the sides of your glutes, and hold briefly."},{"title":"Return","text":"Let your legs come back together slowly without letting the weight stack touch down."}],"de":[{"title":"Einstellen","text":"Setz dich mit dem Rücken ans Polster, die Beinpolster liegen außen an den Knien an."},{"title":"Öffnen","text":"Drück die Knie so weit wie möglich auseinander, spann dabei das seitliche Gesäß an und halte kurz."},{"title":"Schließen","text":"Führ die Beine langsam wieder zusammen, ohne das Gewicht abzulegen."}],"pt-PT":[{"title":"Ajustar","text":"Senta-te com as costas no encosto e as almofadas encostadas à parte de fora dos joelhos."},{"title":"Abrir","text":"Afasta os joelhos o máximo que conseguires, a contrair a parte lateral dos glúteos, e segura um instante."},{"title":"Fechar","text":"Junta as pernas devagar, sem deixar as placas pousarem."}],"pt-BR":[{"title":"Ajuste","text":"Sente com as costas no encosto e as almofadas apoiadas na parte de fora dos joelhos."},{"title":"Abrir","text":"Afaste os joelhos o máximo que conseguir, contraindo a lateral dos glúteos, e segure um instante."},{"title":"Fechar","text":"Junte as pernas devagar, sem deixar as placas encostarem."}]}'::jsonb,
    'machine', '{weight,reps}', '{"glutes":1}'::jsonb, 60),
  ('hip-adduction-machine', '{"en":"Hip Adduction Machine","de":"Adduktorenmaschine","pt-PT":"Máquina de adutores","pt-BR":"Cadeira adutora"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Sit with your back against the pad and the thigh pads against the inside of your knees. Start at a stretch you can control."},{"title":"Squeeze","text":"Squeeze your knees together until the pads meet, keeping your back on the pad."},{"title":"Return","text":"Let your legs open slowly back to the start without letting the weight rest."}],"de":[{"title":"Einstellen","text":"Setz dich mit dem Rücken ans Polster, die Beinpolster liegen innen an den Knien. Wähl eine Dehnung, die du kontrollieren kannst."},{"title":"Schließen","text":"Drück die Knie zusammen, bis sich die Polster berühren. Der Rücken bleibt am Polster."},{"title":"Öffnen","text":"Lass die Beine langsam wieder auseinandergehen, ohne das Gewicht abzulegen."}],"pt-PT":[{"title":"Ajustar","text":"Senta-te com as costas no encosto e as almofadas na parte de dentro dos joelhos. Começa com uma abertura que controles."},{"title":"Fechar","text":"Aperta os joelhos um contra o outro até as almofadas se tocarem, com as costas no encosto."},{"title":"Abrir","text":"Deixa as pernas abrirem devagar até ao início, sem pousar as placas."}],"pt-BR":[{"title":"Ajuste","text":"Sente com as costas no encosto e as almofadas na parte de dentro dos joelhos. Comece com uma abertura que você controle."},{"title":"Fechar","text":"Aperte os joelhos um contra o outro até as almofadas se encostarem, com as costas no encosto."},{"title":"Abrir","text":"Deixe as pernas abrirem devagar até o início, sem apoiar as placas."}]}'::jsonb,
    'machine', '{weight,reps}', '{"adductors":1}'::jsonb, 60),
  ('copenhagen-plank', '{"en":"Copenhagen Plank","de":"Copenhagen Plank","pt-PT":"Prancha Copenhaga","pt-BR":"Prancha Copenhague"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Lie on your side next to a bench, forearm under your shoulder, and rest the inside of your top knee or ankle on the bench."},{"title":"Lift","text":"Press the top leg into the bench and lift your hips until your body forms a straight line. The bottom leg hangs free."},{"title":"Hold","text":"Keep your hips high and breathe steadily for the full time. Then do the same time on the other side."}],"de":[{"title":"Aufbau","text":"Leg dich seitlich neben eine Bank, Unterarm unter der Schulter, und leg das obere Bein mit Knie oder Knöchel auf die Bank."},{"title":"Anheben","text":"Drück das obere Bein in die Bank und heb die Hüfte, bis dein Körper eine gerade Linie bildet. Das untere Bein hängt frei."},{"title":"Halten","text":"Halt die Hüfte die ganze Zeit oben und atme ruhig weiter. Danach die gleiche Zeit auf der anderen Seite."}],"pt-PT":[{"title":"Preparação","text":"Deita-te de lado junto a um banco, antebraço por baixo do ombro, e apoia o joelho ou o tornozelo da perna de cima no banco."},{"title":"Elevar","text":"Pressiona a perna de cima contra o banco e sobe a anca até o corpo ficar em linha reta. A perna de baixo fica solta."},{"title":"Manter","text":"Mantém a anca alta e respira com calma durante todo o tempo. Depois faz o mesmo tempo do outro lado."}],"pt-BR":[{"title":"Preparação","text":"Deite de lado junto a um banco, antebraço embaixo do ombro, e apoie o joelho ou o tornozelo da perna de cima no banco."},{"title":"Elevar","text":"Pressione a perna de cima contra o banco e eleve o quadril até o corpo ficar em linha reta. A perna de baixo fica solta."},{"title":"Segure","text":"Mantenha o quadril alto e respire com calma durante todo o tempo. Depois faça o mesmo tempo do outro lado."}]}'::jsonb,
    'bodyweight', '{seconds}', '{"adductors":0.6,"obliques":0.3,"abs":0.1}'::jsonb, 60),
  ('seated-calf-raise', '{"en":"Seated Calf Raise","de":"Wadenheben sitzend","pt-PT":"Gémeos sentado","pt-BR":"Panturrilha sentado"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Sit with the balls of your feet on the platform edge and the knee pad snug on your lower thighs."},{"title":"Rise","text":"Release the safety and push up onto your toes as high as you can. Pause briefly at the top."},{"title":"Lower","text":"Lower your heels slowly below the platform for a full stretch, without bouncing."}],"de":[{"title":"Einstellen","text":"Setz dich hin, die Fußballen auf der Plattformkante, das Kniepolster liegt fest auf den unteren Oberschenkeln."},{"title":"Hoch","text":"Löse die Sicherung und drück dich so weit wie möglich auf die Zehenspitzen. Halte oben kurz."},{"title":"Absenken","text":"Senk die Fersen langsam unter die Plattform, bis die Waden gedehnt sind, ohne zu federn."}],"pt-PT":[{"title":"Ajustar","text":"Senta-te com as pontas dos pés na borda da plataforma e a almofada bem assente na parte de baixo das coxas."},{"title":"Subir","text":"Solta o travão e sobe na ponta dos pés o mais alto possível. Faz uma breve pausa em cima."},{"title":"Descida","text":"Desce os calcanhares devagar abaixo da plataforma para alongar bem, sem ressaltos."}],"pt-BR":[{"title":"Ajuste","text":"Sente com as pontas dos pés na borda da plataforma e a almofada bem firme na parte de baixo das coxas."},{"title":"Subir","text":"Solte a trava e suba na ponta dos pés o mais alto possível. Segure um instante em cima."},{"title":"Descida","text":"Desça os calcanhares devagar abaixo da plataforma para alongar bem, sem quicar."}]}'::jsonb,
    'machine', '{weight,reps}', '{"calves":1}'::jsonb, 60),
  ('leg-press-calf-raise', '{"en":"Leg Press Calf Raise","de":"Wadenheben an der Beinpresse","pt-PT":"Gémeos na prensa","pt-BR":"Panturrilha no leg press"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Sit in the leg press with the balls of your feet on the bottom edge of the platform, heels free. Legs straight, knees not locked."},{"title":"Press","text":"Push the platform away by pointing your toes as far as you can, without bending your knees."},{"title":"Return","text":"Let the platform come back slowly until your calves are fully stretched. Keep your feet firmly on the edge."}],"de":[{"title":"Aufbau","text":"Setz dich in die Beinpresse und stell die Fußballen an die untere Plattformkante, Fersen frei. Beine gestreckt, Knie nicht durchgedrückt."},{"title":"Drücken","text":"Drück die Plattform weg, indem du die Zehen so weit wie möglich streckst. Die Knie bewegen sich dabei nicht."},{"title":"Zurück","text":"Lass die Plattform langsam zurückkommen, bis die Waden voll gedehnt sind. Die Füße bleiben fest auf der Kante."}],"pt-PT":[{"title":"Preparação","text":"Senta-te na prensa e apoia as pontas dos pés na borda de baixo da plataforma, calcanhares livres. Pernas esticadas sem bloquear."},{"title":"Empurrar","text":"Empurra a plataforma a esticar ao máximo as pontas dos pés, sem dobrar os joelhos."},{"title":"Voltar","text":"Deixa a plataforma voltar devagar até alongares bem os gémeos. Mantém os pés firmes na borda."}],"pt-BR":[{"title":"Preparação","text":"Sente no leg press e apoie as pontas dos pés na borda de baixo da plataforma, calcanhares livres. Pernas estendidas sem travar."},{"title":"Empurrar","text":"Empurre a plataforma estendendo ao máximo as pontas dos pés, sem dobrar os joelhos."},{"title":"Voltar","text":"Deixe a plataforma voltar devagar até alongar bem as panturrilhas. Mantenha os pés firmes na borda."}]}'::jsonb,
    'machine', '{weight,reps}', '{"calves":1}'::jsonb, 60),
  ('smith-calf-raise', '{"en":"Smith Machine Calf Raise","de":"Wadenheben an der Multipresse","pt-PT":"Gémeos na máquina Smith","pt-BR":"Panturrilha no Smith"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Stand on a step or plate under the Smith bar with the bar on your upper back and the balls of your feet on the edge."},{"title":"Rise","text":"Unhook the bar and push up onto your toes as high as you can, legs straight. Pause briefly at the top."},{"title":"Lower","text":"Lower your heels slowly below the edge for a full stretch. Rack the bar after your last rep."}],"de":[{"title":"Aufbau","text":"Stell dich unter der Multipresse auf eine Stufe oder Scheibe, Stange auf dem oberen Rücken, Fußballen auf der Kante."},{"title":"Hoch","text":"Häng die Stange aus und drück dich mit gestreckten Beinen so weit wie möglich auf die Zehenspitzen. Halte oben kurz."},{"title":"Absenken","text":"Senk die Fersen langsam unter die Kante, bis die Waden gedehnt sind. Häng die Stange nach der letzten Wiederholung ein."}],"pt-PT":[{"title":"Preparação","text":"Sobe para um degrau ou disco por baixo da barra da máquina Smith, com a barra nas costas e as pontas dos pés na borda."},{"title":"Subir","text":"Solta a barra e sobe na ponta dos pés o mais alto possível, pernas esticadas. Faz uma breve pausa em cima."},{"title":"Descida","text":"Desce os calcanhares devagar abaixo da borda para alongar bem. Prende a barra no fim da última repetição."}],"pt-BR":[{"title":"Preparação","text":"Suba em um degrau ou anilha embaixo da barra do Smith, com a barra nas costas e as pontas dos pés na borda."},{"title":"Subir","text":"Solte a barra e suba na ponta dos pés o mais alto possível, pernas estendidas. Segure um instante em cima."},{"title":"Descida","text":"Desça os calcanhares devagar abaixo da borda para alongar bem. Trave a barra depois da última repetição."}]}'::jsonb,
    'machine', '{weight,reps}', '{"calves":1}'::jsonb, 60),
  ('single-leg-calf-raise', '{"en":"Single-Leg Calf Raise","de":"Wadenheben einbeinig","pt-PT":"Gémeos unilateral","pt-BR":"Panturrilha unilateral"}'::jsonb,
    '{"en":[{"title":"Position","text":"Stand on one foot with the ball of the foot on a step edge, a dumbbell in the same-side hand if you like. Hold on with your free hand."},{"title":"Rise","text":"Push up onto your toes as high as you can with a straight leg and pause briefly."},{"title":"Lower","text":"Lower your heel slowly below the step for a full stretch. Finish all reps, then switch legs."}],"de":[{"title":"Position","text":"Stell dich auf einem Bein mit dem Fußballen auf eine Stufe, optional mit Kurzhantel auf derselben Seite. Halt dich mit der freien Hand fest."},{"title":"Hoch","text":"Drück dich mit gestrecktem Bein so weit wie möglich auf die Zehenspitzen und halte kurz."},{"title":"Absenken","text":"Senk die Ferse langsam unter die Stufe, bis die Wade gedehnt ist. Erst alle Wiederholungen, dann Bein wechseln."}],"pt-PT":[{"title":"Posição","text":"Fica num pé só com a ponta do pé na borda de um degrau e, se quiseres, um halter do mesmo lado. Segura-te com a mão livre."},{"title":"Subir","text":"Sobe na ponta do pé o mais alto possível com a perna esticada e faz uma breve pausa."},{"title":"Descida","text":"Desce o calcanhar devagar abaixo do degrau para alongar bem. Faz todas as repetições e troca de perna."}],"pt-BR":[{"title":"Posição","text":"Fique em um pé só com a ponta do pé na borda de um degrau e, se quiser, um halter do mesmo lado. Apoie-se com a mão livre."},{"title":"Subir","text":"Suba na ponta do pé o mais alto possível com a perna estendida e segure um instante."},{"title":"Descida","text":"Desça o calcanhar devagar abaixo do degrau para alongar bem. Faça todas as repetições e troque de perna."}]}'::jsonb,
    'bodyweight', '{weight,reps}', '{"calves":1}'::jsonb, 60),
  ('tibialis-raise', '{"en":"Tibialis Raise","de":"Tibialis Raises","pt-PT":"Elevação de tibiais","pt-BR":"Elevação de tibial"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Lean your back against a wall with your heels about 30 cm in front of you, legs straight."},{"title":"Lift","text":"Pull your toes up towards your shins as high as you can, keeping your heels on the floor."},{"title":"Lower","text":"Lower your toes slowly until they almost touch the floor, then go straight into the next rep."}],"de":[{"title":"Aufbau","text":"Lehn dich mit dem Rücken an eine Wand, die Fersen etwa 30 cm vor dir, Beine gestreckt."},{"title":"Hochziehen","text":"Zieh die Zehen so weit wie möglich Richtung Schienbein, die Fersen bleiben am Boden."},{"title":"Absenken","text":"Senk die Zehen langsam ab, bis sie fast den Boden berühren, und geh direkt in die nächste Wiederholung."}],"pt-PT":[{"title":"Preparação","text":"Encosta as costas a uma parede com os calcanhares uns 30 cm à tua frente, pernas esticadas."},{"title":"Elevar","text":"Puxa as pontas dos pés em direção às canelas o mais alto possível, com os calcanhares no chão."},{"title":"Descida","text":"Desce as pontas dos pés devagar até quase tocarem no chão e passa logo à repetição seguinte."}],"pt-BR":[{"title":"Preparação","text":"Encoste as costas em uma parede com os calcanhares uns 30 cm à sua frente, pernas estendidas."},{"title":"Elevar","text":"Puxe as pontas dos pés em direção às canelas o mais alto possível, com os calcanhares no chão."},{"title":"Descida","text":"Desça as pontas dos pés devagar até quase encostarem no chão e emende na próxima repetição."}]}'::jsonb,
    'bodyweight', '{reps}', '{"tibialis":1}'::jsonb, 60),
  ('treadmill', '{"en":"Treadmill","de":"Laufband","pt-PT":"Passadeira","pt-BR":"Esteira"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Stand with your feet on the side rails, clip the safety key to your clothing and start at a slow speed."},{"title":"Move","text":"Walk or run tall in the middle of the belt with relaxed arms. Hold the handrails only to get on and off."},{"title":"Pace","text":"Choose a speed and incline you can sustain. For a warm-up you should still be able to talk in full sentences."}],"de":[{"title":"Start","text":"Stell dich mit den Füßen auf die Seitenleisten, befestige den Sicherheitsclip an deiner Kleidung und starte langsam."},{"title":"Laufen","text":"Geh oder lauf aufrecht in der Mitte des Bandes, die Arme locker. Halt dich nur beim Auf- und Absteigen fest."},{"title":"Tempo","text":"Wähl Geschwindigkeit und Steigung so, dass du sie halten kannst. Beim Aufwärmen solltest du noch ganze Sätze sprechen können."}],"pt-PT":[{"title":"Preparação","text":"Põe os pés nas laterais da passadeira, prende a mola de segurança à roupa e começa a uma velocidade baixa."},{"title":"Movimento","text":"Caminha ou corre direito no meio do tapete, com os braços soltos. Segura-te às barras só para subir e descer."},{"title":"Ritmo","text":"Escolhe uma velocidade e inclinação que consigas manter. No aquecimento, deves conseguir falar em frases completas."}],"pt-BR":[{"title":"Preparação","text":"Coloque os pés nas laterais da esteira, prenda o clipe de segurança na roupa e comece em uma velocidade baixa."},{"title":"Movimento","text":"Caminhe ou corra ereto no meio da lona, com os braços soltos. Segure nas barras só para subir e descer."},{"title":"Ritmo","text":"Escolha uma velocidade e inclinação que você consiga manter. No aquecimento, você deve conseguir falar frases completas."}]}'::jsonb,
    'machine', '{seconds}', '{"quads":0.35,"calves":0.25,"glutes":0.2,"hamstrings":0.2}'::jsonb, 60),
  ('elliptical', '{"en":"Elliptical","de":"Crosstrainer","pt-PT":"Elíptica","pt-BR":"Elíptico"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Step onto the pedals, hold the moving handles and choose a resistance you can move smoothly against."},{"title":"Move","text":"Push and pull the handles as you stride, keeping your whole foot on the pedals and your torso upright."},{"title":"Pace","text":"Keep a steady, even rhythm. For a warm-up you should still be able to hold a conversation comfortably."}],"de":[{"title":"Start","text":"Stell dich auf die Pedale, greif die beweglichen Griffe und wähl einen Widerstand, bei dem du flüssig treten kannst."},{"title":"Bewegung","text":"Drück und zieh die Griffe im Takt der Schritte. Die Füße bleiben flach auf den Pedalen, der Oberkörper aufrecht."},{"title":"Tempo","text":"Halte einen gleichmäßigen Rhythmus. Beim Aufwärmen solltest du dich noch locker unterhalten können."}],"pt-PT":[{"title":"Preparação","text":"Sobe para os pedais, agarra as pegas móveis e escolhe uma resistência que te deixe mexer com fluidez."},{"title":"Movimento","text":"Empurra e puxa as pegas ao ritmo das passadas, com os pés assentes nos pedais e o tronco direito."},{"title":"Ritmo","text":"Mantém um ritmo constante e regular. No aquecimento, deves conseguir conversar sem esforço."}],"pt-BR":[{"title":"Preparação","text":"Suba nos pedais, segure os pegadores móveis e escolha uma resistência que permita um movimento fluido."},{"title":"Movimento","text":"Empurre e puxe os pegadores no ritmo das passadas, com os pés apoiados nos pedais e o tronco ereto."},{"title":"Ritmo","text":"Mantenha um ritmo constante e regular. No aquecimento, você deve conseguir conversar sem esforço."}]}'::jsonb,
    'machine', '{seconds}', '{"quads":0.4,"glutes":0.3,"hamstrings":0.15,"calves":0.15}'::jsonb, 60),
  ('exercise-bike', '{"en":"Exercise Bike","de":"Fahrrad-Ergometer","pt-PT":"Bicicleta estática","pt-BR":"Bicicleta ergométrica"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Adjust the seat so your knee stays slightly bent at the bottom of the pedal stroke. Start with light resistance."},{"title":"Pedal","text":"Pedal in smooth circles with your torso still and the balls of your feet on the pedals."},{"title":"Pace","text":"Hold a steady cadence and set the resistance for your goal. For a warm-up you should still be able to talk."}],"de":[{"title":"Einstellen","text":"Stell den Sattel so ein, dass das Knie am tiefsten Punkt leicht gebeugt bleibt. Starte mit wenig Widerstand."},{"title":"Treten","text":"Tritt in runden, gleichmäßigen Kreisen, Oberkörper ruhig, die Fußballen auf den Pedalen."},{"title":"Tempo","text":"Halte eine konstante Trittfrequenz und pass den Widerstand an dein Ziel an. Beim Aufwärmen solltest du noch reden können."}],"pt-PT":[{"title":"Ajustar","text":"Ajusta o selim para o joelho ficar ligeiramente fletido no ponto mais baixo da pedalada. Começa com pouca resistência."},{"title":"Pedalar","text":"Pedala em círculos suaves, com o tronco estável e a parte da frente dos pés nos pedais."},{"title":"Ritmo","text":"Mantém uma cadência constante e ajusta a resistência ao teu objetivo. No aquecimento, deves conseguir falar."}],"pt-BR":[{"title":"Ajuste","text":"Ajuste o banco para o joelho ficar levemente flexionado no ponto mais baixo da pedalada. Comece com pouca carga."},{"title":"Pedalar","text":"Pedale em círculos suaves, com o tronco estável e a parte da frente dos pés nos pedais."},{"title":"Ritmo","text":"Mantenha uma cadência constante e ajuste a carga ao seu objetivo. No aquecimento, você deve conseguir falar."}]}'::jsonb,
    'machine', '{seconds}', '{"quads":0.6,"glutes":0.2,"hamstrings":0.1,"calves":0.1}'::jsonb, 60),
  ('rowing-machine', '{"en":"Rowing Machine","de":"Rudergerät","pt-PT":"Máquina de remo","pt-BR":"Remo ergométrico"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Strap your feet in with the strap across the widest part of your foot. Set the damper to a moderate level, around 3 to 5."},{"title":"Stroke","text":"Drive with your legs first, then lean back slightly and pull the handle to your lower ribs. Return in reverse: arms, body, legs."},{"title":"Pace","text":"Make the return about twice as long as the drive and hold a steady stroke rate, around 20 to 24 per minute for easy work."}],"de":[{"title":"Einstellen","text":"Schnall die Füße so an, dass der Gurt über der breitesten Stelle liegt. Stell die Luftklappe auf eine mittlere Stufe, etwa 3 bis 5."},{"title":"Zug","text":"Drück zuerst mit den Beinen ab, lehn dich dann leicht zurück und zieh den Griff zu den unteren Rippen. Zurück geht es umgekehrt: Arme, Oberkörper, Beine."},{"title":"Tempo","text":"Lass das Vorrollen etwa doppelt so lange dauern wie den Zug und halte eine gleichmäßige Schlagzahl, locker etwa 20 bis 24 pro Minute."}],"pt-PT":[{"title":"Preparação","text":"Prende os pés com a fita sobre a parte mais larga do pé. Põe o regulador de ar num nível médio, por volta de 3 a 5."},{"title":"Remada","text":"Empurra primeiro com as pernas, depois inclina-te um pouco para trás e puxa a pega até às costelas de baixo. Volta pela ordem inversa: braços, tronco, pernas."},{"title":"Ritmo","text":"A recuperação deve durar cerca do dobro da puxada. Mantém uma cadência constante, cerca de 20 a 24 remadas por minuto em ritmo leve."}],"pt-BR":[{"title":"Preparação","text":"Prenda os pés com a fita sobre a parte mais larga do pé. Coloque o regulador de ar em um nível médio, por volta de 3 a 5."},{"title":"Remada","text":"Empurre primeiro com as pernas, depois incline o corpo um pouco para trás e puxe o pegador até as costelas de baixo. Volte na ordem inversa: braços, tronco, pernas."},{"title":"Ritmo","text":"A volta deve durar cerca do dobro da puxada. Mantenha uma cadência constante, cerca de 20 a 24 remadas por minuto em ritmo leve."}]}'::jsonb,
    'machine', '{seconds}', '{"quads":0.35,"lats":0.25,"upper_back":0.2,"glutes":0.2}'::jsonb, 60),
  ('stair-climber', '{"en":"Stair Climber","de":"Stepper","pt-PT":"Máquina de escadas","pt-BR":"Simulador de escada"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Step onto the stairs, hold the side rails lightly and start at a slow step speed."},{"title":"Climb","text":"Place your whole foot on each step and stand tall. Don''t lean on the rails or hang off them."},{"title":"Pace","text":"Raise the speed only as far as you can keep good posture. For a warm-up you should still be able to talk."}],"de":[{"title":"Start","text":"Stell dich auf die Stufen, halt dich locker an den Seitengriffen fest und starte mit niedrigem Tempo."},{"title":"Steigen","text":"Setz bei jedem Schritt den ganzen Fuß auf und bleib aufrecht. Stütz dich nicht auf die Griffe und häng dich nicht rein."},{"title":"Tempo","text":"Erhöh das Tempo nur so weit, wie du aufrecht bleiben kannst. Beim Aufwärmen solltest du noch reden können."}],"pt-PT":[{"title":"Preparação","text":"Sobe para os degraus, segura-te ao de leve às barras laterais e começa a uma velocidade baixa."},{"title":"Subir","text":"Apoia o pé todo em cada degrau e mantém-te direito. Não te apoies nem te pendures nas barras."},{"title":"Ritmo","text":"Aumenta a velocidade só até onde consegues manter a postura. No aquecimento, deves conseguir falar."}],"pt-BR":[{"title":"Preparação","text":"Suba nos degraus, segure de leve nas barras laterais e comece em uma velocidade baixa."},{"title":"Subir","text":"Apoie o pé inteiro em cada degrau e mantenha o corpo ereto. Não se apoie nem se pendure nas barras."},{"title":"Ritmo","text":"Aumente a velocidade só até onde você consegue manter a postura. No aquecimento, você deve conseguir falar."}]}'::jsonb,
    'machine', '{seconds}', '{"glutes":0.4,"quads":0.4,"calves":0.2}'::jsonb, 60),
  ('air-bike', '{"en":"Air Bike","de":"Air Bike","pt-PT":"Air bike","pt-BR":"Air bike"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Adjust the seat so your knee stays slightly bent at the bottom of the stroke, and hold the moving handles."},{"title":"Move","text":"Push and pull the handles as you pedal so arms and legs work together. The harder you go, the higher the resistance."},{"title":"Pace","text":"Start easy and build up. For intervals, go all out in the work period, then pedal slowly until your breathing settles."}],"de":[{"title":"Einstellen","text":"Stell den Sattel so ein, dass das Knie am tiefsten Punkt leicht gebeugt bleibt, und greif die beweglichen Griffe."},{"title":"Bewegung","text":"Drück und zieh die Griffe beim Treten, damit Arme und Beine zusammenarbeiten. Je schneller du trittst, desto höher der Widerstand."},{"title":"Tempo","text":"Fang locker an und steigere dich. Gib bei Intervallen in der Belastung alles und tritt danach locker, bis sich deine Atmung beruhigt."}],"pt-PT":[{"title":"Ajustar","text":"Ajusta o selim para o joelho ficar ligeiramente fletido no ponto mais baixo e agarra as pegas móveis."},{"title":"Movimento","text":"Empurra e puxa as pegas enquanto pedalas, para braços e pernas trabalharem juntos. Quanto mais forte, maior a resistência."},{"title":"Ritmo","text":"Começa devagar e aumenta aos poucos. Nos intervalos, dá tudo no esforço e depois pedala devagar até a respiração acalmar."}],"pt-BR":[{"title":"Ajuste","text":"Ajuste o banco para o joelho ficar levemente flexionado no ponto mais baixo e segure os pegadores móveis."},{"title":"Movimento","text":"Empurre e puxe os pegadores enquanto pedala, para braços e pernas trabalharem juntos. Quanto mais forte, maior a resistência."},{"title":"Ritmo","text":"Comece leve e vá aumentando. Nos intervalos, dê tudo no esforço e depois pedale devagar até a respiração acalmar."}]}'::jsonb,
    'machine', '{seconds}', '{"quads":0.45,"glutes":0.2,"upper_back":0.2,"chest":0.15}'::jsonb, 60);
